# ============ MULTI-USER TASK SCHEDULER ============

class MultiUserTaskScheduler:
    """Round-robin task scheduler to ensure all users get fair processing time"""
    
    def __init__(self):
        self.user_queues = {}  # user_id -> queue
        self.user_tasks = {}   # user_id -> current task
        self.current_user_index = 0
        self.user_list = []
        self._scheduler_task = None
        self._running = False
        self._lock = asyncio.Lock()
        
    async def start(self):
        """Start the scheduler"""
        self._running = True
        self._scheduler_task = asyncio.create_task(self._scheduler_loop())
        print("✅ Multi-user task scheduler started")
        
    async def stop(self):
        """Stop the scheduler"""
        self._running = False
        if self._scheduler_task:
            self._scheduler_task.cancel()
            try:
                await self._scheduler_task
            except:
                pass
        print("🔄 Multi-user task scheduler stopped")
        
    def register_user(self, user_id: int, task_coroutine):
        """Register a user's task to be scheduled"""
        async def wrapper():
            try:
                await task_coroutine
            finally:
                await self._unregister_user(user_id)
        
        if user_id not in self.user_queues:
            self.user_queues[user_id] = asyncio.Queue()
            self.user_tasks[user_id] = asyncio.create_task(wrapper())
            self._update_user_list()
            print(f"📋 User {user_id} registered with scheduler")
        
    async def _unregister_user(self, user_id: int):
        """Remove user from scheduler"""
        async with self._lock:
            if user_id in self.user_queues:
                del self.user_queues[user_id]
            if user_id in self.user_tasks:
                del self.user_tasks[user_id]
            self._update_user_list()
            print(f"📋 User {user_id} unregistered from scheduler")
    
    def _update_user_list(self):
        """Update the list of active users"""
        self.user_list = list(self.user_queues.keys())
        
    async def _scheduler_loop(self):
        """Main scheduler loop - gives each user a time slice"""
        while self._running:
            if not self.user_list:
                await asyncio.sleep(0.1)
                continue
            
            # Round-robin through users
            for user_id in self.user_list[:]:  # Use copy to avoid modification during iteration
                if not self._running:
                    break
                
                if user_id not in self.user_queues:
                    continue
                
                # Give this user a time slice (process up to 5 cards)
                try:
                    # Signal this user's task to process
                    await self.user_queues[user_id].put("process")
                    # Small delay to allow processing
                    await asyncio.sleep(0.1)
                except Exception as e:
                    print(f"⚠️ Error scheduling user {user_id}: {e}")
                
                # Yield to next user
                await asyncio.sleep(0)
            
            # Brief pause between cycles
            await asyncio.sleep(0.05)
    
    async def wait_for_slot(self, user_id: int):
        """Wait for this user's turn to process"""
        if user_id not in self.user_queues:
            return True
        
        try:
            # Wait for scheduler to give us a slot (timeout after 5 seconds)
            await asyncio.wait_for(self.user_queues[user_id].get(), timeout=5.0)
            return True
        except asyncio.TimeoutError:
            print(f"⏰ User {user_id} timeout waiting for slot")
            return False

