# Update the create_progress_buttons function

async def update_progress_message(
    context: ContextTypes.DEFAULT_TYPE,
    chat_id: int,
    message_id: int,
    current: int,
    total: int,
    approved: int = 0,
    charged: int = 0,
    dead: int = 0,
    errors: int = 0,
    gateway: str = "Shopify",
    start_time: float = None
):
    """Update progress message with premium emojis - NO BUTTONS"""
    
    # Only update every 10 cards or at completion
    if current > 0 and current < total and current % 10 != 0:
        return
    
    # Skip if less than 2 seconds since last update
    if hasattr(update_progress_message, 'last_update_time'):
        last_time = update_progress_message.last_update_time
        if time.time() - last_time < 2.0 and current < total:
            return
    
    update_progress_message.last_update_time = time.time()
    
    # Calculate elapsed time
    elapsed_time = 0
    if start_time:
        elapsed_time = int(time.time() - start_time)
        minutes = elapsed_time // 60
        seconds = elapsed_time % 60
        time_str = f"{minutes}m {seconds}s" if minutes > 0 else f"{seconds}s"
    else:
        time_str = "0s"
    
    # Determine status
    if current >= total:
        status_text = f"FINISHED ✅"
        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["success"], "✅")
    else:
        status_text = f"PROCESSING {current}/{total}"
        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["time"], "🔄")
    
    # Premium emojis for each line
    gateway_emoji = premium_emoji(PREMIUM_EMOJI_IDS.get(gateway.lower(), "5427168083074628963"), "💳")
    checked_emoji = premium_emoji(PREMIUM_EMOJI_IDS["stats"], "📊")
    approved_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
    charged_emoji = premium_emoji(PREMIUM_EMOJI_IDS["charged"], "💎")
    dead_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
    errors_emoji = premium_emoji(PREMIUM_EMOJI_IDS["error"], "⚠️")
    time_emoji = premium_emoji(PREMIUM_EMOJI_IDS["time"], "⏱️")
    
    # Build the progress message
    progress_text = (
        f"{gateway_emoji} <b>Gateway</b> ➛ {gateway}\n"
        f"{status_emoji} <b>Status</b> ➛ {status_text}\n"
        f"{checked_emoji} <b>Checked</b> ➛ {current}/{total}\n"
        f"{approved_emoji} <b>Approved</b> ➛ {approved}\n"
        f"{charged_emoji} <b>Charged</b> ➛ {charged}\n"
        f"{dead_emoji} <b>Dead</b> ➛ {dead}\n"
        f"{errors_emoji} <b>Errors</b> ➛ {errors}\n"
        f"{time_emoji} <b>Time</b> ➛ {time_str}"
    )
    
    try:
        await context.bot.edit_message_text(
            chat_id=chat_id,
            message_id=message_id,
            text=progress_text,
            parse_mode=ParseMode.HTML
        )
    except Exception as e:
        if "message is not modified" not in str(e).lower():
            print(f"⚠️ Progress update error: {e}")


