class PayPalAPIPool:
    """
    PayPal API Pool - Rotates between multiple PayPal APIs
    Supports weighted round-robin and automatic failover
    """
    
    def __init__(self, apis=None):
        if apis is None:
            apis = PAYPAL_API_POOL_CONFIG
        self.apis = apis
        self.api_stats = {}
        self._lock = asyncio.Lock()
        self.session = None
        self._api_index = 0
        
        # Initialize stats for each API
        for api in self.apis:
            self.api_stats[api["name"]] = {
                "total_requests": 0,
                "successful": 0,
                "failed": 0,
                "avg_response_time": 0,
                "last_used": 0,
                "enabled": api.get("enabled", True),
                "weight": api.get("weight", 1)
            }
        
        print(f"🔌 PayPal API Pool initialized with {len(self.apis)} APIs")
        for api in self.apis:
            print(f"   • {api['name']}: {api['url']}")
    
    async def get_session(self):
        """Get or create HTTP session"""
        if self.session is None or self.session.is_closed:
            timeout = httpx.Timeout(60.0, connect=15.0, read=50.0)
            self.session = httpx.AsyncClient(
                timeout=timeout,
                verify=False,
                limits=httpx.Limits(max_keepalive_connections=20, max_connections=50),
                http2=True
            )
        return self.session
    
    async def get_next_api(self) -> dict:
        """Get next enabled API using round-robin with weights"""
        async with self._lock:
            enabled_apis = [api for api in self.apis if api.get("enabled", True)]
            
            if not enabled_apis:
                print("⚠️ All PayPal APIs disabled! Re-enabling all...")
                for api in self.apis:
                    api["enabled"] = True
                enabled_apis = self.apis.copy()
            
            # Weighted selection
            total_weight = sum(api.get("weight", 1) for api in enabled_apis)
            rand = random.uniform(0, total_weight)
            cumulative = 0
            
            for api in enabled_apis:
                cumulative += api.get("weight", 1)
                if rand <= cumulative:
                    selected = api
                    break
            else:
                selected = enabled_apis[0]
            
            # Update last used
            self.api_stats[selected["name"]]["last_used"] = time.time()
            
            stats = self.api_stats.get(selected["name"], {})
            success_rate = (stats.get('successful', 0) / max(stats.get('total_requests', 1), 1)) * 100
            print(f"🔄 [PayPal Pool] Selected: {selected['name']} (success: {success_rate:.0f}%)")
            
            return selected.copy()
    
    def mark_api_result(self, api_name: str, success: bool, response_time: float, is_retryable: bool = False):
        """Mark API call result for statistics and weighting"""
        for api in self.apis:
            if api["name"] == api_name:
                if success:
                    api["success_count"] = api.get("success_count", 0) + 1
                    api["last_success"] = time.time()
                    # Increase weight on success (max 20)
                    api["weight"] = min(20, api.get("weight", 1) + 1)
                else:
                    api["fail_count"] = api.get("fail_count", 0) + 1
                    # Decrease weight on failure (min 0.5)
                    api["weight"] = max(0.5, api.get("weight", 1) - 0.5)
                
                # Update average response time
                old_avg = api.get("avg_response_time", 0)
                total_calls = api.get("success_count", 0) + api.get("fail_count", 0)
                if total_calls > 0:
                    api["avg_response_time"] = ((old_avg * (total_calls - 1)) + response_time) / total_calls
                
                # Auto-disable if 5 consecutive failures with no successes
                if api.get("fail_count", 0) >= 5 and api.get("success_count", 0) == 0:
                    print(f"⚠️ Disabling PayPal API {api_name} due to 5 consecutive failures")
                    api["enabled"] = False
                break
        
        # Update stats dict
        if api_name in self.api_stats:
            self.api_stats[api_name]["total_requests"] += 1
            if success:
                self.api_stats[api_name]["successful"] += 1
            else:
                if is_retryable:
                    self.api_stats[api_name]["retryable"] = self.api_stats[api_name].get("retryable", 0) + 1
                else:
                    self.api_stats[api_name]["failed"] += 1
            
            old_avg = self.api_stats[api_name]["avg_response_time"]
            total = self.api_stats[api_name]["total_requests"]
            if total > 0:
                self.api_stats[api_name]["avg_response_time"] = ((old_avg * (total - 1)) + response_time) / total
    
    async def check_card_with_pool(self, card: str, amount: str = "1.00", 
                                    currency: str = "USD", proxy: str = None, 
                                    user_id: int = None) -> Dict:
        """
        Check a card using the best available API from the pool
        """
        max_attempts = 3
        tried_apis = []
        
        for attempt in range(max_attempts):
            # Get a new API for each attempt
            api = await self.get_next_api()
            api_name = api["name"]
            
            if api_name in tried_apis:
                continue
            tried_apis.append(api_name)
            
            print(f"\n🔍 [PayPal Pool] Attempt {attempt + 1}/{max_attempts} using: {api_name}")
            
            start_time = time.time()
            
            try:
                result = await self._make_api_request(api, card, amount, currency, proxy)
                elapsed = time.time() - start_time
                
                if result is None:
                    self.mark_api_result(api_name, False, elapsed, True)
                    continue
                
                status_category = result.get("status_category", "unknown")
                
                # Any valid response (even declined) means API is working
                if status_category in ["charged", "approved", "declined"]:
                    self.mark_api_result(api_name, True, elapsed, False)
                    result["api_used"] = api_name
                    result["api_attempt"] = attempt + 1
                    print(f"✅ [PayPal Pool] {api_name} returned: {status_category}")
                    return result
                else:
                    self.mark_api_result(api_name, False, elapsed, True)
                    continue
                
            except Exception as e:
                elapsed = time.time() - start_time
                self.mark_api_result(api_name, False, elapsed, True)
                print(f"❌ [PayPal Pool] {api_name} error: {str(e)[:100]}")
                continue
        
        # All attempts failed
        return {
            "status": "error",
            "result": "ALL_APIS_FAILED",
            "message": "All PayPal APIs failed",
            "status_display": "⚠️ ALL APIS FAILED",
            "status_category": "error",
            "elapsed": 0,
            "price": f"${amount}",
            "gateway": "PayPal"
        }
    
    async def _make_api_request(self, api: dict, card: str, amount: str, currency: str, proxy: str = None) -> Dict:
        """Make request to a specific PayPal API"""
        
        # Parse card
        parts = card.split('|')
        if len(parts) != 4:
            return None
        
        card_num, month, year, cvv = parts
        
        # Format year (API expects 2-digit year)
        if len(year) == 4:
            year_2digit = year[2:]
        else:
            year_2digit = year
        
        formatted_card = f"{card_num}|{month}|{year_2digit}|{cvv}"
        
        session = await self.get_session()
        
        # Prepare payload based on API field names
        card_field = api.get("card_field", "card")
        amount_field = api.get("amount_field", "amount")
        
        payload = {
            card_field: formatted_card,
            amount_field: amount
        }
        
        # Add currency if supported
        if api.get("currency"):
            payload["currency"] = currency
        
        # Add proxy if provided
        if proxy:
            # Format proxy for the API
            formatted_proxy = format_proxy_for_paypal(proxy)
            if formatted_proxy:
                # Some APIs accept proxy in params
                if api.get("proxy_param"):
                    payload["proxy"] = formatted_proxy
        
        print(f"📤 [PayPal] POST {api['url']}")
        print(f"📤 Payload: {payload}")
        
        try:
            response = await session.post(
                api["url"],
                json=payload,
                headers={
                    "User-Agent": generate_user_agent(),
                    "Accept": "application/json",
                    "Content-Type": "application/json"
                }
            )
            
            elapsed = response.elapsed.total_seconds() if hasattr(response, 'elapsed') else 0
            print(f"📥 Response time: {elapsed:.2f}s | Status: {response.status_code}")
            
            if response.status_code == 200:
                try:
                    data = response.json()
                    print(f"📄 Response: {json.dumps(data, indent=2)[:500]}")
                    return self._parse_response(data, card, amount, elapsed)
                except json.JSONDecodeError as e:
                    print(f"⚠️ JSON parse error: {e}")
                    return None
            else:
                print(f"⚠️ HTTP {response.status_code}")
                return None
                
        except httpx.TimeoutException:
            print(f"⏰ Timeout")
            return None
        except Exception as e:
            print(f"❌ Request error: {e}")
            return None
    
    def _parse_response(self, data: dict, card: str, amount: str, elapsed: float) -> Dict:
        """Parse PayPal API response"""
        
        # Try different possible response field names
        result_text = data.get('result', data.get('status', data.get('message', 'UNKNOWN')))
        status_text = data.get('status', data.get('success', False))
        code_text = data.get('code', '')
        
        result_upper = str(result_text).upper()
        status_upper = str(status_text).upper()
        code_upper = str(code_text).upper()
        
        full_response = f"{result_upper} {status_upper} {code_upper}"
        
        print(f"📊 [PayPal Parse] Result: {result_text[:100]}")
        
        # ============ CHECK FOR APPROVED/LIVE RESPONSES ============
        
        # CHARGED
        if any(p in full_response for p in ["CHARGE 2$", "2$"]):
            status_display = "🔥 CHARGED "
            status_category = "charged"
            final_message = f"Charged ${amount}"
            print(f"🔥 [CHARGED] Card charged successfully")
        
        # EXISTING_ACCOUNT_RESTRICTED (LIVE)
        elif "EXISTING_ACCOUNT_RESTRICTED" in full_response:
            status_display = "✅ EXISTING ACCOUNT RESTRICTED"
            status_category = "approved"
            final_message = "Existing Account Restricted - Card is LIVE"
            print(f"✅ [APPROVED] Existing Account Restricted")
        
        # RISK_DISALLOWED (LIVE)
        elif "RISK_DISALLOWED" in full_response:
            status_display = "✅ RISK DISALLOWED"
            status_category = "approved"
            final_message = "Risk Disallowed - Card is LIVE"
            print(f"✅ [APPROVED] Risk Disallowed")
        
        # APPROVED
        elif "APPROVED" in full_response and "DECLINED" not in full_response:
            status_display = "✅ APPROVED"
            status_category = "approved"
            final_message = "Card Approved"
            print(f"✅ [APPROVED] Card approved")
        
        # INSUFFICIENT FUNDS (LIVE)
        elif any(p in full_response for p in ["INSUFFICIENT", "FUNDS"]):
            status_display = "💰 INSUFFICIENT FUNDS"
            status_category = "approved"
            final_message = "Insufficient Funds - Card is LIVE"
            print(f"💰 [APPROVED] Insufficient Funds")
        
        # CVV LIVE
        elif any(p in full_response for p in ["CVV LIVE", "INCORRECT_CVV", "CVV_MISMATCH"]):
            status_display = "✅ CVV LIVE"
            status_category = "approved"
            final_message = "CVV Live - Card is valid"
            print(f"✅ [APPROVED] CVV Live")
        
        # 3D/OTP REQUIRED
        elif any(p in full_response for p in ["3D", "OTP", "SECURE", "AUTHENTICATION", "3DS"]):
            status_display = "🔐 3D REQUIRED"
            status_category = "approved"
            final_message = "3D Secure Required - Authentication needed"
            print(f"🔐 [APPROVED] 3D Required")
        
        # ============ CHECK FOR DECLINED RESPONSES ============
        
        # CARD DECLINED
        elif any(p in full_response for p in ["CARD_DECLINED", "DECLINED", "DO NOT HONOR"]):
            status_display = "❌ DECLINED"
            status_category = "declined"
            final_message = "Card Declined"
            print(f"❌ [DECLINED] Card declined")
        
        # EXPIRED CARD
        elif "EXPIRED" in full_response:
            status_display = "❌ EXPIRED CARD"
            status_category = "declined"
            final_message = "Card has expired"
            print(f"❌ [DECLINED] Expired card")
        
        # LOST OR STOLEN
        elif any(p in full_response for p in ["LOST", "STOLEN"]):
            status_display = "❌ LOST/STOLEN CARD"
            status_category = "declined"
            final_message = "Card reported lost or stolen"
            print(f"❌ [DECLINED] Lost/Stolen card")
        
        # GENERIC ERROR
        elif "GENERIC_ERROR" in full_response:
            status_display = "❌ GENERIC ERROR"
            status_category = "declined"
            final_message = "Generic error - Card declined"
            print(f"❌ [DECLINED] Generic error")
        
        # Default - check status
        elif status_upper == "SUCCESS" or status_text is True:
            status_display = "✅ APPROVED"
            status_category = "approved"
            final_message = result_text[:100]
            print(f"✅ [APPROVED] Status success")
        
        else:
            status_display = "❌ DECLINED"
            status_category = "declined"
            final_message = result_text[:100] if result_text else "Unknown response"
            print(f"❌ [DECLINED] Unknown response")
        
        return {
            "status": "success" if status_category in ["charged", "approved"] else "declined",
            "result": result_text,
            "message": final_message,
            "raw_message": result_text,
            "status_display": status_display,
            "status_category": status_category,
            "elapsed": elapsed,
            "price": f"${amount}",
            "gateway": "PayPal",
            "code": code_text
        }
    
    def get_stats(self) -> str:
        """Get formatted statistics for all APIs"""
        result = "📊 <b>PayPal API Pool Statistics</b>\n\n"
        
        for api in self.apis:
            name = api["name"]
            stats = self.api_stats.get(name, {})
            enabled = "✅" if api.get("enabled", True) else "❌"
            total = stats.get('total_requests', 0)
            successful = stats.get('successful', 0)
            failed = stats.get('failed', 0)
            success_rate = (successful / max(total, 1)) * 100
            
            result += f"{enabled} <b>{name}</b>\n"
            result += f"   ├─ Requests: {total}\n"
            result += f"   ├─ Success Rate: {success_rate:.1f}%\n"
            result += f"   ├─ Successful: {successful}\n"
            result += f"   ├─ Failed: {failed}\n"
            result += f"   ├─ Avg Time: {stats.get('avg_response_time', 0):.2f}s\n"
            result += f"   └─ Weight: {api.get('weight', 1):.1f}\n\n"
        
        return result
    
    async def close(self):
        """Close HTTP session"""
        if self.session:
            await self.session.aclose()
            self.session = None


