def format_proxy_for_paypal(proxy: str) -> Optional[str]:
    """
    Format proxy specifically for PayPal API
    Properly handles all proxy formats
    """
    if not proxy:
        return None
    
    try:
        original = proxy
        
        # Remove any existing http:// or https:// for parsing
        clean_proxy = proxy
        if clean_proxy.startswith(('http://', 'https://')):
            clean_proxy = clean_proxy.split('://', 1)[1]
        
        # ============ FIX: Handle malformed proxy with @ after port ============
        # Example: http://px173007.pointtoserver.com:10780@purevpn0s12153504:1LTpwxbCJbEdXo
        # This should be: purevpn0s12153504:1LTpwxbCJbEdXo@px173007.pointtoserver.com:10780
        
        # Check if there's an @ after a colon (malformed format)
        if '@' in clean_proxy:
            # Find the last @ in the string
            at_pos = clean_proxy.rfind('@')
            before_at = clean_proxy[:at_pos]
            after_at = clean_proxy[at_pos + 1:]
            
            # Check if before_at contains a colon (port)
            if ':' in before_at and after_at:
                # This is malformed: host:port@user:pass
                # Extract host:port from before_at
                parts = before_at.split(':')
                if len(parts) >= 2:
                    # The last part before @ might be the port
                    if parts[-1].isdigit():
                        # Format: host:port@user:pass
                        host = ':'.join(parts[:-1])
                        port = parts[-1]
                        # after_at should be user:pass
                        if ':' in after_at:
                            user, password = after_at.split(':', 1)
                            # Reconstruct correctly: user:pass@host:port
                            formatted = f"http://{user}:{password}@{host}:{port}"
                            print(f"✅ [PayPal Proxy] Fixed malformed proxy: {mask_proxy(formatted)}")
                            return formatted
                        else:
                            # after_at is just user? Try to parse differently
                            user = after_at
                            if ':' in before_at:
                                password = before_at.split('@')[0] if '@' in before_at else ''
                            else:
                                password = ''
                            if password:
                                formatted = f"http://{user}:{password}@{host}:{port}"
                                return formatted
        
        # Format 1: host:port:user:pass
        parts = clean_proxy.split(':')
        if len(parts) == 4:
            # Check if second part is numeric (port) -> host:port:user:pass
            if parts[1].isdigit():
                host, port, user, password = parts
                formatted = f"http://{user}:{password}@{host}:{port}"
                print(f"✅ [PayPal Proxy] Formatted host:port:user:pass -> {mask_proxy(formatted)}")
                return formatted
            # Check if fourth part is numeric (port) -> user:pass:host:port
            elif parts[3].isdigit():
                user, password, host, port = parts
                formatted = f"http://{user}:{password}@{host}:{port}"
                print(f"✅ [PayPal Proxy] Formatted user:pass:host:port -> {mask_proxy(formatted)}")
                return formatted
        
        # Format 2: user:pass@host:port
        if '@' in clean_proxy:
            # Check if we have a valid user:pass@host:port format
            auth, hostport = clean_proxy.split('@', 1)
            if ':' in auth and ':' in hostport:
                # Already correct format, just add http:// if needed
                if not clean_proxy.startswith(('http://', 'https://')):
                    formatted = f"http://{clean_proxy}"
                else:
                    formatted = clean_proxy
                print(f"✅ [PayPal Proxy] Using as-is: {mask_proxy(formatted)}")
                return formatted
        
        # Format 3: host:port only
        if len(parts) == 2 and parts[1].isdigit():
            formatted = f"http://{clean_proxy}"
            print(f"✅ [PayPal Proxy] Formatted host:port -> {mask_proxy(formatted)}")
            return formatted
        
        # Format 4: Try to detect if it's ip:port:user:pass but with non-numeric port detection
        if len(parts) >= 4:
            # Try to find which part is the port (should be numeric)
            port_index = -1
            for i, part in enumerate(parts):
                if part.isdigit() and len(part) <= 5 and 1 <= int(part) <= 65535:
                    port_index = i
                    break
            
            if port_index != -1:
                # Found a port number
                if port_index == 1:
                    # Format: host:port:user:pass
                    host = parts[0]
                    port = parts[1]
                    user = parts[2] if len(parts) > 2 else ''
                    password = parts[3] if len(parts) > 3 else ''
                    if user and password:
                        formatted = f"http://{user}:{password}@{host}:{port}"
                        return formatted
                elif port_index == 3:
                    # Format: user:pass:host:port
                    user = parts[0]
                    password = parts[1]
                    host = parts[2]
                    port = parts[3]
                    if user and password:
                        formatted = f"http://{user}:{password}@{host}:{port}"
                        return formatted
        
        # If already has http://
        if proxy.startswith(('http://', 'https://')):
            print(f"✅ [PayPal Proxy] Using as-is: {mask_proxy(proxy)}")
            return proxy
        
        print(f"⚠️ [PayPal Proxy] Could not parse: {original[:50]}...")
        return None
        
    except Exception as e:
        print(f"⚠️ [PayPal Proxy] Error formatting: {e}")
        return None

async def parse_paypal_response(response_json: dict, elapsed: float, proxy: str = None) -> Dict:
    """Parse PayPal API response with proper field handling - FULL CODE"""
    
    # Default result
    default_result = {
        "status": "error",
        "result": "UNKNOWN_ERROR",
        "message": "Unknown error occurred",
        "status_display": "⚠️ ERROR",
        "status_category": "error",
        "elapsed": elapsed,
        "proxy_used": proxy,
        "retryable": False
    }
    
    if not response_json or not isinstance(response_json, dict):
        return default_result
    
    # ============ EXTRACT RESPONSE FIELDS ============
    result_text = response_json.get('result', '')
    status_text = response_json.get('status', '')
    code_text = response_json.get('code', '')
    message_text = response_json.get('message', '')
    response_data = response_json.get('response', {})
    
    # Handle nested response
    if isinstance(response_data, dict):
        result_text = response_data.get('result', result_text)
        status_text = response_data.get('status', status_text)
        message_text = response_data.get('message', message_text)
    
    result_upper = str(result_text).upper()
    status_upper = str(status_text).upper()
    code_upper = str(code_text).upper()
    message_upper = str(message_text).upper()
    
    # Combine all text for checking
    full_response = f"{result_upper} {status_upper} {code_upper} {message_upper}"
    
    print(f"📊 [PayPal Parse] Full response: {full_response[:200]}")
    
    # ============ CHECK FOR CHARGED/SUCCESS RESPONSES (HIGHEST PRIORITY) ============
    charged_patterns = [
        "CHARGED",  "APPROVED - AVS",
         "TRANSACTION_COMPLETED", "CAPTURED",
        "CHARGE 2$", "2$", 
    ]
    
    for pattern in charged_patterns:
        if pattern in full_response:
            # Extract amount if available
            amount_match = re.search(r'\$?(\d+\.?\d*)', full_response)
            amount_text = f" ${amount_match.group(1)}" if amount_match else ""
            
            print(f"🔥 [PAYPAL] CHARGED detected: {pattern}")
            return {
                "status": "success",
                "result": "CHARGED",
                "message": f"CHARGED 0.1",
                "status_display": "🔥 CHARGED ",
                "status_category": "charged",
                "elapsed": elapsed,
                "proxy_used": proxy,
                "retryable": False,
                "code": pattern
            }
    
    # ============ CHECK FOR APPROVED/LIVE RESPONSES ============
    approved_patterns = [
         "APPROVED CCN", 
        
        "CVV LIVE", "CVV_VERIFIED", "CARD_VERIFICATION_SUCCESSFUL",
        "AUTHENTICATION_SUCCESSFUL", "PAYMENT_METHOD_ADDED",
        "CARD_VALID", "LIVE CARD"
    ]
    
    for pattern in approved_patterns:
        if pattern in full_response:
            # Check if it's EXISTING_ACCOUNT_RESTRICTED - this is LIVE
            if "EXISTING_ACCOUNT_RESTRICTED" in full_response:
                print(f"✅ [PAYPAL] EXISTING_ACCOUNT_RESTRICTED detected - Card is LIVE!")
                return {
                    "status": "success",
                    "result": "EXISTING_ACCOUNT_RESTRICTED",
                    "message": "EXISTING ACCOUNT RESTRICTED - Card is LIVE",
                    "status_display": "✅ CVV LIVE",
                    "status_category": "declined",
                    "elapsed": elapsed,
                    "proxy_used": proxy,
                    "retryable": False,
                    "code": "EXISTING_ACCOUNT_RESTRICTED"
                }
            
            # Check for RISK_DISALLOWED - also LIVE
            elif "RISK_DISALLOWED" in full_response:
                print(f"✅ [PAYPAL] RISK_DISALLOWED detected - Card is LIVE!")
                return {
                    "status": "success",
                    "result": "RISK_DISALLOWED",
                    "message": "RISK DISALLOWED - Card is LIVE",
                    "status_display": "✅ CVV LIVE",
                    "status_category": "declined",
                    "elapsed": elapsed,
                    "proxy_used": proxy,
                    "retryable": False,
                    "code": "RISK_DISALLOWED"
                }
            
            
    
    # ============ CHECK FOR INSUFFICIENT FUNDS ============
    insufficient_patterns = [
        "INSUFFICIENT_FUNDS", "INSUFFICIENT FUNDS", "INSUFFICIENT",
        "FUNDS", "BALANCE", "NOT ENOUGH FUNDS", "LOW BALANCE"
    ]
    
    for pattern in insufficient_patterns:
        if pattern in full_response:
            print(f"💰 [PAYPAL] INSUFFICIENT FUNDS detected - Card is LIVE!")
            return {
                "status": "success",
                "result": "INSUFFICIENT_FUNDS",
                "message": "INSUFFICIENT FUNDS - Card has balance issue",
                "status_display": "💰 INSUFFICIENT FUNDS",
                "status_category": "approved",
                "elapsed": elapsed,
                "proxy_used": proxy,
                "retryable": False,
                "code": "INSUFFICIENT_FUNDS"
            }
    
    # ============ CHECK FOR CVV RELATED (Card is LIVE but CVV wrong) ============
    cvv_patterns = [
        "INCORRECT_CVV", "CVV_MISMATCH", "INVALID_SECURITY_CODE",
        "CVV ERROR", "SECURITY CODE", "CVC", "CVV2_FAILURE"
    ]
    
    for pattern in cvv_patterns:
        if pattern in full_response:
            print(f"✅ [PAYPAL] CVV issue detected - Card is LIVE!")
            return {
                "status": "success",
                "result": "CVV_LIVE",
                "message": "CVV ",
                "status_display": "✅ CVV LIVE",
                "status_category": "approved",
                "elapsed": elapsed,
                "proxy_used": proxy,
                "retryable": False,
                "code": "CVV_MISMATCH"
            }
    
    # ============ CHECK FOR 3D/OTP REQUIRED ============
    threeds_patterns = [
        "3D", "3DS", "THREEDS", "OTP", "SECURE", "AUTHENTICATION",
        "3D_SECURE", "REQUIRES_AUTHENTICATION", "CHALLENGE_REQUIRED"
    ]
    
    for pattern in threeds_patterns:
        if pattern in full_response:
            print(f"🔐 [PAYPAL] 3D/OTP REQUIRED detected!")
            return {
                "status": "success",
                "result": "3D_REQUIRED",
                "message": "3D Secure required - Authentication needed",
                "status_display": "🔐 3D REQUIRED",
                "status_category": "approved",
                "elapsed": elapsed,
                "proxy_used": proxy,
                "retryable": False,
                "code": "3D_REQUIRED"
            }
    
    # ============ CHECK FOR DECLINED RESPONSES ============
    declined_patterns = [
        "CARD_DECLINED", "DECLINED", "GENERIC_ERROR", "R_ERROR",
        "EXPIRED_CARD", "LOST_CARD", "STOLEN_CARD", "RESTRICTED_CARD",
        "INCORRECT_NUMBER", "DO_NOT_HONOR", "PICKUP_CARD",
        "NOT_ACCEPTED", "REJECTED", "INVALID", "UNAUTHORIZED",
        "PAYMENT_DENIED", "TRANSACTION_NOT_PERMITTED", "ISSUER_DECLINE",
        "DO_NOT_HONOR", "HARD_DECLINE", "SOFT_DECLINE"
    ]
    
    for pattern in declined_patterns:
        if pattern in full_response:
            # Skip if it's actually APPROVED (like APPROVED but with DECLINED in same string)
            if "APPROVED" in full_response and pattern == "DECLINED":
                continue
            print(f"❌ [PAYPAL] DECLINED detected: {pattern}")
            return {
                "status": "declined",
                "result": pattern,
                "message": f"{pattern} - Card declined",
                "status_display": "❌ DECLINED",
                "status_category": "declined",
                "elapsed": elapsed,
                "proxy_used": proxy,
                "retryable": False,
                "code": pattern
            }
    
    # ============ CHECK FOR CARD EXPIRED ============
    if "EXPIRED" in full_response:
        print(f"❌ [PAYPAL] EXPIRED CARD detected")
        return {
            "status": "declined",
            "result": "EXPIRED_CARD",
            "message": "Card has expired",
            "status_display": "❌ EXPIRED",
            "status_category": "declined",
            "elapsed": elapsed,
            "proxy_used": proxy,
            "retryable": False,
            "code": "EXPIRED_CARD"
        }
    
    # ============ CHECK FOR LOST/STOLEN CARD ============
    lost_stolen_patterns = ["LOST CARD", "STOLEN CARD", "LOST_OR_STOLEN"]
    for pattern in lost_stolen_patterns:
        if pattern in full_response:
            print(f"❌ [PAYPAL] LOST/STOLEN CARD detected")
            return {
                "status": "declined",
                "result": "LOST_STOLEN_CARD",
                "message": "Card reported lost or stolen",
                "status_display": "❌ LOST/STOLEN",
                "status_category": "declined",
                "elapsed": elapsed,
                "proxy_used": proxy,
                "retryable": False,
                "code": "LOST_STOLEN"
            }
    
    # ============ CHECK FOR FORMAT ERROR ============
    format_error_patterns = ["INVALID_CARD", "INVALID NUMBER", "INCORRECT NUMBER"]
    for pattern in format_error_patterns:
        if pattern in full_response:
            print(f"❌ [PAYPAL] INVALID CARD NUMBER detected")
            return {
                "status": "declined",
                "result": "INVALID_CARD_NUMBER",
                "message": "Invalid card number format",
                "status_display": "❌ INVALID CARD",
                "status_category": "declined",
                "elapsed": elapsed,
                "proxy_used": proxy,
                "retryable": False,
                "code": "INVALID_CARD"
            }
    
 
    
    # ============ CHECK FOR NO SESSION / SITE ERROR (Retryable) ============
    retryable_patterns = [
        "NO_SESSION_TOKEN", "SITE DEAD", "PROXY DEAD", "CONNECTION ERROR",
        "TIMEOUT", "INVALID_PROXY", "SESSION_EXPIRED", "RATE_LIMIT",
        "TOO_MANY_REQUESTS", "SERVICE_UNAVAILABLE", "BAD_GATEWAY"
    ]
    
    for pattern in retryable_patterns:
        if pattern in full_response:
            print(f"🔄 [PAYPAL] Retryable error detected: {pattern}")
            return {
                "status": "error",
                "result": pattern,
                "message": f"{pattern} - Retryable error",
                "status_display": "⚠️ RETRYABLE",
                "status_category": "retryable",
                "elapsed": elapsed,
                "proxy_used": proxy,
                "retryable": True,
                "code": pattern
            }
    
    # ============ DEFAULT: DECLINED ============
    print(f"❌ [PAYPAL] Unknown response - treating as DECLINED: {result_text[:100]}")
    return {
        "status": "declined",
        "result": "DECLINED",
        "message": result_text or "Card declined",
        "status_display": "❌ DECLINED",
        "status_category": "declined",
        "elapsed": elapsed,
        "proxy_used": proxy,
        "retryable": False
    }
    
    

async def make_paypal_request(card: str, amount: str = "1.00", currency: str = "USD", proxy: str = None, retry_count: int = 0, user_id: int = None) -> Dict:
    """Make PayPal request using Railway API endpoint with retry logic and proxy support"""
    
    # Default result
    default_result = {
        "status": "error",
        "result": "REQUEST_FAILED",
        "message": "Request failed to complete",
        "status_display": "⚠️ REQUEST FAILED",
        "status_category": "error",
        "elapsed": 0,
        "proxy_used": proxy,
        "retryable": True
    }
    
    print("\n" + "="*80)
    print(f"💳 [PAYPAL DEBUG] Processing card: {card[:20]}...")
    print(f"💰 [PAYPAL DEBUG] Amount: ${amount} USD")
    if retry_count > 0:
        print(f"🔄 [PAYPAL DEBUG] RETRY ATTEMPT #{retry_count}")
    
    # Get rotating proxy if not provided and user_id is available
    if not proxy and user_id:
        proxy = get_rotating_proxy_for_user(user_id, 'paypal')
    
    if proxy:
        print(f"🔌 [PAYPAL DEBUG] Using proxy: {mask_proxy(proxy)}")
    else:
        print(f"🔌 [PAYPAL DEBUG] No proxy - direct connection")
    print("="*80)
    
    # Format the proxy properly
    formatted_proxy = None
    if proxy:
        formatted_proxy = format_proxy_for_paypal(proxy)
        if formatted_proxy:
            print(f"✅ [PAYPAL DEBUG] Formatted proxy: {mask_proxy(formatted_proxy)}")
        else:
            print(f"⚠️ [PAYPAL DEBUG] Could not format proxy, falling back to direct connection")
            proxy = None
    
    try:
        headers = {
            "User-Agent": generate_user_agent(),
            "Accept": "application/json",
            "Content-Type": "application/json",
            "Accept-Language": "en-US,en;q=0.9",
            "Connection": "close",
        }
        
        payload = {
            "card": card,
            "amount": amount
        }
        
        print(f"📤 [PAYPAL DEBUG] POST Request to: {PAYPAL_API_ENDPOINT}")
        print(f"📤 [PAYPAL DEBUG] Payload: {payload}")
        
        # ============ FIXED: Progressive timeouts with retry ============
        if retry_count == 0:
            timeout_value = PAYPAL_TIMEOUT  # 90 seconds
        else:
            timeout_value = PAYPAL_TIMEOUT + 10  # 100 seconds on retry
        
        print(f"⏱️ [PAYPAL DEBUG] Timeout: {timeout_value}s")
        
        start_time = time.time()
        
        # Configure client with SHORT timeouts
        client_kwargs = {
            'timeout': httpx.Timeout(
                timeout_value, 
                connect=PAYPAL_CONNECT_TIMEOUT,  # 10 seconds
                read=timeout_value - 5
            ),
            'verify': False,
            'follow_redirects': True,
            'limits': httpx.Limits(max_keepalive_connections=0, max_connections=1)
        }
        
        # Add proxy if provided
        if formatted_proxy:
            try:
                if '@' in formatted_proxy:
                    hostport = formatted_proxy.split('@')[1]
                    if ':' in hostport:
                        host, port = hostport.split(':', 1)
                        if port.isdigit():
                            client_kwargs['proxy'] = formatted_proxy
                            print(f"🔌 [PAYPAL DEBUG] Using proxy: {mask_proxy(formatted_proxy)}")
                        else:
                            print(f"⚠️ [PAYPAL DEBUG] Invalid port, using direct connection")
                            formatted_proxy = None
                    else:
                        print(f"⚠️ [PAYPAL DEBUG] Invalid proxy format, using direct connection")
                        formatted_proxy = None
                else:
                    parts = formatted_proxy.replace('http://', '').split(':')
                    if len(parts) >= 2 and parts[1].isdigit():
                        client_kwargs['proxy'] = formatted_proxy
                        print(f"🔌 [PAYPAL DEBUG] Using proxy: {mask_proxy(formatted_proxy)}")
                    else:
                        print(f"⚠️ [PAYPAL DEBUG] Invalid proxy format, using direct connection")
                        formatted_proxy = None
            except Exception as e:
                print(f"⚠️ [PAYPAL DEBUG] Error configuring proxy: {e}")
                formatted_proxy = None
        
        # Make request with SHORT timeout
        async with httpx.AsyncClient(**client_kwargs) as client:
            response = await client.post(
                PAYPAL_API_ENDPOINT,
                headers=headers,
                json=payload
            )
        
        elapsed = time.time() - start_time
        
        print(f"📥 [PAYPAL DEBUG] Response time: {elapsed:.2f}s")
        print(f"📊 [PAYPAL DEBUG] Status code: {response.status_code}")
        
        if response.status_code == 200:
            try:
                response_json = response.json()
                print(f"✅ [PAYPAL DEBUG] Parsed JSON")
                print(f"📄 [PAYPAL DEBUG] Response content: {json.dumps(response_json, indent=2)}")
                
                if response_json is None or not isinstance(response_json, dict):
                    return default_result
                
                return await parse_paypal_response(response_json, elapsed, proxy)
                
            except json.JSONDecodeError as e:
                print(f"⚠️ [PAYPAL DEBUG] JSON parse error: {e}")
                return {
                    "status": "error",
                    "result": "JSON_ERROR",
                    "message": "Invalid JSON response",
                    "status_display": "⚠️ JSON ERROR",
                    "status_category": "error",
                    "elapsed": elapsed,
                    "proxy_used": proxy,
                    "retryable": True
                }
        else:
            print(f"⚠️ [PAYPAL DEBUG] HTTP error: {response.status_code}")
            retryable = response.status_code in [500, 502, 503, 504, 408, 429]
            return {
                "status": "error",
                "result": f"HTTP_{response.status_code}",
                "message": f"HTTP Error: {response.status_code}",
                "status_display": f"⚠️ HTTP {response.status_code}",
                "status_category": "error",
                "elapsed": elapsed,
                "proxy_used": proxy,
                "retryable": retryable
            }
            
    except httpx.TimeoutException as e:
        elapsed = time.time() - start_time if 'start_time' in locals() else 0
        print(f"⏰ [PAYPAL DEBUG] Timeout after {elapsed:.1f}s")
        
        # ============ ADDED: Retry on timeout (only once) ============
        if retry_count == 0:
            print(f"🔄 [PAYPAL DEBUG] Timeout occurred - retrying once...")
            await asyncio.sleep(2)  # Wait 2 seconds before retry
            return await make_paypal_request(card, amount, currency, proxy, retry_count=1, user_id=user_id)
        
        return {
            "status": "error",
            "result": "TIMEOUT",
            "message": "Request timeout after retry",
            "status_display": "⚠️ TIMEOUT",
            "status_category": "error",
            "elapsed": elapsed,
            "proxy_used": proxy,
            "retryable": False
        }
    except Exception as e:
        elapsed = time.time() - start_time if 'start_time' in locals() else 0
        print(f"❌ [PAYPAL DEBUG] Error: {e}")
        return {
            "status": "error",
            "result": "ERROR",
            "message": str(e)[:100],
            "status_display": "⚠️ ERROR",
            "status_category": "error",
            "elapsed": elapsed,
            "proxy_used": proxy,
            "retryable": True
        }
        



# Updated check_card_paypal function with retry logic
async def check_card_paypal_with_pool(card: str, amount: str = "1.00", 
                                        currency: str = "USD", proxy: str = None, 
                                        user_id: int = None) -> Dict:
    """
    Check card using PayPal API Pool with automatic rotation
    """
    print(f"\n{'='*80}")
    print(f"💳 [PAYPAL API POOL] Checking card: {card[:20]}...")
    print(f"💰 Amount: ${amount} {currency}")
    if proxy:
        print(f"🔌 Using proxy: {mask_proxy(proxy)}")
    print(f"{'='*80}")
    
    # Use the pool to check the card
    result = await paypal_api_pool.check_card_with_pool(card, amount, currency, proxy, user_id)
    
    return result
    
    # ============ FIXED: Only 1 attempt (no retry) for speed ============
    try:
        # Get proxy if allowed
        fresh_proxy = None
        if user_id and user_manager.can_use_proxy(user_id):
            fresh_proxy = get_rotating_proxy_for_user(user_id, 'paypal')
            print(f"🔌 [PAYPAL] Using proxy: {mask_proxy(fresh_proxy) if fresh_proxy else 'None'}")
        
        # Make the request (no retry loop)
        result = await make_paypal_request(card, amount, currency, fresh_proxy, retry_count=0, user_id=user_id)
        
        # Get status
        status = result.get("status", "error")
        
        # Mark proxy as working if we got a response (even if declined)
        if fresh_proxy and status in ["success", "declined"]:
            proxy_manager.mark_proxy_success_for_user(user_id, fresh_proxy)
            print(f"✅ [PAYPAL] Proxy working: {mask_proxy(fresh_proxy)}")
        elif fresh_proxy and status == "error":
            proxy_manager.mark_proxy_failure_for_user(user_id, fresh_proxy)
            print(f"❌ [PAYPAL] Marked proxy as failed: {mask_proxy(fresh_proxy)}")
        
        return result
        
    except Exception as e:
        print(f"❌ [PAYPAL GATEWAY] Error: {e}")
        return {
            "status": "error",
            "result": "ERROR",
            "message": str(e)[:100],
            "status_display": "⚠️ ERROR",
            "status_category": "error",
            "retryable": False
        }

def format_paypal_response_stylish(result: Dict, card: str, bin_info: tuple, amount: str) -> Tuple[str, str]:
    """Format PayPal response with PREMIUM EMOJIS - Like Shopify Gateway"""
    bin_info_text, bank, country, currency_code, country_code = bin_info
    
    status_category = result.get("status_category", "unknown")
    result_text = result.get("result", "UNKNOWN")
    message = result.get("message", "Unknown")
    code = result.get("code", "")
    elapsed = result.get("elapsed", 0)
    
    # Parse card parts
    card_parts = card.split('|')
