# ============ HELPER FUNCTIONS FOR CARD EXTRACTION ============

def extract_card_from_args(update: Update, context: ContextTypes.DEFAULT_TYPE) -> str:
    """Extract single card from command arguments"""
    if not context.args:
        return None
    card_text = " ".join(context.args).strip()
    return card_formatter.extract_single_card_from_text(card_text)


def extract_cards_from_args(update: Update, context: ContextTypes.DEFAULT_TYPE) -> list:
    """Extract multiple cards from command arguments"""
    if not context.args:
        return []
    
    cards_text = " ".join(context.args)
    card_strings = cards_text.split()
    
    cards = []
    for card_str in card_strings:
        card = card_formatter.extract_single_card_from_text(card_str)
        if card:
            cards.append(card)
    
    return cards


