async def off_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Turn off a gateway - /off <gateway>"""
    if update.effective_user.id != OWNER_ID:
        await update.message.reply_text("❌ Admin only command.")
        return
    
    if not context.args:
        await update.message.reply_text(
            "🔴 <b>Turn Off Gateway</b>\n\n"
            "Usage: <code>/off &lt;gateway&gt;</code>\n"
            "Example: <code>/off aumc</code>\n"
            "Example: <code>/off paypal</code>\n"
            "Example: <code>/off all</code> - Turn off ALL gateways\n\n"
            "Use <code>/gateways</code> to see all gateways.",
            parse_mode=ParseMode.HTML
        )
        return
    
    gateway = context.args[0].lower()
    
    # Handle "all" special case
    if gateway == "all":
        count = 0
        for gw in gateway_manager.gateways:
            if gateway_manager.set_status(gw, False):
                count += 1
        
        await update.message.reply_text(
            f"🔴 <b>All Gateways Turned OFF</b>\n\n"
            f"✅ {count} gateways disabled.\n\n"
            f"Use <code>/on all</code> to turn them back on.",
            parse_mode=ParseMode.HTML,
            reply_markup=back_menu()
        )
        return
    
    # Turn off specific gateway
    if gateway_manager.set_status(gateway, False):
        enabled, name, emoji = gateway_manager.get_status(gateway)
        await update.message.reply_text(
            f"🔴 <b>Gateway Turned OFF</b>\n\n"
            f"{emoji} <code>{gateway}</code> ({name}) is now <b>DISABLED</b>.\n\n"
            f"Users will see: 🚧 Gate under maintenance.\n\n"
            f"Use <code>/on {gateway}</code> to turn it back on.",
            parse_mode=ParseMode.HTML,
            reply_markup=back_menu()
        )
    else:
        await update.message.reply_text(
            f"❌ Unknown gateway: <code>{gateway}</code>\n\n"
            f"Use <code>/gateways</code> to see available gateways.",
            parse_mode=ParseMode.HTML
        )


