async def auto_detect_reply_with_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Automatically detect when a user replies to a card with ANY command
    and start checking immediately without needing to type the command again
    """
    user_id = update.effective_user.id
    message = update.effective_message
    
    # Check if this is a reply
    if not message.reply_to_message:
        return False
    
    # Get the command from the message text
    command_text = message.text.strip().lower()
    
    # Extract just the command (first word)
    command_parts = command_text.split()
    if not command_parts:
        return False
    
    command = command_parts[0]
    
    # Check if the user has a pending file
    if user_id in pending_files:
        # Let the file handler process it
        return False
    
    # Get the replied message content (should contain card)
    replied_msg = message.reply_to_message
    card_text = replied_msg.text or replied_msg.caption or ""
    
    # Extract card from the replied message
    card = card_formatter.extract_single_card_from_text(card_text)
    
    if not card:
        # No card found in replied message
        return False
    
    print(f"🎯 [AUTO-DETECT] User {user_id} replied with command '{command}' to card: {card[:20]}...")
    
    # Map common commands to gateways
    gateway_map = {
        # PayPal
        '/pp': ('paypal', False),
        '/paypal': ('paypal', False),
        
        # Shopify / Autosopi
        '/sh': ('shopify', False),
        '/shopify': ('shopify', False),
        '/auc': ('autosopi', False),
        '/autosopi': ('autosopi', False),
        
        # Stripe Charge
        '/sc': ('stripe_charge_v2', False),
        '/stripe': ('stripe_charge_v2', False),
        '/stc': ('stripe_charge', False),
        
        # Stripe Auth
        '/sta': ('stripe_auth', False),
        
        # Razorpay
        '/rz': ('razorpay', False),
        '/mrz': ('razorpay', True),
        
        # Braintree
        '/btn': ('braintree', False),
        
        # B3Charged
        '/b3': ('b3charged', False),
        
        # Payflow
        '/pf': ('payflow', False),
        
        # Adyen
        '/ad': ('adyen', False),
        
        # Auto Stripe
        '/chk': ('auto_stripe', False),
        
        # New Stripe
        '/nstripe': ('new_stripe', False),
        
        # Mass check commands (if user replies with mass command)
        '/mpp': ('paypal', True),
        '/aumc': ('autosopi', True),
        '/msh': ('shopify', True),
        '/msc': ('stripe_charge_v2', True),
        '/mrz': ('razorpay', True),
        '/mb3': ('b3charged', True),
        '/btnm': ('braintree', True),
        '/pfmc': ('payflow', True),
        '/mad': ('adyen', True),
        '/mchk': ('auto_stripe', True),
        '/mstc': ('stripe_charge', True),
    }
    
    if command not in gateway_map:
        # Unknown command, let normal handler process
        return False
    
    gateway, is_mass = gateway_map[command]
    
    # Check if user can access gateway
    if not user_manager.can_access_gateway(user_id, gateway):
        await message.reply_text(
            f" USE /buy TO UPGRADE YOUR TIER 💎\n"
        
        )
        await message.reply_text(error_message, parse_mode=ParseMode.HTML)
        add_user_credits(u_id, 1)
        return
    
    # For single check
    if not is_mass:
        # Check credits first
        can_proceed, error_msg = await check_and_deduct_credits(user_id, update, context, is_mass_check=False, card_count=1)
        if not can_proceed:
            await message.reply_text(error_msg, parse_mode=ParseMode.HTML)
            return True
        
        # Delete the command message to keep chat clean
        try:
            await message.delete()
        except:
            pass
        
        # Start the appropriate single check
        if gateway == 'paypal':
            await single_check_paypal_with_gif(update, context, card)
        elif gateway == 'shopify':
            await single_check_shopify_pool(update, context, card)
        elif gateway == 'autosopi':
            await autosopi_single_check_logic(update, context, card)
        elif gateway == 'stripe_charge_v2':
            await single_check_stripe_charge_v2(update, context)
        elif gateway == 'stripe_charge':
            await stripe_charge_single_check_logic(update, context, card)
        elif gateway == 'stripe_auth':
            await stripe_auth_single_check_logic(update, context, card)
        elif gateway == 'razorpay':
            await single_check_razorpay(update, context)
        elif gateway == 'braintree':
            await single_check_braintree_advanced(update, context)
        elif gateway == 'b3charged':
            await b3charged_single_check_logic(update, context, card)
        elif gateway == 'payflow':
            await payflow_single_check_logic(update, context, card)
        elif gateway == 'adyen':
            await adyen_direct_single_check_logic(update, context, card)
        elif gateway == 'auto_stripe':
            await single_check_auto_stripe(update, context)
        elif gateway == 'new_stripe':
            await single_check_new_stripe(update, context)
             
        return True
    
    # For mass check (if user replies with mass command and multiple cards in replied message)
    else:
        # Extract all cards from the replied message
        cards_text = replied_msg.text or replied_msg.caption or ""
        lines = cards_text.strip().split('\n')
        
        cards = []
        for line in lines:
            line = line.strip()
            if line and not line.startswith('#'):
                card = card_formatter.extract_single_card_from_text(line)
                if card:
                    cards.append(card)
        
        if not cards:
            await message.reply_text("❌ No valid cards found in the replied message.")
            return True
        
        # Check batch size limit
        max_batch = user_manager.get_max_batch_size(user_id)
        if len(cards) > max_batch:
            cards = cards[:max_batch]
            await message.reply_text(f"⚠️ Truncated to {max_batch} cards (your tier limit)")
        
        # Check credits for mass check
        can_proceed, error_msg = await check_and_deduct_mass_credits(user_id, update, context, len(cards))
        if not can_proceed:
            await message.reply_text(error_msg, parse_mode=ParseMode.HTML)
            return True
        
        # Delete the command message
        try:
            await message.delete()
        except:
            pass
        
        # Create progress message
        fire_emoji = premium_emoji(PREMIUM_EMOJI_IDS["charged"], "🔥")
        time_emoji = premium_emoji(PREMIUM_EMOJI_IDS["time"], "🔄")
        card_emoji = premium_emoji(PREMIUM_EMOJI_IDS["card"], "💳")
        
        progress_msg = await update.message.reply_text(
            f"{fire_emoji} <b>Processing {len(cards)} cards from reply</b>\n\n"
            f"{card_emoji} <b>Gateway:</b> {gateway.upper()}\n"
            f"{time_emoji} <b>Starting...</b>",
            parse_mode=ParseMode.HTML,
            reply_markup=create_progress_buttons(0, len(cards), 0, 0, "", "Starting...")
        )
        
        # Start the appropriate mass check
        if gateway == 'paypal':
            asyncio.create_task(mass_check_logic(update, context, cards))
        elif gateway == 'autosopi':
            asyncio.create_task(autosopi_mass_check_logic(update, context, cards, progress_msg))
        elif gateway == 'shopify':
            asyncio.create_task(shopify_mass_check_logic(update, context, cards))
        elif gateway == 'stripe_charge_v2':
            asyncio.create_task(stripe_charge_v2_mass_check_logic(update, context, cards))
        elif gateway == 'razorpay':
            asyncio.create_task(razorpay_mass_check_logic(update, context, cards))
        elif gateway == 'b3charged':
            asyncio.create_task(b3charged_mass_check_logic(update, context, cards))
        elif gateway == 'braintree':
            asyncio.create_task(mass_check_braintree_advanced_logic(update, context, cards))
        elif gateway == 'payflow':
            asyncio.create_task(payflow_mass_check_logic(update, context, cards))
        elif gateway == 'adyen':
            asyncio.create_task(adyen_direct_mass_check_logic(update, context, cards))
        elif gateway == 'auto_stripe':
            asyncio.create_task(auto_stripe_mass_check_with_pool(update, context, cards, None))
        
        return True
    
    return False

# ============ USER MANAGEMENT SYSTEM (UPDATED WITH CREDITS) ============

