async def get_checkout_attempt_id_adyen() -> str:
    """Get checkout attempt ID from Adyen"""
    try:
        headers = {"Content-Type": "application/json"}
        payload = {
            "version": "6.12.0",
            "channel": "Web",
            "platform": "Web",
            "buildType": "esm",
            "locale": "en-US",
            "referrer": ADYEN_GIFT_URL,
            "screenWidth": 1920,
            "containerWidth": 0,
            "component": "scheme",
            "flavor": "components",
            "level": "all"
        }
        
        async with httpx.AsyncClient(timeout=10.0, verify=False) as client:
            response = await client.post(
                ADYEN_CHECKOUT_URL,
                params={"clientKey": ADYEN_CLIENT_KEY},
                json=payload,
                headers=headers
            )
            
            if response.status_code == 200:
                result = response.json()
                if isinstance(result, dict):
                    if 'checkoutAttemptId' in result:
                        return result['checkoutAttemptId']
                    elif 'id' in result:
                        return result['id']
    except Exception as e:
        print(f"⚠️ [ADYEN] Checkout attempt ID error: {e}")
    
    # Fallback
    return str(uuid.uuid4()) + str(int(time.time() * 1000)) + "C1DCEF21E46D212F48F5B8517E50932C590D7B5E0EF3A3977CB31686F71049F0"[:32]


async def extract_access_token_adyen(html_content: str) -> str:
    """Extract access token from HTML"""
    pattern = r'"refreshTokenResJson":\s*{\s*"response":\s*{\s*"access_token":\s*"([^"]+)"'
    match = re.search(pattern, html_content)
    
    if match:
        return match.group(1)
    
    pattern2 = r'access_token":"([^"]+)"'
    match = re.search(pattern2, html_content)
    
    if match:
        return match.group(1)
    
    return None


async def refresh_token_adyen() -> str:
    """Refresh Adyen access token"""
    headers = {
        'accept': '*/*',
        'accept-language': 'en-US,en;q=0.9',
        'user-agent': generate_user_agent(),
    }
    
    try:
        async with httpx.AsyncClient(timeout=10.0, verify=False) as client:
            response = await client.get(ADYEN_GIFT_URL, headers=headers)
            
            if response.status_code == 200:
                access_token = await extract_access_token_adyen(response.text)
                if access_token:
                    return access_token
    except Exception as e:
        print(f"⚠️ [ADYEN] Token refresh error: {e}")
    
    return None


