    if pending.get("payment_id") != payment_id:
        await update.message.reply_text(
            f"❌ Payment ID mismatch.\n"
            f"Expected: <code>{pending.get('payment_id')}</code>",
            parse_mode=ParseMode.HTML
        )
        return
    
    username = pending.get("username", "Unknown")
    plan_name = pending.get("plan_name", "Unknown")
    
    # Remove pending payment
