async def feedback_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Send feedback with ANY media to feedback group - /fb or /feedback (reply to any message)
    """
    
    user_id = update.effective_user.id
    user = update.effective_user
    message = update.effective_message
    
    print(f"🔍 [FEEDBACK DEBUG] /feedback command received from user {user_id}")
    print(f"🔍 [FEEDBACK DEBUG] Message text: {message.text}")
    print(f"🔍 [FEEDBACK DEBUG] Has reply_to_message: {message.reply_to_message is not None}")
    
    # Check if user is replying to a message
    if not message.reply_to_message:
        await message.reply_text(
            "📝 <b>Feedback System</b>\n\n"
            "Usage: Reply to ANY message with <code>/feedback</code> or <code>/fb</code>\n\n"
            "Examples:\n"
            "• Send a photo, then reply with /feedback\n"
            "• Send a text message, then reply with /feedback\n"
            "• Send a file/video, then reply with /feedback\n\n"
            "Your feedback will be sent to the admin team.",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Send "processing" message
    processing_msg = await message.reply_text("📤 Sending your feedback to admin...")
    
    # Get the replied message
    replied_msg = message.reply_to_message
    
    print(f"🔍 [FEEDBACK DEBUG] Replied message type: {type(replied_msg).__name__}")
    print(f"🔍 [FEEDBACK DEBUG] Replied message has photo: {replied_msg.photo is not None}")
    print(f"🔍 [FEEDBACK DEBUG] Replied message has text: {replied_msg.text is not None}")
    print(f"🔍 [FEEDBACK DEBUG] Replied message has caption: {replied_msg.caption is not None}")
    
    # Get any extra text from the command (after /feedback or /fb)
    command_text = message.text
    user_extra_text = ""
