# ============ ROUTE FEEDBACK COMMANDS PROPERLY ============
# Add this function to handle feedback commands before other handlers

async def feedback_router(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Route feedback commands to the correct handler
    This ensures /feedback and /fb work even when replying to messages
    """
    message = update.effective_message
    if not message or not message.text:
        return False
    
    text = message.text.lower().strip()
    
    # Check if it's a feedback command
    if text.startswith('/feedback') or text.startswith('/fb'):
        print(f"🔄 [FEEDBACK ROUTER] Routing feedback command: {text}")
        await feedback_command(update, context)
        return True
    
    return False


