async def autosopi_sites_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show Autosopi sites count and status - /sites"""
    if not await verify_group_access(update, context):
        return
    
    user_id = update.effective_user.id
    
    if not user_manager.can_access_gateway(user_id, 'autosopi'):
        await update.message.reply_text("❌ Your tier doesn't have access to Autosopi gateway.")
        return
    
    sites = autosopi_site_manager.sites
    failures = autosopi_site_manager.site_failures
    
    if not sites:
        await update.message.reply_text(
            f"📋 <b>No sites available for rotation.</b>\n\n"
            f"Use /submitsite to add sites or wait for admin to add them.",
            parse_mode=ParseMode.HTML,
            reply_markup=back_menu()
        )
        return
    
    # Count sites by status
    healthy_sites = 0
    warning_sites = 0
    dead_sites = 0
    
    for site in sites:
        fail_count = failures.get(site, 0)
        if fail_count >= 3:
            dead_sites += 1
        elif fail_count > 0:
            warning_sites += 1
        else:
            healthy_sites += 1
    
    msg = (
        f"🌐 <b>Autosopi Sites Status</b>\n\n"
        f"━━━━━━━━━━━━━━━━━━━\n"
        f"📊 <b>Total Sites:</b> {len(sites)}\n"
        f"✅ <b>Healthy:</b> {healthy_sites}\n"
        f"⚠️ <b>Warning:</b> {warning_sites}\n"
        f"💀 <b>Dead:</b> {dead_sites}\n"
        f"━━━━━━━━━━━━━━━━━━━"
    )
    
    await update.message.reply_text(msg, parse_mode=ParseMode.HTML, reply_markup=back_menu())
    
