def approve_site(self, site: str, admin_id: int) -> Tuple[bool, str]:
    """Approve a pending site (admin only)"""
    if admin_id != OWNER_ID:
        return False, "❌ Only owner can approve sites"
    
    for pending in self.pending_sites[:]:
        if (pending['site'] == site or 
            site in pending['site'] or 
            pending['original_site'] == site or
            pending['site'] in site):
            
            if pending['site'] not in self.sites:
                self.sites.append(pending['site'])
                self.site_stats[pending['site']] = {
                    'successes': 0,
                    'failures': 0,
                    'total': 0,
                    'added_by': pending['user_id'],
                    'added_at': time.time(),
                    'added_by_name': pending['user_name']
                }
            
            self.pending_sites.remove(pending)
            self.save_sites()
            self.save_pending_sites()
            self.reset_rotation()
            return True, f"✅ Site approved and added to rotation: {pending['site']}"
    
    return False, "❌ Site not found in pending list"

def reject_site(self, site: str, admin_id: int, reason: str = "") -> Tuple[bool, str]:
    """Reject a pending site (admin only)"""
    if admin_id != OWNER_ID:
        return False, "❌ Only owner can reject sites"
    
    for pending in self.pending_sites[:]:
        if (pending['site'] == site or 
            site in pending['site'] or 
            pending['original_site'] == site):
            
            self.pending_sites.remove(pending)
            self.save_pending_sites()
            msg = f"❌ Site rejected: {pending['site']}"
            if reason:
                msg += f"\nReason: {reason}"
            return True, msg
    
    return False, "❌ Site not found in pending list"

def list_pending_sites(self) -> str:
    """Get formatted list of pending sites"""
    if not self.pending_sites:
        return "⏳ No pending site submissions"
    
    result = "⏳ <b>Pending Site Submissions:</b>\n\n"
    for i, pending in enumerate(self.pending_sites, 1):
        submitted = datetime.fromtimestamp(pending['submitted_at']).strftime("%Y-%m-%d %H:%M")
        result += f"{i}. <code>{pending['site']}</code>\n"
        result += f"   👤 Submitted by: {pending['user_name']} (ID: {pending['user_id']})\n"
        result += f"   📅 {submitted}\n\n"
    
    return result

def test_all_sites_parallel(self) -> dict:
    """Test all sites in parallel"""
    # This is a placeholder - you'll need to implement actual testing
    results = {}
    for site in self.sites:
        results[site] = (True, "Site working")
    return results


async def process_single_site(site: str, user_id: int, user_name: str, can_add_directly: bool, user_proxies: list, working: list, cheap_sites: list, failed: list, no_cheap_products: list, timeout_sites: list) -> dict:
    """Process a single site - runs in parallel for batch processing"""
    
    # Get a random proxy for this site (rotate through available proxies)
    current_proxy = None
    if user_proxies:
        current_proxy = random.choice(user_proxies)
        print(f"🔍 Checking site with proxy: {mask_proxy(current_proxy)}")
    
    # Step 1: Check accessibility with proxy
    try:
        is_working, test_msg = await test_site_with_proxy(site, current_proxy, timeout=10)
    except Exception as e:
        print(f"⏰ Site timeout: {site}")
        return {'site': site, 'timeout': True}
    
    if not is_working:
        print(f"❌ Site failed: {site} - {test_msg}")
        return {'site': site, 'failed': True}
    
    # Step 2: Check for cheap products (UNDER $10) with proxy
    try:
        has_cheap, prices, price_msg = await check_site_product_prices_with_proxy(site, current_proxy, timeout=15, max_price=10)
    except asyncio.TimeoutError:
        print(f"⏰ Site timeout (price check): {site}")
        return {'site': site, 'timeout': True}
    
    if not has_cheap:
        print(f"💰 No products under $10: {site}")
        return {'site': site, 'no_cheap': True}
    
    # Add the site if it has cheap products (under $10)
    success, result_msg = autosopi_site_manager.add_site(
        site, user_id, user_name, bypass_pending=can_add_directly
    )
    if success and can_add_directly:
        user_manager.increment_sites_added(user_id)
        print(f"✅ Site added: {site} (products under $10)")
        return {'site': site, 'added': True}
    else:
        print(f"❌ Site add failed: {site}")
        return {'site': site, 'failed': True}


async def check_site_product_prices_with_proxy(site_url: str, proxy: str = None, timeout: int = 15, max_price: float = 1) -> Tuple[bool, List[float], str]:
    """
    Check if site has products under max_price (default $1 - changed from $10)
    """
    try:
        # Normalize URL
        if not site_url.startswith(('http://', 'https://')):
            full_url = f"https://{site_url}"
        else:
            full_url = site_url
        
        # Configure client with proxy
        client_kwargs = {
            'timeout': httpx.Timeout(timeout, connect=8.0, read=12.0),
            'verify': False,
            'follow_redirects': True
        }
        
        if proxy:
            proxy_url = format_proxy(proxy)
            if proxy_url:
                client_kwargs['proxy'] = proxy_url
        
        async with httpx.AsyncClient(**client_kwargs) as client:
            response = await client.get(full_url, headers={
                'User-Agent': generate_user_agent()
            })
            
            if response.status_code != 200:
                return False, [], f"Failed to load site: HTTP {response.status_code}"
            
            html = response.text
            soup = BeautifulSoup(html, 'html.parser')
            
            # Price patterns
            price_patterns = [
                r'\$\d+\.?\d{0,2}',
                r'(\d+\.?\d{0,2})\s?USD',
                r'price["\']?\s*[=:]\s*["\']?(\d+\.?\d{0,2})',
                r'product-price["\']?\s*[=:]\s*["\']?\$?(\d+\.?\d{0,2})',
            ]
            
            all_prices = []
            
            # Check for Shopify product data
            if 'myshopify.com' in full_url or 'shopify' in html.lower():
                product_pattern = r'product":\s*({[^}]+})'
                product_matches = re.findall(product_pattern, html)
                
                for match in product_matches:
                    variant_pattern = r'"price":\s*"?(\d+\.?\d{0,2})"?' 
                    prices = re.findall(variant_pattern, match)
                    for p in prices:
                        try:
                            price_val = float(p)
                            if 0.50 < price_val < 500:
                                all_prices.append(price_val)
                        except:
                            pass
            
            # If no Shopify data, look for price tags
            if not all_prices:
                price_elements = soup.find_all(['span', 'div', 'p', 'meta'], 
                    attrs={'class': re.compile(r'price|product-price|sale-price|current-price', re.I)})
                
                for elem in price_elements:
                    text = elem.get_text()
                    for pattern in price_patterns:
                        matches = re.findall(pattern, text)
                        for match in matches:
                            if isinstance(match, tuple):
                                match = match[0]
                            clean_num = re.sub(r'[^\d.]', '', str(match))
                            try:
                                price_val = float(clean_num)
                                if 0.50 < price_val < 500:
                                    all_prices.append(price_val)
                            except:
                                pass
            
            all_prices = sorted(list(set(all_prices)))
            
            # ============ CHANGED: Check for products under max_price (default $1) ============
            cheap_prices = [p for p in all_prices if p < max_price]
            
            if cheap_prices:
                cheap_products = len(cheap_prices)
                lowest_price = min(cheap_prices)
                print(f"✅ Site has {cheap_products} products under ${max_price} (lowest: ${lowest_price:.2f})")
                return True, cheap_prices, f"✅ Has products under ${max_price}! Found {cheap_products} products. Lowest: ${lowest_price:.2f}"
            else:
                if all_prices:
                    lowest = min(all_prices)
                    print(f"⚠️ No products under ${max_price}. Lowest price: ${lowest:.2f}")
                    return False, all_prices, f"❌ No products under ${max_price}. Lowest price: ${lowest:.2f}"
                else:
                    print(f"⚠️ Could not detect prices on site")
                    return False, [], "⚠️ Could not detect product prices on this site"
                
    except httpx.TimeoutException:
        return False, [], "⏰ Site timeout"
    except Exception as e:
        print(f"❌ Error checking prices: {e}")
        return False, [], f"❌ Error: {str(e)[:50]}"

# ============ BROADCAST BACKGROUND TASK ============
async def broadcast_worker(context: ContextTypes.DEFAULT_TYPE):
    """Background task to send pending broadcasts to users"""
    broadcast = broadcast_manager.get_next_broadcast()
    if not broadcast:
        return
    
    users = user_manager.list_users()
    sent_count = 0
    
    for user in users:
        try:
            user_id = int(user["id"])
            await context.bot.send_message(
                chat_id=user_id,
                text=f"\n\n{broadcast['message']}",
                parse_mode=ParseMode.HTML
            )
            broadcast_manager.mark_sent(broadcast["id"], user_id)
            sent_count += 1
            
            await asyncio.sleep(0.05)
            
        except Exception as e:
            print(f"⚠️ Failed to send broadcast to {user_id}: {e}")
            continue
    
    broadcast_manager.complete_broadcast(broadcast["id"])
    print(f"📢 Broadcast {broadcast['id']} sent to {sent_count} users")

# ============ KEY EXPIRY CHECK BACKGROUND TASK ============
async def key_expiry_worker(context: ContextTypes.DEFAULT_TYPE):
    """Background task to check for expired keys"""
    key_manager.check_expired_keys()
    
    users = user_manager.users
    current_time = time.time()
    
    for user_id_str, user_data in users.items():
        if user_data.get("tier_expiry", 0) > 0 and current_time > user_data["tier_expiry"]:
            original_tier = user_data.get("upgraded_from", "free")
            user_data["tier"] = original_tier
            user_data["tier_expiry"] = 0
            user_data["upgraded_from"] = None
            print(f"👤 User {user_id_str} tier expired, reverted to {original_tier}")
    
    user_manager.save_users()


# ============ ACCESS CONTROL FUNCTIONS ============

async def check_and_deduct_credits(user_id: int, update: Update, context: ContextTypes.DEFAULT_TYPE, is_mass_check: bool = False, card_count: int = 1) -> Tuple[bool, str]:
    """
    Check if user has enough credits and deduct if they are free tier.
    FREE USERS: 1 credit = 1 card check
    PAID USERS: Unlimited access
    
    Returns: (success, error_message)
    """
    tier = user_manager.get_tier(user_id)
    chat = update.effective_chat
    
    # Debug print
    print(f"🔍 [CREDIT CHECK] User: {user_id}, Tier: {tier}, Chat type: {chat.type}, Is mass: {is_mass_check}, Card count: {card_count}")
    
    # Admin/Owner has unlimited access
    if user_id == OWNER_ID:
        print(f"✅ [CREDIT CHECK] Owner - unlimited access")
        return True, None
    
    # Paid users have unlimited access
    if tier in ['premium', 'ultimate', 'admin']:
        print(f"✅ [CREDIT CHECK] Paid user - unlimited access")
        return True, None
    
    # Free in group chats - SINGLE checks are FREE (no credit deduction)
    if chat.type in ['group', 'supergroup'] and not is_mass_check:
        print(f"✅ [CREDIT CHECK] Free group chat single check - no credit deduction")
        return True, None
    
    # Free user - check credits
    if tier == 'free':
        credits = get_user_credits(user_id)
        print(f"📊 [CREDIT CHECK] Free user {user_id} has {credits} credits")
        
        # Initialize credits for new users (250 free credits)
        if credits == 0 and user_id not in user_credits:
            credits = initialize_new_user_credits(user_id)
            print(f"🎉 New free user {user_id} initialized with {credits} free credits")
        
        # Calculate required credits
        required = card_count if is_mass_check else CREDITS_PER_CHECK
        
        print(f"📊 [CREDIT CHECK] Required credits: {required}")
        
        # Check if enough credits
        if credits < required:
            error_msg = (
                f"❌ <b>Insufficient Credits!</b>\n\n"
                f"🎯 Your balance: <b>{credits}</b> credits\n"
                f"💸 Cost for this check: <b>{required}</b> credit(s)\n"
                f"━━━━━━━━━━━━━━━━━━━\n\n"
                f"💎 <b>Ways to get more credits:</b>\n"
                f"├─ Use in group chats (FREE! No credits used)\n"
                f"├─ Redeem a credit key: /redeemcredits &lt;key&gt;\n"
                f"├─ Upgrade to Premium/Ultimate\n"
                f"└─ Contact @lencax\n\n"
                f"📝 <b>Commands:</b>\n"
                f"├─ /credits - Check balance\n"
                f"├─ /redeemcredits - Add credits\n"
                f"└─ /price - Upgrade\n\n"
                f"💀 <b>Bot</b> ➛ @BLADESARKS_V3bot"
            )
            print(f"❌ [CREDIT CHECK] Insufficient credits! User {user_id} has {credits}, needs {required}")
            return False, error_msg
        
        # Deduct credits
        if deduct_user_credits(user_id, required):
            new_credits = get_user_credits(user_id)
            print(f"💎 [CREDIT CHECK] User {user_id} used {required} credit(s). Remaining: {new_credits}")
            return True, None
        else:
            print(f"❌ [CREDIT CHECK] Failed to deduct credits for user {user_id}")
            return False, "❌ Failed to deduct credits. Please try again."
    
    return True, None


