def get_top_users_for_stats(self, period='alltime', limit=10) -> list:
    """Get top users for stats display"""
    self.check_reset()
    
    if period not in self.stats:
        return []
    
    data = self.stats[period]
    
    if not data:
        return []
    
    sorted_users = sorted(data.items(), key=lambda x: x[1]['hits'], reverse=True)[:limit]
    
    users = []
    medals = ['🥇', '🥈', '🥉']
    
    for i, (user_id, user_data) in enumerate(sorted_users, 1):
        medal = medals[i-1] if i <= 3 else f"{i}."
        username = user_data.get('username', f"User {user_id[:6]}")
        hits = user_data.get('hits', 0)
        
        users.append({
            'rank': medal,
            'username': username,
            'hits': hits
        })
    
    return users

