def create_order(session, payment_link_id, amount_paise, payment_page_item_id, customer_data=None):
    """Create order with proper customer data"""
    if not payment_link_id:
        logger.error("Cannot create order: payment_link_id is missing")
        return None

    url = f"https://api.razorpay.com/v1/payment_pages/{payment_link_id}/order"
    headers = {
        "Accept": "application/json",
        "Content-Type": "application/json",
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
        "Origin": "https://pages.razorpay.com",
        "Referer": "https://pages.razorpay.com/"
    }

    # Build line items
    line_items = []
    if payment_page_item_id:
        line_items.append({
            "payment_page_item_id": payment_page_item_id,
            "amount": amount_paise
        })
    else:
        line_items.append({
            "amount": amount_paise,
            "quantity": 1,
            "name": "Payment"
        })

    payload = {
        "line_items": line_items,
        "notes": {"source": "api_checker"}
    }

    # Add customer data if provided (required for this merchant)
    if customer_data:
        payload["customer"] = customer_data

    for attempt in range(3):
        try:
            resp = session.post(url, headers=headers, json=payload, timeout=20)
            
            if resp.status_code == 200:
                order_data = resp.json()
                order_id = order_data.get("order", {}).get("id")
                if order_id:
                    logger.info(f"Order created successfully: {order_id}")
                    return order_id
                else:
                    logger.warning(f"Order created but no ID found: {order_data}")
                    # Try alternative response format
                    if order_data.get("id"):
                        return order_data.get("id")
            elif resp.status_code == 404:
                logger.error(f"Payment link not found (404): {payment_link_id}")
                return None
            elif resp.status_code == 400:
                error_data = resp.json()
                logger.error(f"Bad request (400): {error_data}")
                # Check if it's a validation error
                if "customer" in str(error_data):
                    # Need customer data
                    logger.info("Order requires customer data, retrying with customer info...")
                    if not customer_data:
                        customer_data = {
                            "name": "Test User",
                            "email": f"test{random.randint(1000,9999)}@example.com",
                            "contact": f"999999{random.randint(1000,9999)}"
                        }
                        continue
                return None
            else:
                logger.warning(f"Order creation failed with status {resp.status_code}: {resp.text[:200]}")

        except Exception as e:
            logger.error(f"Order creation attempt {attempt + 1} failed: {e}")
            if attempt < 2:
                time.sleep(2)

    return None


async def remove_normal_sites_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Remove all normal sites (sites that are NOT GOOD / have products over $10) - /rnormal"""
    
    if not await verify_group_access(update, context):
        return
    
    user_id = update.effective_user.id
    
    # Only owner/admin can use this command
    if user_id != OWNER_ID:
        await update.message.reply_text("❌ Admin only command.", reply_markup=back_menu())
        return
    
    # Get all sites
    all_sites = autosopi_site_manager.sites.copy()
    
    # Separate GOOD sites from normal sites
    good_sites = []
    normal_sites = []
    
    for site in all_sites:
        if site_quality_tracker.is_good_site(site):
            good_sites.append(site)
        else:
            normal_sites.append(site)
    
    if not normal_sites:
        await update.message.reply_text(
            f"✅ <b>No normal sites to remove!</b>\n\n"
            f"📊 Total sites: {len(all_sites)}\n"
            f"🌟 GOOD sites: {len(good_sites)}\n"
            f"📌 Normal sites: 0\n\n"
            f"All sites are already GOOD (under $10).",
            parse_mode=ParseMode.HTML,
            reply_markup=back_menu()
        )
        return
    
    # Send confirmation message
    confirm_keyboard = [
        [
            InlineKeyboardButton("✅ YES, REMOVE NORMAL SITES", callback_data='confirm_remove_normal'),
            InlineKeyboardButton("❌ CANCEL", callback_data='cancel_remove_normal')
        ]
    ]
    confirm_markup = InlineKeyboardMarkup(confirm_keyboard)
    
    # Show preview of sites to remove
    preview = ""
    for site in normal_sites[:20]:
        preview += f"  • <code>{site}</code>\n"
    if len(normal_sites) > 20:
        preview += f"  ... and {len(normal_sites) - 20} more\n"
    
    await update.message.reply_text(
        f"⚠️ <b>Remove Normal Sites</b>\n\n"
        f"📊 <b>Summary:</b>\n"
        f"   🌟 GOOD sites: {len(good_sites)} (will be KEPT)\n"
        f"   📌 Normal sites: {len(normal_sites)} (will be REMOVED)\n"
        f"   📝 Total sites: {len(all_sites)}\n\n"
        f"<b>Sites to remove ({len(normal_sites)}):</b>\n"
        f"{preview}\n"
        f"<i>⚠️ This action cannot be undone!</i>\n\n"
        f"Are you sure you want to remove all normal sites?",
        parse_mode=ParseMode.HTML,
        reply_markup=confirm_markup
    )


async def confirm_remove_normal_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Handle confirm remove normal sites callback"""
    query = update.callback_query
    await query.answer()
    
    user_id = update.effective_user.id
    
    if user_id != OWNER_ID:
        await query.edit_message_text("❌ Only the owner can remove sites.", reply_markup=back_menu())
        return
    
    if query.data == 'confirm_remove_normal':
        # Get all sites
        all_sites = autosopi_site_manager.sites.copy()
        
        # Separate GOOD sites from normal sites
        good_sites = []
        normal_sites = []
        
        for site in all_sites:
            if site_quality_tracker.is_good_site(site):
                good_sites.append(site)
            else:
                normal_sites.append(site)
        
        if not normal_sites:
            await query.edit_message_text(
                "✅ No normal sites to remove.",
                reply_markup=back_menu()
            )
            return
        
        # Remove all normal sites
        removed = []
        failed = []
        
        for site in normal_sites:
            success, result = autosopi_site_manager.remove_site(site, user_id)
            if success:
                removed.append(site)
            else:
                failed.append(site)
        
        # Reset rotation indices
        autosopi_site_manager.reset_rotation()
        
        # Prepare result message
        result_msg = f"✅ <b>Normal Sites Removed!</b>\n\n"
        result_msg += f"📊 <b>Results:</b>\n"
        result_msg += f"   ✅ Removed: {len(removed)} normal sites\n"
        result_msg += f"   ❌ Failed: {len(failed)}\n"
        result_msg += f"   🌟 GOOD sites kept: {len(good_sites)}\n"
        result_msg += f"   📝 Total sites now: {len(autosopi_site_manager.sites)}\n\n"
        
        if removed:
            result_msg += "<b>✅ Removed sites:</b>\n"
            for site in removed[:15]:
                result_msg += f"  • <code>{site}</code>\n"
            if len(removed) > 15:
                result_msg += f"  ... and {len(removed) - 15} more\n"
        
        if failed:
            result_msg += f"\n<b>❌ Failed to remove ({len(failed)}):</b>\n"
            for site in failed[:10]:
                result_msg += f"  • <code>{site}</code>\n"
        
        await query.edit_message_text(
            result_msg,
            parse_mode=ParseMode.HTML,
            reply_markup=back_menu()
        )
        
    elif query.data == 'cancel_remove_normal':
        await query.edit_message_text(
            "❌ Operation cancelled.\n\nNo sites were removed.",
            parse_mode=ParseMode.HTML,
            reply_markup=back_menu()
        )


