async def stopchk_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Terminate all ongoing checks for a user - /stopchk <user_id>
    Admin only command
    
    This will stop ALL active sessions for the specified user across all gateways.
    """
    if update.effective_user.id != OWNER_ID:
        await update.message.reply_text("❌ Admin only command.")
        return
    
    if not context.args:
        await update.message.reply_text(
            "🛑 <b>Stop All Checks</b>\n\n"
            "Usage: <code>/stopchk &lt;user_id&gt;</code>\n"
            "Example: <code>/stopchk 7062466485</code>\n\n"
            "This will terminate ALL ongoing checks for the user:\n"
            "• Mass checks\n"
            "• Single checks\n"
            "• File processing\n"
            "• All gateways (PayPal, Shopify, Razorpay, etc.)",
            parse_mode=ParseMode.HTML
        )
        return
    
    try:
        target_user_id = int(context.args[0])
    except ValueError:
        await update.message.reply_text("❌ Invalid user ID. Please provide a numeric ID.")
        return
    
    # Check if user exists
    user_data = user_manager.get_user(target_user_id)
    username = user_data.get("username", "Unknown")
    
    # ============ STOP ALL ACTIVE SESSIONS ============
    stopped_sessions = []
    
    # List of all active task dictionaries
    task_dicts = {
        "PayPal": paypal_active_tasks,
        "PayPal Mass": paypal_mass_active_tasks if 'paypal_mass_active_tasks' in globals() else {},
        "Shopify": shopify_active_tasks,
        "Razorpay": razorpay_active_tasks,
        "Razorpay2": razorpay2_active_tasks if 'razorpay2_active_tasks' in globals() else {},
        "Razorpay Gate2": razorpay_gate2_active_tasks if 'razorpay_gate2_active_tasks' in globals() else {},
        "Stripe Charge": stripe_charge_active_tasks,
        "Stripe Charge V2": stripe_charge_v2_active_tasks if 'stripe_charge_v2_active_tasks' in globals() else {},
        "Stripe Auth": stripe_auth_active_tasks,
        "Stripe Auth V2": stripe_auth_v2_active_tasks if 'stripe_auth_v2_active_tasks' in globals() else {},
        "Stripe PL": stripe_pl_active_tasks if 'stripe_pl_active_tasks' in globals() else {},
        "Braintree": braintree_active_tasks,
        "Autosopi": autosopi_active_tasks,
        "Payflow": payflow_active_tasks,
        "B3Charged": b3charged_active_tasks,
        "Adyen Direct": adyen_direct_active_tasks,
        "Auto Stripe": auto_stripe_active_tasks,
        "MSH Shopify": msh_active_tasks if 'msh_active_tasks' in globals() else {},
        "ST1": st1_active_tasks if 'st1_active_tasks' in globals() else {},
        "PayPal Donation": paypal_donation_active_tasks if 'paypal_donation_active_tasks' in globals() else {},
        "PayPal Donation 50": paypal_donation_50_active_tasks if 'paypal_donation_50_active_tasks' in globals() else {},
        "United Way": united_way_active_tasks if 'united_way_active_tasks' in globals() else {},
        "Dabbagh": dabbagh_active_tasks if 'dabbagh_active_tasks' in globals() else {},
        "Princess": princess_active_tasks if 'princess_active_tasks' in globals() else {},
        "Stripe Charger 1": stripe_charger1_active_tasks if 'stripe_charger1_active_tasks' in globals() else {},
        "Razorpay Go": razorpay_go_active_tasks if 'razorpay_go_active_tasks' in globals() else {},
        "Stripe 4USD": stripe_4usd_active_tasks if 'stripe_4usd_active_tasks' in globals() else {},
        "New Stripe": new_stripe_active_tasks if 'new_stripe_active_tasks' in globals() else {},
        "STC1": stc1_active_tasks if 'stc1_active_tasks' in globals() else {},
        "SC1": sc1_active_tasks if 'sc1_active_tasks' in globals() else {},
        "Adyen": adyen_active_tasks if 'adyen_active_tasks' in globals() else {},
    }
    
    # Stop each active task
    for gateway_name, task_dict in task_dicts.items():
        if target_user_id in task_dict:
            task_dict.pop(target_user_id, None)
            stopped_sessions.append(gateway_name)
            print(f"🛑 Stopped {gateway_name} session for user {target_user_id}")
    
    # Stop mass check if running
    if target_user_id in running_mass_checks:
        running_mass_checks.pop(target_user_id, None)
        stopped_sessions.append("Mass Check")
        print(f"🛑 Stopped mass check for user {target_user_id}")
    
    # Stop any pending file processing
    if target_user_id in pending_files:
        pending_files.pop(target_user_id, None)
        stopped_sessions.append("File Processing")
        print(f"🛑 Cancelled file processing for user {target_user_id}")
    
    # Clear speed controller to free resources
    if target_user_id in user_speed_controllers:
        user_speed_controllers.pop(target_user_id, None)
        print(f"🛑 Cleared speed controller for user {target_user_id}")
    
    # Clear any waiting states in context
    waiting_states = [
        'waiting_for_proxy', 'waiting_for_my_proxy', 'waiting_for_my_proxy_remove',
        'waiting_for_amount', 'waiting_for_razorpay_amount', 'waiting_for_razorpay_site',
        'waiting_for_autosopi_submit', 'waiting_for_autosopi_test',
        'waiting_for_autosopi_add', 'waiting_for_autosopi_remove'
    ]
    
    # Clear proxy rotation index for this user
    if target_user_id in autosopi_proxy_tracker.proxy_rotation_index:
        autosopi_proxy_tracker.proxy_rotation_index.pop(target_user_id, None)
    
    # Clear retry manager for this user
    if hasattr(autosopi_retry_manager, 'clear_user_retries'):
        autosopi_retry_manager.clear_user_retries(target_user_id)
    
    # Build response
    if stopped_sessions:
        response = (
            f"🛑 <b>All Checks Stopped!</b>\n\n"
            f"👤 <b>User:</b> {username} (<code>{target_user_id}</code>)\n"
            f"✅ <b>Stopped Sessions:</b>\n"
        )
        for session in stopped_sessions:
            response += f"   • {session}\n"
        response += f"\n<i>All ongoing checks have been terminated.</i>"
    else:
        response = (
            f"ℹ️ <b>No Active Checks Found</b>\n\n"
            f"👤 <b>User:</b> {username} (<code>{target_user_id}</code>)\n"
            f"User has no active sessions to stop."
        )
    
    await update.message.reply_text(response, parse_mode=ParseMode.HTML, reply_markup=back_menu())
    
    # Send notification to the user that their checks were stopped
    try:
        await context.bot.send_message(
            chat_id=target_user_id,
            text=(
                f"🛑 <b>Your Checks Have Been Stopped</b>\n\n"
                f"An admin has terminated all your ongoing checks.\n\n"
                f"📌 <b>Stopped:</b> {', '.join(stopped_sessions) if stopped_sessions else 'No active sessions'}\n\n"
                f"You can start new checks anytime."
            ),
            parse_mode=ParseMode.HTML
        )
        print(f"📢 Notification sent to user {target_user_id} about stopped checks")
    except Exception as e:
        print(f"⚠️ Could not notify user {target_user_id}: {e}")


async def stopchk_all_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    Terminate ALL ongoing checks for ALL users - /stopchk_all
    Admin only command - USE WITH CAUTION!
    """
    if update.effective_user.id != OWNER_ID:
        await update.message.reply_text("❌ Admin only command.")
        return
    
    # Ask for confirmation first
    keyboard = [
        [
            InlineKeyboardButton("✅ YES, STOP ALL", callback_data='confirm_stop_all'),
            InlineKeyboardButton("❌ CANCEL", callback_data='cancel_stop_all')
        ]
    ]
    reply_markup = InlineKeyboardMarkup(keyboard)
    
    # Count active sessions
    total_active = 0
