async def stop_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Stop all current sessions for the user"""
    u_id = update.effective_user.id
    message = update.effective_message
    stopped_sessions = []
    
    # List of all active task dictionaries
    task_dicts = {
        "PayPal": paypal_active_tasks,
        "Shopify": shopify_active_tasks,
        "Razorpay": razorpay_active_tasks,
        "Stripe Charge": stripe_charge_active_tasks,
        "Stripe Charge V2": stripe_charge_v2_active_tasks if 'stripe_charge_v2_active_tasks' in globals() else {},
        "Stripe Auth": stripe_auth_active_tasks,
        "Braintree": braintree_active_tasks,
        "Autosopi": autosopi_active_tasks,
        "Payflow": payflow_active_tasks,
        "B3Charged": b3charged_active_tasks,
        "Adyen Direct": adyen_direct_active_tasks,
        "Auto Stripe": auto_stripe_active_tasks,
        "MSH Shopify": msh_active_tasks if 'msh_active_tasks' in globals() else {},
    }
    
    # Stop each active task
    for gateway_name, task_dict in task_dicts.items():
        if u_id in task_dict:
            task_dict.pop(u_id, None)
            stopped_sessions.append(gateway_name)
            print(f"🛑 Stopped {gateway_name} session for user {u_id}")
    
    # Stop mass check if running
    if u_id in running_mass_checks:
        running_mass_checks.pop(u_id, None)
        stopped_sessions.append("Mass Check")
        print(f"🛑 Stopped mass check for user {u_id}")
    
    # Stop any pending file processing
    if u_id in pending_files:
        pending_files.pop(u_id, None)
        stopped_sessions.append("File Processing")
        print(f"🛑 Cancelled file processing for user {u_id}")
    
    # Clear speed controller to free resources
    if u_id in user_speed_controllers:
        user_speed_controllers.pop(u_id, None)
        print(f"🛑 Cleared speed controller for user {u_id}")
    
    # Clear any waiting proxy input states
    waiting_states = [
        'waiting_for_proxy', 'waiting_for_my_proxy', 'waiting_for_my_proxy_remove',
        'waiting_for_amount', 'waiting_for_razorpay_amount', 'waiting_for_razorpay_site',
        'waiting_for_autosopi_submit', 'waiting_for_autosopi_test',
        'waiting_for_autosopi_add', 'waiting_for_autosopi_remove'
    ]
    
    cleared_states = []
    for state in waiting_states:
        if context.user_data.get(state):
            context.user_data.pop(state, None)
            cleared_states.append(state)
    
    # Clear any pending retries for this user
    if hasattr(autosopi_retry_manager, 'clear_user_retries'):
        autosopi_retry_manager.clear_user_retries(u_id)
    
    # Reset proxy rotation index for this user
    if u_id in autosopi_proxy_tracker.proxy_rotation_index:
        autosopi_proxy_tracker.proxy_rotation_index.pop(u_id, None)
    
    # Build response message
    if stopped_sessions or cleared_states:
        msg = "🛑 <b>Session(s) Stopped Successfully!</b>\n\n"
        
        if stopped_sessions:
            msg += "<b>✅ Stopped Sessions:</b>\n"
            for session in stopped_sessions:
                msg += f"   • {session}\n"
            msg += "\n"
        
        if cleared_states:
            msg += "<b>🗑️ Cleared Waiting States:</b>\n"
            for state in cleared_states:
                msg += f"   • {state.replace('_', ' ').title()}\n"
            msg += "\n"
        
        msg += "<i>All ongoing checks have been terminated.\nYou can start new checks immediately.</i>"
    else:
        msg = "❌ <b>No active sessions found.</b>\n\n"
        msg += "You don't have any ongoing checks to stop.\n\n"
        msg += "<b>Active gateways you can stop:</b>\n"
        msg += "• /aumc - Autosopi\n"
        msg += "• /mpp - PayPal\n"
        msg += "• /msh - Shopify\n"
        msg += "• /mrz - Razorpay\n"
        msg += "• /stmc - Stripe Charge\n"
        msg += "• /sc - Stripe Charge V2\n"
        msg += "• /msc - Stripe Charge V2 Mass\n"
        msg += "• /stamc - Stripe Auth\n"
        msg += "• /btnm - Braintree\n"
        msg += "• /mb3 - B3Charged\n"
        msg += "• /pfmc - Payflow"
    
    await message.reply_text(msg, parse_mode=ParseMode.HTML, reply_markup=back_menu())

