TOP_USERS_FILE = "top_users.json"

class TopUsersManager:
    """Track and display top users by charged cards"""
    
    def __init__(self, data_file=TOP_USERS_FILE):
        self.data_file = data_file
        self.top_users = self.load_data()
        
    def load_data(self):
        """Load top users data from file"""
        if Path(self.data_file).exists():
            try:
                with open(self.data_file, 'r', encoding='utf-8') as f:
                    return json.load(f)
            except Exception as e:
                print(f"⚠️ Error loading top users: {e}")
                return {}
        return {}
    
    def save_data(self):
        """Save top users data to file"""
        try:
            with open(self.data_file, 'w', encoding='utf-8') as f:
                json.dump(self.top_users, f, indent=2)
        except Exception as e:
            print(f"⚠️ Error saving top users: {e}")
    
    def update_user(self, user_id: int, username: str, charged_count: int):
        """Update or add user to top list"""
        user_id_str = str(user_id)
        
        if user_id_str not in self.top_users:
            self.top_users[user_id_str] = {
                'username': username,
                'charged': 0,
                'last_update': time.time()
            }
        
        # Update if new count is higher
        if charged_count > self.top_users[user_id_str]['charged']:
            self.top_users[user_id_str]['charged'] = charged_count
            self.top_users[user_id_str]['username'] = username
            self.top_users[user_id_str]['last_update'] = time.time()
            self.save_data()
            return True
        return False
    
    def increment_charged(self, user_id: int, username: str):
        """Increment charged count for a user"""
        user_id_str = str(user_id)
        
        if user_id_str not in self.top_users:
            self.top_users[user_id_str] = {
                'username': username,
                'charged': 0,
                'last_update': time.time()
            }
        
        self.top_users[user_id_str]['charged'] += 1
        self.top_users[user_id_str]['username'] = username
        self.top_users[user_id_str]['last_update'] = time.time()
        self.save_data()
        return self.top_users[user_id_str]['charged']
    
    def get_top_users(self, limit: int = 10) -> list:
        """Get top users sorted by charged count"""
        users = []
        for user_id, data in self.top_users.items():
            users.append({
                'user_id': user_id,
                'username': data.get('username', 'Unknown'),
                'charged': data.get('charged', 0)
            })
        
        # Sort by charged count (highest first)
        users.sort(key=lambda x: x['charged'], reverse=True)
        return users[:limit]
    
    def get_user_rank(self, user_id: int) -> int:
        """Get rank of a specific user"""
        user_id_str = str(user_id)
        if user_id_str not in self.top_users:
            return -1
        
        charged = self.top_users[user_id_str]['charged']
        users = self.get_top_users(100)  # Get top 100
        
        for idx, user in enumerate(users, 1):
            if user['user_id'] == user_id_str:
                return idx
        return -1


# Create global instance
top_users_manager = TopUsersManager()


