@check_gateway("paypal")
async def single_check_paypal_with_pool(update: Update, context: ContextTypes.DEFAULT_TYPE, card: str):
    """Single card check with PayPal using API pool"""
    u_id = update.effective_user.id
    message = update.effective_message
    username = update.effective_user.username or update.effective_user.first_name
    
    # Check credits
    can_proceed, error_msg = await check_and_deduct_credits(u_id, update, context, is_mass_check=False, card_count=1)
    if not can_proceed:
        await message.reply_text(error_msg, parse_mode=ParseMode.HTML)
        return
    
    # Check gateway access
    if not user_manager.can_access_gateway(u_id, 'paypal'):
        tier = user_manager.get_tier(u_id)
        await message.reply_text(
            f"❌ <b>PayPal not available for {tier.upper()} tier</b>\n\n"
            f"Upgrade to Premium/Ultimate to use PayPal gateway.",
            parse_mode=ParseMode.HTML
        )
        add_user_credits(u_id, 1)
        return
    
    try:
        tier = user_manager.get_tier(u_id)
        if u_id not in user_speed_controllers:
            user_speed_controllers[u_id] = SpeedController(TIER_SPEEDS.get(tier, 900), tier)
        speed_controller = user_speed_controllers[u_id]
        
        amount = context.user_data.get('payment_amount', DEFAULT_AMOUNT)
        
        status_msg = await message.reply_text("🔄 Checking ...")
        
        await speed_controller.wait_if_needed()
        start = time.time()
        
        # Get proxy if allowed
        proxy_str = None
        if user_manager.can_use_proxy(u_id):
            if u_id in autosopi_proxy_tracker.working_proxies and autosopi_proxy_tracker.working_proxies[u_id]:
                proxy_list = autosopi_proxy_tracker.working_proxies[u_id]
                if proxy_list:
                    proxy_str = proxy_list[0]
        
        # Use the pool
        result = await check_card_paypal_with_pool(card, amount, DEFAULT_CURRENCY, proxy_str, u_id)
        
        elapsed = time.time() - start
        speed_controller.record_response(elapsed)
        
        bin_info = await get_bin_info(card)
        
        try:
            await status_msg.delete()
        except:
            pass
        
        # Format result
        ui, status_category = format_paypal_response_stylish(result, card, bin_info, amount)
        
        await message.reply_text(ui, parse_mode=ParseMode.HTML)
        
        # Save hit if charged
        if status_category == "charged":
            await save_hit_to_file(
                card=card, gateway="PayPal",
                response=result.get("message", "Charged"),
                price=f"${amount}",
                bin_info=bin_info, user_id=u_id, user_tier=tier
            )
            
            user_data = user_manager.get_user(u_id)
            await send_hit_notification(
                context=context, gateway="PayPal", card=card,
                response=result.get("message", "Charged"),
                price=f"${amount}",
                user=user_data, bin_info=bin_info, status_category="charged"
            )
            user_manager.increment_hits(u_id)
        
        user_manager.increment_checks(u_id)
        
        # Show remaining credits for free users
        if user_manager.get_tier(u_id) == 'free':
            remaining = get_user_credits(u_id)
            await message.reply_text(
                f"💎 <b>Credits Remaining: {remaining}</b>\n"
                f"Use /credits to check balance.",
                parse_mode=ParseMode.HTML
            )
        
    except Exception as e:
        try:
            await status_msg.delete()
        except:
            pass
        await message.reply_text(f"❌ Error: {str(e)[:100]}")
        print(f"❌ Error: {traceback.format_exc()}")
        add_user_credits(u_id, 1)

async def single_check_paypal_with_gif(update: Update, context: ContextTypes.DEFAULT_TYPE, card: str):
    """Single check with GIF on top + result below"""
    u_id = update.effective_user.id
    message = update.effective_message
    username = update.effective_user.username or update.effective_user.first_name
    
    # ============ CREDIT CHECK FIRST - STOP IF NO CREDITS ============
    can_proceed, error_msg = await check_and_deduct_credits(u_id, update, context, is_mass_check=False, card_count=1)
    if not can_proceed:
        await message.reply_text(error_msg, parse_mode=ParseMode.HTML)
        return
    
    # Check gateway access
    if not user_manager.can_access_gateway(u_id, 'paypal'):
        tier = user_manager.get_tier(u_id)
        await message.reply_text(
            f"❌ <b>PayPal not available for {tier.upper()} tier</b>\n\n"
            f"Upgrade to Premium/Ultimate to use PayPal gateway.",
            parse_mode=ParseMode.HTML
        )
        # Refund credits since gateway not available
        add_user_credits(u_id, 1)
        return
    
    try:
        tier = user_manager.get_tier(u_id)
        if u_id not in user_speed_controllers:
            user_speed_controllers[u_id] = SpeedController(TIER_SPEEDS.get(tier, 900), tier)
        speed_controller = user_speed_controllers[u_id]
        
        amount = context.user_data.get('payment_amount', DEFAULT_AMOUNT)
        
        status_msg = await message.reply_text("🔄 Checking card with PayPal...")
        
        await speed_controller.wait_if_needed()
        start = time.time()
        
        proxy_str = get_proxy_for_user(u_id) if user_manager.can_use_proxy(u_id) else None
        result = await check_card_paypal(card, amount, DEFAULT_CURRENCY, proxy_str, u_id)
        
        elapsed = time.time() - start
        speed_controller.record_response(elapsed)
        
        bin_info = await get_bin_info(card)
        
        try:
            await status_msg.delete()
        except:
            pass
        
        # Determine status
        status_category = result.get("status_category", "unknown")
        response_text = result.get("message", "Unknown")
        result_code = result.get("code", "")
        
        # ============ ALWAYS SHOW RESPONSE (NO HIDING) ============
        response_upper = f"{response_text} {result_code}".upper()
        
        # Determine the correct status display
        if "DECLINED" in status_category.upper() or "declined" in response_upper:
            status_display = "❌ DECLINED"
            final_category = "declined"
        elif "3D" in response_upper or "OTP" in response_upper or "SECURE" in response_upper:
            status_display = "🔐 3D REQUIRED"
            final_category = "approved"
        elif "INSUFFICIENT" in response_upper:
            status_display = "💰 INSUFFICIENT FUNDS"
            final_category = "approved"
        elif "CVV" in response_upper and "LIVE" in response_upper:
            status_display = "✅ CVV LIVE"
            final_category = "approved"
        elif "CHARGED" in response_upper or "ORDER COMPLETED" in response_upper:
            status_display = "🔥 CHARGED 🔥"
            final_category = "charged"
        else:
            status_display = "❌ DECLINED"
            final_category = "declined"
        
        # Parse card for display
        card_parts = card.split('|')
        card_num = card_parts[0] if len(card_parts) > 0 else card
        exp_month = card_parts[1] if len(card_parts) > 1 else "XX"
        exp_year = card_parts[2] if len(card_parts) > 2 else "XX"
        cvv = card_parts[3] if len(card_parts) > 3 else "XXX"
        
        bin_text, bank, country, _, _ = bin_info
        
        # Format country with flag
        country_name = country.replace('🌐', '').strip()
        flag_map = {
            'THAILAND': '🇹🇭', 'USA': '🇺🇸', 'UNITED STATES': '🇺🇸',
            'UK': '🇬🇧', 'UNITED KINGDOM': '🇬🇧', 'CANADA': '🇨🇦',
            'AUSTRALIA': '🇦🇺', 'INDIA': '🇮🇳', 'UAE': '🇦🇪'
        }
        country_flag = "🌍"
        for key, flag in flag_map.items():
            if key in country_name.upper():
                country_flag = flag
                break
        
        # Format bank name (truncate if too long)
        bank_display = bank if bank != 'N/A' else "Unknown"
        if len(bank_display) > 25:
            bank_display = bank_display[:22] + "..."
        
        # Format response message (clean up)
        clean_response = response_text.replace("RISK_DISALLOWED - ", "").replace("Card charged", "Card declined")
        if "RISK_DISALLOWED" in clean_response.upper():
            clean_response = "RISK_DISALLOWED - Card declined"
        
        # Build the output
        output = (
            f"┏━━━━━━━⍟\n"
            f"┃ {status_display}\n"
            f"┗━━━━━━━━━━━⊛\n\n"
            f"[⌬] 𝐂𝐚𝐫𝐝 ↣ {card_num} | {exp_month} | {exp_year} | {cvv}\n"
            f"[⌬] 𝐆𝐚𝐭𝐞𝐰𝐚𝐲 ↣ PayPal\n"
            f"[⌬] 𝐀𝐦𝐨𝐮𝐧𝐭 ↣ ${amount}\n"
            f"[⌬] 𝐑𝐞𝐬𝐩𝐨𝐧𝐬𝐞 ↣ {clean_response}\n"
            f"[⌬] 𝐁𝐈𝐍 ↣ {bin_text}\n"
            f"[⌬] 𝐁𝐚𝐧𝐤 ↣ {bank_display}\n"
            f"[⌬] 𝐂𝐨𝐮𝐧𝐭𝐫𝐲 ↣ {country_name}\n"
            f"[⌬] 𝐓𝐢𝐦𝐞 ↣ {elapsed:.2f}s"
        )
        
        await message.reply_text(output, parse_mode=ParseMode.HTML)
        
        # Only save as hit if ACTUALLY CHARGED
        if final_category == "charged":
            await save_hit_to_file(
                card=card, gateway="PayPal",
                response=clean_response, price=f"${amount}",
                bin_info=bin_info, user_id=u_id, user_tier=tier
            )
            
            # Send GIF only for actual charged cards
            await send_gif_with_result_combined(
                update=update,
                context=context,
                card=card,
                gateway="PayPal",
                response=clean_response,
                price=f"${amount}",
                bin_info=bin_info,
                status_category="charged",
                username=username
            )
            
            user_data = user_manager.get_user(u_id)
            await send_hit_notification(
                context=context, gateway="PayPal", card=card,
                response=clean_response, price=f"${amount}",
                user=user_data, bin_info=bin_info, status_category="charged"
            )
            
            user_manager.increment_hits(u_id)
        
        user_manager.increment_checks(u_id)
        
        # Show remaining credits for free users
        tier_check = user_manager.get_tier(u_id)
        if tier_check == 'free':
            remaining = get_user_credits(u_id)
            await message.reply_text(
                f"💎 <b>Credits Remaining: {remaining}</b>\n"
                f"Use /credits to check balance.",
                parse_mode=ParseMode.HTML
            )
        
    except Exception as e:
        try:
            await status_msg.delete()
        except:
            pass
        await message.reply_text(f"❌ Error: {str(e)[:100]}")
        print(f"❌ Error: {traceback.format_exc()}")
        # Refund credits on error
        add_user_credits(u_id, 1)
@check_gateway("paypal")
async def paypal_mass_check_with_pool(update: Update, context: ContextTypes.DEFAULT_TYPE, 
                                       cards: list, progress_msg=None, gateway_type: str = "paypal"):
    """
    Mass check for PayPal using API pool with premium emojis
    Supports: paypal, princess (gate2)
    """
    u_id = update.effective_user.id
    message = update.effective_message
    total = len(cards)
    username = update.effective_user.username or update.effective_user.first_name
    
    print(f"\n{'='*80}")
    print(f"🚀 [PAYPAL MASS CHECK] Starting batch for user {u_id}")
    print(f"📊 Total cards: {total}")
    print(f"🎯 Gateway: {gateway_type.upper()}")
    print(f"{'='*80}")
    
    amount = context.user_data.get('payment_amount', DEFAULT_AMOUNT)
    
    stats = {
        "charged": 0,
        "approved": 0,
        "ccn": 0,  # For Princess gateway
        "declined": 0,
        "errors": 0,
        "total": total,
        "processed": 0,
        "api_usage": {}
    }
    
    start_time = time.time()
    
    try:
        paypal_active_tasks[u_id] = True
        
        tier = user_manager.get_tier(u_id)
        
        CONCURRENCY = {
            "free": 2,
            "premium": 5,
            "ultimate": 5,
            "admin": 5,
        }.get(tier, 2)
        
        # Premium emojis for progress
        approved_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
        charged_emoji = premium_emoji(PREMIUM_EMOJI_IDS["charged"], "🔥")
        ccn_emoji = premium_emoji(PREMIUM_EMOJI_IDS["money"], "💰")
        dead_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
        errors_emoji = premium_emoji(PREMIUM_EMOJI_IDS["error"], "⚠️")
        time_emoji = premium_emoji(PREMIUM_EMOJI_IDS["time"], "⏱️")
        
        gateway_display = "Princess PayPal" if gateway_type == "princess" else "PayPal"
        
        if progress_msg is None:
            progress_text = (
                f"<b>Gateway</b> ➛ {gateway_display}\n"
                f"<b>Status</b> ➛ STARTING...\n"
                f"<b>Checked</b> ➛ 0/{total}\n"
                f"<b>Charged</b> ➛ 0 {charged_emoji}\n"
                f"<b>Approved</b> ➛ 0 {approved_emoji}\n"
                f"<b>CVV Live</b> ➛ 0 {ccn_emoji}\n"
                f"<b>Declined</b> ➛ 0 {dead_emoji}\n"
                f"<b>Errors</b> ➛ 0 {errors_emoji}\n"
                f"<b>Time</b> ➛ 0s"
            )
            progress_msg = await message.reply_text(progress_text, parse_mode=ParseMode.HTML)
        
        if u_id not in user_speed_controllers:
            user_speed_controllers[u_id] = SpeedController(TIER_SPEEDS.get(tier, 900), tier)
        speed_controller = user_speed_controllers[u_id]
        
        semaphore = asyncio.Semaphore(CONCURRENCY)
        stats_lock = asyncio.Lock()
        processed_count = 0
        
        async def update_progress(current: int):
            """Update progress message"""
            if current > 0 and current < total and current % 5 != 0:
                return
            elapsed = int(time.time() - start_time)
            minutes = elapsed // 60
            seconds = elapsed % 60
            time_str = f"{minutes}m {seconds}s" if minutes > 0 else f"{seconds}s"
            
            if current >= total:
                status_text = "FINISHED ✅"
                status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["success"], "✅")
            else:
                status_text = f"PROCESSING {current}/{total}"
                status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["time"], "🔄")
            
            # Build progress text based on gateway type
            if gateway_type == "princess":
                progress_text = (
                    f"<b>Gateway</b> ➛ {gateway_display}\n"
                    f"<b>Status</b> ➛ {status_text} {status_emoji}\n"
                    f"<b>Checked</b> ➛ {current}/{total}\n"
                    f"<b>Charged</b> ➛ {stats['charged']} {charged_emoji}\n"
                    f"<b>Approved</b> ➛ {stats['approved']} {approved_emoji}\n"
                    f"<b>CVV Live</b> ➛ {stats['ccn']} {ccn_emoji}\n"
                    f"<b>Declined</b> ➛ {stats['declined']} {dead_emoji}\n"
                    f"<b>Errors</b> ➛ 0 {errors_emoji}\n"
                    f"<b>Time</b> ➛ {time_str}"
                )
            else:
                progress_text = (
                    f"<b>Gateway</b> ➛ {gateway_display}\n"
                    f"<b>Status</b> ➛ {status_text} {status_emoji}\n"
                    f"<b>Checked</b> ➛ {current}/{total}\n"
                    f"<b>Charged</b> ➛ {stats['charged']} {charged_emoji}\n"
                    f"<b>Approved</b> ➛ {stats['approved']} {approved_emoji}\n"
                    f"<b>Declined</b> ➛ {stats['declined']} {dead_emoji}\n"
                    f"<b>Errors</b> ➛ 0 {errors_emoji}\n"
                    f"<b>Time</b> ➛ {time_str}"
                )
            
            try:
                await progress_msg.edit_text(progress_text, parse_mode=ParseMode.HTML)
            except:
                pass
        
        async def process_single_card(card: str, idx: int):
            """Process a single card"""
            nonlocal processed_count
            
            await asyncio.sleep(random.uniform(0.1, 0.3))
            
            async with semaphore:
                await speed_controller.wait_if_needed()
                start = time.time()
                
                # Get proxy if allowed
                proxy_str = None
                if user_manager.can_use_proxy(u_id):
                    if u_id in autosopi_proxy_tracker.working_proxies and autosopi_proxy_tracker.working_proxies[u_id]:
                        proxy_list = autosopi_proxy_tracker.working_proxies[u_id]
                        if proxy_list:
                            proxy_index = idx % len(proxy_list)
                            proxy_str = proxy_list[proxy_index]
                
                # ============ CHOOSE GATEWAY ============
                if gateway_type == "princess":
                    # Parse card for Princess gateway
                    parts = card.split('|')
                    if len(parts) != 4:
                        result = {'status': 'error', 'message': 'Invalid card format'}
                    else:
                        cc, mm, yy, cvv = parts
                        # Convert year to 2-digit
                        if len(yy) == 4:
                            yy = yy[2:]
                        if len(mm) == 1:
                            mm = f'0{mm}'
                        user_proxies = [proxy_str] if proxy_str else None
                        result = await check_card_princess(cc, mm, yy, cvv, user_proxies)
                    elapsed = time.time() - start
                    speed_controller.record_response(elapsed)
                else:
                    # Use PayPal API pool
                    result = await paypal_api_pool.check_card_with_pool(card, amount, DEFAULT_CURRENCY, proxy_str, u_id)
                    elapsed = time.time() - start
                    speed_controller.record_response(elapsed)
                
                # Get BIN info
                bin_info = await get_bin_info(card)
                
                # Get response
                response_msg = result.get("message", "")
                status = result.get("status", "unknown")
                api_used = result.get("api_used", "unknown")
                result_text = result.get("result", "")
                
                # Update stats
                async with stats_lock:
                    processed_count += 1
                    
                    if api_used not in stats["api_usage"]:
                        stats["api_usage"][api_used] = 0
                    stats["api_usage"][api_used] += 1
                    
                    if gateway_type == "princess":
                        if status == "charged":
                            stats["charged"] += 1
                            stats["approved"] += 1
                            print(f"🔥 [CHARGED] {card[:20]}...")
                        elif status == "approved":
                            stats["approved"] += 1
                            print(f"✅ [APPROVED] {card[:20]}...")
                        elif status == "ccn":
                            stats["ccn"] += 1
                            print(f"💰 [CVV LIVE] {card[:20]}...")
                        elif status == "dead" or status == "declined":
                            stats["declined"] += 1
                            print(f"❌ [DECLINED - HIDDEN] {card[:20]}...")
                        else:
                            stats["errors"] += 1
                            print(f"⚠️ [ERROR - HIDDEN] {card[:20]}...")
                    else:
                        # PayPal status
                        if status == "charged":
                            stats["charged"] += 1
                            stats["approved"] += 1
                            print(f"🔥 [CHARGED] {card[:20]}...")
                        elif status == "approved":
                            stats["approved"] += 1
                            print(f"✅ [APPROVED] {card[:20]}...")
                        elif status == "declined":
                            stats["declined"] += 1
                            print(f"❌ [DECLINED - HIDDEN] {card[:20]}...")
                        else:
                            stats["errors"] += 1
                            print(f"⚠️ [ERROR - HIDDEN] {card[:20]}...")
                    
                    if processed_count % 5 == 0 or processed_count == total:
                        await update_progress(processed_count)
                
                # ============ SEND RESULT FOR CHARGED/APPROVED/LIVE CARDS ============
                should_send = status in ["charged", "approved"] or (gateway_type == "princess" and status == "ccn")
                
                if should_send:
                    # Parse card parts for display
                    card_parts = card.split('|')
                    card_num = card_parts[0] if len(card_parts) > 0 else card
                    exp_month = card_parts[1] if len(card_parts) > 1 else "XX"
                    exp_year = card_parts[2] if len(card_parts) > 2 else "XX"
                    exp_year_short = exp_year[-2:] if len(exp_year) == 4 else exp_year
                    cvv_display = card_parts[3] if len(card_parts) > 3 else "XXX"
                    
                    bin_text, bank, country, _, _ = bin_info
                    
                    # Format country with flag
                    country_name = country.replace('🌐', '').strip()
                    flag_map = {
                        'USA': '🇺🇸', 'UNITED STATES': '🇺🇸', 'UK': '🇬🇧', 'CANADA': '🇨🇦',
                        'AUSTRALIA': '🇦🇺', 'INDIA': '🇮🇳', 'UAE': '🇦🇪'
                    }
                    country_flag = "🌍"
                    for key, flag in flag_map.items():
                        if key in country_name.upper():
                            country_flag = flag
                            break
                    
                    # Format bank name
                    bank_display = bank if bank != 'N/A' else "Unknown"
                    if len(bank_display) > 25:
                        bank_display = bank_display[:22] + "..."
                    
                    # Determine status emoji and display
                    if status == "charged":
                        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["charged"], "🔥")
                        status_display = "CHARGED"
                        clean_response = f"Charged ${amount}"
                        should_save = True
                    elif status == "approved" and gateway_type == "princess":
                        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
                        status_display = "APPROVED"
                        clean_response = "Payment Method Added"
                        should_save = False
                    elif status == "ccn":
                        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["money"], "💰")
                        status_display = "CVV LIVE"
                        clean_response = "CVV Live - Card is valid"
                        should_save = False
                    elif status == "approved":
                        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
                        status_display = "APPROVED"
                        clean_response = response_msg[:60] if response_msg else "Card Approved"
                        should_save = False
                    else:
                        status_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
                        status_display = "DECLINED"
                        clean_response = "CARD DECLINED"
                        should_save = False
                    
                    # Build output with Premium Emojis
                    output = (
                        f"┏━━━━━━━⍟\n"
                        f"┃ {status_emoji} {status_display}\n"
                        f"┗━━━━━━━━━━━⊛\n\n"
                        f"<b>Card</b> ↣ <code>{card_num}|{exp_month}|{exp_year_short}|{cvv_display}</code>\n"
                        f"<b>Gateway</b> ↣ {gateway_display}\n"
                        f"<b>Amount</b> ↣ ${amount}\n"
                        f"<b>Response</b> ↣ {clean_response}\n"
                        f"<b>BIN</b> ↣ {bin_text}\n"
                        f"<b>Bank</b> ↣ {bank_display}\n"
                        f"<b>Country</b> ↣ {country_name}\n"
                        f"<b>Time</b> ↣ {elapsed:.2f}s"
                    )
                    
                    try:
                        await message.reply_text(output, parse_mode=ParseMode.HTML)
                        print(f"📤 [SENT] {status_display}: {card[:20]}...")
                    except Exception as e:
                        print(f"❌ Error sending result: {e}")
                    
                    # Save hit to file for charged cards
                    if should_save and status == "charged":
                        await save_hit_to_file(
                            card=card, gateway=gateway_display,
                            response=clean_response,
                            price=f"${amount}",
                            bin_info=bin_info, user_id=u_id, user_tier=tier
                        )
                        
                        user_data = user_manager.get_user(u_id)
                        await send_hit_notification(
                            context=context, gateway=gateway_display, card=card,
                            response=clean_response,
                            price=f"${amount}",
                            user=user_data, bin_info=bin_info, status_category="charged"
                        )
                        user_manager.increment_hits(u_id)
                
                user_manager.increment_checks(u_id, 1)
                return result, card
        
        # Process all cards
        tasks = [process_single_card(card, idx) for idx, card in enumerate(cards)]
        
        for coro in asyncio.as_completed(tasks):
            if u_id not in paypal_active_tasks:
                print(f"🛑 Session stopped for user {u_id}")
                break
            try:
                await coro
            except Exception as e:
                print(f"❌ Task error: {e}")
                traceback.print_exc()
                async with stats_lock:
                    stats["errors"] += 1
        
        # Final summary
        if u_id in paypal_active_tasks:
            total_time = time.time() - start_time
            minutes = int(total_time // 60)
            seconds = int(total_time % 60)
            
            # Build API usage summary
            api_summary = ""
            if stats["api_usage"]:
                api_summary = "\n📊 <b>API Usage:</b>\n"
                for api_name, count in sorted(stats["api_usage"].items(), key=lambda x: x[1], reverse=True):
                    api_summary += f"   • {api_name}: {count} cards\n"
            
            # Premium emojis for summary
            charged_emoji_sum = premium_emoji(PREMIUM_EMOJI_IDS["charged"], "🔥")
            approved_emoji_sum = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
            ccn_emoji_sum = premium_emoji(PREMIUM_EMOJI_IDS["money"], "💰")
            declined_emoji_sum = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
            errors_emoji_sum = premium_emoji(PREMIUM_EMOJI_IDS["error"], "⚠️")
            total_emoji = premium_emoji(PREMIUM_EMOJI_IDS["stats"], "📝")
            time_emoji_sum = premium_emoji(PREMIUM_EMOJI_IDS["time"], "⏱️")
            skull_emoji = premium_emoji(PREMIUM_EMOJI_IDS["skull"], "💀")
            
            # Build summary based on gateway type
            if gateway_type == "princess":
                summary = (
                    f"{skull_emoji} <b>Princess PayPal Mass Check Complete</b>\n\n"
                    f"{charged_emoji_sum} <b>Charged</b> ➛ {stats['charged']}\n"
                    f"{approved_emoji_sum} <b>Approved</b> ➛ {stats['approved']}\n"
                    f"{ccn_emoji_sum} <b>CVV Live</b> ➛ {stats['ccn']}\n"
                    f"{declined_emoji_sum} <b>Declined</b> ➛ {stats['declined']} (Hidden)\n"
                    f"{errors_emoji_sum} <b>Errors</b> ➛ 0\n"
                    f"{total_emoji} <b>Total</b> ➛ {total}\n"
                    f"{time_emoji_sum} <b>Time</b> ➛ {minutes}m {seconds}s\n"
                    f"{skull_emoji} <b>Bot</b> ➛ @BLADESARKS_V3bot"
                )
            else:
                summary = (
                    f"{skull_emoji} <b>PayPal Mass Check Complete</b>\n\n"
                    f"{charged_emoji_sum} <b>Charged</b> ➛ {stats['charged']}\n"
                    f"{approved_emoji_sum} <b>Approved</b> ➛ {stats['approved']}\n"
                    f"{declined_emoji_sum} <b>Declined</b> ➛ {stats['declined']} (Hidden)\n"
                    f"{errors_emoji_sum} <b>Errors</b> ➛ 0\n"
                    f"{total_emoji} <b>Total</b> ➛ {total}\n"
                    f"{time_emoji_sum} <b>Time</b> ➛ {minutes}m {seconds}s\n"
                    f"{skull_emoji} <b>Bot</b> ➛ @BLADESARKS_V3bot"
                )
            
            await update_progress(total)
            await message.reply_text(summary, parse_mode=ParseMode.HTML)
            print(f"📊 Final summary sent to user {u_id}")
        
        return stats
        
    except Exception as e:
        print(f"❌ PayPal mass check error: {e}")
        traceback.print_exc()
        try:
            if progress_msg:
                await progress_msg.edit_text(f"❌ Error: {str(e)[:100]}")
            else:
                await message.reply_text(f"❌ Error: {str(e)[:100]}")
        except:
            pass
    finally:
        paypal_active_tasks.pop(u_id, None)
        print(f"🏁 [PayPal Mass] Session ended for user {u_id}")
@check_gateway("paypal")       
async def mass_check_paypal(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Mass card check with PayPal gateway - /mpp"""
    if not await verify_group_access(update, context):
        return
    
    user_id = update.effective_user.id
    message = update.effective_message
    
    if not context.args:
        await message.reply_text(
            "📦 <b>PayPal Mass Check</b>\n\n"
            "Usage: <code>/mpp &lt;card1&gt; &lt;card2&gt; ...</code>\n\n"
            "Example: <code>/mpp 4111111111111111|12|2028|123 4222222222222222|11|2026|456</code>\n\n"
            "Or reply to a .txt file with /mpp",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Check if user can mass check
    if not user_manager.can_mass_check(user_id):
        tier = user_manager.get_tier(user_id)
        await message.reply_text(
            f"❌ <b>Mass Check Not Available for {tier.upper()} Tier</b>\n\n"
            f"Use <code>/pp &lt;card&gt;</code> for single checks.\n\n"
            f"💎 Upgrade to Premium/Ultimate for mass checks.",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Extract cards
    cards_text = " ".join(context.args)
    card_strings = cards_text.split()
    
    cards = []
    invalid_cards = []
    
    for card_str in card_strings:
        card = card_formatter.extract_single_card_from_text(card_str)
        if card:
            cards.append(card)
        else:
            invalid_cards.append(card_str[:30])
    
    if invalid_cards:
        await message.reply_text(
            f"⚠️ Found {len(invalid_cards)} invalid card(s). They will be skipped.\n"
            f"First invalid: {invalid_cards[0]}..."
        )
    
    if not cards:
        await message.reply_text("❌ No valid cards found.")
        return
    
    # Check batch size limit
    tier = user_manager.get_tier(user_id)
    max_batch = user_manager.get_max_batch_size(user_id)
    if len(cards) > max_batch:
        cards = cards[:max_batch]
        await message.reply_text(f"⚠️ Your tier allows max {max_batch} cards. Truncating.")
    
    # Check credits for mass check (1 credit per card for free users)
    can_proceed, error_msg = await check_and_deduct_mass_credits(user_id, update, context, len(cards))
    if not can_proceed:
        await message.reply_text(error_msg, parse_mode=ParseMode.HTML)
        return
    
    # Delete command message
    try:
        await message.delete()
    except:
        pass
    
    # ============ FIXED: Use paypal_mass_check_with_pool ============
    await paypal_mass_check_with_pool(update, context, cards, None, gateway_type="paypal")


async def mass_check_paypal_princess(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Mass card check with Princess PayPal gateway - /mpp1"""
    if not await verify_group_access(update, context):
        return
    
    user_id = update.effective_user.id
    message = update.effective_message
    
    if user_id in princess_active_tasks:
        await message.reply_text(
            "⚠️ You already have an active Princess gateway session.\n"
            "Please wait for it to finish or use /stop to cancel.",
            parse_mode=ParseMode.HTML
        )
        return
    
    if not user_manager.can_access_gateway(user_id, 'paypal'):
        tier = user_manager.get_tier(user_id)
        await message.reply_text(
            f"❌ Princess gateway not available for {tier.upper()} tier.",
            parse_mode=ParseMode.HTML
        )
        return
    
    if not user_manager.can_mass_check(user_id):
        tier = user_manager.get_tier(user_id)
        await message.reply_text(
            f"❌ Mass check not available for {tier.upper()} tier.\n\n"
            f"Use /pp1 for single checks.\n"
            f"💎 Upgrade to Premium/Ultimate for mass checks.",
            parse_mode=ParseMode.HTML
        )
        return
    
    # Check if reply to file
    if message.reply_to_message and message.reply_to_message.document:
        try:
            file = await message.reply_to_message.document.get_file()
            content = await file.download_as_bytearray()
            content = content.decode('utf-8', errors='ignore')
            
            cards = []
            for line in content.splitlines():
                line = line.strip()
                if line and not line.startswith('#'):
                    card = card_formatter.extract_single_card_from_text(line)
                    if card:
                        cards.append(card)
            
            if not cards:
                await message.reply_text("❌ No valid cards found in file.")
                return
                
            await message.delete()
            await paypal_mass_check_with_pool(update, context, cards, None, gateway_type="princess")
            return
            
        except Exception as e:
            await message.reply_text(f"❌ Error reading file: {str(e)[:100]}")
            return
    
    # Handle direct text input
    if not context.args:
        await message.reply_text(
            "📦 <b>Princess PayPal Mass Check</b>\n\n"
            "Usage: <code>/mpp1 &lt;card1&gt; &lt;card2&gt; ...</code>\n"
            "Or reply to a .txt file with /mpp1\n\n"
            "Example: <code>/mpp1 4242424242424242|12|2028|123 4222222222222222|11|2026|456</code>\n\n"
            "💰 Amount: $2.00\n"
            "📍 Gateway: PayPal via Princess For A Day\n"
            "✅ Only charged/approved/cvv live cards will be shown",
            parse_mode=ParseMode.HTML
        )
        return
    
    cards_text = " ".join(context.args)
    card_strings = cards_text.split()
    
    cards = []
    for card_str in card_strings:
        card = card_formatter.extract_single_card_from_text(card_str)
        if card:
            cards.append(card)
    
    if not cards:
        await message.reply_text("❌ No valid cards found.")
        return
    
    # Check batch size limit
    max_batch = user_manager.get_max_batch_size(user_id)
    if len(cards) > max_batch:
        cards = cards[:max_batch]
        await message.reply_text(f"⚠️ Your tier allows max {max_batch} cards. Truncating.")
    
    # Check credits for mass check
    can_proceed, error_msg = await check_and_deduct_mass_credits(user_id, update, context, len(cards))
    if not can_proceed:
        await message.reply_text(error_msg, parse_mode=ParseMode.HTML)
        return
    
    try:
        await message.delete()
    except:
        pass
    
    # ============ FIXED: Use paypal_mass_check_with_pool with princess gateway ============
    await paypal_mass_check_with_pool(update, context, cards, None, gateway_type="princess")
async def mass_check_logic(update: Update, context: ContextTypes.DEFAULT_TYPE, cards: list, progress_msg=None):
    """Mass check logic for PayPal gateway - FIXED with correct PayPal function"""
    u_id = update.effective_user.id
    message = update.effective_message
    total = len(cards)
    
    print(f"\n{'='*80}")
    print(f"👷 [WORKER MODE] Starting batch for user {u_id}")
    print(f"📊 Total cards: {total}")
    print(f"👥 Workers: {20}")
    print(f"{'='*80}")
    
    try:
        paypal_active_tasks[u_id] = True
        
        tier = user_manager.get_tier(u_id)
        
        stats = {
            "charged": 0,
            "approved": 0,
            "declined": 0,
            "errors": 0,
            "total": total,
            "processed": 0
        }
        
        start_time = time.time()
        amount = context.user_data.get('payment_amount', DEFAULT_AMOUNT)
        
        if u_id not in user_speed_controllers:
            user_speed_controllers[u_id] = SpeedController(TIER_SPEEDS.get(tier, 900), tier)
        speed_controller = user_speed_controllers[u_id]
        
        # ============ CREATE PROGRESS MESSAGE ============
        if progress_msg is None:
            charged_emoji = premium_emoji(PREMIUM_EMOJI_IDS["charged"], "🔥")
            approved_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
            dead_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
            errors_emoji = premium_emoji(PREMIUM_EMOJI_IDS["error"], "⚠️")
            time_emoji = premium_emoji(PREMIUM_EMOJI_IDS["time"], "⏱️")
            
            progress_text = (
                f"<b>Gateway</b> ➛ PayPal\n"
                f"<b>Status</b> ➛ STARTING...\n"
                f"<b>Checked</b> ➛ 0/{total}\n"
                f"<b>Charged</b> ➛ 0 {charged_emoji}\n"
                f"<b>Approved</b> ➛ 0 {approved_emoji}\n"
                f"<b>Dead</b> ➛ 0 {dead_emoji}\n"
                f"<b>Errors</b> ➛ 0 {errors_emoji}\n"
                f"<b>Time</b> ➛ 0s"
            )
            progress_msg = await message.reply_text(progress_text, parse_mode=ParseMode.HTML)
        
        async def update_progress(current: int):
            """Update progress message"""
            if current > 0 and current < total and current % 5 != 0:
                return
            elapsed = int(time.time() - start_time)
            minutes = elapsed // 60
            seconds = elapsed % 60
            time_str = f"{minutes}m {seconds}s" if minutes > 0 else f"{seconds}s"
            
            charged_emoji = premium_emoji(PREMIUM_EMOJI_IDS["charged"], "🔥")
            approved_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
            dead_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
            errors_emoji = premium_emoji(PREMIUM_EMOJI_IDS["error"], "⚠️")
            
            if current >= total:
                status_text = "FINISHED ✅"
            else:
                status_text = f"PROCESSING {current}/{total}"
            
            progress_text = (
                f"<b>Gateway</b> ➛ PayPal\n"
                f"<b>Status</b> ➛ {status_text}\n"
                f"<b>Checked</b> ➛ {current}/{total}\n"
                f"<b>Charged</b> ➛ {stats['charged']} {charged_emoji}\n"
                f"<b>Approved</b> ➛ {stats['approved']} {approved_emoji}\n"
                f"<b>Dead</b> ➛ {stats['declined']} {dead_emoji}\n"
                f"<b>Errors</b> ➛ {stats['errors']} {errors_emoji}\n"
                f"<b>Time</b> ➛ {time_str}"
            )
            try:
                await progress_msg.edit_text(progress_text, parse_mode=ParseMode.HTML)
            except Exception as e:
                if "message is not modified" not in str(e).lower():
                    print(f"⚠️ Progress update error: {e}")
        
        # Get working proxies for user
        user_proxies = []
        if user_manager.can_use_proxy(u_id):
            if u_id in autosopi_proxy_tracker.working_proxies and autosopi_proxy_tracker.working_proxies[u_id]:
                user_proxies = autosopi_proxy_tracker.working_proxies[u_id]
                print(f"🔌 Using {len(user_proxies)} working proxies for rotation")
        
        # Process cards sequentially
        proxy_index = 0
        for i, card in enumerate(cards, 1):
            if u_id not in paypal_active_tasks:
                break
            
            await update_progress(i - 1)
            
            await speed_controller.wait_if_needed()
            
            # Get rotating proxy
            proxy_str = None
            if user_proxies:
                proxy_str = user_proxies[proxy_index % len(user_proxies)]
                proxy_index += 1
            
            start = time.time()
            
            # ============ FIXED: Use paypal_api_pool.check_card_with_pool ============
            result = await paypal_api_pool.check_card_with_pool(card, amount, DEFAULT_CURRENCY, proxy_str, u_id)
            
            elapsed = time.time() - start
            speed_controller.record_response(elapsed)
            
            bin_info = await get_bin_info(card)
            status_category = result.get("status_category", "unknown")
            response_text = result.get("message", "Unknown")
            result_status = result.get("result", "")
            result_code = result.get("code", "")
            
            # Update stats
            if status_category == "charged":
                stats["charged"] += 1
                stats["approved"] += 1
                print(f"🔥 CHARGED: {card[:20]}...")
            elif status_category == "approved":
                stats["approved"] += 1
                print(f"✅ APPROVED: {card[:20]}...")
            elif status_category == "declined":
                stats["declined"] += 1
                print(f"❌ DECLINED: {card[:20]}...")
            else:
                stats["errors"] += 1
                print(f"⚠️ ERROR: {card[:20]}...")
            
            # Send result for charged/approved cards
            if status_category in ["charged", "approved"]:
                ui, _ = format_paypal_response_stylish(result, card, bin_info, amount)
                await message.reply_text(ui, parse_mode=ParseMode.HTML)
            
            # Save hit for charged cards
            if status_category == "charged":
                await save_hit_to_file(
                    card=card, gateway="PayPal",
                    response=response_text, price=f"${amount}",
                    bin_info=bin_info, user_id=u_id, user_tier=tier
                )
                
                user_data = user_manager.get_user(u_id)
                await send_hit_notification(
                    context=context, gateway="PayPal", card=card,
                    response=response_text, price=f"${amount}",
                    user=user_data, bin_info=bin_info, status_category="charged"
                )
                user_manager.increment_hits(u_id)
            
            user_manager.increment_checks(u_id, 1)
            stats["processed"] = i
            
            # Delay between cards
            if i < total:
                await asyncio.sleep(1.0)
        
        # Final summary
        if u_id in paypal_active_tasks:
            total_time = time.time() - start_time
            minutes = int(total_time // 60)
            seconds = int(total_time % 60)
            cards_per_minute = (total / (total_time / 60)) if total_time > 0 else 0
            
            await update_progress(total)
            
            charged_emoji = premium_emoji(PREMIUM_EMOJI_IDS["charged"], "🔥")
            approved_emoji = premium_emoji(PREMIUM_EMOJI_IDS["approved"], "✅")
            dead_emoji = premium_emoji(PREMIUM_EMOJI_IDS["declined"], "❌")
            errors_emoji = premium_emoji(PREMIUM_EMOJI_IDS["error"], "⚠️")
            total_emoji = premium_emoji(PREMIUM_EMOJI_IDS["stats"], "📝")
            time_emoji = premium_emoji(PREMIUM_EMOJI_IDS["time"], "⏱️")
            skull_emoji = premium_emoji(PREMIUM_EMOJI_IDS["skull"], "💀")
            
            summary = (
                f"{skull_emoji} <b>Mass Check Complete</b>\n\n"
                f"{charged_emoji} <b>Charged</b> ➛ {stats['charged']}\n"
                f"{approved_emoji} <b>Approved</b> ➛ {stats['approved']}\n"
                f"{dead_emoji} <b>Dead</b> ➛ {stats['declined']}\n"
                f"{errors_emoji} <b>Errors</b> ➛ {stats['errors']}\n"
                f"{total_emoji} <b>Total</b> ➛ {total}\n"
                f"📈 <b>Rate</b> ➛ {cards_per_minute:.1f} cards/min\n"
                f"{time_emoji} <b>Time</b> ➛ {minutes}m {seconds}s\n"
                f"{skull_emoji} <b>Bot</b> ➛ @BLADESARKS_V3bot"
            )
            
            await message.reply_text(summary, parse_mode=ParseMode.HTML)
        
        return stats
        
    except Exception as e:
        print(f"❌ Mass check error: {e}")
        traceback.print_exc()
        try:
            if progress_msg:
                await progress_msg.edit_text(f"❌ Error: {str(e)[:100]}")
            else:
                await message.reply_text(f"❌ Error: {str(e)[:100]}")
        except:
            pass
    finally:
        paypal_active_tasks.pop(u_id, None)
        print(f"🏁 Session ended for user {u_id}")
        
async def test_my_proxies_autosopi(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Test your proxies specifically for Autosopi API - /testautoproxy"""
    if not await verify_group_access(update, context):
        return
    
    user_id = update.effective_user.id
    
    if not user_manager.can_use_proxy(user_id):
        await update.message.reply_text("❌ Your tier doesn't support proxy usage.")
        return
    
    if user_id not in proxy_manager.user_proxies or not proxy_manager.user_proxies[user_id]:
        await update.message.reply_text(
            "📋 You don't have any proxies to test.\n"
            "Use /addmyproxy <proxy> to add proxies first.",
            parse_mode=ParseMode.HTML
        )
        return
    
    msg = await update.message.reply_text(
        f"🧪 <b>Testing your proxies for Autosopi API</b>\n\n"
        f"📊 Found {len(proxy_manager.user_proxies[user_id])} proxies\n"
        f"🔄 Testing each proxy...\n"
        f"This may take a moment.",
        parse_mode=ParseMode.HTML
    )
    
    working_count = await test_and_populate_proxies_for_user(user_id, context)
    
    if working_count > 0:
        working_list = "\n".join([f"  • {mask_proxy(p)}" for p in autosopi_proxy_tracker.working_proxies.get(user_id, [])[:10]])
        result = (
            f"✅ <b>Proxy Test Complete</b>\n\n"
            f"🔌 Working proxies: {working_count}/{len(proxy_manager.user_proxies[user_id])}\n\n"
            f"<b>Working Proxies:</b>\n{working_list}\n\n"
            f"🔄 These proxies will be used for /aumc with automatic rotation."
        )
    else:
        result = (
            f"❌ <b>No working proxies found!</b>\n\n"
            f"All {len(proxy_manager.user_proxies[user_id])} proxies failed.\n\n"
            f"Please add different proxies using /addmyproxy or /massproxy"
        )
    
    await msg.edit_text(result, parse_mode=ParseMode.HTML, reply_markup=back_menu())
